pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never fit the smallest
    // plausible item are pure waste — penalize them heavily.
    if post_residual > 0 {
        let dead = (post_residual < 10) as f64;
        score += dead * 500.0;
        // Partially dead: too small for the upcoming item but still open space.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 40.0 + (next_item_size - post_residual) as f64 * 0.5;
        }
    } else {
        // Perfect fit — reward strongly.
        score -= 200.0;
    }

    // Exact or near-exact packing bonus (post_residual within a small epsilon).
    if post_residual <= 5 {
        score -= 80.0;
    }

    // Open-bin pressure: discourage spreading across many bins; a tight fit
    // into an existing bin is preferred as open_bins_count grows.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: if this is the only bin that can fit the item, using it
    // avoids opening a new bin — reward it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Prefer bins tighter than average (they are the scarce-fit bins).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Lookahead: if the next item fits the post-residual, this placement is
    // especially good (chained packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin offers a good fit
    // (large residual waste elsewhere) or late in the stream when fresh bins
    // can still absorb future items.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let scarcity = (fitting_bins_count == 0) as f64;
        let bad_fits = (mean_residual > 60.0) as f64;
        score = 150.0 - scarcity * 120.0 - bad_fits * 40.0 - progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 45.0 * (-diff / 12.0).exp(); // strong reward when next item fills this bin
        // Penalize leaving a gap that is too small for the next item (dead space).
        if post_residual < next_item_size {
            score += 8.0 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer minimal waste.
        score += 2.0 * post_residual as f64;
    }

    // Penalize residual far above mean residual (relative coupling).
    score += 1.5 * (post_residual as f64 - mean_residual).max(0.0);
    score -= 0.5 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bonus: only bin that fits -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer filling bins with small residual (tight fit reward).
    score -= 10.0 * (-post_residual as f64 / 10.0).exp();

    // New-bin candidate handling: make new bin moderately attractive only when
    // no open bin gives a good fit; otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 5.0;
        } else {
            score += 25.0;
        }
    }

    // Slight preference to close out nearly-full bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize residuals that are too small
    // to plausibly hold a future item (below the minimum item size of 1,
    // but practically below a usable threshold).
    let usable_threshold = 20.0;
    if (post_residual as f64) < usable_threshold && post_residual > 0 {
        score += (usable_threshold - post_residual as f64) * 6.0;
    }

    // Reward tight fits: item fills the bin almost exactly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating
    // into existing bins rather than opening more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64) * (0.5 + 0.5 * progress);
    score += pressure * 0.8;

    // New-bin candidate: only attractive when item is large relative to
    // capacity or existing bins have poor residuals.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin mildly; offset by dead-space savings
        // when the item is large.
        score += 18.0 - 0.25 * (item_size as f64);
        // If current bin would leave a big dead gap but a fresh bin fits
        // the item snugly, opening is fine.
        if (post_residual as f64) < usable_threshold {
            score -= 12.0;
        }
        // Lookahead: if next item would fit in a fresh bin's residual,
        // opening is more attractive.
        if next_item_size > 0 && next_item_size <= bin_residual - item_size {
            score -= 8.0;
        }
    } else {
        // Existing bin: reward if residual after placement still fits
        // the lookahead item (keeps future flexibility).
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        } else if next_item_size > post_residual {
            score += 3.0;
        }
        // Slight reward for placing into bins with below-average residual
        // (uses up the fullest bins first, best-fit style).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual below 10 (min item size) is pure waste; ramp penalty as gap shrinks.
    if post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    } else if post_residual <= 25 {
        // Medium gaps: mildly risky, penalize proportionally to how little can fit.
        score += 12.0 * (25.0 - post_residual as f64) / 15.0;
    }

    // Reward near-perfect fits (tight packing) with a strong subtraction.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // penalize leaving large residuals so bins close out faster.
    let open_pressure = (open_bins_count as f64).ln().max(0.0) * 4.0;
    score += open_pressure * (post_residual as f64 / bin_capacity as f64);

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly reward this placement (chained packing).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0; // next item still fits: keep this bin attractive
    }

    // New-bin candidate: only attractive when this bin would leave a big
    // unusable gap or when open bins are congested (high mean residual spread).
    if bin_residual == bin_capacity {
        let gap_penalty = if post_residual < 10 { 25.0 } else { 0.0 };
        score += gap_penalty;
        score -= 5.0 * open_pressure;
        // If the current bin is the only fitting one, opening a new bin is bad.
        if fitting_bins_count == 1 {
            score += 80.0;
        }
    }

    // Early stream: be slightly more conservative (keep fresh bins available).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 3.0 * (post_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it's already tight — favor filling it further.
    let bin_res_f = bin_residual as f64;
    if bin_res_f < mean_residual {
        score -= (mean_residual - bin_res_f) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues mod 10 create "usable" vs "dead" classes
    let r = post_residual % 10;
    // Dead-space penalty grows when post_residual is small but not class-aligned
    if post_residual > 0 {
        if r == 0 {
            score -= 6.0; // perfectly divisible residual, easy to fill later
        } else if r <= 2 {
            score += 10.0; // near-dead sliver
        }
    } else {
        score -= 20.0; // perfect closure
    }

    // Fraction-of-capacity classes: quarter/half/three-quarter residuals are prime targets
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    let diff = (post_residual as i32 - half as i32).abs();
    if diff <= 2 { score -= 4.0; }
    let diffq = (post_residual as i32 - quarter as i32).abs();
    if diffq <= 2 { score -= 3.0; }

    // Lookahead coupling: does post_residual pair with next item via integer division?
    if next_item_size > 0 && post_residual >= next_item_size {
        let fits_next = post_residual - next_item_size;
        score -= (fits_next % 10 == 0) as i32 as f64 * 5.0;
        score += (fits_next > 0 && fits_next < 5) as i32 as f64 * 6.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 3.0; // blocks the lookahead item in this bin
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: keep it neutral-ish early, expensive when many bins already open
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 + 10.0 * (1.0 - progress) - 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size > bin_capacity / 2 {
            score -= 6.0; // big next item may deserve its own fresh bin
        }
    }

    // Slight preference for bins tighter than the mean (compact packing)
    score += ((bin_residual as f64 - mean_residual) * 0.05).clamp(-3.0, 3.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps that can never hold future items
    // (items >= 1, but realistically small fragments) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 20.0;
    }

    // Reward exact / near-exact fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Perfect fit of residual: item exactly fills the bin.
    if item_size == bin_residual {
        score -= 150.0;
    }

    // Lookahead coupling: if the next item fits in the post residual,
    // this placement chains nicely; otherwise penalize blocking.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 15.0;
        } else if post_residual > 0 {
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage proliferation of bins.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: only attractive when residual would be large dead space
    // or no good fit exists; make the fresh bin slightly less attractive than
    // a reasonable fit but better than a bad one.
    if bin_residual == bin_capacity {
        score = (bin_capacity - item_size) as f64;
        if fitting_bins_count == 0 {
            score -= 200.0; // forced new bin
        } else if (bin_capacity - item_size) < 10 {
            score += 50.0; // would create tiny dead space immediately
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item size -> strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near match: next item fits into post residual
    else if next_item_size > 0 && post_residual >= next_item_size {
        // tighter leftover after also placing next item is better
        score -= 50.0 + (post_residual - next_item_size) as f64 * 0.5;
    } else if next_item_size > 0 {
        // next item won't fit here: penalize small dead space left behind
        let dead = post_residual as f64;
        if dead > 0.0 && dead < 10.0 {
            score += 80.0; // tiny unusable gap
        }
    }

    // Last chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Compare against mean residual: bins with residual below mean are tighter fits, prefer them
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: penalize unless current bin would leave very little space
    if bin_residual == bin_capacity {
        score += 40.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 60.0; // fresh bin can host the next item too
        }
    }

    // Late in stream: consolidate, avoid spreading
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize small unusable gaps harshly.
    // Gaps below the minimum item size (1) are dead; treat small residuals
    // (<= 20) as increasingly costly dead space.
    if post_residual <= 20 {
        score += (21 - post_residual as i32) as f64 * 3.0;
    } else if post_residual > 40 {
        // Large leftover is fine (still usable), slight reward.
        score -= 5.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open bins pressure: penalize using bins when many are open,
    // encouraging consolidation into existing bins rather than spreading.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // If next item would not fit in post residual but fits in a fresh bin,
    // slightly penalize tight fits that strand the next item.
    if next_item_size > post_residual as u32 && post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate: make empty bins moderately attractive only when
    // current item is large relative to mean residual or no good fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Prefer new bin for large items early, or when open bins are fragmented.
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score -= 10.0 + 20.0 * item_frac - 10.0 * progress + fragmentation * 0.2;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Slight preference for bins tighter than average (best-fit flavor).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // hold the smallest item (1..=100 range, but tiny gaps < ~12 are
    // nearly unusable) are heavily penalized.
    if post_residual > 0 && post_residual < 12 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 15.0;
    }

    // Reward tight fits (perfect or near-perfect packing).
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this bin (chained fit).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
        if next_item_size == post_residual {
            score -= 30.0;
        }
    }
    // If next item does NOT fit in post residual but would fit the current
    // residual, penalize (we would strand the next item).
    if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
        score += 20.0;
    }

    // Last-chance bin: only bin that fits the item -> avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: opening a bin is only attractive when the item is
    // large relative to capacity (good fresh utilization) or when open-bin
    // pressure / fragmentation is high.
    if bin_residual == bin_capacity {
        let utilization = item_size as f64 / bin_capacity as f64;
        let mut new_bin_score = 100.0 * (1.0 - utilization);
        // Pressure: many open bins with fragmented residuals -> new bin ok.
        let fragmentation = (mean_residual - post_residual as f64).abs();
        new_bin_score -= open_bins_count as f64 * 2.0;
        new_bin_score -= fragmentation * 0.5;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score += progress * 20.0;
        score = score.max(new_bin_score);
        score = new_bin_score;
    }

    // Mild open-bin pressure: prefer fewer bins when all else is equal.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly useless.
    if post_residual > 0 {
        if post_residual <= 10 {
            // Unusable sliver: heavy penalty.
            score += (11 - post_residual as i32 as f64) * 40.0;
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 30 {
            score += 8.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 150.0;
    }

    // Reward tight fits relative to residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 30.0;

    // Open-bin pressure: prefer filling existing bins when many are open.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when current bins are crowded or fit is bad.
    if bin_residual == bin_capacity {
        score += 120.0 + open_bins_count as f64 * -2.0 + (100.0 - fit_ratio * 100.0);
        // If the next item could use this fresh bin well, slight bonus for opening.
        if next_item_size > 0 && next_item_size <= 50 {
            score -= 20.0;
        }
    }

    // Lookahead: if post_residual exactly matches next item, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 100.0;
    } else if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 10 {
        score += 20.0; // would leave a sliver after next item
    }

    // Mean residual coupling: when mean residual is high, avoid leaving more.
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Late in stream: consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.8;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into a
    // "usable" class (>= 10, i.e. can hold a typical item) are preferred.
    let post_class = post_residual / 10;
    let cap_class = bin_capacity / 10;

    // Reward tight fits: the smaller the post_class relative to capacity class,
    // the better. Use a harmonic (inverse) weighting.
    if post_residual == 0 {
        score -= 60.0; // perfect closure
    } else {
        // Harmonic penalty: leftover classes 1..3 are nearly dead space.
        if post_class <= 3 {
            score += (4 - post_class) as f64 * 12.0;
        } else {
            score -= 8.0;
        }
    }

    // Lookahead coupling: if the next item exactly fits the post residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // next item fits: leftover after that pair
            let pair_post = post_residual - next_item_size;
            score -= 15.0;
            if pair_post / 10 == 0 {
                score += 6.0; // near-dead after pair
            }
        } else {
            // next item will not fit here; residual class value matters more
            score += 5.0;
        }
    } else {
        // last item: prefer closing bins tightly
        score -= 20.0;
    }

    // Last-chance bonus: if this is the ONLY bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item
    // is large relative to capacity or no good fit exists.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin: its full residual
        score = bin_capacity as f64 * 0.5;
        // opening a new bin is attractive for large items or when open bins
        // are fragmented (high mean residual spread)
        if item_size >= bin_capacity * 6 / 10 {
            score -= 25.0;
        }
        if mean_residual < 20.0 {
            score -= 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Stream progression: later in the stream, be more conservative about
    // opening bins and prefer closing existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= progress * 10.0;
    } else {
        score += progress * 15.0;
    }

    // Mild pressure toward bin consolidation.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable gap" zone
    // (1..=12, too small for the smallest items) are heavily penalized,
    // while very tight fits (post_residual == 0) are strongly rewarded.
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual <= 12 {
        score += (13.0 - post_residual as f64) * 8.0; // unusable dead space
    } else if post_residual <= 25 {
        score += 4.0; // mildly awkward gap
    } else {
        // Larger usable leftovers are mildly attractive, scaled by how well
        // the next item would fit into them.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0; // lookahead: leftover is reusable by next item
        }
    }

    // Lookahead penalty: if the next item cannot use this bin's leftover,
    // and it's small enough that the leftover is wasteful, penalize.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 3.0;
    }

    // Last-chance bonus: if this is the ONLY bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into
    // new bins; encourage consolidating into existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate handling: an empty bin gets a baseline that makes it
    // attractive only when existing bins would create dead space or when the
    // mean residual across open bins is already high (fragmented state).
    if bin_residual == bin_capacity {
        score = 40.0 + open_bins_count as f64 * 0.3;
        if post_residual <= 12 || (fitting_bins_count >= 1 && mean_residual < 20.0) {
            // existing bins are roomy/fit well -> prefer them
            score += 15.0;
        }
        if mean_residual > 45.0 {
            score -= 10.0; // open bins are fragmented; fresh bin is fine
        }
    }

    // Mean residual coupling: prefer bins whose residual is below average
    // (tighter bins first), keeping roomy bins for larger future items.
    score -= (mean_residual - bin_residual as f64).clamp(-30.0, 30.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Tight fit relative to residual: fraction of residual consumed.
    let fill_frac = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fill_frac;

    // Pressure from number of open bins: discourage spreading when many bins open.
    score += 2.0 * open_bins_count as f64;

    // Mean residual coupling: prefer bins whose residual is below mean (tighter bins).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Lookahead: if next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 90.0;
        } else if next_item_size <= post_residual {
            score -= 20.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            // next item can't use this gap: penalize medium dead gaps less if large
            score += 10.0;
        }
    }

    // New-bin candidate: baseline preference to reuse open bins, unless
    // existing fits are all poor (large dead space) or bins are numerous.
    if bin_residual == bin_capacity {
        let mut new_bin_score = 55.0 + 1.5 * open_bins_count as f64;
        // If the item is large, opening fresh is safer than wasting space.
        if item_size >= 60 {
            new_bin_score -= 30.0;
        }
        // If no open bin leaves a decent residual, opening a new bin is attractive:
        // emulate by penalizing existing-bin path when item barely fits.
        if bin_residual - item_size <= 0 {
            new_bin_score -= 100.0;
        }
        // Late in stream, prefer consolidation into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score += 20.0 * progress;
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: penalize wasted residual non-linearly (quartic emphasis on dead space)
    let mut score = norm_pr.powf(4.0) * cap;

    // Smooth interaction: residual value decays with stream progress
    score -= norm_pr * cap * (1.0 - progress) * 0.5;

    // Reward tight fits (small post_residual) more strongly later in the stream
    let tight = 1.0 - norm_pr;
    score -= tight.powf(3.0) * (1.0 + progress) * 10.0;

    // Lookahead coupling: bonus if next item fits smoothly into post residual
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            let snug = 1.0 - ((pr - ni) / cap);
            score -= snug * snug * 8.0;
        } else {
            // penalize residuals that can't host the next item, scaled by gap
            let gap = (ni - pr) / cap;
            score += gap * gap * 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress * 0.5);
    }

    // Mild pressure to consolidate when many bins are open
    score += (open_bins_count as f64).ln().max(0.0) * norm_pr * 2.0;

    // Deviation from mean residual: prefer bins below-mean (filling fuller bins)
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 4.0 - dev * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    // Integer-division thresholds on post_residual (harmonic bands)
    let band = post_residual / (bin_capacity / 4); // 0..=4 harmonic class
    score -= (4 - band) as f64 * 3.0; // reward residuals in higher (fuller) bands

    // Modulo arithmetic: residual that is a multiple of common small sizes is "usable"
    let usable = (post_residual % 10 == 0) as f64 * 6.0
               + (post_residual % 20 == 0) as f64 * 4.0
               + (post_residual % 25 == 0) as f64 * 3.0;
    score -= usable;

    // Penalize tiny dead space that nothing (min size 1..100 unknown) can use later:
    // exact-fill bonus dominates everything.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score += 15.0; // likely dead space
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        score -= 20.0 - (gap as f64).min(20.0) * 0.5;
        if gap == 0 { score -= 50.0; }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 5.0; // next item can't use this residual
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: neutral baseline slightly above good fits,
    // but attractive when existing bins are fragmented.
    if bin_residual == bin_capacity {
        score = 40.0 + mean_residual * 0.3 - (open_bins_count as f64) * 0.5;
        if next_item_size > 0 && next_item_size > mean_residual {
            score -= 10.0; // existing bins too fragmented for lookahead
        }
    }

    // Stream progression: late in stream, tighten packing (prefer fullest bins)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= frac * progress * 10.0;
    score += (mean_residual - frac * bin_capacity as f64).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: heavily reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when the next item fits the post-residual exactly or well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 250.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize dead space proportionally.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.8 * dead;
        }
    }

    // Relative to mean residual: prefer bins whose post-residual is below the mean
    // (tighter packing), penalize bins leaving above-average residual.
    score += 1.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: make it attractive only when it enables a good chain
    // (empty residual 100 can host many next items), otherwise keep it mediocre.
    if bin_residual == bin_capacity {
        score = 60.0 + 0.5 * post_residual as f64;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 80.0;
        }
        if fitting_bins_count == 1 {
            score += 150.0; // don't abandon the only fitting open bin
        }
    }

    // Slight late-stream tightening: prefer compact bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.3 * progress * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Strong best-fit pressure: squared residual waste dominates.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Lookahead coupling: if the next item cannot fit in the leftover, the
    // residual is likely dead space; penalize proportionally to how far short it falls.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            let shortfall = (next_item_size - post_residual) as f64;
            score += 4.0 * shortfall;
        } else {
            // Reward bins whose leftover stays useful for the known next item.
            score -= 2.0 * (next_item_size as f64).min(post_residual as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Scarcity pressure: many open bins -> consolidate; few open bins -> new bins are cheap.
    let scarcity = (open_bins_count as f64).ln().max(0.0);
    score += 1.5 * scarcity;

    // Prefer bins tighter than the current mean residual (they are closer to full).
    score += 0.8 * (mean_residual - post_residual as f64);

    // Early in the stream, opening fresh bins is more acceptable; later, avoid
    // spreading out — penalize the new-bin candidate progressively.
    if bin_residual == bin_capacity {
        score += 10.0 + 25.0 * progress - 2.0 * scarcity;
        // If nothing else fits (this call is the only candidate), opening is fine.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Perfect fit celebration.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect fit (zero waste).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual exactly matches the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }
    // Partial lookahead credit: next item still fits in the leftover space.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 + (post_residual - next_item_size) as f64 * 0.1;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Leftover is dead space for the next item: penalize proportionally.
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Last-chance bin: if this is the only bin that can fit the item, use it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Compare post_residual against the mean residual across open bins:
    // leaving a residual close to the mean keeps flexibility; extreme leftovers are bad.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // Penalize very small unusable leftovers (dead space < 10 is likely wasted).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // New-bin candidate: only attractive when the item is large relative to capacity
    // (poor fit elsewhere) or when existing bins are quite full on average.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        let mut new_bin_score = 50.0 - fill_ratio * 80.0;
        // If mean residual across open bins is small, opening a new bin is reasonable.
        new_bin_score -= (100.0 - mean_residual) * 0.3;
        // Late in the stream, slightly discourage spawning extra bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score += progress * 20.0;
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post-residual nonlinearly
    score -= (1.0 - (post_residual as f64) / cap).powi(3) * 30.0;

    // Penalize dead space that no typical small item can reuse
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Last-chance bin: strong incentive to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward if next item fits the post-residual exactly-ish
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let gap = post_residual as f64 - next_item_size as f64;
        score -= (1.0 - gap / cap) * 20.0;
    } else if next_item_size > 0 {
        // next item won't fit here: mild penalty proportional to wasted potential
        score += 5.0 * (next_item_size as f64 / cap);
    }

    // Perfect residual for lookahead: big bonus
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fits are poor
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowdedness = (open_bins_count as f64) / (1.0 + mean_residual / cap * 10.0);
        let poor_fit = if fitting_bins_count >= 1 {
            let best_alt = post_residual as f64; // placeholder: residual if placed here
            0.0
        } else { 0.0 };
        let waste_if_open = (bin_capacity - item_size) as f64;
        // Penalize opening a new bin, but less when item is large or bins are crowded
        score += 15.0 + waste_if_open * 0.3
                 - crowdedness * 2.0
                 - progress * 10.0;
        // Large items deserve fresh bins more
        score -= (item_size as f64 / cap) * 10.0;
    }

    // Time horizon: late in stream, consolidate aggressively into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0 * (1.0 - (post_residual as f64) / cap);

    // Prefer bins with residual close to mean (balance preservation)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space: residuals that are too small to fit typical future items
    if post_residual > 0 {
        let dead_threshold = 20.0;
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 6.0;
        }
    }

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item nearly fits, mild penalty for blocking
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Open bins pressure: discourage spreading across many bins when few fit options exist
    let last_chance = fitting_bins_count == 1;
    if last_chance {
        score -= 12.0;
    } else {
        score += (open_bins_count as f64) * 0.4;
    }

    // Prefer bins tighter than the mean residual (compact packing)
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Mild preference for opening new bins early in stream when fit is poor
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 5.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to be useful
    // (below the minimum plausible item size) are heavily penalized.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // unusable sliver -> strong penalty
        } else if post_residual <= 20 {
            score += 25.0; // marginal gap -> moderate penalty
        } else if post_residual <= 40 {
