        } else {
            score -= 10.0; // large residual remains flexible
        }
    } else {
        score -= 80.0; // perfect fill: reward heavily
    }

    // Reward tight fits relative to the item size (low waste ratio).
    let waste_ratio = post_residual as f64 / (bin_residual as f64 + 1.0);
    score += 30.0 * waste_ratio;

    // Open-bin pressure: discourage scattering items across many bins
    // when few bins are open; encourage consolidation later.
    score += (open_bins_count as f64) * 0.8;

    // Last-chance bonus: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // New-bin candidate: make the empty bin attractive only when the
    // item fits poorly everywhere else (i.e., its natural score is low
    // only for large post_residual). Penalize new bins slightly by
    // default so consolidation wins ties, but keep them viable for
    // items that would strand big items.
    if bin_residual == bin_capacity {
        score += 5.0;
        // If the next item is large and this bin would be nearly empty
