    score += (mean_residual - bin_residual as f64) * 0.3;

    // Slight early-stream preference for opening bins with big items
    // (long streams: progress-aware nudge).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 2.0;

    score
}

