        * (mean_residual - bin_residual as f64);

    // Prefer filling bins that are relatively full already (best-fit flavor).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;

    // base: prefer tight fits (small post_residual), non-linearly
    let x = pr / cap; // normalized post residual
    let mut score = x * x * (3.0 - 2.0 * x) * cap; // smoothstep dead-space penalty

    // polynomial coupling of post_residual with stream progress:
    // early on tolerate slack; late in the stream punish it quadratically
    score += pr * (0.5 + 2.5 * progress * progress);

    // exact fit reward
    if post_residual == 0 {
        score -= 30.0 + 20.0 * progress;
    }

    // lookahead: reward residual that can host the next item (smooth, not piecewise)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = (pr - nxt).max(0.0);
        let match_quality = 1.0 - (fits_next / cap).min(1.0);
        score -= 8.0 * match_quality * (0.5 + 0.5 * progress);
    }

    // last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0 + 10.0 * progress;
    }

    // penalize spreading across many open bins mildly; encourage consolidation
    score += (open_bins_count as f64).ln().max(0.0) * 1.5;

    // new-bin candidate: baseline cost that grows as stream progresses,
    // but is relaxed when residuals across open bins are large (bad fits everywhere)
    if is_new_bin {
        score = cap * (1.0 + 0.5 * progress)
            - (mean_residual / cap) * 40.0 * progress;
        // opening a new bin is fine if this item is large relative to capacity
        score -= (item_size as f64 / cap) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual by capacity fraction bands.
    // Dead space below the smallest item (1) is worthless; but residual classes
    // in (0, 10] are near-dead since items are typically >= 10 in classic streams.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class thresholds via integer division on post_residual
    let class = post_residual / 10; // 0..=10 harmonic class
    match class {
        0 => { score += 40.0; }                    // unusable sliver -> heavy penalty
        1 => { score += 18.0; }                    // fits only tiny items
        2 => { score += 6.0; }                     // moderate dead space
        3 | 4 | 5 => { score -= 8.0; }             // sweet spot: half-filled bins
        6 | 7 => { score -= 4.0; }                 // good residual
        _ => { score -= 2.0; }                     // nearly empty bin used well
    }

    // Exact-fill reward: perfect packing is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Coupling with next item: if next item fits exactly in post_residual,
    // strongly reward this placement (chained exact fits).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item fits: penalize proportionally to wasted gap after both
            let gap2 = post_residual - next_item_size;
            score += gap2 as f64 * 0.5;
        } else {
            // next item won't fit here: mild penalty, this bin becomes closed-end
            score += 5.0;
            // but if residual is a "harmonic" size (multiple of 10), it may fit
            // future common sizes; soften penalty
            if post_residual % 10 == 0 && post_residual >= 10 {
                score -= 4.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets a base cost so we only open
    // new bins when existing fits are bad.
    if bin_residual == bin_capacity {
        score += 30.0;
        // early in stream, opening bins is cheaper (need spread)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    // Prefer bins below mean residual (fill the emptier ones first keeps
    // tight bins available for small items).
    score += (pr - mean_residual) * 0.15;

    // Modulo tie-break: reward residuals divisible by 5 (likely reusable).
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Late stream: consolidate aggressively, penalize leaving many open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable gap" zone
    // (1..=12, too small for the smallest items) are heavily penalized,
    // while very tight fits (post_residual == 0) are strongly rewarded.
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual <= 12 {
        score += (13.0 - post_residual as f64) * 8.0; // unusable dead space
    } else if post_residual <= 25 {
        score += 4.0; // mildly awkward gap
    } else {
        // Larger usable leftovers are mildly attractive, scaled by how well
        // the next item would fit into them.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0; // lookahead: leftover is reusable by next item
        }
    }

    // Lookahead penalty: if the next item cannot use this bin's leftover,
    // and it's small enough that the leftover is wasteful, penalize.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 3.0;
    }

    // Last-chance bonus: if this is the ONLY bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into
    // new bins; encourage consolidating into existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate handling: an empty bin gets a baseline that makes it
    // attractive only when existing bins would create dead space or when the
    // mean residual across open bins is already high (fragmented state).
    if bin_residual == bin_capacity {
        score = 40.0 + open_bins_count as f64 * 0.3;
        if post_residual <= 12 || (fitting_bins_count >= 1 && mean_residual < 20.0) {
            // existing bins are roomy/fit well -> prefer them
            score += 15.0;
        }
        if mean_residual > 45.0 {
            score -= 10.0; // open bins are fragmented; fresh bin is fine
        }
    }

    // Mean residual coupling: prefer bins whose residual is below average
    // (tighter bins first), keeping roomy bins for larger future items.
    score -= (mean_residual - bin_residual as f64).clamp(-30.0, 30.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Lookahead: reward exact match of next item into the post-residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = (post_residual - next_item_size) as f64;
        score -= 200.0 + 100.0 * (1.0 - slack_after_next / cap);
        if slack_after_next == 0.0 {
            score -= 500.0; // chain of two perfect fits
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use this bin's leftover: penalize dead space,
        // more so when the leftover is small/unusable.
        let dead = post_residual as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 60.0 + dead * (0.5 + 0.5 * progress);
        if next_item_size > bin_residual {
            score += 20.0; // next item won't fit this bin at all
        }
    }

    // Relative-to-mean coupling: bins tighter than average are precious.
    let rel = if mean_residual > 0.0 {
        post_residual as f64 / mean_residual
    } else {
        1.0
    };
    score += 30.0 * (rel - 1.0);

    // Last-chance bin before opening a new bin: strong bonus to use it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: mildly penalize opening fresh bins unless
    // current leftovers are large and scattered (many open bins).
    if bin_residual == bin_capacity {
        let avg_open = if open_bins_count > 0 { mean_residual / open_bins_count as f64 } else { 0.0 };
        score = cap * 0.4 + avg_open * 0.5 + (open_bins_count as f64).sqrt() * 5.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 40.0; // item is small relative to next: prefer existing bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where item fills a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize small unusable post-residual (< 10) — dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big bonus.
    if next_item_size > 0 {
        if post_residual as u64 == next_item_size as u64 {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Next item won't fit here; slight penalty for wasting residual.
            score += 5.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // consolidating into existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when open bins are fragmented
        // or early in the stream.
        score += 30.0
            + 20.0 * (1.0 - progress)
            + 5.0 * (open_bins_count as f64).ln().max(0.0);
        // Allow new bin if mean residual is tiny (all bins nearly full).
        score -= 40.0 * (1.0 - mean_residual / bin_capacity as f64).max(0.0);
    } else {
        // Existing bin: slight reward when mean residual is large (consolidate).
        score -= 8.0 * (mean_residual / bin_capacity as f64);
    }

    // Mild preference for bins with residual close to item size (tight packing).
    let slack = (bin_residual as f64 - item_size as f64).abs();
    score += 0.1 * slack;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr;

    // Polynomial in x, modulated by progress: early stream prefers tight fills (low x),
    // late stream penalizes large residuals more aggressively.
    let poly = x * x * (1.0 - x) * 30.0; // peaks mid-range residual (dead space)
    score += poly * (0.5 + progress);

    // Reward near-perfect fits smoothly (small post residual gets bonus)
    let tight = (1.0 - x).powf(3.0) * item_size as f64 * (0.3 + 0.7 * progress);
    score -= tight;

    // Last-chance bin: reward strongly, smoothly scaled by scarcity of fitting bins
    if fitting_bins_count <= 1 {
        score -= 8.0 + 12.0 * (1.0 - progress);
    } else {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead: if next item fits the post residual exactly or well, reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= (1.0 - gap / cap).powf(2.0) * 10.0;
    } else if next_item_size > post_residual as u32 {
        score += 3.0;
    }

    // Deviation from mean residual: prefer bins close to mean (smooth coupling)
    score += ((pr - mean_residual).abs() / cap).powf(2.0) * 15.0;

    // New-bin candidate: penalize opening a new bin unless current residual is large
    if bin_residual == bin_capacity {
        score += 5.0 + 20.0 * (1.0 - progress) + (item_size as f64 / cap) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo small divisors: dead space
    // that is not representable as a useful item size is penalized.
    let pr = post_residual;
    if pr > 0 {
        // Residuals in "awkward" classes (not multiples of 5/10) are harder to fill.
        if pr % 10 == 0 {
            score -= 6.0;
        } else if pr % 5 == 0 {
            score -= 2.0;
        } else {
            score += 3.0;
        }
        // Very small dead space is fine (nearly full bin) - reward tight fits.
        if pr <= 3 {
            score -= 12.0;
        } else if pr <= 8 {
            score -= 5.0;
        }
        // Integer-division threshold: post_residual in [10, 25] is a
        // "half-dead" zone that rarely gets filled - penalize strongly.
        if pr >= 10 && pr <= 25 {
            score += 9.0;
        }
    } else {
        // Perfect fill: huge reward.
        score -= 30.0;
    }

    // Lookahead coupling: if the next item exactly fills the post_residual,
    // this placement chains perfectly - big reward.
    if next_item_size > 0 {
        if next_item_size == pr && pr > 0 {
            score -= 20.0;
        } else if next_item_size <= pr && pr > 0 {
            // Next item fits: mild reward proportional to leftover after chain.
            let chain_left = pr - next_item_size;
            score -= (4.0 * chain_left as f64).min(8.0);
        } else {
            // Next item won't fit in this residual: penalize large residuals
            // slightly more, since they become dead space.
            score += 0.02 * pr as f64;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Fraction-of-capacity harmony: prefer bins whose fill level
    // (item placed) lands on nice capacity fractions.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    if (fill * 4.0).fract() < 1e-9 {
        score -= 3.0; // quarter multiples
    } else if (fill * 10.0).fract() < 1e-9 {
        score -= 1.5; // tenth multiples
    }

    // Early stream: encourage opening fewer bins only mildly; late stream:
    // consolidate aggressively into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * (1.0 - progress) * (open_bins_count as f64).recip().min(1.0);

    // New-bin candidate: make empty bins moderately attractive only when
    // no open bin gives a good fit (post_residual large relative to mean).
    if bin_residual == bin_capacity {
        let bad_fit = post_residual as f64 > mean_residual + 15.0;
        if bad_fit {
            score -= 8.0;
        } else {
            score += 5.0; // prefer existing bins when fit is decent
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item (1)
    // are already fine, but residuals in the "awkward" band (1..=12) that no
    // typical item can use are heavily penalized.
    if post_residual > 0 && post_residual <= 12 {
        score += 25.0 - 2.0 * post_residual as f64;
    }

    // Perfect fit: zero post residual is the ideal outcome.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward filling a bin to near-capacity (post_residual small but usable).
    score -= 0.5 * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    // Last-chance bin: if this is the only fitting bin, prefer using it over
    // opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading items across
    // bins; instead favor consolidating into fewer bins.
    score += 0.35 * open_bins_count as f64;

    // New-bin candidate: make it attractive only when current residuals are
    // fragmented (mean residual low relative to item) or no good fit exists.
    if bin_residual == bin_capacity {
        // Baseline neutral score; penalize opening bins when consolidation
        // pressure is high, reward when open bins are badly fragmented.
        score += 10.0 + 0.35 * open_bins_count as f64;
        if mean_residual < item_size as f64 * 1.2 {
            score -= 20.0; // open bins too full/fragmented -> new bin is good
        }
        // If next item is large, a fresh bin is valuable.
        if next_item_size >= 70 {
            score -= 10.0;
        }
    } else {
        // Prefer bins whose residual can still host the lookahead item.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 12.0;
            } else if post_residual > 0 {
                score += 8.0; // creates a gap that breaks the lookahead
            }
        }
        // Prefer bins tighter than the average residual (denser packing).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Early stream: be slightly more liberal with new bins to build structure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && progress < 0.3 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with non-linear squashing.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 40.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward when post_residual matches next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post_residual as f64 - nxt).abs();
        // Exact match is ideal: chain the next item perfectly.
        score -= 30.0 * (-gap / 12.0).exp();
        // Penalize post_residual that is just barely too small for next item (dead space trap).
        if (post_residual as f64) < nxt && post_residual > 0 {
            score += 15.0 * (1.0 - (post_residual as f64) / nxt);
        }
    } else {
        // Last item: fill as tightly as possible.
        score -= 25.0;
    }

    // Coupling with mean residual: prefer bins whose resulting residual stays
    // near the fleet mean (balanced packing) unless it's a perfect chain.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 3.0 * dev.sqrt();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing fits are poor (post_residual would be large relative to capacity
    // and no good lookahead chain exists).
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 / (bin_capacity as f64);
        let chain_bonus = if next_item_size > 0 && (post_residual as f64 - next_item_size as f64).abs() < 8.0 { 25.0 } else { 0.0 };
        score += 18.0 + 50.0 * (1.0 - poor_fit) - chain_bonus;
        // Early in the stream, opening bins is cheap; later, avoid bin proliferation.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
        // Many open bins: discourage more.
        score += 2.0 * open_bins_count as f64;
    } else {
        // Existing bin: mild reward for consolidation as stream progresses.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimize post_residual relative to capacity.
    let tightness = (bin_residual - post_residual) as f64 / bin_capacity as f64;
    score -= 40.0 * tightness * tightness;

    // Penalize leaving awkward dead space that no typical item (1..100) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain = post_residual as f64 - next_item_size as f64;
        score -= 18.0 - 0.15 * chain;
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item won't fit here anyway; slight penalty for wasting capacity.
        score += 6.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Time horizon: early in stream, consolidate into existing bins; later, be pickier.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 12.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Global residual pressure: if mean residual across bins is high, encourage
    // filling the emptiest-feeling bins (deviation from mean).
    let dev = post_residual as f64 - mean_residual;
    score += 0.35 * dev;

    // Discourage opening new bins when open bins are scarce and item is large.
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (open_bins_count as f64 + 1.0);
        score += 20.0 * scarcity + 8.0 * (1.0 - item_size as f64 / bin_capacity as f64);
        // Allow new bin early when lookahead item is huge (reserve strategy).
        if next_item_size >= 70 && progress < 0.3 {
            score -= 15.0;
        }
    } else {
        // Existing bins get a baseline bonus to avoid needless bin proliferation.
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: penalize wasted residual non-linearly (quartic emphasis on dead space)
    let mut score = norm_pr.powf(4.0) * cap;

    // Smooth interaction: residual value decays with stream progress
    score -= norm_pr * cap * (1.0 - progress) * 0.5;

    // Reward tight fits (small post_residual) more strongly later in the stream
    let tight = 1.0 - norm_pr;
    score -= tight.powf(3.0) * (1.0 + progress) * 10.0;

    // Lookahead coupling: bonus if next item fits smoothly into post residual
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            let snug = 1.0 - ((pr - ni) / cap);
            score -= snug * snug * 8.0;
        } else {
            // penalize residuals that can't host the next item, scaled by gap
            let gap = (ni - pr) / cap;
            score += gap * gap * 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress * 0.5);
    }

    // Mild pressure to consolidate when many bins are open
    score += (open_bins_count as f64).ln().max(0.0) * norm_pr * 2.0;

    // Deviation from mean residual: prefer bins below-mean (filling fuller bins)
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 4.0 - dev * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues mod 10 create "usable" vs "dead" classes
    let r = post_residual % 10;
    // Dead-space penalty grows when post_residual is small but not class-aligned
    if post_residual > 0 {
        if r == 0 {
            score -= 6.0; // perfectly divisible residual, easy to fill later
        } else if r <= 2 {
            score += 10.0; // near-dead sliver
        }
    } else {
        score -= 20.0; // perfect closure
    }

    // Fraction-of-capacity classes: quarter/half/three-quarter residuals are prime targets
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    let diff = (post_residual as i32 - half as i32).abs();
    if diff <= 2 { score -= 4.0; }
    let diffq = (post_residual as i32 - quarter as i32).abs();
    if diffq <= 2 { score -= 3.0; }

    // Lookahead coupling: does post_residual pair with next item via integer division?
    if next_item_size > 0 && post_residual >= next_item_size {
        let fits_next = post_residual - next_item_size;
        score -= (fits_next % 10 == 0) as i32 as f64 * 5.0;
        score += (fits_next > 0 && fits_next < 5) as i32 as f64 * 6.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 3.0; // blocks the lookahead item in this bin
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: keep it neutral-ish early, expensive when many bins already open
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 + 10.0 * (1.0 - progress) - 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size > bin_capacity / 2 {
            score -= 6.0; // big next item may deserve its own fresh bin
        }
    }

    // Slight preference for bins tighter than the mean (compact packing)
    score += ((bin_residual as f64 - mean_residual) * 0.05).clamp(-3.0, 3.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are wasted capacity.
    if post_residual > 0 && post_residual <= 10 {
        score += 45.0; // unusable dead space for items >= 10
    } else if post_residual > 10 && post_residual <= 20 {
        score += 12.0; // marginal gap, only fits the smallest items
    }

    // Reward tight fits (perfect packing).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Prefer bins whose residual is close to the mean (balanced usage),
    // but only mildly, so dead-space penalty dominates.
    score += (bin_residual as f64 - mean_residual).abs() * 0.15;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Lookahead: if the next item fits the post-residual, this is a great chain.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual <= 10 {
        score += 25.0; // gap blocks the known next item -> dead space confirmed
    }

    // New-bin candidate handling: fresh bin is attractive early or when the
    // current item is large (would leave a big, useful residual anyway),
    // but unattractive when a decent existing fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item = item_size as f64 > 60.0;
        let poor_existing = fitting_bins_count == 0
            || (fitting_bins_count == 1 && bin_residual - item_size <= 10);
        if poor_existing || large_item {
            score -= 35.0 + progress * 10.0;
        } else {
            score += 20.0; // keep using open bins when they fit reasonably
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward when the leftover exactly matches the next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0; // perfect chain: this bin becomes exactly usable next step
    } else if next_item_size > 0 && post_residual > next_item_size {
        // leftover can still hold next item, but penalize slack proportionally
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - 0.35 * slack;
        if slack > 40.0 {
            score += 0.5 * (slack - 40.0); // wasteful leftover even if next fits
        }
    } else if next_item_size > 0 {
        // next item cannot use the leftover: dead-space risk
        let gap = (next_item_size - post_residual) as f64;
        score += 0.6 * gap;
    }

    // Compare leftover against mean residual across open bins
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Mild pressure to consolidate into fewer bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.15 * open_bins_count as f64 * progress;

    // Discard tiny unusable leftovers
    if post_residual < 10 {
        score += 12.0;
    }

    // New-bin candidate: keep it neutral-ish, only attractive when current bin fit is bad
    if bin_residual == bin_capacity {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Lookahead: if the next item can also fit in the leftover space, big bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
        // Extra bonus if next item nearly fills the remaining space too.
        let chain_tight = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
        score -= 15.0 * chain_tight;
    }
    // Penalize leftovers that are too small for the next item (dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.35 * (post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 40.0;
        // Cheaper to open a new bin early in the stream (more future flexibility).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // If many bins are open, prefer packing into existing ones.
        score += 2.0 * open_bins_count as f64;
        // If current item is large and fits poorly elsewhere, new bin is attractive:
        // this call has zero post_residual, so the tightness bonus already helps.
        // If the next item is large, a fresh bin is more likely to host it.
        if next_item_size > 50 {
            score -= 10.0;
        }
        // If only one fitting bin exists, opening new is less attractive.
        if fitting_bins_count <= 1 {
            score += 25.0;
        }
    }

    // Mild penalty for placing into bins whose residual deviates from the mean
    // (keeps residual distribution homogeneous, improving future fit chances).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Small penalty for very large leftover fragments (unusable dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // nearly-perfect fill is great, but tiny scraps are fine
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual
    let mut score = pr as f64;
    // Smooth non-linear coupling of post_residual with stream progress
    let coupling = (1.0 + progress * progress) * (x * x) * cap;
    score += 0.5 * coupling;
    // Penalize residuals that cannot fit the lookahead item smoothly
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let gap = (n - pr).max(0.0) / cap;
        score += 12.0 * gap * gap * cap;
        // Reward if next item fits exactly-ish (smooth tanh-like via ratio)
        let fit_ratio = (pr / n).min(2.0);
        score -= 4.0 * fit_ratio / (1.0 + fit_ratio * fit_ratio);
    }
    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - x) * (1.0 - x);
    }
    // Mild pressure toward consolidation when many bins are open
    let open_pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += 6.0 * open_pressure * (x - (mean_residual / cap)).abs() * cap;
    // Slight bias toward tight fits overall
    score -= 3.0 * (1.0 - x) * (1.0 - x);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual by capacity fractions
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Dead-space penalty grows superlinearly for small unusable leftovers
    if post_residual > 0 {
        let frac = post / cap;
        if frac < 0.10 {
            score += 40.0; // tiny dead space: fine, near-perfect fit
        } else if frac < 0.20 {
            score += 12.0;
        } else if frac < 0.35 {
            score -= 5.0;
        } else if frac < 0.50 {
            score -= 10.0;
        } else {
            score -= 15.0; // large leftover is reusable
        }
    }

    // Harmonic pairing: does next_item_size fit exactly (or well) into post_residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        let pair_waste = post_residual - next_item_size;
        // reward tight chains (modulo-style exact fits)
        if pair_waste == 0 {
            score -= 30.0;
        } else if pair_waste <= 10 {
            score -= 15.0;
        } else if pair_waste <= 25 {
            score -= 6.0;
        }
    } else if next_item_size > post_residual {
        // leftover can't host next item: mild penalty proportional to unusability
        score += 3.0 + (next_item_size - post_residual) as f64 * 0.05;
    }

    // Last-chance bin before opening a new one: strong reward to use it
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer bins tighter than the mean (best-fit flavor with harmonic shift)
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // New-bin candidate: keep it unattractive unless open bins are badly fragmented
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 { mean_residual / cap } else { 0.0 };
        score += 25.0 - 20.0 * fragmentation;
        // late in the stream, avoid opening bins for small items
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress * (1.0 - (item_size as f64 / 100.0));
    }

    // Tie-break: mild preference for fewer open bins (consolidation)
    score += 0.2 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never fit the smallest
    // plausible item are pure waste — penalize them heavily.
    if post_residual > 0 {
        let dead = (post_residual < 10) as f64;
        score += dead * 500.0;
        // Partially dead: too small for the upcoming item but still open space.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 40.0 + (next_item_size - post_residual) as f64 * 0.5;
        }
    } else {
        // Perfect fit — reward strongly.
        score -= 200.0;
    }

    // Exact or near-exact packing bonus (post_residual within a small epsilon).
    if post_residual <= 5 {
        score -= 80.0;
    }

    // Open-bin pressure: discourage spreading across many bins; a tight fit
    // into an existing bin is preferred as open_bins_count grows.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: if this is the only bin that can fit the item, using it
    // avoids opening a new bin — reward it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Prefer bins tighter than average (they are the scarce-fit bins).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Lookahead: if the next item fits the post-residual, this placement is
    // especially good (chained packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin offers a good fit
    // (large residual waste elsewhere) or late in the stream when fresh bins
    // can still absorb future items.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let scarcity = (fitting_bins_count == 0) as f64;
        let bad_fits = (mean_residual > 60.0) as f64;
        score = 150.0 - scarcity * 120.0 - bad_fits * 40.0 - progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near-exact matches with the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0; // perfect 2-chain: bin fully consumed by two items
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Prefer bins where the next item leaves minimal dead space.
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot follow into this bin: penalize by the leftover gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 8.0 * (gap / bin_capacity as f64);
        }
    }

    // Favor tight fits overall (small post_residual relative to capacity).
    score += 6.0 * (post_residual as f64 / bin_capacity as f64);

    // Compare against mean residual: placing into a below-average-residual bin
    // is a good fit; placing into an above-average bin wastes large space.
    let dev = mean_residual - post_residual as f64;
    score -= 0.35 * dev;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Late in the stream, closing out bins tightly matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mild penalty for spreading across many open bins.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (non-linear).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 40.0 * tightness * tightness;
    }

    // Penalize large dead space, especially if next item can't use it.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 0.8 * (next_item_size - post_residual) as f64;
        } else {
            // Lookahead bonus: bin can also host the next item.
            score -= 5.0;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fit_quality = if open_bins_count > 0 {
            mean_residual / bin_capacity as f64
        } else {
            0.0
        };
        // Penalize opening new bins mildly; worse late in stream or when
        // existing residuals are large (items should fill them).
        score += 25.0 + 30.0 * progress + 50.0 * avg_fit_quality;
        // But if nothing fits well (large mean residual means fragmented),
        // a fresh bin is less bad: soften penalty.
        if mean_residual < item_size as f64 {
            score -= 15.0;
        }
    } else {
        // Prefer bins whose residual is close to item size (best-fit flavor).
        let gap = (bin_residual - item_size) as f64;
        score += 0.3 * gap;
        // Slight preference for bins below mean residual (balance load).
        score += 0.1 * (bin_residual as f64 - mean_residual).max(0.0);
    }

    // Mild exploration pressure: as stream progresses, consolidate more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0 * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = pr / cap; // normalized post residual in [0,1]
    let p = progress.clamp(0.0, 1.0);

    // Smooth interaction: residual value weighted by progress polynomial
    let mut score = pr as f64;
    score += (t * t) * (1.0 - p) * 30.0;          // early: penalize large residual quadratically
    score -= (t * t * t) * p * 40.0;              // late: reward filling bins deeply
    score += (1.0 - t) * (1.0 - t) * p * 25.0;    // late: penalize near-full residual waste? (small residual left)

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0 * (0.5 + 0.5 * p);
    }

    // New-bin candidate: mildly discouraged unless residual fit is bad
    if bin_residual == bin_capacity {
        let waste = pr / cap;
        score += 15.0 + 50.0 * (1.0 - waste * waste);
    }

    // Lookahead: favor bins whose post residual fits next item
    if next_item_size > 0 && (post_residual as u64) < next_item_size as u64 {
        score += 10.0 * (1.0 - p);
    } else if next_item_size > 0 {
        score -= 8.0;
    }

    // Mean residual coupling
    score += 0.15 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction does it land in?
    // Classes (of 100): [0..10) perfect, [10..25) good, [25..50) mediocre, [50..100) bad.
    let class = post_residual / 25; // 0,1,2,3
    let class_penalty = match class {
        0 => -18.0,
        1 => -6.0,
        2 => 4.0,
        _ => 10.0,
    };
    score += class_penalty;

    // Fine-grained tightness: reward exact/near-exact fills superlinearly.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    } else if post_residual <= 10 {
        score -= 4.0;
    }

    // Modulo-arithmetic harmony: does the residual combine with a typical next item?
    // Reward residuals that are "friendly" multiples near common size bands.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits here: reward proportional to how snugly
            let snug = (post_residual - next_item_size) as f64;
            score -= 8.0 - snug * 0.15;
        } else {
            // next item will NOT fit here: penalize blocking potential
            score += 3.0;
        }
        // Harmonic check: residual + next item == capacity (perfect 2-item closure)
        if post_residual + next_item_size == bin_capacity {
            score -= 6.0;
        }
    }

    // Integer-division threshold on bin_residual: bins with small residual
    // (nearly full) should be drained first to close them out.
    let drain_class = bin_residual / 20; // 0..=5
    score -= (5 - drain_class.min(5)) as f64 * 2.0;

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin is only attractive when no
    // open bin gives a decent fit (post_residual here would be capacity-item).
    if bin_residual == bin_capacity {
        // Base reluctance to open new bins; relax as stream progresses and
        // when many bins are open with high mean residual (fragmentation).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_score = 55.0 - progress * 10.0;
        if open_bins_count == 0 {
            new_bin_score -= 40.0; // must open a bin
        }
        if mean_residual > 60.0 && open_bins_count > 2 {
            new_bin_score -= 8.0; // open bins are fragmented anyway
        }
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            new_bin_score -= 15.0; // perfect pair in a fresh bin
        }
        score = new_bin_score;
    }

    // Mild preference for filling bins with larger residual gap first when
    // many bins compete (best-fit core already via post_residual).
    score -= (fitting_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // A residual that cannot hold the next item is "dead space": penalize hard.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Gap too small for lookahead item: dead weight, scale by how close
            // it is to being useful (a gap of 0 is better than a gap of 9).
            let gap = next_item_size - post_residual;
            score += 25.0 + (gap as f64) * 1.5;
        } else {
            // Gap can host the next item: reward proportionally.
            score -= 10.0;
        }
    }

    // Reward near-perfect fits (tight packing).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    } else if post_residual <= 10 {
        score -= 8.0;
    }

    // --- Open-bin pressure ---
    // Prefer filling existing bins over opening new ones.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin.
        score += 30.0 + 4.0 * (open_bins_count as f64);

        // If other bins fit, the new bin must lose unless fits are terrible.
        if fitting_bins_count > 0 {
            // Penalty grows if many bins compete (a good fit exists elsewhere).
            score += 15.0 * (fitting_bins_count as f64).min(3.0);
        }
        // Late in the stream, opening new bins is even less desirable.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    } else {
        // Reward using an existing bin, more so when bins are plentiful.
        score -= 5.0 + 2.0 * (open_bins_count as f64).min(10.0);
        // Last-chance bin: strongly favor using it before it goes to waste.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // Mild alignment with global state: prefer bins whose residual is below
    // the mean (i.e., fuller bins), keeping the mean residual high.
    score += 0.3 * (mean_residual - post_residual as f64).max(-50.0).min(50.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead fit: post_residual exactly matches next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 {
        let gap = post_residual as f64 - next_item_size as f64;
        if gap >= 0.0 {
            // Next item still fits: mild reward proportional to closeness.
            score -= (20.0 * gap / (bin_capacity as f64)).min(15.0);
        } else {
            // Dead space: next item cannot use remainder; penalize by magnitude.
            score += (-gap) * 0.8;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer bins tighter than the mean residual (good space usage).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Slight penalty for many open bins to encourage consolidation.
    score += open_bins_count as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward tight fits: perfect fit strongly favored.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Penalize residuals that no plausible item can use (dead space).
        // Smallest item is >=1, so any residual >=1 is technically usable,
        // but small residuals (< threshold) are near-perfect fits.
        if post_residual <= 10 {
            score -= 25.0 * (1.0 - post_residual as f64 / 10.0);
        }
        // Dead-space penalty grows with stream progress (less time to recover).
        let dead = (post_residual as f64 / bin_capacity as f64).powf(1.5);
        score += 40.0 * dead * (0.5 + 0.5 * t);
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // this placement is excellent; if next item would be stranded, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size > post_residual {
            // Next item won't fit here anyway; slight penalty for small leftover
            // that could have held the next item if we chose differently.
            if next_item_size <= bin_residual {
                score += 8.0;
            }
        } else {
            // Next item fits in leftover; reward proportionally.
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // existing bins fit poorly (large post_residual) or few bins are open.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 15.0;
        // Early in stream, opening bins is cheap (build diversity of residuals).
        score -= 25.0 * (1.0 - t);
        // If many bins are open and mean residual is small, avoid new bins.
        let mr = if open_bins_count > 0 { mean_residual } else { bin_capacity as f64 };
        score += 10.0 * (1.0 - mr / bin_capacity as f64);
        // If a fitting bin exists but this new-bin call must lose, ensure it
        // scores above a decent existing-bin placement.
        if fitting_bins_count > 0 {
            let best_existing_leftover = post_residual; // existing-bin call sees same item
            if best_existing_leftover <= item_size {
                score += 30.0;
            }
        }
    }

    // Mild preference to fill bins with larger residuals when many bins open
    // (consolidation pressure), scaled by global mean residual.
    if open_bins_count > 3 {
        score += 0.05 * (open_bins_count as f64).ln() * (bin_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: tight fit reward, quadratic in normalized post-residual
    let mut score = norm_pr * norm_pr * cap + pr;

    // Smooth stream-progress coupling: penalize residual more as stream advances
    score += 12.0 * norm_pr * norm_pr * (progress * progress);

    // Lookahead coupling: reward leaving space usable by the next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            let slack = ((pr - n) / cap).min(1.0);
            score -= 8.0 * (1.0 - slack * slack) * (0.5 + 0.5 * progress);
        } else {
            let gap = (n - pr) / cap;
            score += 6.0 * gap * gap;
        }
    }

    // Last-chance bin: strong reward for using it instead of opening a bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - norm_pr * norm_pr);
    }

    // New-bin candidate: mild penalty so we prefer reusing bins unless fit is terrible
    if bin_residual == bin_capacity {
        score += 10.0 + 8.0 * progress;
    }

    // Mean-residual interaction: bins with unusually small residual are precious
    let dev = (mean_residual - pr) / cap;
    score += 4.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo-10 buckets.
    let class = post_residual % 10;
    let harmonic_penalty = match class {
        0 => -12.0, // perfectly divisible residual -> very reusable
        5 => -6.0,  // half-class residual
        2 | 4 | 6 | 8 => -2.0, // even residuals pair well
        1 | 3 | 7 | 9 => 4.0,  // odd residuals are awkward
        _ => 0.0,
    };
    score += harmonic_penalty;

    // Reward tight fits: post_residual small relative to capacity.
    let tightness = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 20.0 * tightness * tightness;

    // Penalize large unusable dead space (below typical small item size).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // dead space trap
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            score -= 5.0 * (post_residual - next_item_size) as f64 / bin_capacity as f64;
        } else {
            score += 3.0; // next item won't fit here; deprioritize mildly
        }
    }

    // Last-chance bin bonus: only one fitting bin -> strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: keep it neutral-to-slightly-worse unless
    // all open bins would leave bad residuals.
    if bin_residual == bin_capacity {
        // Fresh bin score: base cost of opening a bin, softened early in stream
        // and when many bins are open (fragmentation risk).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 40.0 + 20.0 * progress + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin can host the lookahead comfortably
        }
        if mean_residual > 30.0 {
            score -= 8.0; // open bins are roomy anyway; opening more is fine
        }
    }

    // Mean-residual alignment: prefer bins whose residual is near the mean
    // (keeps the pool homogeneous and predictable).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Integer-division threshold on post_residual: multiples of 25 are prime slots.
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold even the
    // minimum item size are pure waste -> heavy quadratic penalty.
    if post_residual < 10 {
        score += 200.0 + (10 - post_residual) as f64 * 20.0;
    } else if post_residual < 20 {
        // Small gaps are only usable by tiny items; penalize softly.
        score += 15.0;
    } else {
        // Reward near-perfect fits: the closer post_residual is to the
        // smallest plausible future item, the better the packing.
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 30.0 * tightness * tightness;
    }

    // If the lookahead item fits exactly into the post residual, strongly
    // reward this bin (perfect 2-item chain).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
        let leftover = post_residual - next_item_size;
        if leftover < 10 {
            score -= 20.0; // chain ends in a perfect fill
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Post residual can't host the next item: mild penalty for breaking chains.
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading by
    // penalizing new-bin behavior and rewarding consolidation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins and progress,
        // but allow it when no good fit exists (post residual large gap avoided).
        score += 10.0 + pressure * 3.0;
        // A fresh bin gives post_residual = capacity - item_size; if that is
        // a clean, usable residual, soften the penalty slightly.
        if post_residual >= 20 {
            score -= 5.0;
        }
    } else {
        // Existing bins get a small consolidation bonus under pressure.
        score -= pressure.min(8.0);
    }

    // Prefer bins whose residual is below the mean (they are closer to being
    // closed out), keeping the open set tidy.
    if bin_residual != bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score -= 0.3 * diff;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // next item fits: reward closeness of match
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item won't fit: penalize small leftover dead space
            let tight = post_residual as f64 / bin_capacity as f64;
            score += 20.0 * (1.0 - tight);
        }
    } else {
        // Last item: reward tightest packing
        score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Relative to mean residual: prefer bins with residual close to item needs
    score += 0.3 * (mean_residual - bin_residual as f64).abs();

    // Last-chance bin bonus: only bin that fits -> strong reward to avoid new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let poor_fit = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
        // baseline slightly above average open-bin score; cheaper to open early-ish
        score += 5.0 + 10.0 * (1.0 - progress);
        if poor_fit > 0.5 {
            score -= 12.0; // item is small relative to empty bin; fine to open
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 8.0; // pair fits nicely in fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (item_size as f64);

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // penalize leaving dead space unusable by the next item
        score += 0.25 * (post_residual as f64).min(next_item_size as f64);
    }

    // Exact fill bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer fuller bins among many open bins (reduce bin count)
    let fill_ratio = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 6.0 * fill_ratio * (open_bins_count as f64).ln().max(1.0);

    // Penalize bins far from mean residual (prefer homogeneity, eases future packing)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Time horizon: late in the stream, be more conservative, prefer tight packing
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 0.10 * post_residual as f64;

    // New-bin candidate: only attractive when open bins would leave large dead space
    if bin_residual == bin_capacity {
        score = 55.0 + 0.15 * item_size as f64
            - 30.0 * progress
            - if fitting_bins_count == 0 { 10.0 } else { 0.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base: tight fit preferred, with non-linear (quadratic) waste penalty
    let mut score = pr + (pr / cap) * pr * 0.5;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, waste matters less; later, tight packing is rewarded more strongly.
    let progress_coupling = 3.0 * progress * (pr / cap) * (1.0 - progress) + 2.0 * progress * progress * (pr / cap);
    score += progress_coupling * pr * 0.1;

    // Reward using the last-chance bin (avoid opening a new bin unnecessarily)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - progress);
    }

    // Lookahead synergy: if next item fits exactly in post_residual, strongly favor this bin
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // partial synergy: next item leaves small residual again
        let nxt = next_item_size as f64;
        let after = pr - nxt;
        score -= 10.0 * (1.0 - after / cap) * (1.0 - progress);
    }

    // Penalize new-bin candidates unless existing bins are quite full on average
    if bin_residual == bin_capacity {
        let mean_fullness = 1.0 - (mean_residual / cap);
        score += 20.0 * (1.0 - mean_fullness) * (1.0 + progress);
        score += open_bins_count as f64 * 0.5;
        // early stream: new bins are cheaper
        score -= 15.0 * (1.0 - progress) * (1.0 - progress);
    } else {
        // mild bonus for placing into bins that are already well filled
        score -= 5.0 * (1.0 - bin_residual as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize leftover space into
    // capacity-fraction buckets. Leftovers in "prime" classes (very small,
    // hard to reuse) are penalized; leftovers matching common item sizes
    // (harmonic classes) are rewarded.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class index via integer division thresholds on post_residual.
    let class = post_residual / 10; // 0..=10 harmonic class
    match class {
        0 => score += 25.0,               // dead space < 10: nearly unusable
        1 => score += 15.0,               // 10..19: only fits tiny items
        2 | 3 => score -= 4.0,            // 20..39: decent reuse band
        4 | 5 => score -= 8.0,            // 40..59: prime reuse band
        6 | 7 => score -= 6.0,            // 60..79
        8 | 9 => score -= 3.0,            // 80..99: loose bin, less urgent
        _ => {}                           // full/empty bin: neutral
    }

    // Lookahead coupling: reward if next item fits into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        // Harmonic match: how well next item divides the leftover.
        let slack = post_residual - next_item_size;
        let match_bonus = 12.0 - (slack as f64) * 0.15;
        score -= match_bonus.max(2.0);
    } else if next_item_size > post_residual {
        // Next item won't fit here; penalize leftovers smaller than next item
        // (wasted potential) proportionally to how close we came.
        if post_residual > 0 && next_item_size > 0 {
            let gap = (next_item_size - post_residual) as f64;
            if gap < 10.0 {
                score += 8.0 - gap * 0.5; // near-miss: painful waste
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer tighter fits overall: reward small post_residual relative to mean.
    score -= (mean_residual - post).max(0.0) * 0.05;

    // Slight pressure to consolidate into existing bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        score -= 3.0 * progress;
    }

    // New-bin candidate (empty bin) should only win when all open bins are poor:
    // give it a mild penalty that shrinks when mean residual across open bins is low.
    if bin_residual == bin_capacity {
        let openness = (mean_residual / cap).clamp(0.0, 1.0);
        score += 5.0 + 15.0 * openness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (10)
    // are pure waste -> heavy penalty proportional to how "dead" the gap is.
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
        // Perfect fill bonus
        if post_residual == 0 {
            score -= 25.0;
        }
    }

    // Tight-fit reward: fraction of bin used by this placement
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 15.0;

    // Penalize leaving a gap that is too small for the lookahead item
    // but large enough to be "tempting" (wasted potential).
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += post_residual as f64 * 0.6;
        }
        // Reward if this placement leaves room exactly for the next item
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: discourage scattering across many bins.
    score += open_bins_count as f64 * 0.8;

    // Mean-residual coupling: bins far below mean residual are poor candidates
    // (their space is more useful for future items); prefer bins near/below mean.
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.15;

    // New-bin candidate: only attractive when it enables a big item placement
    // or existing fits are all poor. Base penalty so open bins win ties.
    if bin_residual == bin_capacity {
        score += 20.0;
        if item_size >= 70 {
            score -= 18.0;
        }
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but avoid tiny unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        // Dead space: too small for any item (min size 1..100, but small slivers waste capacity).
        score += 25.0;
    }

    // Aggressive 2-step lookahead: perfect match where next item exactly fills remaining space.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;

        if post == next {
            // Perfect 2-chain: this bin becomes exactly full after the next item.
            score -= 120.0;
        } else if post > next {
            // Next item fits here too: reward proportionally to how well it packs.
            let match_ratio = next / post;
            score -= 60.0 * match_ratio * match_ratio;
        } else {
            // Next item won't fit in this bin's remainder: mild penalty scaled by gap.
            let gap = next - post;
            score += 0.35 * gap;
        }

        // Compare post_residual against mean residual across open bins:
        // leaving this bin below-average residual concentrates waste favorably.
        if post < mean_residual {
            score -= 0.5 * (mean_residual - post);
        } else {
            score += 0.3 * (post - mean_residual);
        }
    } else {
        // Last item: just minimize final waste (already base score).
        score -= 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the item
    // is large relative to capacity or all open bins fit poorly.
    if bin_residual == bin_capacity {
        // Virtual new bin: its post_residual = capacity - item_size is naturally large.
        // Penalize it unless existing bins are crowded (low mean residual) or many bins
        // already fit the item (no scarcity pressure).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let scarcity = if open_bins_count > 0 {
            (mean_residual / bin_capacity as f64).max(0.0)
        } else {
            1.0
        };
        // Low mean_residual (crowded bins) -> cheaper to open a new bin.
        score += 40.0 + 150.0 * scarcity - 30.0 * progress;
        if fitting_bins_count > 1 {
            // Other options exist; make new bin less attractive.
            score += 50.0;
        }
    }

    // Slight preference for bins whose residual is close to item size pre-placement
    // (best-fit coupling), scaled by how full the bin already is.
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score -= 0.4 * tightness * (0.5 + 0.5 * fill);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core best-fit sharpening: reward tight fits super-linearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 8.0 * fit_ratio * fit_ratio;

    // Strong last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoiding fragmentation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead coupling: penalize if the next item would fit perfectly in the
    // post-residual but we consumed it now; reward if post-residual is dead space
    // that the next item cannot use anyway.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // We just destroyed a perfect slot for the next item -> penalize.
            score += 25.0;
        } else if next_item_size > post_residual {
            // Post-residual becomes unusable dead space for next item anyway;
            // filling it now is fine, slightly reward.
            score -= 6.0;
        } else {
            // Next item still fits here after placement: mild reward for
            // preserving chaining potential.
            score -= 3.0;
        }
    }

    // New-bin candidate handling: an empty bin has high residual; make it
    // attractive only when existing bins would leave large dead space or
    // when existing bins are crowded.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Baseline cost of opening a bin, modulated by how much waste
        // the best existing option would create and global slack.
        let waste_pressure = (mean_residual - item_size as f64).max(0.0);
        score += 30.0 - waste_pressure * 0.5;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // Many open bins -> discourage opening more.
        score += 2.0 * open_bins_count as f64;
    } else {
        // Reward using bins whose residual is far from the mean (rebalance outliers).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score -= 0.3 * dev;
    }

    // Small global-state term: with few open bins, slightly prefer any real bin
    // to keep bin count low early.
    if open_bins_count <= 2 && !is_new_bin {
        score -= 4.0;
    }

    // Dead-space penalty: residual below smallest plausible item (size 1)
    // is fine, but large post-residuals that no typical item uses are waste.
    if post_residual > 0 && post_residual < 10 {
        score -= 10.0; // nearly perfect fill
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_frac = item_size as f64 / cap;

    // Base: waste after placement, with non-linear polynomial shaping
    let mut score = pr;

    // Smooth polynomial coupling of post-residual with stream progress:
    // early stream -> tolerate larger residuals; late stream -> punish waste harder
    let progress_weight = 0.5 + 1.5 * progress * progress;
    score += 0.35 * progress_weight * (pr * pr) / cap;

    // Reward tight fits (small post_residual relative to capacity) with a
    // non-linear saturation term; stronger late in the stream
    let tightness = 1.0 - (pr / cap);
    score -= 6.0 * tightness.powi(3) * (0.4 + 0.6 * progress);

    // Lookahead: if the next item fits exactly into post_residual, reward heavily
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let gap = pr - nx;
            score -= 8.0 * (1.0 - gap / cap) * (0.5 + 0.5 * progress);
        } else {
            // next item cannot use this residual: mildly penalize leaving large dead space
            score += 0.25 * (pr / cap).powi(2) * nx / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0 * (0.6 + 0.4 * progress);
    }

    // Mild penalty for bins with residuals far from the mean (keeps bin pool homogeneous)
    score += 0.15 * ((pr - mean_residual) / cap).powi(2) * 10.0;

    // New-bin candidate handling: neutral-ish baseline so open bins that fit
    // decently are preferred, but a fresh bin is attractive when fits are bad
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).ln().max(0.0);
        score = cap * (0.55 + 0.25 * progress) + 3.0 * openness;
        // if the item fits the empty bin very poorly, discourage it
        score += 10.0 * fit_frac * fit_frac;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    // Integer-division thresholds on post_residual (harmonic bands)
    let band = post_residual / (bin_capacity / 4); // 0..=4 harmonic class
    score -= (4 - band) as f64 * 3.0; // reward residuals in higher (fuller) bands

    // Modulo arithmetic: residual that is a multiple of common small sizes is "usable"
    let usable = (post_residual % 10 == 0) as f64 * 6.0
               + (post_residual % 20 == 0) as f64 * 4.0
               + (post_residual % 25 == 0) as f64 * 3.0;
    score -= usable;

    // Penalize tiny dead space that nothing (min size 1..100 unknown) can use later:
    // exact-fill bonus dominates everything.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score += 15.0; // likely dead space
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        score -= 20.0 - (gap as f64).min(20.0) * 0.5;
        if gap == 0 { score -= 50.0; }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 5.0; // next item can't use this residual
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: neutral baseline slightly above good fits,
    // but attractive when existing bins are fragmented.
    if bin_residual == bin_capacity {
        score = 40.0 + mean_residual * 0.3 - (open_bins_count as f64) * 0.5;
        if next_item_size > 0 && next_item_size > mean_residual {
            score -= 10.0; // existing bins too fragmented for lookahead
        }
    }

    // Stream progression: late in stream, tighten packing (prefer fullest bins)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= frac * progress * 10.0;
    score += (mean_residual - frac * bin_capacity as f64).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead space penalty: gaps too small to ever hold a min-size item (1..10)
        // are pure waste; penalize them quadratically.
        if post_residual < 10 {
            score += (11 - post_residual) as f64 * (11 - post_residual) as f64 * 8.0;
        }
        // Gaps that can only hold very small items are semi-waste.
        else if post_residual < 25 {
            score += (25 - post_residual) as f64 * 2.0;
        }
    }

    // Reward tight fits (small waste relative to item size).
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= 40.0 / (1.0 + tightness * 4.0);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new bins and
    // encourage consolidating into existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; only attractive when
        // existing fits would leave large dead space.
        score += 30.0 + pressure;
    } else {
        score -= pressure.min(25.0);
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward it.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 80.0;
    } else if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
        // Next item would no longer fit here; slight penalty for consuming space it needed.
        score += 5.0;
    }

    // Slight preference for bins below mean residual (keeps residuals balanced).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but with diminishing
    // returns so that tiny residuals are not over-rewarded.
    let pr = post_residual as f64;
    score = pr * 1.0 + (pr * pr) / (bin_capacity as f64 * 4.0);

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // exactly (or nearly) matches the next item's size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs();
        if gap == 0 {
            // Perfect 2-step chain: this bin will be exactly filled next step.
            score -= 60.0;
        } else if (post_residual as i64) >= (next_item_size as i64) {
            // Next item fits here too: reward proportionally to closeness.
            score -= 30.0 * (1.0 - gap as f64 / bin_capacity as f64);
        } else {
            // Next item cannot follow: penalize dead space relative to next size.
            score += 10.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Relative-to-mean coupling: bins with residual below the mean are
    // "almost full" — placing here consolidates waste.
    let dev = mean_residual - pr;
    if dev > 0.0 {
        score -= 8.0 * (dev / bin_capacity as f64).min(1.0);
    } else {
        score += 4.0 * ((-dev) / bin_capacity as f64).min(1.0);
    }

    // Last-chance bin: if this is the only bin that fits, avoid forcing
    // a bad fit unless the fit is genuinely tight.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let tightness = 1.0 - (item_size as f64 / bin_residual as f64);
        score -= 15.0 * tightness; // reward if tight, mild otherwise
    }

    // New-bin candidate handling: an empty bin should only win when no
    // open bin offers a decent fit. Penalize opening new bins, more so
    // early in the stream when consolidation matters most.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 + 20.0 * (1.0 - progress);
        // If next item is huge, an empty bin preserves flexibility.
        if next_item_size > bin_capacity / 2 {
            score -= 18.0;
        }
    }

    // Mild bonus for reducing the number of "fragmented" bins: prefer
    // bins whose residual stays a "usable" size (>= 10) after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // avoid creating unusable slivers
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 45.0 * fill_ratio * fill_ratio;

    // Penalize dead space non-linearly: small post-residuals are fine, large ones are waste.
    let pr = post_residual as f64;
    score += 0.35 * (pr / 10.0).powi(2);

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 18.0; // tiny slivers are still useful-ish
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item could use this bin's post-residual, reward it.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 + 8.0 * (next_item_size as f64 / post_residual.max(1) as f64);
    }
    // If next item cannot fit post-residual, mild penalty proportional to leftover.
    if next_item_size > post_residual && post_residual > 0 {
        score += 4.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
    }

    // Global state coupling: when many bins are open with slack, prefer filling
    // existing bins over opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when existing bins are underutilized.
        score += 55.0 + 30.0 * (open_bins_count as f64 / (open_bins_count as f64 + 3.0));
        score += 20.0 * mean_residual / bin_capacity as f64;
        // Late in the stream, opening new bins is more acceptable.
        score -= 30.0 * progress;
        // If item is large and nothing fits well, new bin is fine (handled by comparisons).
        if fitting_bins_count == 0 {
            score -= 70.0;
        }
    } else {
        // Reward using existing bins, more so when mean residual is high (lots of slack).
        score -= 10.0 * (mean_residual / bin_capacity as f64);
    }

    // Mild preference to consolidate into fewer bins early on.
    score -= 3.0 / (open_bins_count as f64 + 1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Core: quadratic in post_residual, tighter penalties for tiny dead space.
    let mut score = pr * (1.0 + pr_norm) - 2.0 * pr_norm * pr_norm * cap;

    // Smooth stream-progress coupling: later in stream, prefer tighter fits more strongly.
    score += progress * 0.5 * pr * pr_norm;

    // Reward near-full fills (small post residual) smoothly.
    score -= 30.0 * (-pr_norm * 6.0).exp();

    // Lookahead: if next item fits the post residual, reward this bin.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (1.0 - (next_item_size as f64 / pr));
    } else if next_item_size > 0 {
        score += 4.0 * (next_item_size as f64 - pr) / cap;
    }

    // Last-chance bin: strongly favor using it to avoid opening new bins.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Mean residual context: prefer bins deviating below mean (tighter bins) when mean is high.
    score += 0.1 * (mean_residual - br) * (1.0 + progress);

    // Mild penalty scaled by number of open bins to consolidate.
    score += 0.05 * open_bins_count as f64 * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Perfect fit: huge reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: classify leftover into capacity fractions
    let frac = post / cap;
    let class = if post_residual == 0 { 0 }
        else if frac <= 0.1 { 1 }
        else if frac <= 0.25 { 2 }
        else if frac <= 0.5 { 3 }
        else { 4 };
    score += class as f64 * 8.0;

    // Lookahead: if next item exactly fills post_residual, strong reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 500.0;
    }
    // Next item fits into post_residual: mild reward proportional to tightness
    else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0 * (next_item_size as f64 / post);
    }
    // Next item cannot use the leftover: penalize dead space more when leftover is small
    else if next_item_size > 0 {
        score += 15.0 * (1.0 - frac);
    }

    // Last-chance bin: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Penalize opening new bins when many bins already open and mean residual is large
    if bin_residual == bin_capacity {
        score += 25.0 + 5.0 * open_bins_count as f64 + 10.0 * (mean_residual / cap).max(0.0);
        // But if no open bin has a decent leftover, allow opening
        if mean_residual < 20.0 {
            score -= 40.0;
        }
    }

    // Small leftover (<10) is nearly dead space: extra penalty
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: any small leftover gap that no future item
    // (min size 1..10) can plausibly reuse is wasted capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 3.0; // smaller gap => harsher penalty
    }

    // Perfect fit is highly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving room for the lookahead item when possible.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0; // gap too small for the next item
    }

    // Open-bin pressure: discourage spreading across many bins when a tight
    // fit exists; encourage using a fitting bin when it's the last chance.
    score += open_bins_count as f64 * 0.6;
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when open bins would create dead space.
    if bin_residual == bin_capacity {
        score += 5.0 + open_bins_count as f64 * 0.3;
        if post_residual < 10 {
            score += 30.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        }
    }

    // Mean residual coupling: prefer bins far from the mean (tighter than average).
    score -= (mean_residual - post_residual as f64) * 0.2;

    // Late in the stream, consolidate aggressively.
    if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact / near-exact fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    }

    // Aggressive 2-step lookahead: if the NEXT item exactly fills this bin's post-residual,
    // strongly favor this bin (creates a perfect two-item packing).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 800.0;
        } else if diff <= 5.0 {
            score -= 150.0;
        } else if diff <= 10.0 {
            score -= 60.0;
        }
        // Penalize post_residual that is slightly larger than next item (leaves tiny dead space after)
        if post_residual > next_item_size && (post_residual - next_item_size) <= 8 {
            score += 40.0;
        }
    }

    // Tightness reward: bins with small residual relative to mean are precious; use them.
    let tightness = if mean_residual > 0.0 {
        bin_residual as f64 / mean_residual
    } else {
        1.0
    };
    if tightness < 0.6 {
        score -= 80.0;
    } else if tightness > 1.4 {
        score += 30.0;
    }

    // Last-chance bin: if this is the ONLY bin that fits the item, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin would be left
    // with large unusable dead space or the fit is genuinely bad.
    if bin_residual == bin_capacity {
        // Base penalty: prefer reusing open bins.
        score += 200.0;
        // But if placing here would leave a big dead fragment in an existing bin,
        // opening a fresh bin becomes attractive.
        if post_residual as f64 > mean_residual * 1.5 && post_residual > 25 {
            score -= 350.0;
        }
        // Late in stream, new bins are cheaper (fewer future items to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 100.0 * progress;
        // If next item is large, a fresh bin gives flexibility.
        if next_item_size > 60 {
            score -= 120.0;
        }
    }

    // Mild penalty for leaving residuals in the awkward 11..20 range (hard to fill later)
    if post_residual >= 11 && post_residual <= 20 {
        score += 25.0;
    }
    // Residuals in 40..60 are very reusable (fit most item sizes)
    if post_residual >= 40 && post_residual <= 60 {
        score -= 30.0;
    }

    // Scale by number of competing bins: more options -> be pickier about loose fits
    if fitting_bins_count > 3 {
        score += (post_residual as f64) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose residual is nearly consumed.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fill_ratio * fill_ratio;

    // Exact-fit jackpot.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: reward if the next item fits into the post residual (chaining).
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_tightness = next_item_size as f64 / post_residual.max(1) as f64;
        score -= 6.0 * chain_tightness;
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        // Penalize leaving dead space the next item cannot use.
        let waste = post_residual.min(next_item_size.saturating_sub(1)) as f64;
        score += 0.15 * waste;
    }

    // Penalize small unusable residuals that block future items.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 3.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin is fine early, increasingly costly later
        // (encourages consolidation as stream progresses).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 4.0 + 10.0 * progress + 0.5 * open_bins_count as f64;
        // But if no open bin fits at all (fitting_bins_count only counts open bins,
        // new bin excluded), the caller still needs a bin; keep it attractive.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        // If next item is huge relative to capacity, a fresh bin is valuable.
        if next_item_size > 0 && (next_item_size as f64 / bin_capacity as f64) > 0.7 {
            score -= 5.0;
        }
    } else {
        // Mild penalty for bins far from the mean residual (outliers),
        // keeping the bin pool homogeneous.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Prefer using bins that are already small-residual overall.
    score += 0.02 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual
    let mut score = pr as f64;
    // non-linear coupling of post_residual with stream progress
    score += 40.0 * x * x * (1.0 - progress);
    score -= 30.0 * x * x * progress;
    // penalize residuals that cannot fit the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let waste = (x - nx).max(0.0);
        score += 25.0 * waste * (1.0 - waste) * (0.5 + 0.5 * progress);
        // reward if post residual still fits next item smoothly
        let fits_next = if x >= nx { 1.0 } else { 0.0 };
        score -= 10.0 * fits_next * nx * x;
    }
    // last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 35.0 * (0.3 + 0.7 * progress);
    }
    // mild penalty when many open bins (prefer consolidation)
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - x);
    // deviation from mean residual: prefer bins near the mean
    let dev = (x * cap - mean_residual).abs() / cap;
    score += 8.0 * dev * dev;
    // new-bin candidate: make empty-bin score smooth but competitive
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress) + 5.0 * x * x;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 500.0;
    }

    // Harmonic class of post_residual: mod-10 classes
    let pr = post_residual;
    let class = pr % 10;
    // Residuals that are "dead" (too small for typical min item, and not zero) are penalized
    if pr > 0 && pr < 10 {
        score += 40.0;
    }
    // Harmonic dead-zone: residuals in (0,10) unusable; also penalize awkward classes
    match class {
        0 => score -= 25.0,                    // clean multiple of 10
        1 | 9 => score += 12.0,                // awkward
        2 | 8 => score += 6.0,
        5 => score -= 5.0,                     // half-class, flexible
        _ => {}
    }

    // Lookahead coupling: does next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Chain placement possible: reward proportional to how well next item fits
            let slack = (pr - next_item_size) as f64;
            score -= 60.0 - slack * 0.8;
        } else {
            // Next item won't fit here; if post residual is small it's fine, else penalize waste
            let waste = (pr - (pr % next_item_size.max(1))) as f64;
            score += waste * 0.05;
        }
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: prefer opening a new bin only when mean residual of open bins is low
    if bin_residual == bin_capacity {
        // New bin baseline: neutral-ish, adjusted by stream progress and congestion
        score = 45.0
            - mean_residual * 0.6
            + (open_bins_count as f64) * 3.0
            + (step_index as f64 / total_items.max(1) as f64) * 10.0;
        // If item is large relative to capacity, opening fresh bin is more attractive
        score -= item_size as f64 * 0.2;
        // Lookahead: if next item is big, a fresh bin helps
        if next_item_size > 50 {
            score -= 20.0;
        }
    }

    // Mild penalty for leaving very large residuals when many bins are open (fragmentation)
    if pr > 60 && open_bins_count > 3 {
        score += 8.0;
    }

    // Tie-break: prefer bins with residual close to item (tight fit)
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space: residuals that are too small to fit typical future items
    if post_residual > 0 {
        let dead_threshold = 20.0;
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 6.0;
        }
    }

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item nearly fits, mild penalty for blocking
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Open bins pressure: discourage spreading across many bins when few fit options exist
    let last_chance = fitting_bins_count == 1;
    if last_chance {
        score -= 12.0;
    } else {
        score += (open_bins_count as f64) * 0.4;
    }

    // Prefer bins tighter than the mean residual (compact packing)
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Mild preference for opening new bins early in stream when fit is poor
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 5.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect fit (zero waste).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual exactly matches the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }
    // Partial lookahead credit: next item still fits in the leftover space.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 + (post_residual - next_item_size) as f64 * 0.1;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Leftover is dead space for the next item: penalize proportionally.
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Last-chance bin: if this is the only bin that can fit the item, use it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Compare post_residual against the mean residual across open bins:
    // leaving a residual close to the mean keeps flexibility; extreme leftovers are bad.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // Penalize very small unusable leftovers (dead space < 10 is likely wasted).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // New-bin candidate: only attractive when the item is large relative to capacity
    // (poor fit elsewhere) or when existing bins are quite full on average.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        let mut new_bin_score = 50.0 - fill_ratio * 80.0;
        // If mean residual across open bins is small, opening a new bin is reasonable.
        new_bin_score -= (100.0 - mean_residual) * 0.3;
        // Late in the stream, slightly discourage spawning extra bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score += progress * 20.0;
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post-residual nonlinearly
    score -= (1.0 - (post_residual as f64) / cap).powi(3) * 30.0;

    // Penalize dead space that no typical small item can reuse
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Last-chance bin: strong incentive to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward if next item fits the post-residual exactly-ish
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let gap = post_residual as f64 - next_item_size as f64;
        score -= (1.0 - gap / cap) * 20.0;
    } else if next_item_size > 0 {
        // next item won't fit here: mild penalty proportional to wasted potential
        score += 5.0 * (next_item_size as f64 / cap);
    }

    // Perfect residual for lookahead: big bonus
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fits are poor
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowdedness = (open_bins_count as f64) / (1.0 + mean_residual / cap * 10.0);
        let poor_fit = if fitting_bins_count >= 1 {
            let best_alt = post_residual as f64; // placeholder: residual if placed here
            0.0
        } else { 0.0 };
        let waste_if_open = (bin_capacity - item_size) as f64;
        // Penalize opening a new bin, but less when item is large or bins are crowded
        score += 15.0 + waste_if_open * 0.3
                 - crowdedness * 2.0
                 - progress * 10.0;
        // Large items deserve fresh bins more
        score -= (item_size as f64 / cap) * 10.0;
    }

    // Time horizon: late in stream, consolidate aggressively into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0 * (1.0 - (post_residual as f64) / cap);

    // Prefer bins with residual close to mean (balance preservation)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap; // normalized post residual in [0,1]

    // Smooth polynomial coupling: waste penalized more strongly as stream progresses
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) + norm_pr * progress * progress;
    score += 30.0 * poly;

    // Reward tight fits (small post residual) with a smooth saturating term
    let tight = (1.0 - norm_pr).powi(3);
    score -= 12.0 * tight;

    // Lookahead: if next item fits into the post residual, reward this bin
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = (pr - nx).max(0.0);
        let next_util = nx / cap;
        score -= 8.0 * next_util * (1.0 - fits_next / cap);
    } else {
        // last item: strongly prefer minimal residual
        score += 5.0 * norm_pr;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mild penalty when many bins are open and this one is nearly empty (avoid bin sprawl)
    let sprawl = (open_bins_count as f64).ln().max(0.0);
    score += 2.0 * sprawl * norm_pr * (1.0 - progress);

    // Contextual: penalize leaving residual far from mean residual (fragmentation signal)
    let dev = (norm_pr * cap - mean_residual).abs() / cap;
    score += 3.0 * dev * dev;

    // New-bin candidate: neutral baseline scaled by progress (prefer reuse early, allow opening late)
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress) + 10.0 * norm_pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into a
    // "usable" class (>= 10, i.e. can hold a typical item) are preferred.
    let post_class = post_residual / 10;
    let cap_class = bin_capacity / 10;

    // Reward tight fits: the smaller the post_class relative to capacity class,
    // the better. Use a harmonic (inverse) weighting.
    if post_residual == 0 {
        score -= 60.0; // perfect closure
    } else {
        // Harmonic penalty: leftover classes 1..3 are nearly dead space.
        if post_class <= 3 {
            score += (4 - post_class) as f64 * 12.0;
        } else {
            score -= 8.0;
        }
    }

    // Lookahead coupling: if the next item exactly fits the post residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // next item fits: leftover after that pair
            let pair_post = post_residual - next_item_size;
            score -= 15.0;
            if pair_post / 10 == 0 {
                score += 6.0; // near-dead after pair
            }
        } else {
            // next item will not fit here; residual class value matters more
            score += 5.0;
        }
    } else {
        // last item: prefer closing bins tightly
        score -= 20.0;
    }

    // Last-chance bonus: if this is the ONLY bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item
    // is large relative to capacity or no good fit exists.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin: its full residual
        score = bin_capacity as f64 * 0.5;
        // opening a new bin is attractive for large items or when open bins
        // are fragmented (high mean residual spread)
        if item_size >= bin_capacity * 6 / 10 {
            score -= 25.0;
        }
        if mean_residual < 20.0 {
            score -= 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Stream progression: later in the stream, be more conservative about
    // opening bins and prefer closing existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= progress * 10.0;
    } else {
        score += progress * 15.0;
    }

    // Mild pressure toward bin consolidation.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (below the minimum plausible item size)
    // are nearly worthless, so punish them super-linearly.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Reward leaving a gap that the lookahead item could use (lookahead-aware packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + (post_residual as f64 - next_item_size as f64).min(20.0) * 0.5;
    } else if next_item_size > 0 && post_residual > 0 {
        // Gap that the next item cannot use: potential dead space, mild penalty.
        score += 4.0;
    }

    // Open-bin pressure: discourage scattering across many bins; encourage filling
    // existing bins when many are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (3.0 + 5.0 * progress);
    score += pressure;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Mean-residual coupling: when the fleet average residual is low, filling this
    // bin is valuable; when it is high, prefer tighter fits (post_residual term already does).
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.3;

    // Mild penalty for using a nearly full bin when plenty of alternatives fit
    // (keep big residuals for big future items), unless it's a great fit.
    if post_residual > 20 && bin_residual < bin_capacity {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Exact-fit reward: strongly favor bins whose residual is fully consumed.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward leaving a residual that exactly matches the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        score -= 60.0 * (1.0 - gap / cap).max(0.0);
        if post_residual == next_item_size {
            score -= 300.0; // perfect chain: this bin's leftover fits next item exactly
        }
        // Penalize leaving dead space the next item cannot use
        if post < nxt && post_residual > 0 {
            score += 25.0 * (1.0 - post / cap);
        }
    }

    // Tightness reward relative to mean residual: prefer bins tighter than average.
    score -= 0.8 * (mean_residual - post);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Mild pressure to fill existing bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post / cap);

    // Penalize new-bin candidate slightly so it's only chosen when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 40.0 + 30.0 * progress;
        if fitting_bins_count > 0 && post_residual as f64 > mean_residual {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let pn = pr / bin_capacity as f64; // normalized post residual in [0,1]
    let t = progress;

    // Dead-space penalty grows super-linearly as the stream advances,
    // penalizing small leftover fragments late in the stream.
    score += (pn * pn) * (20.0 + 60.0 * t) * (1.0 - pn);

    // Smooth interaction: residual vs mean residual deviation, modulated by progress.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += dev * (10.0 * t * t + 5.0 * t + 2.0);

    // Reward near-perfect fits with a smooth quadratic bonus.
    let fit_quality = 1.0 - pn;
    score -= 15.0 * fit_quality * fit_quality * (1.0 + t);

    // Lookahead: if next item fits into post_residual, reward this placement smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) / bin_capacity as f64;
            score -= 12.0 * (1.0 - slack * slack) * (0.5 + t);
        } else {
            score += 8.0 * (1.0 + t);
        }
    }

    // Last-chance bonus: penalize other bins when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - pn * pn);
    }

    // New-bin candidate: mildly discourage opening a new bin early,
    // more acceptable late when open bins are fragmented.
    if bin_residual == bin_capacity {
        let frag = (mean_residual / bin_capacity as f64).min(1.0);
        score = 5.0 + 30.0 * (1.0 - t) * (1.0 - frag) + 10.0 * frag * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual: reward residuals that are
    // "useful" modular anchors (multiples of common item sizes) ---
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit is always best
    } else {
        // harmonic anchors: residuals divisible by common sizes 10..=25
        let mut anchor_bonus = 0.0;
        for d in [10u32, 20, 25, 50, 100] {
            if pr % d == 0 {
                anchor_bonus += 8.0 * (d as f64).ln();
            }
        }
        score -= anchor_bonus;

        // integer-division class: pr / 10 gives the "harmonic band"
        let band = pr / 10;
        // mid bands (2..5) are flexible; tiny bands (<2) are near-dead space
        match band {
            0 => score += 25.0,                    // dead space < 20
            1 => score += 10.0,                    // narrow but usable
            2 | 3 | 4 | 5 => score -= 6.0,         // sweet spot
            6 | 7 | 8 => score -= 2.0,             // roomy bin
            _ => score += 4.0,                     // nearly empty bin, wasteful use
        }
    }

    // --- Lookahead coupling: does post_residual pair with next item? ---
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0; // sets up a perfect follow-up fit
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            // reward if leftover after next item lands in a good harmonic class
            if slack % 10 == 0 {
                score -= 12.0;
            }
            score -= (slack.min(40) as f64) * 0.15;
        } else {
            // next item won't fit here: penalize proportionally to overshoot
            let miss = next_item_size - post_residual;
            score += (miss as f64) * 0.35;
        }
    }

    // --- Last-chance bin pressure ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0; // strongly favor using the only fitting bin
    } else if fitting_bins_count > 2 {
        score += 3.0; // many options: slight preference for tighter fits elsewhere
    }

    // --- New-bin candidate logic ---
    if bin_residual == bin_capacity {
        // opening a new bin is only attractive when existing bins are crowded
        // or the fit would leave terrible residue
        let crowding = mean_residual / bin_capacity as f64;
        let bad_fit = (post_residual > 0 && post_residual < 10) as f64 * 20.0;
        let pressure = (open_bins_count as f64) * 0.5;
        score += 55.0 - bad_fit - pressure - crowding * 30.0
               - (fitting_bins_count == 0) as i32 as f64 * 100.0;
    }

    // --- Mild progression term: late in the stream, consolidate ---
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += t * 2.0 - (mean_residual - post_residual as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual is "dead" if it's too small to hold even the smallest plausible item.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 120.0; // unusable sliver -> strong penalty
        } else if post_residual < 20 {
            score += 60.0; // likely dead space
        } else if post_residual < 40 {
            score += 15.0; // marginal
        } else {
            // Larger residuals remain usable; reward proportional usefulness
            score -= (post_residual as f64 - 40.0) * 0.4;
        }
    }

    // Tight fit reward: near-perfect packing gets strong bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * 40.0;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // (penalize new-bin candidate and spread).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * 0.6 * (0.5 + 0.5 * progress);

    // New-bin candidate: only attractive when no good fit exists (large item, tight fits bad).
    if bin_residual == bin_capacity {
        score += 55.0 + open_bins_count as f64 * 2.0;
        // If the item leaves a large usable gap and fits well, opening a fresh bin is fine
        if item_size >= bin_capacity * 3 / 4 {
            score -= 45.0;
        }
    }

    // Lookahead: if the next item would fit perfectly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap_after_next = post_residual - next_item_size;
        if gap_after_next < 10 {
            score -= 35.0; // chain perfect fit
        } else if gap_after_next < 20 {
            score -= 15.0;
        }
    }
    // If next item cannot fit into post-residual but post-residual is small, mild extra penalty
    if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 25.0;
    }

    // Mean residual coupling: if this bin is much emptier than average, slightly prefer it
    // to balance out residuals across bins.
    score -= (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual), but penalize unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space too small for any item (min size 1..100 unknown, but tiny gaps rarely reusable)
    }

    // 2-step lookahead: perfect match where next item exactly fills the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // chain fit: this bin will be perfectly closed next step
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // reward placements that leave room for the next item, scaled by slack smallness
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty proportional to overshoot
            score += 5.0 * ((next_item_size - post_residual) as f64 / item_size.max(1) as f64);
        }
    }

    // Compare post_residual against mean residual: leaving residual near mean keeps flexibility.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using the only bin that fits, avoid opening new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        // new bin baseline: its post_residual is large; add fixed cost so open bins win when decent
        score += 40.0;
        // but if no open bin can chain-fit the next item, opening fresh is attractive
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
        // early in stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    // Slight preference to consolidate into fewer bins when many are open.
    score += 1.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: reward tight fits (low post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits but leaves more waste: mild reward proportional to how well it packs.
            let frac = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * frac;
        } else if next_item_size > bin_residual {
            // Next item cannot fit here anyway; slightly favor bins that keep flexibility.
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: penalize opening a new bin, unless residuals across open bins
    // are all large (poor fits everywhere) or late in the stream.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_penalty = 40.0;
        // If mean residual is large, open bins are roomy; opening a new bin is less costly.
        new_bin_penalty -= (mean_residual / bin_capacity as f64) * 25.0;
        // Late in the stream, avoid stranding residual capacity: prefer open bins more.
        new_bin_penalty += progress * 30.0;
        // Many open bins: spreading items thin is bad.
        new_bin_penalty += (open_bins_count as f64).ln().max(0.0) * 4.0;
        // If next item is large, a fresh bin may serve it better.
        if next_item_size > 50 {
            new_bin_penalty -= 10.0;
        }
        score += new_bin_penalty.max(0.0);
    }

    // Penalize leaving tiny unusable residuals (dead space < 10 unless exact).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Mild preference for bins already below mean residual (consolidating space).
    if bin_residual != bin_capacity {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.05 * diff;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = pr / cap; // normalized post residual

    // Base: tight fits preferred, with quadratic sharpening of small residuals
    let mut score = x * (1.0 + 2.0 * x * x);

    // Smooth non-linear coupling with stream progress: late in the stream,
    // increasingly reward tight fits (multiply down good fits, push up loose ones)
    let progress_coupling = 1.0 + 0.8 * t * (1.0 - x);
    score *= progress_coupling;

    // Cubic interaction: penalize mid-range residuals more strongly as stream advances
    score += 3.0 * t * x * (1.0 - x) * x;

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 5.0 * (1.0 - x);
    }

    // Dead-space penalty relative to mean residual of open bins
    score += 0.05 * (x - mean_residual / cap).abs();

    // Lookahead: if next item can use the post residual, reward; else penalize
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let usable = (nx - x).max(0.0);
        score += 2.0 * usable * (1.0 + t);
    }

    // Mild penalty for spreading across many open bins
    score += 0.01 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: make it attractive only when no open bin fits well
    if bin_residual == bin_capacity {
        score = 1.5 + 2.0 * t - (fitting_bins_count as f64).max(1.0).recip();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    let pr = post_residual;
    let m4 = (pr % 25) as f64;           // quarter-capacity harmonic class
    let m8 = (pr % 12) as f64;           // finer harmonic ripple
    let half = (bin_capacity / 2) as f64;

    // Reward residuals that align with common item sizes (multiples of 10 / 25).
    if pr % 10 == 0 { score -= 6.0; }
    if pr % 25 == 0 { score -= 4.0; }
    // Penalize awkward tiny residuals that waste capacity.
    if pr > 0 && pr < 10 { score += 8.0; }

    // Non-linear ripple from harmonic classes.
    score -= 2.0 * ((m4 / 25.0) * std::f64::consts::PI).cos();
    score += 0.5 * (m8 / 12.0);

    // Lookahead coupling: does next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Perfect harmonic match: next item exactly fills the leftover class.
            if next_item_size == pr { score -= 10.0; }
            else if pr - next_item_size <= 10 { score -= 3.0; }
            score -= 1.5;
        } else {
            // Next item cannot use this residual class: penalize proportionally.
            let gap = (next_item_size - pr) as f64;
            score += 0.05 * gap;
        }
    } else {
        // Last item: prefer tightest fill.
        score -= 5.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 7.0;
    }

    // Prefer filling nearly-full bins (best-fit flavor with capacity fraction).
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 3.0 * fill * fill;

    // Slight penalty when many bins are open and this one is still empty-ish.
    if open_bins_count > 4 && fill < 0.25 {
        score += 1.0;
    }

    // Early stream: keep bins balanced via mean residual coupling.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.03 * progress * (post_residual as f64 - mean_residual);

    // New-bin candidate: neutral-ish baseline, only attractive when residual classes
    // of open bins are hopeless (handled implicitly by their penalties).
    if bin_residual == bin_capacity {
        score += 4.0 - 2.0 * (fitting_bins_count as f64).min(3.0);
        if next_item_size > 0 && next_item_size >= half as u32 { score -= 2.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for any plausible
    // future item (below the smallest useful size) are heavily penalized.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score += 1000.0; // exact fit: perfect, but keep base low
    }

    // Dead-zone penalty: residuals in [1, 12] are nearly unusable.
    let pr = post_residual as f64;
    if pr > 0.0 && pr <= 12.0 {
        score += 25.0 * (1.0 - pr / 12.0);
    }
    // Moderate dead zone [13, 25] mildly penalized.
    else if pr > 12.0 && pr <= 25.0 {
        score += 8.0 * (1.0 - (pr - 12.0) / 13.0);
    }

    // Reward tight fits: fraction of bin used by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio * fill_ratio;

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (penalize new-bin candidate); with few bins, opening is cheap.
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * (open_bins_count as f64).sqrt();
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0; // next item won't fit here; gap likely wasted
    }

    // Mean-residual coupling: bins far below mean residual are worth filling.
    score -= 0.3 * ((mean_residual - bin_residual as f64).abs());

    // Slight preference to use bins early in the stream.
    score += 5.0 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // closely matches the next item size (perfect chaining).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 12.0 * (1.0 - gap / (bin_capacity as f64));
        // Exact match for next item: strong bonus.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // If next item cannot fit anywhere after this placement, penalize.
        if post_residual < next_item_size {
            score += 8.0;
        }
    } else {
        // Last item: prefer minimal waste directly.
        score -= 10.0;
    }

    // Relative-to-mean coupling: bins tighter than the mean are precious,
    // prefer filling them; loose bins get a mild penalty.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin (only fitting bin): strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize creating tiny dead space (<10) that is hard to reuse,
    // but only when it doesn't match the next item.
    if post_residual > 0 && post_residual < 10 && next_item_size != post_residual {
        score += 15.0;
    }

    // Perfect closure bonus.
    if post_residual == 0 {
        score -= 18.0;
    }

    // New-bin candidate: make it unattractive unless very few bins fit
    // the item and all fits would be terrible.
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count == 0 {
            score -= 60.0;
        } else if fitting_bins_count == 1 {
            // allow new bin only if the single fitting bin would leave huge waste
            let waste = post_residual as f64;
            if waste > 0.6 * bin_capacity as f64 {
                score -= 45.0;
            }
        }
    }

    // Late in the stream: consolidate aggressively to avoid opening bins
    // that will be nearly empty at the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Penalize small unusable leftovers (< 10, assuming min item 10; mild below 20).
    if post_residual < 10 {
        score -= 8.0;
    } else if post_residual < 20 {
        score -= 3.0;
    }

    // Lookahead coupling: if the next item could fit in the post-residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0;
            // Perfect pairing: next item exactly consumes leftover.
            if next_item_size == post_residual {
                score -= 10.0;
            }
        } else if next_item_size <= post_residual + 10 {
            score -= 2.0;
        } else {
            // Large dead space that the next item cannot use: penalize proportionally.
            score += 0.05 * (post_residual as f64 - next_item_size as f64).abs();
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoids fragmentation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the current fit is terrible and global residuals are low.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin.
        score += 20.0;
        // More attractive early in the stream (long horizon amortizes bin cost).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // Attractive when existing bins are nearly full on average.
        score -= 0.15 * mean_residual;
        // Less attractive when many bins are already open (consolidate instead).
        score += 1.5 * open_bins_count as f64;
        // If the item fits snugly in a fresh bin (large item), opening is fine.
        if item_size >= 70 {
            score -= 12.0;
        }
        // If the next item is small, a fresh bin wastes potential.
        if next_item_size > 0 && next_item_size <= 20 {
            score += 5.0;
        }
    } else {
        // Mild preference for reusing bins with more residual (keep tight bins
        // available for large future items) — counterbalanced by fit reward.
        score += 0.03 * bin_residual as f64;
        // When many bins can fit the item, prefer the one with the least waste,
        // already handled; add slight tie-break by residual ordering.
        if fitting_bins_count > 2 {
            score -= 1.0;
        }
    }

    // Late-stream consolidation: as the stream ends, prefer filling existing bins
    // almost regardless of fit quality to avoid stranded residual.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.85 && !is_new_bin {
        score -= 10.0 * (progress - 0.85) * 10.0;
    }

    // Global state coupling: if mean residual is high, discourage spreading into
    // loose bins; encourage filling the emptiest ones (higher residual here).
    if mean_residual > 30.0 && !is_new_bin {
        score += 0.05 * (mean_residual - 30.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Quadratic penalty on wasted residual, scaled by stream progress
    let norm_pr = pr / cap;
    score += norm_pr * norm_pr * cap * (0.5 + 0.5 * progress);

    // Reward tight fits (small post_residual relative to item)
    let tight = 1.0 - pr / (bin_residual as f64).max(1.0);
    score -= tight * tight * it * 0.3;

    // Non-linear coupling: prefer using bins whose residual is close to item size
    let fit_ratio = it / (bin_residual as f64).max(1.0);
    score -= (fit_ratio * (2.0 - fit_ratio)).max(0.0) * 8.0;

    // Lookahead: penalize leaving residual that barely misses next item
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let near = (1.0 - gap / cap).max(0.0);
        if pr >= next_item_size as f64 {
            score -= near * near * 10.0 * (1.0 - progress);
        } else {
            score += near * near * 6.0;
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across many bins when residuals are large
    let mr = mean_residual / cap;
    score += open_bins_count as f64 * mr * mr * 2.0;

    // New-bin candidate: only attractive late or when item is huge relative to mean residual
    if bin_residual == bin_capacity {
        let openness = (1.0 - progress).max(0.0);
        let poor_fit = (it / (mean_residual + 1.0)).max(0.0);
        score = cap * (1.0 - 0.6 * openness) - 12.0 * poor_fit.min(2.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by capacity fraction bands.
    let frac = post_residual as f64 / bin_capacity as f64;
    // Penalize dead-space classes: residuals in awkward bands are less reusable.
    if post_residual == 0 {
        score -= 40.0; // perfect fit is ideal
    } else {
        // Harmonic class via integer division thresholds on post_residual
        let class = post_residual / 10; // classes 0..=9 (residual 0..100)
        match class {
            0 => score -= 20.0,            // residual < 10: nearly dead, but bin almost full
            1 => score -= 12.0,            // 10..19: still usable for smallest items
            2 => score += 6.0,             // 20..29: awkward mid band
            3 => score += 10.0,            // 30..39: awkward
            4 => score -= 4.0,             // 40..49: decent
            5 => score += 2.0,             // 50..59: half bin, fine
            6 => score += 4.0,
            7 => score += 6.0,
            8 => score += 8.0,
            _ => score += 10.0,            // large residual: wasteful placement
        }
        // Modulo arithmetic coupling: residual divisible by common item sizes is more reusable.
        if post_residual % 10 == 0 { score -= 3.0; }
        if post_residual % 20 == 0 { score -= 3.0; }
    }

    // Lookahead: reward bins whose post_residual can host the next item (chained fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Next item cannot fit here; mildly penalize since bin becomes dead for lookahead.
        score += 4.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Progress-scaled pressure: later in the stream, prefer filling existing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (1.0 - frac);

    // Mean residual coupling: when open bins are generally full, tighten preference for tight fits.
    score += 0.05 * (mean_residual - post_residual as f64);

    // New-bin candidate: penalize opening a new bin unless current fit is truly poor.
    if bin_residual == bin_capacity {
        score += 18.0;
        if fitting_bins_count > 0 && next_item_size > 0 {
            score += 6.0;
        }
        // Early stream: opening bins is cheaper; late stream: avoid spreading.
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // --- Strict dead-space avoidance ---
    // Small unusable gaps (<10) are heavily penalized; smaller gap => bigger penalty.
    if !is_new_bin {
        if post_residual > 0 && post_residual < 10 {
            score += (10 - post_residual) as f64 * 14.0;
        }
        // Perfect fit: strong reward.
        if post_residual == 0 {
            score -= 35.0;
        }
        // Tightness reward: favor bins where the item fills most of the residual.
        let tightness = item_size as f64 / bin_residual.max(1) as f64;
        score -= 10.0 * tightness;

        // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 18.0;
        }
    }

    // --- Open-bin pressure ---
    // With many open bins, prefer consolidating into existing bins.
    score += open_bins_count as f64 * 0.5;
    // Progression: early in stream, be slightly more willing to spread out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 3.0;

    // --- Lookahead coupling ---
    if next_item_size > 0 && !is_new_bin {
        if next_item_size <= post_residual {
            score -= 12.0; // next item can reuse the gap: great
        } else if post_residual > 0 {
            score += 6.0; // gap likely becomes dead space
        }
    }

    // --- New-bin candidate scoring ---
    if is_new_bin {
        // Neutral base: only chosen when all existing fits are poor.
        score = bin_capacity as f64 * 0.55 + open_bins_count as f64 * 0.6;
        // If no open bin fits at all, opening a new bin is mandatory/cheap.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        // Early stream: new bins are cheaper to open.
        score -= (1.0 - progress) * 5.0;
        // Lookahead: new bin leaves room for the next item too.
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Two-step lookahead: reward exact match of post_residual with next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 / (1.0 + diff);
        // Perfect 2-step match: strong bonus.
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // If item won't fit after this placement, mild penalty for stranding next item.
        if post_residual < next_item_size && post_residual > 0 {
            score += 10.0;
        }
    } else {
        // Last item: just minimize waste.
        score += 5.0;
    }

    // Penalize dead space that no plausible item (min size 1..10) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer bins tighter than the mean residual (compact packing).
    score -= 0.15 * (mean_residual - bin_residual as f64);

    // New-bin candidate: penalize mildly so we only open when open bins are poor fits.
    if bin_residual == bin_capacity {
        score += 45.0;
        // But if this bin is the only fitting option context (no open bins), neutralize.
        if open_bins_count == 0 {
            score -= 45.0;
        }
        // Late in stream, opening fresh bins is cheaper than fragmentation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.7 && post_residual as f64 > 0.9 * next_item_size as f64 {
            score -= 20.0;
        }
    }

    // Slight preference for tighter bins overall.
    score += 0.05 * (bin_capacity as f64 - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Perfect fill: extremely strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead coupling (k=2): if the next item exactly fills what remains,
    // this placement sets up a chain of perfect fills.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0 + 200.0 * progress;
        } else if post_residual >= next_item_size {
            // leftover still usable by next item: mild reward
            score -= 20.0;
        } else {
            // dead space the next item cannot use: penalize proportionally
            score += 1.5 * (post_residual as f64) * (1.0 - progress);
        }
    }

    // Last-chance bin: if this is the only bin that fits the item, strongly
    // prefer using it over opening a new bin.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 250.0;
    }

    // New-bin candidate: default penalty so we only open a new bin when open
    // bins would leave large unusable residuals. Penalty shrinks for large
    // items late in the stream (fewer chances left to fill leftovers).
    if is_new_bin {
        score += 60.0 - 30.0 * progress;
        // Opening a bin is more attractive when open bins are already crowded
        // (low mean residual means poor future flexibility).
        score += 0.3 * mean_residual;
    } else {
        // Prefer tighter fits among open bins: penalize deviation from mean.
        score += 0.1 * (post_residual as f64 - mean_residual).abs();
    }

    // Small tie-break: prefer bins with less residual before placement
    // (best-fit flavor) scaled by how many alternatives exist.
    if fitting_bins_count > 1 {
        score += 0.05 * (fitting_bins_count as f64) * (bin_residual as f64 - item_size as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: non-linear polynomial coupling of post_residual with stream progress.
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) + norm_pr * (1.0 - progress);
    let mut score = pr * (0.5 + poly);

    // Penalize large wasted residuals late in the stream (dead space grows costly).
    score += (norm_pr * norm_pr * norm_pr) * cap * (0.2 + 0.8 * progress);

    // Reward tight fits: small post_residual relative to item size.
    let tightness = item_size as f64 / (item_size as f64 + pr);
    score -= tightness * tightness * (cap * 0.3) * (0.5 + progress);

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let slack = (pr - next_item_size as f64) / cap;
        score -= 15.0 * (1.0 - slack) * (1.0 + progress);
    } else if next_item_size > 0 {
        // Next item cannot use the leftover; penalize proportionally to wasted space.
        score += 5.0 * norm_pr * (0.5 + progress);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // Mean-residual coupling: prefer bins that bring residual toward the mean (balance).
    score += 0.3 * (pr - mean_residual).abs() * (0.5 + progress);

    // Many open bins: mild pressure to consolidate into existing bins.
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    // New-bin candidate: keep it competitive only when residuals are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        score = 10.0 + cap * (0.4 - 0.35 * fragmentation) * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize dead space into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    // Integer-division thresholds on post_residual: buckets of size 10.
    let bucket = post_residual / 10;

    // Reward small post_residual strongly (non-linearly).
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 4.0);

    // Harmonic bonus: post_residual that is a "nice" residue (multiple of 5 or 10)
    // is more likely to be filled by future items.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Coupling with lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        if next_item_size == post_residual {
            score -= 15.0;
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item won't fit here; penalize leaving a large unusable residue.
        score += 6.0 + frac * 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer filling bins that are already relatively full (tight packing).
    let used_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= used_frac * 10.0;

    // Penalize opening new bins when many open bins exist and this one fits well.
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty grows with number of open bins.
        score += 15.0 + open_bins_count as f64 * 2.0;
        // But if the item is huge and mean residual across bins is small,
        // opening a fresh bin may be better.
        if item_size as f64 > mean_residual + 5.0 && mean_residual < item_size as f64 {
            score -= 25.0;
        }
        // Late in the stream, prefer reusing existing bins.
        score += (step_index as f64 / total_items.max(1) as f64) * 10.0;
    } else if (post_residual as i64 - bin_residual as i64 + item_size as i64) >= 0 {
        // Reusing an existing bin: mild reward scaled by mean residual alignment.
        if (post_residual as f64 - mean_residual).abs() < 10.0 {
            score -= 3.0;
        }
    }

    // Bucket-based tie-breaker: prefer residues in mid-range buckets (20..=40)
    // which historically pair well with typical item sizes.
    if bucket >= 2 && bucket <= 4 {
        score -= 2.0;
    } else if post_residual > 0 && post_residual < 10 {
        // Nearly-full bin: excellent, reward heavily.
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    let dead_zone: f64 = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 6.0;
    }
    // Perfect fit reward
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward tight fits (small waste relative to item size)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 10.0;

    // Open-bin pressure: discourage spreading across many bins unless fit is good
    score += open_bins_count as f64 * 0.4;

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Lookahead: if next item fits exactly into the post residual, reward heavily
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // Penalize if post residual is too small for the (minimum) next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 8.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current bins are heavily fragmented or this bin would leave big waste anyway.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so new bins are only chosen when genuinely better
        score += 15.0;
        // If the best existing placement would leave a large dead gap, new bin gains appeal
        let gap_penalty = if post_residual == bin_capacity { 0.0 } else { 0.0 };
        let _ = gap_penalty;
        // Fragmentation signal: high mean residual with many bins -> keep packing open bins
        if open_bins_count > 0 && mean_residual > item_size as f64 + 20.0 {
            score += 20.0;
        }
        // Late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    } else {
        // Existing bin: mild bonus for mean residual alignment (keeps residuals balanced)
        score += ((mean_residual - post_residual as f64).abs()) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (tight packing).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Aggressive 2-step lookahead: if the next item fits exactly in the
    // post-residual, this is a perfect chain — reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post == nxt {
            score -= 20.0;
        } else if post >= nxt {
            // Next item fits; penalize proportionally to wasted slack after both.
            let two_step_waste = post - nxt;
            score -= 6.0 * (1.0 - two_step_waste / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize dead space that's too small
            // to be useful for the upcoming item.
            score += 4.0 * (1.0 - post / nxt.max(1.0));
        }
    }

    // Compare post_residual against the mean residual across open bins:
    // leaving less than average slack keeps bins homogeneous and flexible.
    if post_residual as f64 > mean_residual {
        score += 1.5 * (post_residual as f64 - mean_residual) / bin_capacity as f64;
    } else {
        score -= 1.5 * (mean_residual - post_residual as f64) / bin_capacity as f64;
    }

    // Last-chance bin: if this is the only bin that fits the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Penalize the brand-new empty bin candidate mildly, so it's chosen only
    // when no open bin offers a decent fit (or a genuinely better 2-step chain).
    if bin_residual == bin_capacity {
        score += 6.0;
        // Late in the stream, opening new bins wastes capacity — penalize more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 4.0 * progress;
        // But if many bins are open with fragmented slack, a fresh bin is fine.
        if open_bins_count > 8 {
            score -= 2.0;
        }
    }

    // Small bonus for filling bins that are already mostly full (consolidation).
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 3.0 * fill_ratio * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits (best-fit core).
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * tightness * 30.0;

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward if the next item fits the post-residual exactly or well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_fit = (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= (1.0 - next_fit) * 12.0;
        } else {
            // Post-residual too small for next item: penalize wasted sliver.
            if post_residual < 10 {
                score += 8.0;
            }
        }
    } else {
        // Last item: fill as much as possible.
        score -= 40.0;
    }

    // Prefer bins with residuals below the mean (compact bins first).
    let diff = bin_residual as f64 - mean_residual;
    score += diff * 0.4;

    // Time horizon: early in the stream, be conservative with bin openings;
    // late in the stream, pack greedily.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more early on, less late.
        score += 15.0 * (1.0 - progress);
        // If no open bin fits, new bin is the only option (score stays low relative).
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Late in stream, reward using existing bins aggressively.
        score -= 10.0 * progress;
    }

    // Mild penalty when many bins are open: encourage consolidation.
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear reward for tight fits (post_residual small)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness.powf(3.0);

    // Coupling of tightness with stream progress: tighter fits matter more later
    score -= 12.0 * tightness.powf(2.0) * (progress * (1.0 - progress) * 4.0 + progress);

    // Lookahead: reward residuals that can fit the next item, scaled non-linearly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_next = if post_residual as f64 >= nx { 1.0 } else { 0.0 };
        let gap = ((post_residual as f64 - nx) / bin_capacity as f64).max(0.0);
        score -= 9.0 * fit_next * (1.0 - gap).powf(2.0);
        // Penalize residuals that are just barely too small for next item (dead space risk)
        let miss = ((nx - post_residual as f64) / bin_capacity as f64).max(0.0);
        score += 6.0 * (1.0 - fit_next) * (1.0 - miss).powf(2.0) * (0.5 + progress);
    }

    // Last-chance bin: strong reward to use the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across many open bins relative to mean residual
    score += 0.15 * (open_bins_count as f64).ln().max(0.0);

    // Slight pull toward bins with residuals near the mean (keeps bin states homogeneous)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate: penalize opening a new bin, more so early and when alternatives exist
    if bin_residual == bin_capacity {
        let alt = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 1.0 };
        score += 14.0 + 10.0 * (1.0 - progress) + 3.0 * alt.ln();
        // Allow new bin late in stream when mean residual is high (fragmented state)
        score -= 8.0 * progress * (mean_residual / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: bucket by capacity/10.
    let class = (post_residual / (bin_capacity / 10)) as f64;
    score -= 7.0 * class; // reward bins landing in a low (finer) residual class

    // Dead-space penalty: residuals that are odd/small modulo classes are hard to fill.
    let small = post_residual < bin_capacity / 10;
    if small {
        score += 25.0;
    }
    // Penalize residual classes that are prime-ish (3 or 7 units of 10) — awkward gaps.
    if class == 3.0 || class == 7.0 {
        score += 10.0;
    }

    // Lookahead coupling: if the next item fits the post residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 30.0;
        // extra reward if next item harmonically divides the residual well
        let next_class = (post_residual - next_item_size) / (bin_capacity / 10);
        score -= 3.0 * next_class as f64;
    } else if next_item_size > 0 {
        // next item cannot use leftover: mild penalty scaled by gap
        score += 0.3 * (next_item_size as f64 - post_residual as f64).max(0.0);
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Prefer tighter bins generally (best-fit flavor).
    score -= 0.2 * (bin_capacity as f64 - bin_residual as f64);

    // New-bin candidate handling: opening a bin is only attractive late in stream
    // or when the current item leaves a huge awkward residual in every open bin.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let awkward = item_size as f64 > mean_residual + 20.0;
        score = 60.0 - 15.0 * progress;
        if awkward && fitting_bins_count > 0 {
            score += 20.0; // keep using open bins if they aren't too bad
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 5.0; // new bin can host the pair compactly
        }
    }

    // Stream-phase modulation: early on, be greedy about filling bins densely.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even the
    // smallest plausible future item are pure waste -> heavy penalty.
    let min_future = if next_item_size > 0 { next_item_size.min(10) } else { 10 };
    if post_residual > 0 && post_residual < min_future {
        score += 25.0;
    }

    // Perfect fit: ideal placement.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward when the leftover can still accommodate the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 {
        // Lookahead won't fit in this bin afterward -> mild penalty unless gap is tiny anyway.
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using the only bin that can fit the item
    // instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new bins and
    // encourage consolidating into existing ones.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as open bins grow; allow when item is large.
        score += 20.0 + 10.0 * pressure - 0.1 * item_size as f64;
    } else {
        // Existing bin: reward proportional to how full it already is (tight packing).
        let fullness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 12.0 * fullness;
    }

    // Prefer bins below the mean residual (already fuller than average).
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score -= 0.15 * dev;
    }

    // Late in the stream, tighten up: dead space matters more, new bins are costly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 15.0 * progress;
    } else {
        score -= 10.0 * progress * fullness_proxy(bin_residual, bin_capacity);
    }

    score
}

#[inline(always)]
fn fullness_proxy(bin_residual: u32, bin_capacity: u32) -> f64 {
    (bin_capacity - bin_residual) as f64 / bin_capacity as f64
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 1000.0; // perfect 2-item closure
        } else if next_item_size <= post_residual {
            // next item fits: reward tightness of the combined fit
            let two_step_waste = post_residual - next_item_size;
            score -= 60.0 * (1.0 - two_step_waste as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize leftover dead space
            let dead = post_residual as f64;
            if dead > 0.0 {
                score += 0.8 * dead * dead / bin_capacity as f64;
            }
        }
    }

    // Compare post_residual against mean residual across open bins
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        if rel < 0.5 {
            score -= 15.0 * (0.5 - rel); // leaving less slack than average is good
        } else if rel > 1.5 {
            score += 10.0 * (rel - 1.5); // hoarding slack is bad
        }
    }

    // Last-chance bin bonus: avoid wasting the only fitting bin's capacity on a loose fit
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let tightness = item_size as f64 / bin_residual as f64;
        if tightness > 0.6 {
            score -= 25.0 * tightness;
        } else {
            score += 20.0 * (1.0 - tightness);
        }
    }

    // Penalize opening a new bin when decent open bins exist, but allow it
    // when the item is huge relative to residual (poor fit anywhere).
    if bin_residual == bin_capacity {
        let fit_quality = item_size as f64 / bin_capacity as f64;
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        // new bin is attractive for big items or when few bins fit
        score = 40.0 + 30.0 * (1.0 - fit_quality) - 45.0 * scarcity;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 20.0; // new bin supports a clean pair
        }
        if open_bins_count > 0 && fit_quality < 0.4 {
            score += 25.0; // don't open bins for tiny items
        }
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 12.0 * progress * (item_size as f64 / bin_residual.max(1) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins that end up nearly full.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score += tight * tight * 40.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Lookahead: penalize if the next item could perfectly use this bin's post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0; // perfect chain fit
        } else if next_item_size <= post_residual {
            // next item fits here later; keep residual somewhat usable
            score -= (post_residual - next_item_size) as f64 * 0.15;
        } else {
            // next item cannot use the residual: dead space penalty grows
            score += (next_item_size - post_residual) as f64 * 0.10;
        }
    }

    // Global pressure: when many open bins exist, prefer consolidation into tight bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += mean_residual * 0.05 * (1.0 - progress);

    // Mild bonus for using open bins vs opening new ones early in the stream.
    if bin_residual != bin_capacity {
        score -= 5.0 + pressure * 2.0;
    } else {
        // New-bin candidate: penalize slightly unless residual landscape is bad.
        score += 8.0 + mean_residual * 0.02;
    }

    // Progress-scaled dead-space weighting: later in stream, residual waste matters more.
    score += tight * progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Base: waste minimization, weighted by stream progress
    let mut score = pr * (0.6 + 0.8 * progress * progress);

    // Non-linear polynomial coupling of post_residual with progress
    let poly = pr_norm * pr_norm * (1.0 - pr_norm) * (2.0 + 6.0 * progress);
    score += poly * cap;

    // Penalize large post-residual more when many bins are open (fragmentation)
    let frag = (open_bins_count as f64).ln().max(0.0);
    score += pr_norm * pr_norm * frag * 4.0;

    // Reward tight fits: deviation from mean residual
    score -= (mean_residual - pr).abs().max(0.0) * 0.15;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 12.0 + 10.0 * progress;
    }

    // Lookahead: reward residual that can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 3.0 + 4.0 * (1.0 - ((pr - nxt) / cap).abs());
        } else {
            score += 2.0 + nxt * 0.05;
        }
    }

    // New-bin candidate: keep it neutral-slightly-high unless fits are poor
    if bin_residual == bin_capacity {
        score = score.max(0.0) + pr * 0.5 + 6.0 - (fitting_bins_count as f64) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which "slot band" does the leftover fall in?
    // Bands of 10 (harmonic division of capacity 100): 0 = perfect fit, 9 = near-empty bin.
    let band = (post_residual / 10) as f64;
    score += band * 2.0;

    // Exact-fill reward: strongly favor bins where the item leaves zero residual.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Tiny dead space (1..=5) is nearly a perfect fit too.
    if post_residual >= 1 && post_residual <= 5 {
        score -= 120.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // this placement chains perfectly — reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_left = post_residual - next_item_size;
        if chain_left == 0 {
            score -= 150.0;
        } else if chain_left <= 10 {
            score -= 60.0;
        } else {
            // Chain leaves a usable chunk: mild reward proportional to chain quality.
            score -= (next_item_size as f64) * 0.5;
        }
    }

    // If next item does NOT fit into post residual, penalize by how far off it is
    // (modulo-based harmonic mismatch).
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = next_item_size - post_residual;
        score += (gap as f64) * 0.3;
    }

    // Last-chance bin: if this is the ONLY bin that can fit the item, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 100.0;
    }

    // New-bin candidate (empty bin): penalize it so we only open when open bins are bad.
    // The penalty shrinks when the item is large relative to capacity (fewer options later).
    if bin_residual == bin_capacity {
        score += 80.0 - (item_size as f64) * 0.5;
    }

    // Modulo arithmetic on post_residual: residuals that are multiples of 10 align with
    // the harmonic grid and remain reusable for typical small items; odd/prime-ish
    // residuals are dead space.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 15.0;
    } else if post_residual % 10 != 0 && post_residual < 10 {
        score += 10.0;
    }

    // Integer-division thresholds: classify residual into thirds of capacity.
    // A residual >= 2/3 capacity means the bin is still very open — fine.
    // A residual in the middle band (33..66) is the awkward zone — mild penalty.
    let third = bin_capacity / 3;
    if post_residual >= 2 * third {
        score -= 5.0;
    } else if post_residual >= third && post_residual < 2 * third {
        score += 4.0;
    }

    // Stream progression: late in the stream, consolidate aggressively into existing bins
    // to avoid opening bins that will never fill.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= progress * 20.0;
    }

    // Many open bins with high mean residual: push toward using existing capacity.
    if open_bins_count > 2 && mean_residual > (item_size as f64) {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible item are "dead". Penalize them quadratically.
    let min_useful = 10u32;
    if post_residual < min_useful && post_residual > 0 {
        score += (min_useful - post_residual) as f64 * 12.0;
        score += 25.0; // flat dead-space tax
    }

    // Reward near-exact fills strongly (non-linear tightness bonus).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * 30.0;

    // Penalize leaving a gap just below the next item's size (wasted
    // opportunity for the lookahead item).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0; // good: next item can land here
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.6;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating
    // into existing bins; when few bins, opening new ones is cheaper.
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure-scaled penalty,
        // reduced late in the stream where consolidation matters most.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0 + pressure * 45.0 + progress * 10.0;
        // If no open bin fits well, opening is more attractive.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    } else {
        // Mild penalty for bins far from the mean residual (outliers).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post residual,
    // this bin becomes perfectly packed over two steps.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 450.0;
        } else if post_residual > next_item_size {
            // Next item fits but leaves more waste; mild reward scaled by tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 120.0 - slack * 1.5;
        } else {
            // Next item cannot use this bin's residual: penalize proportionally
            // to how stranded the leftover space is.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.8;
        }
    }

    // Compare residual quality against the mean residual of open bins.
    // Bins with residual below average are "tighter" -> prefer filling them.
    let res = post_residual as f64;
    if mean_residual > 0.0 {
        let ratio = res / mean_residual;
        if ratio < 1.0 {
            score -= (1.0 - ratio) * 60.0;
        } else {
            score += (ratio - 1.0) * 40.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residual
    // would be badly wasted (dead space the next item can't use either).
    if bin_residual == bin_capacity {
        let dead = if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.min(10) {
            1.0
        } else {
            0.0
        };
        let waste_here = (bin_residual - item_size) as f64;
        // Prefer new bin only when all open bins would leave large unusable gaps.
        let min_other_waste = if fitting_bins_count == 0 { 0.0 } else { post_residual as f64 };
        if waste_here < min_other_waste || dead > 0.0 {
            score -= 150.0;
        } else {
            score += 350.0 + open_bins_count as f64 * 5.0;
        }
    }

    // Small global pressure: late in the stream, pack tighter.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where the item nearly fills the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize leaving dead space that no plausible future item can use.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 0.0 } else { post_residual as f64 };
        score += 0.25 * dead;
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_fit = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 15.0 * chain_fit;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual too small for the next item: mild penalty for stranding space.
        score += 0.15 * post_residual as f64;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity in existing bins.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; cheaper early in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0 + 45.0 * progress;

        // If the item is large relative to capacity, a fresh bin is more attractive.
        score -= 10.0 * (item_size as f64 / bin_capacity as f64);

        // If many bins fit the item, prefer reusing one; penalize opening new bins.
        if fitting_bins_count > 1 {
            score += 30.0;
        }

        // If the item fits poorly everywhere (large residual gap in mean), new bin helps.
        if (mean_residual - item_size as f64) < 5.0 {
            score -= 18.0;
        }

        // Lookahead synergy: fresh bin can host both this and the next item.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 12.0;
        }
    }

    // Slight preference for bins with residual close to the item (best-fit flavor).
    score += 0.05 * (bin_residual as f64 - item_size as f64).abs();

    // Global pressure: when many bins are open, favor consolidation into existing bins.
    score += 0.5 * open_bins_count as f64 * (1.0 - fill_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: waste minimization with non-linear penalty on small residuals
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth polynomial coupling: waste matters more as stream progresses
    let coupling = 1.0 + 1.5 * progress * (1.0 - progress) * 4.0;
    score *= coupling * 0.5 + 0.5;

    // Reward near-perfect fits with a smooth quadratic bonus
    let fit_quality = 1.0 - norm_pr;
    score -= (item_size as f64 / cap) * fit_quality * 3.0;

    // Penalize leaving residual that no plausible next item fills
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += gap * 0.15 * (1.0 - progress);
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 + progress);
    }

    // Mild penalty for many open bins with large mean residual (fragmentation)
    score += (open_bins_count as f64).ln() * mean_residual * 0.02;

    // New-bin candidate: keep it neutral-ish, slightly favored when existing
    // residuals are fragmented (high mean residual relative to item)
    if bin_residual == bin_capacity {
        score = pr - 2.0 + mean_residual * 0.03 + progress * 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into capacity/10 buckets.
    let class = post_residual / 10;
    score += (class as f64) * 0.7; // finer penalty within same residual range

    // Exact fit reward: post_residual in {0} strongly favored.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 8.0;
    }

    // Harmonic coupling with lookahead: if next item fits the post residual,
    // reward this bin (chained packing); otherwise penalize proportionally.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + 0.25 * (post_residual - next_item_size) as f64;
        } else {
            score += 4.0 + 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_penalty = 45.0;
        // If existing bins leave large unusable residuals, opening new bin is ok.
        if mean_residual > 0.0 {
            let usable = mean_residual < item_size as f64;
            if usable {
                new_bin_penalty -= 20.0;
            }
        }
        if fitting_bins_count == 0 {
            new_bin_penalty -= 60.0; // forced open
        }
        // Late in stream, keep bins tight; early, allow expansion.
        new_bin_penalty *= 1.0 - 0.3 * progress;
        score += new_bin_penalty;
    }

    // Penalize bins whose residual after placement is an awkward harmonic class
    // (small but nonzero, hard to fill: 1..9 mod 20 bands).
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }
    if post_residual >= 10 && post_residual < 20 && next_item_size > 0 && next_item_size > post_residual {
        score += 6.0;
    }

    // Mild preference for filling fuller bins first (lower residual before placement).
    score += 0.1 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Define "unusable" as a gap too small to fit even the smallest plausible item.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0; // heavy penalty for tiny gaps
    } else {
        // Non-linear decay: residual usefulness diminishes super-linearly.
        score += (post_residual as f64 / bin_capacity as f64).powi(2) * 40.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + (post_residual - next_item_size) as f64 * 0.1;
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize slightly to prefer bins that chain.
        score += 6.0;
    }

    // Open-bin pressure: discourage spreading across too many bins.
    score += (open_bins_count as f64) * 1.5;

    // Mean residual coupling: placing into a bin whose residual is far from mean
    // helps rebalance; penalize placements that leave residual near the mean.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= dev * 0.15;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 25.0 + (mean_residual * 0.2);
        // Late in stream, opening new bins is cheaper than fragmenting.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward exact match between post_residual and next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 40.0; // perfect two-step chain
        } else if (diff as u32) < 10 {
            score -= 25.0 - diff as f64;
        } else {
            score += diff as f64 * 0.5;
        }
        // If next item cannot fit anywhere else, prefer keeping space for it.
        if next_item_size > post_residual {
            score += 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize small unusable leftovers (dead space), scaled by tightness.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Relative to mean residual: prefer bins that are already loose (large residual)
    // so tight bins stay available for tight future items.
    if bin_residual as f64 > mean_residual {
        score -= (bin_residual as f64 - mean_residual) * 0.3;
    } else {
        score += (mean_residual - bin_residual as f64) * 0.3;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = bin_capacity as f64 + 20.0 - 60.0 * pressure
            - if next_item_size > 0 && next_item_size > bin_capacity { 10.0 } else { 0.0 };
        // Late in stream, prefer reusing open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 15.0;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Penalize small leftover slivers that few future items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Perfect closure bonus: item exactly fills the bin.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Lookahead coupling: reward leaving space compatible with the next item.
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 15.0; // next item seals this bin perfectly
        } else if gap > 0 && gap <= 20 {
            score -= 8.0;  // next item fits snugly
        } else if gap < 0 && (-gap) as u32 <= item_size / 2 {
            score += 4.0;  // next item barely misses; mild penalty
        }
        // Avoid wasting a big residual when the next item is tiny.
        if post_residual as f64 > mean_residual * 1.5 && next_item_size < 20 {
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
        if post_residual > 40 {
            score += 10.0; // bad fit into the only bin; soften the reward
        }
    }

    // New-bin candidate logic: only attractive when open bins are crowded
    // or the fit into open bins would create large dead space.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowdedness = mean_residual / bin_capacity as f64;
        // Opening a bin is cheap early (long horizon ahead), costly late.
        let time_discount = 1.0 - 0.6 * progress;
        score -= 10.0 * time_discount;
        // If open bins have plenty of room, discourage opening a new one.
        score += 20.0 * (1.0 - crowdedness);
        // If no existing bin fits well, encourage a fresh bin.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    } else {
        // Mild preference to consolidate into fewer bins.
        score += 2.0 / open_bins_count.max(1) as f64;
    }

    // Prefer bins below the mean residual (more filled bins get priority).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: wasted space, damped quadratically as residual grows (large residuals are less costly per unit late)
    let mut score = norm_pr * (1.0 + norm_pr * norm_pr * (1.0 - progress));

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, prefer filling bins tightly (weight residual waste more); later, relax
    let progress_poly = progress * progress * (3.0 - 2.0 * progress);
    score -= 0.35 * progress_poly * norm_pr;

    // Reward tight fits: small post_residual relative to item size
    let item = item_size as f64;
    let fit_ratio = if item > 0.0 { pr / item } else { pr };
    score += 0.5 * (fit_ratio / (1.0 + fit_ratio));

    // Lookahead: bonus if next item fits exactly in post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = pr - nxt;
            score -= 0.4 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; slight penalty if post_residual too small to matter
            score += 0.15 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 1.2;
    } else if fitting_bins_count > 1 {
        // among many candidates, prefer bins with residual closest to item size
        score += 0.1 * (fitting_bins_count as f64).ln() * norm_pr;
    }

    // Mean residual context: if this bin is far below mean residual, it's a good filler
    score -= 0.2 * ((mean_residual - pr) / cap);

    // New-bin candidate handling: make empty bin attractive only when item is large
    if bin_residual == bin_capacity {
        let large_item_bonus = (item / cap).powi(2);
        score = 0.9 + 0.5 * (1.0 - large_item_bonus) - 0.3 * progress;
    }

    // Mild penalty for accumulating many open bins with low fill
    score += 0.02 * (open_bins_count as f64) * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo common capacity fractions.
    let frac_quarter = post_residual % 25;   // C/4 classes
    let frac_fifth = post_residual % 20;     // C/5 classes
    let frac_eighth = post_residual % 12;    // C/8-ish classes

    // Reward residuals that land on "clean" harmonic classes (usable by future items).
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if frac_quarter == 0 || frac_fifth == 0 || frac_eighth == 0 {
        score -= 12.0; // residual sits on a harmonic class likely to be re-filled
    } else {
        // Penalize dead space proportional to how far off the nearest harmonic class it is.
        let off = frac_quarter.min(25 - frac_quarter) as f64
            + frac_fifth.min(20 - frac_fifth) as f64;
        score += 0.25 * off;
    }

    // Integer-division thresholds: small residuals are dead space.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let next_post = post_residual - next_item_size;
            let harmonic_bonus = if next_post % 25 == 0 || next_post % 20 == 0 { 10.0 } else { 0.0 };
            score -= harmonic_bonus;
            // penalize leaving a sliver after the next item too
            if next_post < 10 {
                score += 6.0;
            }
        } else {
            // next item won't fit here; slight penalty for tight bins
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when open bins are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Opening a bin is penalized normally; reward only if existing residuals are tiny/fragmented.
        score += 45.0 - 35.0 * (1.0 - fragmentation) - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin mandatory
        }
    }

    // Mild pressure against accumulating many open bins with large mean residual.
    score += 0.05 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);

    // Tight-fit reward: item fills most of the bin.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    if fill > 0.8 {
        score -= 10.0 * fill;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly useless.
    if post_residual > 0 {
        if post_residual <= 10 {
            // Unusable sliver: heavy penalty.
            score += (11 - post_residual as i32 as f64) * 40.0;
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 30 {
            score += 8.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 150.0;
    }

    // Reward tight fits relative to residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 30.0;

    // Open-bin pressure: prefer filling existing bins when many are open.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when current bins are crowded or fit is bad.
    if bin_residual == bin_capacity {
        score += 120.0 + open_bins_count as f64 * -2.0 + (100.0 - fit_ratio * 100.0);
        // If the next item could use this fresh bin well, slight bonus for opening.
        if next_item_size > 0 && next_item_size <= 50 {
            score -= 20.0;
        }
    }

    // Lookahead: if post_residual exactly matches next item, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 100.0;
    } else if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 10 {
        score += 20.0; // would leave a sliver after next item
    }

    // Mean residual coupling: when mean residual is high, avoid leaving more.
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Late in stream: consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.8;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly into the
    // post-residual, this placement chains perfectly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            let leftover = post_residual - next_item_size;
            score -= 80.0 - leftover as f64 * 2.0;
        } else {
            // Next item cannot use this bin's remainder: penalize dead space
            // proportionally, more so when the remainder is small and useless.
            let waste = (next_item_size - post_residual) as f64;
            score += waste * 0.5;
        }
    }

    // Relative-to-mean-residual coupling: prefer bins tighter than average.
    let diff = post_residual as f64 - mean_residual;
    score += diff * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize mildly so we only open a new bin when
    // existing bins would create bad fits; relax penalty late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 120.0 - 60.0 * progress;
        // If next item is large and current item is small, a fresh bin is attractive.
        if next_item_size > 50 && item_size <= 30 {
            score -= 90.0;
        }
    }

    // Prefer filling bins with larger residuals when few bins are open.
    if open_bins_count > 3 {
        score += (post_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: post_residual too small to hold any plausible item.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score += 50.0;
    }
    // Penalize residuals that are small but non-zero (likely dead space).
    if post_residual > 0 && post_residual < 15 {
        score += (15 - post_residual) as f64 * 1.5;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty for wasting capacity.
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Time horizon: late in the stream, avoid opening new bins (favor consolidation).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and as open bins grow.
        score += 10.0 + 30.0 * progress + 0.8 * open_bins_count as f64;
        // Allow new bin early if current bin fit would be terrible.
        if tightness < 0.15 && progress < 0.3 {
            score -= 25.0;
        }
    } else {
        // Early stream: slight preference for filling existing bins well.
        score -= 5.0 * (1.0 - progress);
    }

    // Global state coupling: prefer bins whose residual is below mean (consolidate fuller bins).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Prefer bins with more competitors? Slight nudge toward bins when many fit (keeps options open).
    if fitting_bins_count > 3 {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: f64, fitting_bins_count: usize) -> f64 {
