pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "reusable" classes (large enough for typical items) get rewarded.
    let cap_f = bin_capacity as f64;
    let post = post_residual as f64;

    // Fraction of capacity remaining after placement.
    let frac = post / cap_f;

    // Reward large post_residual (keeps flexibility), but only up to a point:
    // waste grows quadratically once leftover becomes "dead" (< smallest item 1..=10 band).
    if post_residual >= 20 {
        score -= 0.6 * (frac * frac); // gentle bonus for roomy bins
    } else {
        // Dead-space penalty: quadratic in how close we are to zero residual.
        score += 0.9 * ((20.0 - post) / 20.0) * ((20.0 - post) / 20.0) * 10.0;
    }

    // Modulo arithmetic: leftover divisible into nice chunks is more reusable.
    let r = post_residual;
    if r > 0 && (r % 10 == 0 || r % 25 == 0 || r % 50 == 0) {
        score -= 4.0;
    }
    // Odd tiny leftovers (1..9) are nearly useless -> penalize.
    if r < 10 {
        score += (10 - r) as f64 * 0.8;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0; // perfect closure
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 5.0 * (1.0 - slack / cap_f).max(0.0);
        } else {
            // Next item cannot fit here: mild penalty, stronger if leftover tiny.
            score += 2.0 + 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Prefer filling bins that are already relatively full (best-fit flavor)
    // scaled by stream progression: late in the stream, tighten packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_capacity - bin_residual) as f64 * 0.05 * (0.5 + 0.5 * progress);

    // Discourage proliferating bins when many are open and this one is empty.
    if bin_residual == bin_capacity {
        score += 6.0 + 0.15 * open_bins_count as f64;
        // But allow a fresh bin if item is huge relative to mean residual.
        if (item_size as f64) > mean_residual {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 25.0 * (10.0 - pr) / 10.0; // tiny gap -> large penalty
    } else if pr >= 10.0 && pr < 20.0 {
        score += 8.0 * (20.0 - pr) / 10.0; // moderately small gap -> moderate penalty
    }

    // Reward near-perfect fits.
    if pr == 0 {
        score -= 30.0;
    } else if pr <= 5 {
        score -= 12.0;
    }

    // Pressure from number of open bins: discourage spreading when many bins open.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        score += 4.0; // next item won't fit here; mild penalty
    }

    // Relative residual alignment: prefer bins whose residual is close to item size (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 6.0 * tightness;

    // New-bin candidate: only attractive when current bins are crowded or fit is bad.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        let bad_fit = if post_residual < 10.0 { 1.0 } else { 0.0 };
        score += 15.0 - 12.0 * crowding - 10.0 * bad_fit;
        if item_size >= 70 {
            score -= 8.0; // huge items deserve fresh bins
        }
    }

    // Slight late-stream conservatism: waste less as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 3.0 * progress * (pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 / (1.0 + diff);
        // Perfect chain: item fits now AND next item fills the bin completely
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Penalize leaving residual that is too small for the next item (dead space risk)
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    } else {
        // Last item: strongly prefer tightest fill
        score -= 100.0;
    }

    // Penalize large dead space relative to smallest possible item
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable sliver
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current residuals are poorly matched
    if bin_residual == bin_capacity {
        let mean_gap = (mean_residual - item_size as f64).abs();
        score += 20.0 + mean_gap * 0.3;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0; // fresh bin can host a good 2-step chain
        }
    }

    // Mild preference for bins tighter than average
    score -= (mean_residual - bin_residual as f64) * 0.2;

    // Late-stream consolidation: prefer filling existing bins as stream ends
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual <= 20 {
        score += 6.0;
    }

    // Lookahead: if the next item fits into the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + 0.15 * next_item_size as f64;
        } else {
            // Next item won't fit here; penalize leaving medium gaps that get stranded.
            score += 0.08 * (post_residual as f64);
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    } else if fitting_bins_count > 3 {
        // Many alternatives: mild penalty to encourage consolidation elsewhere.
        score += 1.5 * (fitting_bins_count as f64 - 3.0);
    }

    // Global state coupling: prefer filling bins when many are open (bin-count control).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    // Deviation from mean residual: prefer bins whose residual is close to the mean (balanced packing),
    // but reward using below-mean-residual bins late in the stream.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev * (1.0 - progress) - 0.10 * dev * progress;

    // New-bin candidate: penalize opening a new bin unless the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        let poor_fit = (bin_capacity - item_size) as f64;
        score += 30.0 - 0.2 * poor_fit;
        // Late in the stream, opening new bins is cheaper than stranding gaps.
        score -= 10.0 * progress;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 8.0; // big item coming, fresh bin is fine
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: post residual, with non-linear shaping (favor tight fits)
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Polynomial coupling of post_residual with stream progress:
    // early stream -> tolerate larger residuals; late stream -> penalize waste harder
    let progress_coupling = 1.0 + 1.5 * progress * progress + 2.0 * progress.powi(3);
    score *= progress_coupling;

    // Interaction: waste relative to mean residual across open bins
    let waste_gap = post - mean_residual;
    score += 0.25 * waste_gap * (0.5 + progress);

    // Dead-space penalty: residuals too small to be useful later
    let dead_threshold = 0.15 * cap;
    if post < dead_threshold {
        score += 30.0 * (dead_threshold - post) / cap;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: if next item fits the post residual exactly-ish, reward
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.3 * gap;
        if next_item_size as f64 <= post {
            score -= 8.0 * (1.0 - gap / cap);
        }
    } else {
        // last item: minimize waste maximally
        score += 10.0 * norm_post;
    }

    // Mild penalty for proliferating bins when many are already open
    score += 0.02 * open_bins_count as f64 * norm_post;

    // New-bin candidate: make empty bin attractive only when no tight fit exists
    if bin_residual == bin_capacity {
        let tightness = (post - mean_residual).abs();
        score = 60.0 + 0.5 * tightness + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which "slot band" it falls into.
    // Bands: [0] exact, [1..=10] tiny dead space, (10..=30] medium, (30..=60] useful, >60 large.
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Exact fit: perfect harmony, reward heavily.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty grows superlinearly for small residuals (unusable for items >=10... but sizes 1..=100 now).
        // Classify by integer division thresholds.
        if post_residual <= 10 {
            // Nearly dead space: penalize strongly, scaled by progress (late stream => waste hurts more).
            score += 60.0 * (1.0 + progress) - 2.0 * post_residual as f64;
        } else if post_residual <= 30 {
            score += 10.0;
        } else if post_residual <= 60 {
            score -= 15.0;
        } else {
            score -= 25.0;
        }
    }

    // Harmonic compatibility with the lookahead item: residual class divisible into next item's needs.
    if next_item_size > 0 && post_residual > 0 {
        if post_residual == next_item_size {
            score -= 200.0; // residual exactly absorbs next item
        } else if post_residual >= next_item_size {
            // Residual can host next item; check leftover class after hypothetical placement.
            let nxt_post = post_residual - next_item_size;
            if nxt_post == 0 {
                score -= 150.0;
            } else if nxt_post <= 10 {
                score += 5.0; // would create dead space after next
            } else {
                score -= 10.0;
            }
        } else {
            // Next item cannot use this residual: dead-space risk if residual is tiny.
            if post_residual < next_item_size && post_residual < 10 {
                score += 20.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 80.0;
        // If many bins can fit the item, discourage opening a new one.
        score += 30.0 * fitting_bins_count as f64;
        // Early stream: keep bins open longer (amortization); late stream: new bins cheaper to justify.
        score -= 40.0 * progress;
        // If the item is large relative to capacity, a fresh bin is reasonable.
        if item_size * 4 >= bin_capacity * 3 {
            score -= 50.0;
        }
        // If mean residual across open bins is small, open bins are crowded; new bin may be good.
        if mean_residual < item_size as f64 {
            score -= 60.0;
        }
    } else {
        // Favor tighter bins (best-fit flavor) beyond the raw post_residual ordering.
        let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 20.0 * fill;
    }

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 4 {
        score -= 2.0 * open_bins_count as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize small unusable gaps harshly.
    // Gaps below the minimum item size (1) are dead; treat small residuals
    // (<= 20) as increasingly costly dead space.
    if post_residual <= 20 {
        score += (21 - post_residual as i32) as f64 * 3.0;
    } else if post_residual > 40 {
        // Large leftover is fine (still usable), slight reward.
        score -= 5.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open bins pressure: penalize using bins when many are open,
    // encouraging consolidation into existing bins rather than spreading.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // If next item would not fit in post residual but fits in a fresh bin,
    // slightly penalize tight fits that strand the next item.
    if next_item_size > post_residual as u32 && post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate: make empty bins moderately attractive only when
    // current item is large relative to mean residual or no good fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Prefer new bin for large items early, or when open bins are fragmented.
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score -= 10.0 + 20.0 * item_frac - 10.0 * progress + fragmentation * 0.2;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Slight preference for bins tighter than average (best-fit flavor).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
