pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that no future item (min size 1) could plausibly use:
    // small post residuals are fine, large ones are wasteful.
    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        score += 20.0 * dead * dead;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big bonus.
    if next_item_size > 0 {
        if post_residual as u32 >= next_item_size {
            let next_tight = next_item_size as f64 / (post_residual as f64 - next_item_size as f64 + 1.0);
            score -= 8.0 * next_tight;
        } else {
            // Next item won't fit here; slightly penalize leaving awkward remainder.
            score += 3.0;
        }
        // Reserve room: penalize leaving a residual slightly larger than next item (blocked space).
        let gap = post_residual as i64 - next_item_size as i64;
        if gap > 0 && gap < 10 {
            score += 6.0; // awkward gap just above next item size
        }
    }

    // Time horizon: early in the stream, be conservative (prefer existing bins);
    // late in the stream, tight packing matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * fit_ratio;

    // Global state: many open bins with high mean residual -> prefer filling them.
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 4.0 * (mean_residual - item_size as f64) / bin_capacity as f64;
    }

    // New-bin candidate handling: make an empty bin attractive only when
    // the item is large and current bins would leave big dead space,
    // or when no open bin is a good home.
    if bin_residual == bin_capacity {
        let waste_here = (bin_residual - item_size) as f64;
        let open_waste = if fitting_bins_count > 0 {
            (bin_capacity as f64 - mean_residual).abs()
        } else {
            bin_capacity as f64
        };
        // Prefer new bin when it preserves more usable space than the best open option.
        if waste_here < open_waste * 0.9 {
            score -= 10.0;
        } else {
            score += 12.0; // discourage needless bin proliferation
        }
        // Early stream: opening bins is cheap and useful for future flexibility.
        if progress < 0.3 {
            score -= 3.0;
        }
    }

    // Mild penalty per open bin to consolidate when bins are numerous.
    score += 0.15 * open_bins_count as f64 * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: f64, fitting_bins_count: usize) -> f64 {
