    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod small divisors.
    // Residuals that are multiples of 10 (classic "harmonic" sizes) are more reusable.
    let pr = post_residual;
    let harm10 = (pr % 10 == 0) as f64;
    let harm5 = (pr % 5 == 0) as f64;
    let harm20 = (pr % 20 == 0) as f64;

    // Reward residuals in harmonic classes (likely to be filled by future items).
    score -= 8.0 * harm10 + 4.0 * harm5 + 6.0 * harm20;

    // Penalize small dead space: residuals in awkward classes (1..9, not harmonic).
    if pr > 0 && pr < 10 && !harm5 {
        score += 12.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= pr {
        score -= 10.0;
        if next_item_size == pr {
            score -= 25.0; // perfect closure
        }
        // Harmonic match: next item leaves another harmonic residual
        let npr = pr - next_item_size;
        if npr % 10 == 0 {
            score -= 6.0;
        }
    }
    // Penalize if next item cannot use the remaining space at all (dead end).
    if next_item_size > pr && pr > 0 {
        score += 7.0;
    }

    // Capacity fraction thresholds: prefer filling bins past half capacity.
    let fill_frac = (bin_capacity - pr) as f64 / bin_capacity as f64;
    if fill_frac >= 0.5 {
        score -= 5.0 * fill_frac;
    }
    if fill_frac < 0.25 {
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it rather than wasting it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 18.0;
        if fitting_bins_count == 0 {
            score -= 30.0; // nothing else fits, must open
        } else if fitting_bins_count == 1 {
            score += 8.0; // keep last-chance bin alive
        }
        // Late in the stream, prefer reusing existing bins more strongly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 * progress;
    }

    // Mild preference for bins tighter than the mean residual (better fits).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Integer-division threshold: residual classes by quarters of capacity.
    let quarter = bin_capacity / 4;
    if pr <= quarter && pr > 0 {
        score += 3.0; // tiny leftover is near-useless
    } else if pr > quarter && pr <= 2 * quarter {
        score -= 2.0;
    } else if pr > 2 * quarter {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in [1,9] are unusable for items >=10
    // (items 1..100 interface, but small gaps rarely reusable) -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }

    // Reward exact / near-exact fills.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Perfect-fit bonus when residual exactly matches item size.
    if bin_residual == item_size {
        score -= 50.0;
    }

    // Dead-space pressure scales with how full the bin already is:
    // wasting space in an almost-full bin is worse than in a fresh one.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score += score * 0.3 * fill_ratio;

    // Coupling with mean residual: placing into a bin whose residual is far
    // below the mean (a tight bin) is good; a roomy bin should stay flexible.
    let res_gap = mean_residual - bin_residual as f64;
    score -= 0.5 * res_gap.max(-50.0).min(50.0);

    // Open-bins pressure: with many open bins, prefer packing into existing
    // bins over opening new ones (penalize the new-bin candidate).
    score += 8.0 * open_bins_count as f64;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // reward leaving that gap; if next item cannot use the gap, penalize it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 15.0;
        }
    }

    // Early in the stream, allow slightly more freedom to open bins;
    // late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }

    // Near-match: next item fits snugly into the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Dead space: post residual too small for the next item (likely waste).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 12.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Penalize tight fits that leave unusable residue relative to mean residual.
    if (post_residual as f64) < mean_residual * 0.35 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New empty bin candidate: only attractive when current bin would leave
    // a large awkward residue or no bin fits well.
    if bin_residual == bin_capacity {
        let tight = next_item_size > 0 && post_residual < next_item_size;
        if tight || post_residual as f64 > bin_capacity as f64 * 0.5 {
            score += 15.0;
        } else {
            score += 40.0;
        }
    }

    // Mild pressure to consolidate into fewer bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_ratio = item_size as f64 / bin_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Reward tight fits strongly (best-fit core).
    score -= 6.0 * fit_ratio * fit_ratio;

    // Penalize small dead space that no typical item can use.
    if post > 0.0 && post < 10.0 {
        score += 8.0;
    } else if post >= 10.0 && post < 20.0 {
        score += 3.0;
    }

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual as u32 {
        score -= 20.0;
    } else if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 5.0;
    } else if next_item_size > 0 {
        // Next item won't fit here: slight penalty for consuming this bin's space.
        score += 2.0;
    }

    // New-bin candidate handling: prefer new bin only when fit here is poor
    // and many bins are open; discourage early in the stream.
    if bin_residual == bin_capacity {
        let base = 15.0 - 10.0 * progress;
        let poor_fit_elsewhere = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += base + (open_bins_count as f64).min(20.0) * 0.3 * (1.0 - fit_ratio) - poor_fit_elsewhere * 20.0;
        // If this bin is the only option, opening new bin is legitimate.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Global state: many open bins with high mean residual -> prefer filling existing bins.
    if open_bins_count > 3 && mean_residual > 30.0 {
        score -= 2.0;
    }

    // Late in stream: consolidate aggressively.
    if progress > 0.8 {
        score -= 3.0 * fit_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Normalized post-residual and its non-linear couplings with stream progress
    let post_norm = post / cap;
    let poly = post_norm * post_norm;               // penalize large dead space quadratically
    let smooth = post_norm * (1.0 - post_norm);     // favor mid-range residuals smoothly

    let mut score = post;

    // Quadratic dead-space penalty, amplified as the stream progresses
    score += 12.0 * poly * (0.5 + progress);

    // Mild reward for smooth mid-range fit
    score -= 6.0 * smooth * (1.0 - 0.5 * progress);

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward if the next item fits into the post-residual
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post >= next {
            let tight = 1.0 - (post - next) / cap; // tighter next-fit => larger reward
            score -= 10.0 * tight.max(0.0) * (0.6 + 0.4 * progress);
        } else {
            score += 5.0 * (next - post) / cap;    // penalize blocking the lookahead item
        }
    }

    // Compare against mean residual: bins far below mean are worse fits
    score += 0.15 * (mean_residual - post).max(0.0);

    // Crowding: with many open bins, prefer tightening existing bins
    score -= 0.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - post_norm);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: capacity divided into 4 bands.
    let band = |r: u32| r / (bin_capacity / 4);
    let post_band = band(post_residual);

    // Reward exact or near-exact fits (post_residual in low harmonic class).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    } else if post_band == 0 {
        score -= 6.0;
    }

    // Penalize mid-band dead space (residuals 25..50 are hardest to fill).
    if post_band == 1 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this placement (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            // Next item fits: mild reward proportional to leftover after chain.
            let chain_left = post_residual - next_item_size;
            score -= (10.0 * (1.0 - chain_left as f64 / bin_capacity as f64));
        } else {
            // Next item won't fit here: slight penalty if this bin was the only option.
            if fitting_bins_count == 1 {
                score += 5.0;
            }
        }
    }

    // Last-chance bin logic: if this is the only bin that fits, favor using it
    // to avoid opening a new bin (unless post_residual is huge dead space).
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin
    // offers a decent fit. Penalize the fresh bin, more so early in the stream
    // and when many bins are already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 + 15.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        // But if the item is large relative to capacity, opening fresh is fine.
        if item_size >= bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is already tight — reward concentrating waste there.
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score -= (diff * 0.3).min(10.0);
    } else {
        score += (-diff * 0.1).min(5.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to ever hold another item (min size 1..~10)
    // are pure waste; penalize them heavily.
    if post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Open-bins pressure: discourage spreading into many bins; favor filling existing ones.
    score += 1.5 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward (pairing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap < 10.0 {
            score -= 20.0;
        } else {
            score -= 6.0;
        }
    }

    // New-bin candidate: only attractive when existing bins are mostly full / item is large
    // and would leave a bad gap elsewhere.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        let pressure = mean_residual / bin_capacity as f64;
        // Prefer new bin when it would be nearly filled and open bins are tight.
        let bonus = 30.0 * tightness + 25.0 * (1.0 - pressure);
        // Penalize new bin when many bins could still fit the item.
        score += 55.0 - bonus + 2.0 * fitting_bins_count as f64;
    } else {
        // Mild preference for bins whose residual is closest to the item (tight packing).
        score += 0.3 * (bin_residual as f64 - item_size as f64).abs();
    }

    // Slight stream-progression bias: as stream ends, prioritize closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exhausting fits (minimize dead space).
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 60.0 + (10 - post_residual) as f64 * 2.0;
    }

    // 2-step lookahead: strongly reward bins whose post_residual matches next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 150.0;
        } else if (post_residual as i64) >= next_item_size as i64 {
            // next item can follow here: reward proportional to tightness
            score -= 40.0 - diff as f64 * 0.5;
        } else {
            // next item cannot fit: penalize leftover space that is too small
            score += diff as f64 * 0.3;
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.4;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Penalize opening a new bin when decent open bins exist, unless item is large.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score += 30.0 + waste * 0.5;
        if fitting_bins_count > 0 && post_residual < item_size.min(next_item_size.max(1)) {
            score += 20.0;
        }
        // Opening a new bin is fine late in the stream or when few bins fit.
        if fitting_bins_count <= 1 {
            score -= 60.0;
        }
    }

    // Mild preference to fill older/busy bins to consolidate state.
    score -= (open_bins_count as f64).ln() * 2.0;
    score += (step_index as f64 / total_items.max(1) as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space below
    // next item's size is wasted — penalize if next item can't use it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // residual usable by lookahead: reward proportionally
            score -= 6.0 * (next_item_size as f64) / (post_residual as f64 + 1.0);
        } else {
            // dead space for the lookahead item
            score += 4.0 + 0.15 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Exact fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer bins with residuals close to item size (minimize fragmentation)
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 10.0 * tightness;

    // Global state: many open bins with high mean residual -> encourage
    // filling existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowding = open_bins_count as f64 / 10.0;
    score += crowding * (1.0 - progress) * 2.0;
    score -= 0.05 * mean_residual;

    // New-bin candidate handling: make empty bin attractive only when the
    // item is large relative to capacity or fits are plentiful elsewhere.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 12.0 * (1.0 - large_item);
        if next_item_size > 0 && next_item_size <= post_residual {
            // fresh bin can host both items
            score -= 8.0;
        }
        if open_bins_count == 0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * (0.5 + 0.5 * progress);
    score += 10.0 * poly;

    // Reward tight fits more strongly as the stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 15.0 * tightness * (0.3 + 0.7 * progress);

    // Penalize dead space relative to next item size (smooth interaction)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = pr - nxt;
        if gap > 0.0 {
            score += 5.0 * (gap / cap) * (gap / cap) * 100.0 / cap;
        }
        // Reward leaving exactly enough room for the next item
        let match_term = 1.0 - (gap.abs() / cap);
        score -= 8.0 * match_term * match_term * (pr / cap);
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across many open bins early on
    score += 0.5 * (open_bins_count as f64).ln() * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin unless residuals are all bad
    if bin_residual == bin_capacity {
        score += 25.0 - 20.0 * (mean_residual / cap).min(1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
