    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 12.0;
    }
    if post_residual % 10 == 0 {
        score -= 6.0;
    }
    // Odd/unusable classes
    if post_residual % 2 == 1 {
        score += 4.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (next_item_size as f64) * 0.5;
        } else {
            score += (next_item_size as f64 - post_residual as f64) * 0.3;
        }
        // Harmonic pairing: post_residual == next_item_size exactly chains
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // New-bin candidate handling: neutral baseline, prefer it only when
    // open bins would leave bad fractions
    if bin_residual == bin_capacity {
        score = cap * 0.55;
        if frac_is_bad(mean_residual / cap) {
            score -= 15.0;
        }
        if fitting_bins_count == 1 {
            score += 25.0;
        }
    }

    // Tight-fit reward: item fills most of the bin
    let fill = item_size as f64 / bin_residual as f64;
    if fill > 0.8 {
        score -= 8.0 * (fill - 0.8);
    }

    score
}

fn frac_is_bad(f: f64) -> bool {
    // bad residuals: small fractions unlikely to fit future items
    f < 0.2
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize small unusable gaps more than linearly.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Coupling with lookahead: if next item fits exactly into post_residual, reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // Next item cannot fit in the remaining gap: this gap is likely dead space.
            score += (post_residual as f64) * 0.5 + 5.0;
        }
    }

    // Open bins pressure: discourage spreading across many bins when a tight fit exists.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Mild progression term: later in stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0 * (bin_residual - post_residual) as f64 / bin_capacity as f64;

    // Prefer bins whose residual is close to mean residual (balanced packing),
    // penalize outliers that hoard space.
    score += (mean_residual - bin_residual as f64).abs() * 0.3;

    // New-bin candidate: make opening a new bin unattractive unless the item is huge
    // relative to available residuals (large item leaves large post_residual anyway).
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin; softened when few bins are open.
        score += 45.0 + open_bins_count as f64 * 2.0;
        // If item is large, a fresh bin is more acceptable.
        if item_size >= 60 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward closing the bin completely.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small unusable dead space (no future item can fit it).
        if next_item_size > 0 && post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
        // Dead space that nothing in [1,100] can use is worst.
        if post_residual < 10 && post_residual > 0 {
            score += 40.0;
        }
    }

    // 2-step lookahead: reward a residual that exactly accommodates the next item
    // (chained perfect fit), mildly reward residuals next can still fit into.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            score -= 0.3 * next_item_size as f64;
        } else {
            score += 0.8 * (next_item_size - post_residual) as f64;
        }
    }

    // Prefer filling bins that are already more empty than average (consolidate waste).
    score += 0.4 * (mean_residual - bin_residual as f64).max(0.0);
    score -= 0.2 * (bin_residual as f64 - mean_residual).max(0.0);

    // Last chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New empty bin candidate: only attractive when item is large (poor fit elsewhere)
    // or no open bin can hold the item.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 > 0.7 * bin_capacity as f64;
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score += 250.0; // prefer existing bins that also chain-fit
        }
        if !large_item && fitting_bins_count > 0 {
            score += 120.0;
        }
        if large_item {
            score -= 80.0;
        }
    }

    // Late in the stream, tighten up: favor tighter placements.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 30.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a nonlinear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 4.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: make it attractive only when existing residuals are poor.
    if bin_residual == bin_capacity {
        let mean_waste = mean_residual.max(0.0);
        let poor_state = (mean_waste / bin_capacity as f64).clamp(0.0, 1.0);
        let pressure = (open_bins_count as f64 / (step_index.max(1) as f64 + 1.0)).min(1.0);
        score -= 20.0 * poor_state - 10.0 * pressure;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild penalty for spreading across many bins when mean residual is large.
    score += 0.05 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);

    // Small time-based drift to explore different regimes.
    let t = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * (t * std::f64::consts::PI).sin();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit_norm = item_size as f64 / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early in the stream, prefer tight fills (low post_residual) strongly;
    // late in the stream, weight wasted space quadratically to avoid dead space.
    let early_w = (1.0 - progress) * (1.0 - progress);
    let late_w = progress * progress;
    score += 8.0 * early_w * norm_pr * norm_pr;
    score += 6.0 * late_w * norm_pr * norm_pr * norm_pr;

    // Smooth interaction: item size relative to capacity, coupled with progress.
    score -= 4.0 * fit_norm * (1.0 + progress);

    // Mean residual coupling: penalize bins far from mean residual (smoothly).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // Last-chance bonus (smooth sigmoid-ish shaping, not piecewise).
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Lookahead: reward leaving space compatible with next item.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 2.0 * (1.0 - gap / cap).max(0.0);
    }

    // Mild penalty for proliferation of open bins, smoothed by progress.
    score += 0.5 * (open_bins_count as f64) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space quality classes
    // class 0 = perfect fit, class 1 = tiny dead space, class 2 = medium, class 3+ = large
    let pr = post_residual;
    let class = if pr == 0 { 0 } else if pr <= 10 { 1 } else if pr <= 25 { 2 } else { 3 };
    score += match class { 0 => -40.0, 1 => -15.0, 2 => 5.0, _ => 12.0 };

    // Modulo arithmetic: residuals divisible by small integers are more reusable
    let m3 = (pr % 3 == 0) as f64;
    let m5 = (pr % 5 == 0) as f64;
    let m10 = (pr % 10 == 0) as f64;
    score -= 4.0 * m3 + 6.0 * m5 + 8.0 * m10;

    // Next item lookahead: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // how tightly does next item fit after this placement?
            let npr = pr - next_item_size;
            let tight = 1.0 - (npr as f64 / bin_capacity as f64);
            score -= 10.0 * tight;
            // harmonic match: next item leaves a class-0/1 residual
            if npr <= 10 { score -= 8.0; }
        } else {
            // next item cannot use this bin's leftover: penalize leftover
            score += 6.0;
        }
    }

    // Integer-division threshold on bin_residual fill fraction
    let fill_quarter = bin_residual / 25; // 0..4
    score -= 3.0 * fill_quarter as f64;

    // Last-chance bonus: only one fitting bin -> strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // New-bin candidate handling: only attractive late in stream or when
    // mean residual is too fragmented to accept the item well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - item_size as f64).max(0.0);
        // new bin starts attractive only if existing bins are badly fragmented
        score += 30.0 - 20.0 * progress - 0.4 * fragmentation;
        if open_bins_count == 0 { score -= 60.0; }
    }

    // Prefer tight packing of large items early
    score -= 0.05 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be
    // useful (below the minimum plausible item size) are heavily penalized,
    // but a perfect fit (post_residual == 0) is maximally rewarded.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual < 10 {
        // Unusable dead space: gap smaller than the smallest item.
        score += 60.0 * (10.0 - post_residual as f64);
    } else {
        // Usable residual: mild quadratic penalty on large waste,
        // encouraging bins to be filled tightly.
        let p = post_residual as f64;
        score += 0.02 * p * p;
    }

    // Reward tight fits: fraction of the bin's space consumed by this item.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Lookahead: if the next item exactly fits the post residual, strongly
    // favor this placement (chain packing).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item still fits: moderate bonus proportional to leftover after it.
        let chain_left = post_residual - next_item_size;
        score -= 20.0 * (1.0 - chain_left as f64 / bin_capacity as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use this residual: penalize if residual becomes dead.
        if post_residual < 10 {
            score += 25.0;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate handling: an empty bin is a fresh resource; discourage
    // opening it unless the current item is large and would leave a healthy
    // residual, or open bins are few and fragmented fits look bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        let mut new_bin_cost = 25.0 + open_bins_count as f64;
        // If item is large and leaves a usable residual, opening a new bin is
        // more attractive (subtract).
        if post_residual >= 20 {
            new_bin_cost -= 20.0;
        }
        // If no open bin gives a good fit (this is judged by high mean residual
        // spread), opening a new bin becomes relatively better.
        if (mean_residual - post_residual as f64).abs() < 1.0 {
            // new bin residual equals mean residual trivially; slight nudge.
            new_bin_cost -= 2.0;
        }
        score += new_bin_cost;
    }

    // Mild preference for bins whose residual is already below average
    // (concentrate waste into few bins).
    if bin_residual != bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let nis = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    let mut score = pr;

    // ---- Aggressive 2-step lookahead matching ----
    if next_item_size > 0 {
        if pr == nis {
            // Perfect chain: this item leaves exactly what the next item needs.
            score -= 35.0;
        } else if pr >= nis {
            // Next item still fits here; reward small leftover after the chain.
            let leftover2 = pr - nis;
            score -= 18.0 * (1.0 - leftover2 / cap);
        } else {
            // Next item cannot use the leftover -> the remainder risks being dead space.
            score += 6.0 + 0.15 * (nis - pr);
        }
    }

    // ---- Dead-space penalty: tiny nonzero residuals are hard to fill ----
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr) * 2.5;
    }

    // ---- Last-chance bin: strongly favor using the only bin that fits ----
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // ---- Prefer tighter-than-average bins as a tie-break ----
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // ---- New-bin candidate: only open when existing fits are poor ----
    if bin_residual == bin_capacity {
        score += 28.0 + 0.1 * mean_residual + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly prefer bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize small dead space left behind (unusable gaps).
    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        if dead < 0.10 {
            score -= 8.0 * (1.0 - dead * 10.0);
        } else {
            score += 4.0 * dead;
        }
    } else {
        score -= 15.0; // perfect fill
    }

    // Lookahead: reward if next item fits in the post-residual, penalize otherwise.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            let waste = (next_item_size - post_residual) as f64;
            score += 0.15 * waste;
        }
        // Bonus if next item exactly fits post-residual (chain fill).
        if next_item_size == post_residual {
            score -= 12.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when item is large relative to capacity
    // or current open bins are all fragmented.
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        // Prefer new bin when item is big, many bins open, and mean residual is small.
        score -= 6.0 * (item_size as f64 / bin_capacity as f64) * openness * 0.5;
        score += 10.0 * (1.0 - item_size as f64 / bin_capacity as f64);
        score += 3.0 * fragmentation / bin_capacity as f64;
        score += 5.0 * progress * (openness / (openness + 5.0));
        // Late in stream, avoid spawning bins for small items.
        if item_size < 30 && progress > 0.7 {
            score += 25.0;
        }
    }

    // Mild penalty when this bin's residual deviates from the mean (keep bin states uniform).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Slight preference for bins with more residual when few bins fit the item.
    if fitting_bins_count > 1 {
        score += 0.02 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth non-linear coupling: squared post-residual scaled by progress
    let x = pr / cap;
    score += (x * x) * cap * (0.25 + 0.75 * progress);

    // Cubic penalty for very large dead space
    score += (x * x * x) * cap * progress;

    // Lookahead: reward (subtract) if next item fits in post-residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fit_quality = (pr - nxt) / cap;
            score -= (1.0 - fit_quality) * (2.0 + 3.0 * (1.0 - progress));
        } else {
            // penalize leaving space that next item cannot use
            score += (pr - nxt).max(0.0) * 0.05 * (1.0 - progress);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 5.0 + 10.0 * (1.0 - x);
    }

    // Slight preference for bins tighter than average
    score += (mean_residual - pr) * 0.1;

    // Mild bias toward opening new bins late in the stream when residuals are large
    score -= (1.0 - x) * progress * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins partitioned into capacity-fraction classes.
    // Class 0 = perfect fit (post_residual 0), large class = wasteful dead space.
    let quarter = bin_capacity / 4;
    let residue_class = post_residual % quarter;
    let class_index = post_residual / quarter;
    score += class_index as f64 * 3.0;
    score -= residue_class as f64 * 0.15;

    // Strong reward for exact fill.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits here: reward proportional to how snugly it fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 + slack * 0.05;
        } else {
            // Next item cannot use the leftover space: penalize dead space growth.
            score += 6.0;
            // Harmonic penalty: leftover in awkward classes (e.g. 1..=9 unusable slivers).
            if post_residual < 10 {
                score += 10.0;
            }
        }
    } else {
        // Last item: prefer tightest fit overall.
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only open a new bin when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // New bin is attractive if current item is large (little waste expected later)
        // or the stream is early (long future to amortize the bin).
        let item_frac = item_size as f64 / bin_capacity as f64;
        score = score - 20.0 * (1.0 - item_frac) - 10.0 * (1.0 - progress);
        // But avoid proliferating bins when several could fit.
        if fitting_bins_count > 2 {
            score += 12.0;
        }
    }

    // Slight preference for bins with below-average residual (keep big holes for big items).
    let mean_frac = mean_residual / bin_capacity as f64;
    let this_frac = bin_residual as f64 / bin_capacity as f64;
    score += (this_frac - mean_frac) * 4.0;

    // Mild pressure to consolidate as bins accumulate.
    score += open_bins_count as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A post_residual that is too small for the smallest plausible item (1..=10)
    // is pure dead space; the tighter the gap band, the harsher the penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Moderate dead space (10..=20) is also risky: penalize softly.
    if post_residual >= 10 && post_residual <= 20 {
        score += 0.5 * (post_residual as f64 - 10.0);
    }

    // Perfect fit reward: strongly favor zero post_residual.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than fragmenting capacity across bins.
    score += 0.15 * open_bins_count as f64;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (avoid opening bins unnecessarily).
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits into the post_residual,
    // reward this placement (chaining placements).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // New-bin candidate handling: an empty bin has full residual. Only prefer
    // it when current bins are heavily fragmented (high mean residual spread)
    // and the item is large relative to residual (poor fit elsewhere).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Base penalty so new bins are only chosen when existing fits are bad.
        score += 20.0;
        // If item nearly fills an empty bin, opening is fine.
        if fill_ratio > 0.7 {
            score -= 15.0;
        }
        // If open bins are on average nearly full (low mean residual) and this
        // item is large, opening a new bin avoids dead space.
        if mean_residual < item_size as f64 && fill_ratio > 0.5 {
            score -= 22.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: aggressive 2-step lookahead — reward bins whose post_residual
    // matches the next item's size (perfect chaining).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - gap / bin_capacity as f64).max(0.0);

        // Exact match: post_residual == next_item_size is ideal.
        if post_residual == next_item_size {
            score -= 30.0;
        }
        // Post residual slightly larger than next item still usable.
        else if post_residual > next_item_size {
            score -= 8.0;
        }
        // Dead space: post_residual too small for next item (waste).
        else if post_residual > 0 {
            score += 6.0;
        }
    } else {
        // Last item: prefer minimal waste.
        score -= 10.0;
    }

    // Tight fit reward relative to capacity.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 15.0 * tightness;

    // Penalize bins far below mean residual (they hoard space poorly) —
    // prefer filling bins whose residual is near mean to keep balance.
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when current fit is bad
    // (very large post_residual waste) or no good option exists.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win.
        score += 20.0;
        // But if the item barely fits anywhere, a fresh bin is fine.
        if item_size as f64 / bin_capacity as f64 > 0.7 {
            score -= 25.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            // Fresh bin can host a nice pair; slightly more attractive.
            score -= 10.0;
        }
    }

    // Early in stream: encourage consolidation into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, penalize large post-residual quadratically.
    let pr = post_residual as f64;
    score += 0.35 * pr * pr / bin_capacity as f64;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    } else if fitting_bins_count >= 2 {
        // Multiple candidates: sharpen competition toward best fit.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead: does the next item fit the post-residual? If yes, reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0;
        } else {
            // Wasted residual relative to next item: penalize dead space.
            score += 0.5 * (post_residual as f64 - next_item_size as f64).abs();
        }
    }

    // Time horizon: early in stream, opening new bins is cheap; later, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: reward early, penalize late.
        score -= 30.0 * (1.0 - progress) - 25.0 * progress;
        // Also discourage new bin if existing bins fit well.
        if post_residual < 20 && fitting_bins_count > 0 {
            score += 50.0;
        }
    } else {
        // Existing bin: reward more as stream progresses.
        score -= 15.0 * progress;
    }

    // Global state coupling: if mean residual is high, prefer filling existing bins.
    if bin_residual < bin_capacity {
        score -= 0.3 * (mean_residual - pr).clamp(-20.0, 20.0);
    }

    // Many open bins: encourage closing them out (small residuals are valuable to keep).
    if open_bins_count > 4 && post_residual < 15 {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prn = pr / cap; // normalized post residual
    let p2 = progress * progress;
    let p3 = p2 * progress;
    // Smooth interaction: residual utility decays non-linearly as stream progresses
    let coupling = prn * prn * (1.0 + 2.0 * progress) - prn * (0.5 * p2 + 0.3 * p3);
    score += 40.0 * coupling;

    // Reward tight fits more strongly late in the stream (smooth polynomial)
    let tightness = 1.0 - prn;
    score -= (item_size as f64 / cap) * (1.0 + progress + p2) * 10.0;

    // Penalize dead space (residual too small for smallest plausible item) smoothly
    let dead = if pr < 10.0 { (10.0 - pr) / 10.0 } else { 0.0 };
    score += dead * dead * (5.0 + 10.0 * progress);

    // Last-chance bonus when only this bin can fit the item
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - 0.5 * progress);
    }

    // Lookahead: favor bins whose post residual still fits the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            score -= 8.0 * (ns / cap) * (1.0 + progress);
        } else {
            score += 6.0 * ((ns - pr) / cap) * (1.0 + progress);
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += (open_bins_count as f64).ln().max(0.0) * prn * 2.0;
    // Deviation from mean residual: prefer bins near/below mean (better packing balance)
    score += ((pr - mean_residual) / cap).abs() * (3.0 + 3.0 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into capacity-fraction bands.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0..1

    // Dead-space penalty: residual below smallest plausible item is wasted.
    if post_residual < 10 {
        score += 40.0 * (1.0 - frac);
    }

    // Modulo class of post_residual: values in [0,10), [10,20), ... get
    // different desirability. Bins whose residual is a "harmonic" of common
    // item sizes are more reusable.
    let class = post_residual % 20;
    let class_bonus = match class {
        0 => 6.0,          // exact multiple of 20: very reusable
        1..=9 => 3.0,      // near-multiple: fits small items
        10..=19 => 0.0,    // mid-band: neutral
        _ => 0.0,
    };
    score -= class_bonus;

    // Integer-division threshold on post_residual vs next_item_size:
    // reward if next item fits exactly (perfect harmonic pair).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / cap);
            if post_residual == next_item_size {
                score -= 12.0; // perfect packing of the pair
            }
        } else {
            score += 5.0; // next item won't reuse this bin's leftover
        }
    }

    // Fractional thresholds on residual fill level.
    if frac >= 0.9 {
        score -= 10.0; // nearly-full bin: close it out
    } else if frac >= 0.5 {
        score -= 4.0; // half-full: good progress
    } else if frac < 0.2 && post_residual > 0 {
        score += 6.0; // large dead space created
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when open bins
    // would create bad dead space, and more so later in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 14.0 + 8.0 * progress;
        // But if existing bins are all fragmented, new bin is fine.
        if mean_residual < 15.0 {
            score -= 10.0;
        }
    }

    // Prefer bins tighter than the current mean residual (best-fit flavor).
    score += 0.15 * (mean_residual - post);

    // Mild preference to keep few bins open early on.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero gaps are the worst.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect fit is heavily rewarded.
        score -= 80.0;
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Penalize wasting a large residual on a small item (creates dead space).
    if (post_residual as f64) > 0.5 * (bin_residual as f64) {
        score += 15.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidation.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score += 4.0 * open_pressure;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < next_item_size as f64 {
        // Dead space for the known next item: penalize.
        score += 10.0;
    }

    // New-bin candidate: only attractive when open bins are badly fragmented
    // (high mean residual spread vs. needed space) or few bins fit.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let scarcity_pressure = if fitting_bins_count <= 1 { 20.0 } else { 0.0 };
        let stream_late = step_index as f64 / (total_items as f64).max(1.0);
        score += 45.0 - 0.15 * open_bins_count as f64 - 0.5 * fragmentation + scarcity_pressure - 10.0 * stream_late;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.95;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squashed post-residual dominates.
    let frac_filled = item_size as f64 / bin_capacity as f64;
    score -= 1.6 * frac_filled * frac_filled * (bin_capacity as f64);

    // Penalize dead space that no future item (>=10) can use.
    if post_residual < 10 {
        score -= 25.0; // perfect closure
    } else {
        score += 0.35 * (post_residual as f64).sqrt() * 2.0;
    }

    // Lookahead: if next item fits the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + 0.25 * next_item_size as f64;
        } else {
            // wasted bin if leftover can't host next item
            score += 0.15 * (post_residual as f64 - (next_item_size as f64 - post_residual as f64).abs());
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: opening a bin is costly when many bins fit,
    // but attractive when this is the only fit or residuals are fragmented.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 1.0 / fitting_bins_count as f64 };
        let fragmentation = 1.0 - (mean_residual / bin_capacity as f64);
        score += 30.0 - 22.0 * pressure - 8.0 * fragmentation
            + 10.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Mild preference for fuller bins among many open bins.
    score -= 0.05 * open_bins_count as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Time horizon: late in stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (bin_residual as f64 - post_residual as f64) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Base: quadratic dead-space penalty (smooth, non-linear in post_residual)
    let mut score = post * post / cap;

    // Normalize dead space relative to mean residual state; smooth coupling
    let norm_post = post / cap;
    let norm_mean = mean_residual / cap;
    score += 30.0 * (norm_post - norm_mean) * (norm_post - norm_mean + 0.5);

    // Reward tight fits (small post residual) more aggressively as stream progresses
    let tightness = 1.0 - norm_post;
    score -= progress * 25.0 * tightness * tightness;

    // Lookahead: reward if next item fits the post residual, penalize if it just barely doesn't
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = post - nxt;
        if gap >= 0.0 {
            score -= 8.0 * (1.0 - gap / cap);
        } else {
            score += 5.0 * (-gap / cap) * (1.0 + progress);
        }
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0 * (1.0 - norm_post);
    }

    // New-bin candidate: penalize opening new bins, more so early and when alternatives exist
    if is_new_bin {
        score += 60.0 + 40.0 * (1.0 - progress);
        // But if existing bins would leave very awkward dead space, ease the penalty smoothly
        let awkward = (norm_post - norm_mean).abs();
        score -= 50.0 * awkward * awkward;
    }

    // Mild penalty for bin sprawl when many bins are open
    score += 0.5 * open_bins_count as f64 * norm_post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: small dead space classes are more reusable
    let pr = post_residual as i64;
    let cls: i64 = match pr {
        0 => 0,
        1..=10 => 1,
        11..=30 => 2,
        31..=50 => 3,
        _ => 4,
    };
    score += cls as f64 * 3.0;

    // Modulo arithmetic on post_residual: multiples of common item sizes are reusable
    if pr > 0 {
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 5 == 0 { score -= 3.0; }
        if pr % 20 == 0 { score -= 4.0; }
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            // next item fits, but check leftover class
            let nxt_post = post_residual - next_item_size;
            if nxt_post % 10 == 0 { score -= 15.0; }
            score -= (nxt_post as f64) * 0.3;
        } else {
            // next item won't fit here: penalize slightly, dead-end risk
            score += 8.0;
        }
    }

    // Last chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Prefer tighter bins (best-fit refinement)
    score -= (bin_capacity - bin_residual) as f64 * 0.5;

    // New-bin candidate handling: only open new bin when existing fits are bad
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score += 60.0;
        // but if current item leaves big dead space in every bin, new bin is fine
        if item_size >= 60 { score -= 30.0; }
        // late in stream, prefer consolidating
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 25.0;
        // many open bins with low mean residual: opening new bin is fine
        if mean_residual < 25.0 && open_bins_count > 2 { score -= 10.0; }
    }

    // Penalize placing large items into nearly-full bins leaving tiny residue
    if pr > 0 && pr < 5 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold any
    // realistic future item (1..=10 range is trivial, but gaps of 10..30 are
    // the real "wasted" zone for unknown distributions) get heavily penalized.
    let dead_zone = (post_residual >= 10 && post_residual <= 30) as u32;
    if dead_zone == 1 {
        score += 45.0 + (30 - post_residual) as f64 * 1.5;
    }
    // Perfect fit bonus: annihilate score for near-zero post residual.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Reward tight fills relative to bin residual (fill ratio).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 20.0;

    // Open-bin pressure: prefer consolidating into existing bins when many
    // bins are already open; discourage opening new bins when few are open.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (1.0 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open,
        // allow it only if open bins are very fragmented (high mean residual).
        score += 30.0 + pressure * 2.0 - (mean_residual - 50.0).max(0.0) * 0.4;
    } else {
        // Existing bin gets a consolidation bonus scaled by open-bin pressure.
        score -= pressure.min(25.0);
    }

    // Lookahead: if the next item can fit exactly into the post residual,
    // strongly favor this bin (chained perfect fits).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Next item won't fit here; penalize leaving a residual that
            // neither chains nor is large enough to be generally useful.
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible (huge dead zone already penalized).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Slight preference to place into bins below the mean residual
    // (balances residual distribution, keeps more mid-size gaps alive).
    if bin_residual != bin_capacity {
        score += (mean_residual - bin_residual as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: heavily reward.
    if post_residual == 0 {
        score -= 1000.0;
