    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: waste left after placement
    let mut score = pr;

    // Non-linear waste penalty: quadratic in normalized residual
    let x = pr / cap;
    score += 12.0 * x * x * cap;

    // Perfect-fit reward (smooth, sharp)
    score -= 20.0 * (-pr as f64 * 0.25).exp();

    // Lookahead: penalize residuals too small for the next item, reward ones that fit it
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = nxt - pr;
        if gap > 0.0 {
            score += 3.0 * (gap / cap) * (1.0 + progress);
        } else {
            score -= 2.0 * (-gap / cap) * (1.0 - progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - progress * 0.5);
    }

    // Mild penalty when many bins are open and this one is already tight
    score += 0.15 * open_bins_count as f64 * x;

    // Deviation from mean residual: prefer keeping residual distribution balanced
    score += 0.5 * (pr - mean_residual).abs() / cap;

    // New-bin candidate: neutral-ish, penalize slightly so tight fits win, but
    // reward opening a new bin late in the stream when residual is large
    if bin_residual == bin_capacity {
        score = 6.0 + 4.0 * x - 5.0 * progress * (1.0 - x);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-residual (modulo arithmetic) ---
    // Residuals divisible by common item sizes are "reusable" classes.
    let res = post_residual;
    let class = if res == 0 { 0 } else if res % 20 == 0 { 1 } else if res % 10 == 0 { 2 } else if res % 5 == 0 { 3 } else { 4 };
    // Reward reusable classes (subtract), penalize awkward residues.
    score -= match class { 0 => 60.0, 1 => 40.0, 2 => 25.0, 3 => 10.0, _ => 0.0 };

    // Integer-division dead-space threshold: residual < 10 is unusable (min item size 1... but treat <8 as near-dead).
    if res > 0 && res < 8 {
        score += 30.0; // small dead space penalty beyond raw residual
    }

    // --- Lookahead: does next item fit into post_residual? ---
    if next_item_size > 0 {
        if next_item_size <= res {
            // Harmonic pairing: reward when next item divides or nearly divides residual
            let diff = res - next_item_size;
            if diff == 0 {
                score -= 80.0; // perfect pairing
            } else if diff < 10 {
                score -= 45.0;
            } else if next_item_size % 10 == 0 && res % next_item_size.max(1) == 0 {
                score -= 35.0;
            } else {
                score -= 20.0;
            }
        } else {
            // Next item won't fit here; slight penalty proportional to overflow gap
            score += ((next_item_size - res) as f64).min(25.0) * 0.6;
        }
    } else {
        // Last item: closing a bin fully is ideal
        score -= 50.0;
    }

    // --- Last-chance bonus: this is the only bin that fits ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // --- Coupling with mean residual: prefer bins tighter than average ---
    score += (mean_residual - bin_residual as f64) * 0.3;

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin: base cost plus mild pressure against proliferation.
        score = bin_capacity as f64 - 15.0;
        if open_bins_count > 0 && next_item_size > 0 && res >= next_item_size {
            // (unreachable for empty bin, kept for structure)
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        // Discourage opening a new bin when a decent fit exists elsewhere:
        if fitting_bins_count >= 1 && item_size >= 10 {
            score += 12.0;
        }
        // Late in stream, prefer closing existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    }

    // Fractional capacity coupling: mild bonus for filling large fractions of the bin.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= fill_frac * 15.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized.
    let dead_threshold = 9.0; // smallest useful item is typically >= 10
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 15.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Coupling: penalize leaving gaps that neither fit the lookahead item well
    // nor any plausible small item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // residual can still host the next item -> mild reward
            score -= 8.0;
        } else {
            // residual is dead relative to lookahead -> penalty scaled by gap size
            score += (post_residual as f64) * 1.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new bins
    // (new-bin candidate has residual == capacity; this term is neutral there,
    //  but existing bins get a discount relative to it).
    if bin_residual < bin_capacity {
        let pressure = (open_bins_count as f64).ln().max(0.0);
        score -= 5.0 + pressure * 3.0;
    } else {
        // Opening a new bin is penalized more when many bins are already open.
        score += 10.0 + (open_bins_count as f64) * 2.0;
    }

    // Mean-residual coupling: if this bin's post-residual diverges from the
    // mean, slightly penalize (keeps residual distribution tight).
    score += ((post_residual as f64) - mean_residual).abs() * 0.3;

    // Late in the stream, prefer tightening existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 45.0 * (-diff / 12.0).exp(); // strong reward when next item fills this bin
        // Penalize leaving a gap that is too small for the next item (dead space).
        if post_residual < next_item_size {
            score += 8.0 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer minimal waste.
        score += 2.0 * post_residual as f64;
    }

    // Penalize residual far above mean residual (relative coupling).
    score += 1.5 * (post_residual as f64 - mean_residual).max(0.0);
    score -= 0.5 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bonus: only bin that fits -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer filling bins with small residual (tight fit reward).
    score -= 10.0 * (-post_residual as f64 / 10.0).exp();

    // New-bin candidate handling: make new bin moderately attractive only when
    // no open bin gives a good fit; otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 5.0;
        } else {
            score += 25.0;
        }
    }

    // Slight preference to close out nearly-full bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual close to 0 is good.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits into post_residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
        // Extra reward if next item exactly fills remaining space.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize creating a residual the next item cannot use.
        score += 6.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Prefer fuller bins relative to the mean residual of open bins.
    if (bin_residual as f64) < mean_residual {
        score += 4.0;
    } else {
        score -= 4.0;
    }

    // Early in stream: be slightly more willing to open new bins (better packing later).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, penalized late.
        score += 20.0 * progress - 10.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Later in stream: favor consolidating into existing bins.
        score -= 8.0 * progress;
    }

    // Mild penalty for proliferating open bins when residuals are large.
    if open_bins_count > 4 && mean_residual > 40.0 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer minimal post-residual, with smooth quadratic tightening.
    let mut score = pr + 0.35 * (pr * pr) / cap;

    // Smooth progress coupling: as the stream advances, tighten fit preference.
    let t = progress.clamp(0.0, 1.0);
    score *= 1.0 + 0.8 * t * t;

    // Reward bins whose residual matches the next item well (lookahead chaining).
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let chain_fit = 1.0 - ((pr - next_item_size as f64).abs()) / cap;
        score -= 6.0 * chain_fit * chain_fit;
    } else if next_item_size > 0 {
        // Dead space: next item cannot use this residual.
        score += 3.0 * (pr / cap);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - pr / cap);
    } else {
        // Slight penalty spread across many fitting bins to encourage consolidation.
        score += (fitting_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate: only attractive when residuals are fragmented and item is large.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        let large_item = item_size as f64 / cap;
        score = cap + 8.0 * large_item - 10.0 * fragmentation * (1.0 - t);
        // Late in the stream, discourage opening bins with poor expected fill.
        score += 6.0 * t;
    }

    // Mild penalty for scattering across many open bins relative to mean residual.
    score += 0.05 * (open_bins_count as f64) * (1.0 - (pr / cap));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    let fit_ratio = (item_size as f64) / (bin_capacity as f64);
    score *= 1.0 + 0.5 * fit_ratio;

    // Harmonic class of post_residual: mod-10 buckets penalize dead space
    // that is unlikely to be reused by common item sizes.
    let pr = post_residual;
    if pr > 0 {
        let class = pr % 10;
        // Residuals in 1..9 are hard to fill; 0 or >=10 more reusable.
        if class != 0 && pr < 10 {
            score += 25.0; // tiny useless sliver
        } else if pr < 20 && (pr % 20) < 10 {
            score += 8.0;
        }
        // Perfect power-of-two-like residuals are attractive targets.
        if pr == 10 || pr == 20 || pr == 25 || pr == 40 || pr == 50 {
            score -= 6.0;
        }
    }

    // Lookahead: if next item fits the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 10.0 + 0.2 * (next_item_size as f64);
        } else {
            // next item cannot use leftover: penalize proportional to waste
            score += 0.1 * (pr as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64).max(1.0);
        // Penalize new bins mildly; escalate when many bins are already open
        // and mean residual suggests consolidation is possible.
        let mut new_bin_penalty = 15.0 + 2.0 * open_bins_count as f64;
        if mean_residual >= item_size as f64 {
            new_bin_penalty += 10.0;
        }
        if progress > 0.8 {
            new_bin_penalty += 5.0;
        }
        score += new_bin_penalty;
        // Large items relative to capacity benefit from a fresh bin.
        if fit_ratio > 0.7 {
            score -= 12.0;
        }
    }

    // Slight preference for bins with residuals near item size (tight class match).
    let gap = (bin_residual as i64 - item_size as i64).unsigned_abs() as f64;
    score += 0.05 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the smallest
    // possible item (size 1..~20) are effectively dead space -> heavy penalty.
    if post_residual > 0 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 3.0;
    }
    // Perfect or near-perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // If the leftover can still fit the lookahead item, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // leftover unusable for the next item: penalize proportionally
        score += (next_item_size as f64) * 0.3;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing
    // bins rather than opening new ones; new-bin candidate gets penalized.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 2.0;
    } else {
        score -= open_bins_count as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Tight-fit bonus: reward placements that consume a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 10.0;

    // Early in the stream, be slightly more open to new bins; later, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 5.0;
    }

    // Penalize bins whose residual deviates far below the mean residual
    // (they are nearly full; prefer filling them with tight fits only).
    if (post_residual as f64) < mean_residual * 0.5 && post_residual > 0 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item size -> strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near match: next item fits into post residual
    else if next_item_size > 0 && post_residual >= next_item_size {
        // tighter leftover after also placing next item is better
        score -= 50.0 + (post_residual - next_item_size) as f64 * 0.5;
    } else if next_item_size > 0 {
        // next item won't fit here: penalize small dead space left behind
        let dead = post_residual as f64;
        if dead > 0.0 && dead < 10.0 {
            score += 80.0; // tiny unusable gap
        }
    }

    // Last chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Compare against mean residual: bins with residual below mean are tighter fits, prefer them
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: penalize unless current bin would leave very little space
    if bin_residual == bin_capacity {
        score += 40.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 60.0; // fresh bin can host the next item too
        }
    }

    // Late in stream: consolidate, avoid spreading
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic decay of penalty as post_residual shrinks.
    let t = (post_residual as f64) / (bin_capacity as f64);
    score += 8.0 * t * t;

    // Reward bins whose residual is close to the item (best-fit flavor).
    let slack = (bin_residual as f64 - item_size as f64);
    score -= 6.0 * (1.0 - slack / bin_capacity as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: penalize opening a new bin, more when
    // existing bins could fit and mean residual is large.
    if bin_residual == bin_capacity {
        score += 15.0;
        if fitting_bins_count > 0 {
            score += 10.0 * (mean_residual / bin_capacity as f64).min(1.0);
        }
        // Late in the stream, opening new bins is cheaper than dead space.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 8.0 * progress;
    } else {
        // Penalize placing into a bin when the leftover would be tiny but
        // unusable for the next item (lookahead dead-space check).
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 5.0;
        }
        // Reward exact or near-exact fills.
        if post_residual == 0 {
            score -= 10.0;
        } else if next_item_size > 0 && post_residual == next_item_size {
            score -= 7.0;
        }
        // Mild preference for using bins with smaller residuals first
        // (keeps large residuals flexible).
        score += 2.0 * ((bin_residual as f64) / bin_capacity as f64);
    }

    // Global pressure: many open bins -> prefer consolidation into existing bins.
    if open_bins_count > 4 {
        score -= 1.5 * ((open_bins_count as f64).ln());
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with non-linear polynomial shaping over stream progress
    let mut score = pr;

    // Smooth polynomial coupling: residual penalty grows as stream progresses
    let poly = progress * progress * (3.0 - 2.0 * progress); // smoothstep in [0,1]
    score += poly * 10.0 * norm_pr * norm_pr * cap;

    // Reward tight fits (small post-residual) increasingly late in the stream
    score -= poly * 8.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * cap;

    // Penalize leaving residuals close to the next item's size mismatch (dead space)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += 2.0 * (gap / cap) * (gap / cap) * cap * (0.5 + poly);
    }

    // Last-chance bin bonus: strongly favor the sole fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 * (1.0 + poly);
    }

    // Mild penalty when bin residual deviates from mean residual (imbalance)
    score += 1.5 * (bin_residual as f64 - mean_residual).abs() / cap * (1.0 + poly);

    // New-bin candidate: penalize slightly unless open bins are crowded
    if bin_residual == bin_capacity {
        score += 5.0 - 4.0 * (open_bins_count as f64 / (open_bins_count as f64 + 3.0)) * (1.0 - poly);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: finer granularity near zero.
    let pr = post_residual;
    let class: f64 = if pr == 0 {
        -50.0 // perfect closure is always excellent
    } else if pr <= 5 {
        -20.0
    } else if pr <= 10 {
        -8.0
    } else if pr <= 20 {
        4.0
    } else if pr <= 40 {
        10.0
    } else {
        16.0
    };
    score += class;

    // Modulo-based harmonic refinement: residuals that are multiples of common
    // small item sizes (10, 20, 25, 50) are reusable "harmonic" slots.
    let harmonic = (pr % 10 == 0) as f64 * 3.0
        + (pr % 20 == 0 && pr > 0) as f64 * 2.0
        + (pr % 25 == 0 && pr > 0) as f64 * 2.0
        + (pr % 50 == 0 && pr > 0) as f64 * 3.0;
    score -= harmonic;

    // Lookahead: if the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            // next item fits but leaves another residual; mild reward scaled by tightness
            score -= 8.0 * (next_item_size as f64 / pr as f64);
        } else {
            // next item cannot use this residual: penalize large leftovers
            score += (pr as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit. Give it a penalty that shrinks as open-bin fits worsen.
    if bin_residual == bin_capacity {
        score += 45.0;
        // but if nothing else can fit the item, opening is fine
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Prefer filling bins whose residual is already below average (consolidation).
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Slight early-stream encouragement to keep bins open (fewer bins early).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 2.0 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals of 1..=9 are nearly unusable
    // (items are >= 1 but typical streams waste them), so punish hard.
    if post_residual > 0 && post_residual <= 9 {
        score += 60.0 * (1.0 - (post_residual as f64) / 10.0);
    }
    // Perfect fits are gold.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Mid-range dead space (10..=19) is semi-unusable too; mild penalty.
    if post_residual >= 10 && post_residual <= 19 {
        score += 8.0;
    }

    // Last chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // penalize spreading out (which the new-bin candidate would do).
    score += (open_bins_count as f64) * 1.5;

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // If next item cannot fit in post residual but this bin could hold it
    // alongside (i.e., we leave a gap that blocks the next item), penalize.
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 10.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins),
    // so the looser bins stay available for larger future items.
    score += (mean_residual - post_residual as f64) * 0.5;

    // New-bin candidate must look expensive: empty bin has max residual.
    if bin_residual == bin_capacity {
        score += 15.0 + (open_bins_count as f64).sqrt() * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead fit: post_residual exactly matches next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 100.0;
    }
    // Near-perfect: next item still fits in the post residual.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 - slack.min(40.0);
    }
    // Post residual too small for next item: penalize dead space more if tiny.
    else if next_item_size > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        score += gap.min(30.0);
    }

    // Reward tight fits (small post_residual) generally.
    score -= 0.5 * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64 * 10.0;

    // Penalize leaving residuals below the minimum item size (unusable).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Prefer bins below mean residual (larger residual bins used later).
    if bin_residual != bin_capacity {
        score += 0.3 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Prefer tight fits: reward small post_residual non-linearly (quadratic coupling).
    score -= (cap - pr) / cap * (1.0 - (pr / cap).powi(2)) * 8.0;

    // Lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        if nx <= pr {
            score -= (1.0 - gap / cap) * 6.0;
        } else {
            // post_residual too small for next item: mild penalty scaled by dead space
            score += (pr / cap) * 3.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening new bins early, relax later in stream;
    // penalize more when many bins are open relative to progress.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        score += 10.0 + 20.0 * (1.0 - progress) * pressure;
    }

    // Mean-residual coupling: if this bin's residual deviates below mean, it is a good "filler" bin.
    let bin_res = bin_residual as f64;
    score += (bin_res - mean_residual) / cap * 2.0;

    // Smooth stream-progress term: as stream progresses, prefer tighter packing (lower post_residual).
    score -= progress * (1.0 - pr / cap) * 5.0;

    // Slight non-linear penalty on large unusable residuals.
    score += (pr / cap).powi(3) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: small residues in "good" classes are rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: minimize waste, with non-linear penalty on medium dead space.
    score = pr * (1.0 + 0.35 * (pr / cap));

    // Perfect-fit harmonic classes (residue divisible into small units).
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    } else if post_residual <= 20 {
        score -= 4.0;
    }

    // Modulo arithmetic: residues congruent to small multiples of capacity/10
    // (i.e. 10,20,...,90 classes) are more "reusable" by future items.
    let unit = bin_capacity / 10;
    let cls = post_residual / unit; // harmonic class 0..=10
    score -= (cls as f64) * 1.5;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            score -= 8.0 * (1.0 - slack as f64 / cap);
            // Harmonic match: next item size in same class as post_residual
            if (next_item_size / unit) == cls {
                score -= 5.0;
            }
        } else {
            // next item cannot use this residue: penalize large residues
            score += 0.05 * pr;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 {
            60.0
        } else {
            10.0 + 5.0 * (fitting_bins_count as f64)
        };
        // Later in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = pressure + 20.0 * progress;
    }

    // Slight bias toward tighter (smaller-residual) bins among comparable fits.
    score -= 0.01 * bin_residual as f64;

    // Mean residual coupling: when mean residual is small, waste matters more.
    score += 0.02 * (mean_residual - pr).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A post_residual below the minimum plausible item size (1..100 unknown dist,
    // use a soft threshold ~10) is "dead" unless it's near zero.
    let dead_zone = 10.0;
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 8.0; // waste that can never be filled
    }

    // Reward near-perfect fits strongly (post_residual close to 0).
    if post_residual <= 2 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Coupling: post_residual relative to mean residual — placing into a bin
    // whose residual is already small (tight bin) is good.
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.15;

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin, especially under bin-count pressure.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> discourage opening new bins,
    // encourage filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.3 + 0.4 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when pressure is high.
        score += pressure * 4.0;
        // But if the item fits poorly everywhere else, new bin may win:
        // approximate by checking whether item leaves a huge gap anyway.
        if post_residual > 0 && (post_residual as f64) < dead_zone {
            score -= (dead_zone - post_residual as f64) * 8.0; // neutralize dead-zone penalty for fresh bin
        }
    } else {
        // Reward using existing bins when pressure is high.
        score -= pressure * 0.5;
    }

    // Lookahead: if next item fits exactly into the post residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits but imperfectly: mild reward proportional to fill ratio
        score -= 5.0 * (next_item_size as f64 / post_residual as f64);
    } else if next_item_size > post_residual {
        // next item won't fit in the leftover: leftover likely wasted, penalize
        score += (post_residual as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly matches post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            // next item fits, but penalize leftover after that hypothetical placement
            let second_leftover = post_residual - next_item_size;
            score -= 200.0 - second_leftover as f64 * 2.0;
        } else {
            // next item won't fit here: penalize small unusable residuals
            if post_residual < 10 {
                score += 50.0;
            }
        }
    } else {
        // last item: strongly prefer tightest fit
        score -= 500.0;
    }

    // Relative-to-mean coupling: bins with more residual than average are better targets
    score -= (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin bonus: only bin that can fit the item
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: keep it attractive only when no good fit exists elsewhere
    if bin_residual == bin_capacity {
        // prefer opening a new bin if current best residuals are tight
        score = score * 0.9 + 40.0;
        if mean_residual < item_size as f64 * 0.5 {
            score -= 60.0;
        }
        // late in the stream, avoid opening new bins unnecessarily
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 30.0;
    }

    // Mild penalty for very small dead space that likely becomes waste
    if post_residual > 0 && post_residual < 5 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that can't fit typical small items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits the post residual, reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > post_residual {
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it before opening new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening bins when decent fits exist,
    // but allow it when open bins would leave large post residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste_if_open = (bin_capacity - item_size) as f64;
        score = waste_if_open + 20.0 * progress;
        if fitting_bins_count > 0 {
            score += 10.0;
        }
        // Open new bin is attractive when existing residuals are large and fragmented.
        if mean_residual < 20.0 {
            score -= 6.0;
        }
    }

    // Prefer filling bins with larger residual when many bins are open.
    score += 0.02 * open_bins_count as f64 * (bin_residual as f64 - mean_residual).abs().signum() * (bin_residual as f64 - mean_residual);

    // Mild time-decay toward greedy tight packing late in stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer minimal post residual, with non-linear (quadratic) penalty
    let mut score = norm_post + 0.8 * norm_post * norm_post;

    // Smooth polynomial coupling of residual waste with stream progress:
    // early on, waste is tolerable; later, waste becomes increasingly costly
    let coupling = 1.0 + 2.0 * progress * progress + 1.5 * progress;
    score *= coupling;

    // Interaction: small residual relative to mean residual is a good tight fit
    let mean_norm = mean_residual / cap;
    score -= 0.5 * (1.0 - norm_post) * mean_norm * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 1.0 + 1.5 * progress;
    } else {
        score += 0.1 * (fitting_bins_count as f64).powf(0.5);
    }

    // Lookahead: reward bins whose post residual can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            let slack_fit = (post_residual - next_item_size) as f64 / cap;
            score -= 0.6 * (1.0 - slack_fit) * (1.0 - 0.5 * progress);
        } else {
            // penalize residual just barely unable to fit next item (dead space)
            let gap = (next_item_size - post_residual) as f64 / cap;
            score += 0.4 * gap * (1.0 - gap) + 0.2 * progress * gap;
        }
        _ = nxt;
    }

    // New-bin candidate handling: empty bin has moderate default attractiveness;
    // make it less attractive when good fits exist among open bins
    if bin_residual == bin_capacity {
        score += 0.35 + 0.5 * progress;
    }

    // Mild preference to consolidate into fewer bins
    score += 0.02 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space into
    // residue classes modulo 10 (item granularity scale).
    let class = (post_residual % 10) as f64;
    let class_quot = (post_residual / 10) as f64;

    // Dead space penalty: residuals that no plausible item (1..=100, typical
    // granularity) can use are heavily punished. Residual < 10 is nearly dead.
    if post_residual < 10 {
        // Perfect or near-perfect fit: reward strongly.
        score -= 40.0;
    } else {
        // Penalize awkward residue classes: leftover with large mod-10 residue
        // wastes space; classes near 0 are cleaner.
        score += class * 0.6;

        // Larger usable chunks (quotient of 10s) are valuable: reward them.
        score -= class_quot * 2.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item
    // fits poorly everywhere else or the stream is early and we need spread.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Opening new bins is cheap early, expensive late.
        score += 30.0 + 40.0 * progress;
        // If the item is huge relative to capacity and leaves a small odd
        // residual elsewhere, a fresh bin may still win: soften slightly.
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Lookahead coupling: if the next item would fit exactly into the
    // post-residual, reward this placement (harmonic chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            // Prefer placements that leave room for the next item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 - slack * 0.15;
        } else {
            // Next item won't fit here: mild penalty scaled by overflow.
            let over = (next_item_size - post_residual) as f64;
            score += over * 0.1;
        }
    }

    // Mean-residual coupling: placing into a bin far below the mean residual
    // (i.e., unusually full bin) is good; bins far above mean are wasteful.
    let dev = (bin_residual as f64) - mean_residual;
    score -= dev * 0.08;

    // Slight preference to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: gaps too small for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits
    score -= (item_size as f64 / bin_capacity as f64) * 15.0;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open bins pressure: penalize new bins when many bins are open
    if bin_residual == bin_capacity {
        score += 8.0 + open_bins_count as f64 * 2.5;
    }

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Mild preference for bins with below-average residual (consolidation)
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64) * 5.0;

    // Late in stream: prefer filling existing bins more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: if next item exactly fills post_residual, strongly reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to tightness
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 100.0 * tightness;
        } else {
            // next item cannot fit: penalize wasted residual
            score += 0.5 * post_residual as f64;
        }
    }

    // Compare residual against mean residual: prefer bins tighter than average
    score += 0.3 * (mean_residual - bin_residual as f64).max(-50.0);

    // Last-chance bin: strong reward to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize leaving small unusable dead space (wedge zones)
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // New-bin candidate: only attractive when open bins fit poorly
    if bin_residual == bin_capacity {
        let poor_fit = if fitting_bins_count <= 1 { 0.0 } else { 200.0 };
        score += 30.0 + poor_fit - (mean_residual - item_size as f64).max(0.0) * 2.0;
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) more aggressively.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize awkward residuals that few future items could use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space trap
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; mild penalty proportional to leftover waste
            score += 5.0 * (post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: prefer any fit, minimize post residual.
        score += 0.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Global pressure: many open bins with high mean residual -> prefer filling existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if mean_residual > item_size as f64 * 1.5 && open_bins_count > 2 {
        score -= 10.0 * (mean_residual / bin_capacity as f64) * (0.5 + progress);
    }

    // New-bin candidate handling: empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decreasing late in the stream.
        score = bin_capacity as f64 * (0.9 - 0.2 * progress);
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 20.0; // pairing large items in a fresh bin
        }
    }

    // Slight preference for bins whose residual is close to the item (best-fit flavor).
    let fit_gap = (bin_residual - item_size) as f64;
    score += 0.1 * fit_gap;

    // Non-linear coupling: penalize leaving residuals in the "hard to fill" 30..50 zone.
    if post_residual >= 30 && post_residual <= 50 {
        score += 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr_norm = pr / cap;

    // Base: quadratic penalty on wasted space, weighted by stream progress
    let mut score = pr_norm * (1.0 + pr_norm) * (1.0 + progress);

    // Smooth coupling: post_residual interacting with mean residual across open bins
    score += 0.5 * pr_norm * pr_norm * (mean_residual / cap);

    // Reward tight fits smoothly: subtract a bell-shaped function of post_residual
    let tight = (-((pr - 5.0) * (pr - 5.0)) / 50.0).exp();
    score -= 2.0 * tight * (1.0 + progress);

    // Last-chance bonus: smooth reward when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 3.0 * (1.0 + progress);
    }

    // Lookahead: penalize bins whose post-residual can't fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).max(0.0) / cap;
        let miss = (nxt - pr).max(0.0) / cap;
        score += 1.5 * miss * miss * cap * 0.01;
        score -= 1.0 * gap * gap;
    }

    // Mild penalty for proliferating bins late in the stream
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "usable" residue classes (multiples of 10, small gaps) are preferred.
    let pr = post_residual;
    let class: i64 = if pr == 0 {
        -40 // perfect fit: strongly reward
    } else if pr % 10 == 0 {
        -15 // round residual, easy to refill later
    } else if pr <= 10 {
        -10 // tiny gap, effectively sealed
    } else {
        (pr % 10) as i64 * 3 // penalize awkward remainders
    };
    score += class as f64;

    // Dead-space penalty grows if the leftover can't hold the next item.
    if next_item_size > 0 {
        if pr >= next_item_size {
            score -= 8.0; // this bin stays useful for the lookahead item
        } else if pr < next_item_size && pr > 0 {
            score += (next_item_size - pr) as f64 * 0.5; // stranded space
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate: discourage opening fresh bins unless current bin is a bad fit.
    if bin_residual == bin_capacity {
        // A fresh bin is attractive only when the current placement leaves
        // a large awkward residual or the item is large.
        let awkward = if pr > 0 && pr % 10 != 0 && pr > 10 { 1.0 } else { 0.0 };
        score += 25.0 - awkward * 20.0 - (item_size as f64 * 0.15);
    }

    // Stream progression: later in the stream, prefer tighter packing (smaller post_residual).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    // Slight penalty when this bin is far below the mean residual (wasteful spread).
    if (bin_residual as f64) > mean_residual + 30.0 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strong discount as post_residual approaches 0
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (<= 10) are pure waste; penalize heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // "Awkward gap" zone: residual too small for the lookahead item but
    // nonzero -> likely dead space; scale penalty by gap smallness.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 * (1.0 - (post_residual as f64) / (next_item_size as f64));
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead synergy: residual after placement still fits next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening new
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open,
        // unless it would create a perfectly sized fresh start late in stream.
        score += open_bins_count as f64 * 3.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 15.0; // fresh bin keeps room for a big lookahead
        }
    } else {
        score -= open_bins_count as f64 * 1.5;
    }

    // Stream progression: early on, be a bit more willing to fill existing
    // bins loosely; later, be strict about dead space.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 8.0 * tightness;
    if post_residual > 0 && post_residual < 10 {
        score += progress * 20.0;
    }

    // Mean residual coupling: bins far below mean residual are underfilled;
    // prefer placing into bins whose residual is close to item need.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact 2-step match: post_residual equals next item size -> perfect chain
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 25.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            // dead space relative to next item
            let waste = post_residual as f64;
            score += waste * 0.8;
        }

        // combined fit: item + next item both fit
        let two = item_size as f64 + next_item_size as f64;
        if bin_residual as f64 >= two {
            let after_two = bin_residual as f64 - two;
            score -= 20.0 * (1.0 - after_two / bin_capacity as f64);
        }
    } else {
        // last item: prefer tightest fit
        score += (post_residual as f64) * 0.1;
    }

    // penalize small unusable residuals (dead space < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // reward tightness relative to mean residual
    score -= (mean_residual - post_residual as f64) * 0.3;

    // last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // new-bin candidate: penalize mildly so it's chosen only on poor fits
    if bin_residual == bin_capacity {
        score += 40.0 + 10.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // prefer fuller bins early, spread later
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * (item_size as f64 / 100.0) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward small residuals (dead space zones).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item would fit exactly in the post residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_fit = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - next_fit / bin_capacity as f64);
            // Perfect chaining bonus
            if post_residual == next_item_size {
                score -= 20.0;
            }
        } else {
            // Placing here makes post-residual unusable for next item
            score += 8.0;
        }
    }

    // Last chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity when open bins
    // have plenty of room; but prefer a fresh bin when all fits would be terrible.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so new bins are only chosen when genuinely better.
        score += 15.0 + open_bins_count as f64 * 2.0;
        // If no existing bin gives a decent fit (post_residual would be tiny junk),
        // a fresh bin becomes attractive.
        if !fitting_bins_count == false && post_residual < 15 {
            score -= 40.0;
        }
        // Early stream: slightly prefer accumulating bins with good structure.
        let t = step_index as f64 / (total_items.max(1) as f64);
        score -= 5.0 * (1.0 - t);
    } else {
        // Prefer bins with residual close to item (best-fit style) beyond raw post_residual.
        let spread = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * spread;
        // Slight preference for filling bins with low residual overall (bin closing).
        if bin_residual < 40 {
            score -= 6.0;
        }
    }

    // Global pressure: when many bins are open, consolidate into existing bins.
    score += open_bins_count as f64 * 0.3 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap; // normalized post residual in [0,1]

    // Base: prefer tight fits (low post residual)
    let mut score = pr as f64;

    // Smooth non-linear coupling: quadratic growth penalizes mid-size waste
    score += 40.0 * norm_pr * norm_pr * (1.0 + progress);

    // Cubic term: as stream progresses, demand ever-tighter fits
    score += 25.0 * norm_pr.powi(3) * progress;

    // Lookahead coupling: reward leaving space close to next item size
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let norm_gap = gap / cap;
        score += 20.0 * norm_gap * (0.5 + progress);
        // Bonus if next item fits exactly-ish
        score -= 15.0 * (1.0 - norm_gap.min(1.0)) * (1.0 - progress * 0.5);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - norm_pr);
    }

    // Many fitting bins: mild penalty to spread items evenly, prefer fullest bin
    score += 3.0 * (fitting_bins_count as f64).ln().max(0.0);

    // Mean residual interaction: avoid bins far from the fleet mean when mean is high
    score += 5.0 * ((pr - mean_residual) / cap).abs() * progress;

    // New-bin candidate: penalize opening a new bin, more so as stream progresses
    if bin_residual == bin_capacity {
        score += 60.0 + 40.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the resulting gap (modulo arithmetic on post_residual) ---
    // Gaps that are "harmonically useful" (multiples of common item sizes 10/20/25/50)
    // are rewarded; awkward gaps are penalized.
    let pr = post_residual;
    let harmonic_bonus: f64 = if pr == 0 {
        -60.0 // perfect closure
    } else if pr % 50 == 0 {
        -18.0
    } else if pr % 25 == 0 {
        -12.0
    } else if pr % 20 == 0 {
        -10.0
    } else if pr % 10 == 0 {
        -6.0
    } else {
        // awkward gap: penalize proportionally to how small/prime it is
        let awkward = (pr % 10) as f64;
        4.0 + 0.5 * awkward
    };
    score += harmonic_bonus;

    // --- Integer-division thresholds: gap classes via pr / 10 ---
    let gap_class = pr / 10; // 0..=10
    match gap_class {
        0 => score -= 15.0,             // near-perfect fit
        1 => score += 6.0,              // dead space 10-19 (rarely reusable)
        2 | 3 => score += 2.0,          // marginal
        4 | 5 => score -= 3.0,          // half-bin class, reusable
        _ => {}                          // large gaps are fine
    }

    // --- Lookahead coupling: does the gap fit the next item exactly / at all? ---
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 25.0; // gap consumed exactly by lookahead item
        } else if pr >= next_item_size {
            let slack = (pr - next_item_size) as f64;
            score -= 0.3 * slack; // gap remains usable after next item
        } else {
            let deficit = (next_item_size - pr) as f64;
            score += 0.4 * deficit; // next item won't fit here; gap likely wasted
        }
    }

    // --- Last-chance bin: strongly favor using the only fitting bin ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // --- Fractional capacity coupling: reward tightness relative to capacity ---
    let tightness = (item_size as f64) / (bin_capacity as f64);
    score -= 10.0 * tightness;

    // --- New-bin candidate (empty bin): penalize unless current bins are crowded ---
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = mean_residual / (bin_capacity as f64);
        // open a new bin when existing residuals are small (crowded) or stream is late
        score += 30.0 - 25.0 * crowding - 15.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is mandatory
        }
    } else {
        // mild preference to keep bins balanced: penalize deviation from mean residual
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.15 * dev;
    }

    // --- Modulo coupling between item and residual (harmonic compatibility) ---
    if bin_residual % 10 == item_size % 10 && item_size > 1 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Define a "dead zone" threshold relative to typical small items.
    let dead_zone = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        // Gap too small for the smallest possible item (1): pure waste.
        score += (dead_zone - post_residual as f64) * 8.0;
    } else if post_residual == 0 {
        // Perfect fill: strongly reward.
        score -= 40.0;
    }

    // Reward tight fits (small waste ratio) non-linearly.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += waste_ratio * waste_ratio * 30.0;

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // reward this placement strongly (chain of perfect fits).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain_tightness = (post_residual - next_item_size) as f64;
            score -= 15.0 - chain_tightness * 0.5;
        } else if post_residual > 0 && post_residual < next_item_size {
            // Post-residual too small for next item: penalize mildly if it's dead space.
            score += 5.0;
        }
    }

    // Open bins pressure: discourage spreading across many bins; encourage
    // filling existing bins when many are open.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.4 + 0.6 * progress) * 2.0;

    // Mean residual coupling: bins with residual far below mean are closer to
    // being closed out; prefer placing into them to consolidate.
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score -= deviation * 0.15;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + (post_residual as f64) * 0.1;
    }

    // New-bin candidate: make the empty bin attractive only when the item is
    // large or all existing fits would leave big dead space.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 > 60.0;
        if large_item {
            score -= 10.0; // large items start fresh bins more freely
        } else {
            score += 25.0; // small/medium items should fill existing bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact/near-exact fits (dead-space minimization)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 50.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // matches the next item size well.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if next_item_size <= post_residual {
            // next item fits in this bin afterwards: reward closeness
            score -= 120.0 * (1.0 - gap / bin_capacity as f64);
            if gap < 5.0 {
                score -= 80.0; // near-perfect two-item chain
            }
        } else {
            // next item won't fit here: penalize residual that is too large
            // to be useful but too small for typical items
            score += 30.0 + 0.5 * (post_residual as f64);
        }
    }

    // Relative-to-mean coupling: prefer bins with below-average residual
    // (denser bins) so sparse bins stay available for large items.
    score += 0.8 * (post_residual as f64 - mean_residual).max(0.0);
    score -= 0.3 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a brand-new bin unless current bins are poor fits
    if bin_residual == bin_capacity {
        // new bin baseline: attractive only if item is large or fits are bad
        let fit_quality = if post_residual == 0 { 0.0 } else { post_residual as f64 };
        score += 60.0 + fit_quality * 0.5;
        if next_item_size > 0 && next_item_size <= bin_residual - item_size {
            score -= 40.0; // new bin can host item + next item
        }
        if item_size >= 70 {
            score -= 70.0; // large items: fresh bin is fine
        }
    }

    // Early stream: slightly favor packing into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 20.0 * (1.0 - progress);
    }

    // Mild penalty proportional to item size mismatch with residual
    score += 0.1 * ((bin_residual as f64 - item_size as f64) - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post_residual relative to item, the better.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 18.0 * tightness * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Penalize dead space: residuals too small for typical future items are wasted.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < next_item_size.max(1) && next_item_size > 0 {
        score += 8.0; // residual can't hold the known next item
    }

    // Lookahead coupling: bonus if this placement leaves room exactly for the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 3 {
        score += 2.0 * (fitting_bins_count as f64 - 3.0).min(6.0);
    }

    // Global state: when open bins are collectively full (low mean residual),
    // opening a new bin becomes more attractive; penalize stuffing this bin less.
    let fill_pressure = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
    score += 10.0 * fill_pressure * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: early in the stream, prefer spreading items (keep residuals flexible);
    // late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 6.0 * (post_residual as f64 / bin_capacity as f64);
    score -= progress * 9.0 * tightness;

    // New-bin candidate handling: an empty bin is a fresh resource; prefer it when
    // the item is large and would leave a very awkward residual in an open bin,
    // or when fill pressure is high.
    if bin_residual == bin_capacity {
        let awkward = (post_residual > 0 && post_residual < 20) || fill_pressure > 0.75;
        if awkward {
            score -= 20.0;
        } else {
            score += 14.0; // keep using existing bins when fit is decent
        }
    }

    // Mild penalty for very large item in nearly-full bin creating sliver.
    if item_size >= 60 && post_residual > 0 && post_residual < 15 {
        score += 10.0;
    }

    // Tie-break: prefer bins with residual close to capacity (less committed bins) early on.
    score += 0.05 * (bin_capacity as f64 - bin_residual as f64) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Quadratic waste penalty: dead space hurts super-linearly.
    let norm_post = post / cap;
    score += 30.0 * norm_post * norm_post * cap;

    // Smooth stream-progress coupling: tighten fits as stream advances.
    score -= (1.0 - progress) * 8.0 * norm_post * cap;

    // Lookahead: reward leaving space usable by the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = (post - nxt) / cap;
            score -= 12.0 * (1.0 - slack * slack);
        } else {
            let miss = (nxt - post) / cap;
            score += 10.0 * miss * miss * cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: penalize mildly, but relax when existing fits are poor.
    if bin_residual == bin_capacity {
        let base_penalty = 20.0;
        let poor_fit_bonus = if fitting_bins_count >= 1 {
            (post / cap) * 15.0
        } else {
            0.0
        };
        let crowding = (open_bins_count as f64).ln().max(0.0);
        score += base_penalty + poor_fit_bonus - 1.5 * crowding;
    }

    // Mean-residual coupling: prefer bins close to the mean residual (balanced usage).
    let dev = (post - mean_residual).abs() / cap;
    score += 5.0 * dev * dev * cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo-10 classes capture
    // which future item sizes (multiples of 10 dominate typical streams)
    // can still exploit the leftover space.
    let harmonic_class = post_residual % 10;
    score -= (harmonic_class as f64) * 0.6; // prefer residuals that are "round" multiples

    // Integer division thresholds: residuals divisible into usable chunks
    // (>= 10) are valuable; tiny fragments (< 10) are dead space.
    let usable_chunks = post_residual / 10;
    score -= (usable_chunks as f64) * 2.0;
    if post_residual < 10 {
        score += 25.0; // dead space penalty
    }

    // Perfect fit: zero post residual is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: can the next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // harmonic match: next item aligns with residual class
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 8.0;
            }
        } else {
            score += 6.0; // next item won't fit here; bin likely closes
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost so it is
    // chosen only when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        score = 40.0 + (post_residual as f64);
        // late in the stream, prefer reusing open bins even more
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
        // if several bins fit, opening a new one is wasteful
        if fitting_bins_count > 1 {
            score += 20.0;
        }
    }

    // Mild pressure toward consolidating into bins below mean residual
    // (i.e., tighter bins) to keep a pool of flexible bins open.
    if (post_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize residuals that are too small
    // to plausibly hold a future item (below the minimum item size of 1,
    // but practically below a usable threshold).
    let usable_threshold = 20.0;
    if (post_residual as f64) < usable_threshold && post_residual > 0 {
        score += (usable_threshold - post_residual as f64) * 6.0;
    }

    // Reward tight fits: item fills the bin almost exactly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating
    // into existing bins rather than opening more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64) * (0.5 + 0.5 * progress);
    score += pressure * 0.8;

    // New-bin candidate: only attractive when item is large relative to
    // capacity or existing bins have poor residuals.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin mildly; offset by dead-space savings
        // when the item is large.
        score += 18.0 - 0.25 * (item_size as f64);
        // If current bin would leave a big dead gap but a fresh bin fits
        // the item snugly, opening is fine.
        if (post_residual as f64) < usable_threshold {
            score -= 12.0;
        }
        // Lookahead: if next item would fit in a fresh bin's residual,
        // opening is more attractive.
        if next_item_size > 0 && next_item_size <= bin_residual - item_size {
            score -= 8.0;
        }
    } else {
        // Existing bin: reward if residual after placement still fits
        // the lookahead item (keeps future flexibility).
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        } else if next_item_size > post_residual {
            score += 3.0;
        }
        // Slight reward for placing into bins with below-average residual
        // (uses up the fullest bins first, best-fit style).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item -> huge reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 1000.0;
        } else if post_residual >= next_item_size {
            // Next item still fits: mild reward proportional to how close.
            score -= 2.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize dead space that is too small to be useful.
            score += 0.5 * post_residual as f64;
        }
    }

    // Prefer tight fits overall.
    score += 0.3 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Align with mean residual of open bins.
    score += 0.1 * (post_residual as f64 - mean_residual);

    // New-bin candidate: default high score so it is only chosen when open bins are poor fits.
    if bin_residual == bin_capacity {
        score = 150.0;
        if fitting_bins_count == 0 {
            score = 0.0; // forced new bin
        } else if next_item_size > 0 && post_residual >= next_item_size {
            // An empty bin guarantees future flexibility; occasionally attractive late in stream.
            let progress = step_index as f64 / total_items.max(1) as f64;
            score = 120.0 - 20.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight fit bonus scaled by tightness
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Lookahead: reward bins whose residual can pair with the next item
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if post_residual as f64 == nr {
            score -= 45.0; // perfect pair
        } else if post_residual >= next_item_size {
            score -= 12.0 * (1.0 - ((post_residual as f64 - nr) / bin_capacity as f64));
        } else {
            // residual too small for next item: penalize proportionally
            score += 8.0 * (1.0 - (post_residual as f64 / nr));
        }
    } else {
        // last item: strongly prefer tightest fit
        score -= 30.0 * tightness;
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Penalize opening a new bin when good fits exist
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 15.0 + 0.5 * open_bins_count as f64;
        // but allow new bin if mean residual is low (all bins nearly full)
        if mean_residual < item_size as f64 * 0.5 {
            score -= 30.0;
        }
    }

    // Time horizon: early in stream, be more selective (favor tight fits);
    // late in stream, prefer consolidating into open bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;
    if !is_new_bin {
        score -= 10.0 * progress;
    }

    // Penalize bins deviating from mean residual (keep residual distribution balanced)
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    // Prefer using fuller bins (small residual) overall
    score += 0.05 * bin_residual as f64 / open_bins_count.max(1) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;
    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = 1.0 + 0.6 * t - 0.8 * t * t + 0.4 * t * t * t;
    score *= poly;
    // Penalize residuals that are small but nonzero (dead space) more as stream advances
    let norm_pr = pr / cap;
    score += 12.0 * norm_pr * (1.0 - norm_pr) * (0.5 + t);
    // Reward near-perfect fits strongly
    score -= 10.0 * (1.0 - norm_pr) * (1.0 - norm_pr);
    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 8.0 * (0.5 + t);
    }
    // Lookahead: favor bins whose post_residual fits the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 6.0 * (1.0 - nx / cap) * (0.5 + t);
        } else {
            score += 4.0 * ((nx - pr) / cap) * (0.5 + t);
        }
    }
    // Discourage proliferation of open bins early; allow more later
    score += (open_bins_count as f64) * 0.5 * (1.0 - t);
    // Mean residual context: penalize bins far from mean residual
    score += 0.15 * (pr - mean_residual).abs();
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: which capacity-fraction band it lives in.
    let class = item_size / 10; // 0..=10 harmonic classes
    let next_class = next_item_size / 10;

    // Reward tight fits: post_residual small relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Dead space penalty: residuals that no harmonic class can ever fill.
    // Residuals in (0,10) are unusable (min item = 1..=100 unknown, but small
    // residuals waste capacity). Penalize residual < 10 heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Residuals that are multiples of 10 are "harmonic-friendly": many classes
    // can exactly fill them later.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Lookahead coupling: if next item's class fits exactly in post_residual,
    // strongly favor this bin (chaining perfect pairs).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 20.0; // perfect chain
        } else if slack % 10 == 0 {
            score -= 10.0; // harmonic chain
        } else {
            score -= 3.0;
        }
    } else if next_item_size > 0 {
        // next item cannot follow here: this bin becomes dead after placement.
        score += 6.0;
    }

    // Class affinity: prefer bins whose residual is in the same harmonic class
    // as the item (residual % 10 == item_size % 10 leaves multiples of 10).
    if bin_residual % 10 == item_size % 10 {
        score -= 4.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 0.1 * (post_residual as f64);
    }

    // New-bin candidate: penalize opening a new bin unless current bins are
    // mostly full or the stream is ending.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_fill = 1.0 - mean_residual / (bin_capacity as f64);
        // Opening new bin is bad when open bins are underutilized.
        score += 18.0 * (1.0 - avg_fill);
        // Late in the stream, consolidating matters more.
        score += 10.0 * progress;
        // If item is large and no bin fits well, new bin is fine.
        if class >= 7 {
            score -= 12.0;
        }
    }

    // Prefer filling bins with larger residuals first when many bins are open
    // (keeps the number of active bins balanced).
    score += 0.02 * open_bins_count as f64;

    // Integer-division threshold: if post_residual falls in a "half class"
    // (40..=60), it's a flexible zone; slight reward.
    if post_residual >= 40 && post_residual <= 60 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 + (10 - post_residual) as f64 / 10.0);
    } else if post_residual >= 10 && post_residual < 25 {
        // Medium-small gaps are moderately wasteful too.
        score += 12.0 * (25 - post_residual) as f64 / 15.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Open-bins pressure: prefer packing into existing bins as bins accumulate.
    let pressure = open_bins_count as f64 * 2.5;
    score -= pressure;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
        if next_item_size == post_residual {
            score -= 25.0;
        }
    }

    // Mean residual coupling: penalize bins far below mean residual (isolated small gaps).
    score += (mean_residual - post_residual as f64).abs() * 0.3;

    // New-bin candidate handling: neutral baseline; only attractive when open bins
    // would create dead space or are crowded.
    if bin_residual == bin_capacity {
        score = 30.0 + open_bins_count as f64 * 2.5;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item -> strong reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // next item fits after this placement; penalize leftover gap
            let gap = (post_residual - next_item_size) as f64;
            score += gap * 0.35;
        } else {
            // next item won't fit here; penalize proportionally to mismatch
            let mismatch = (next_item_size - post_residual) as f64;
            score += mismatch * 0.55;
        }
    }

    // Dead-space penalty: tiny unusable residual (< 10, min item size)
    if post_residual < 10 {
        score += 45.0;
    }

    // Relative-to-mean coupling: prefer bins whose residual usage deviates favorably
    let res_f = post_residual as f64;
    score += (res_f - mean_residual) * 0.25;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Prefer filling fuller bins (tighter residual) slightly more as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_capacity - post_residual) as f64 * 0.05 * (0.5 + progress);

    // Mild penalty for opening new bins when many bins are already open
    if bin_residual == bin_capacity {
        score += 12.0 + open_bins_count as f64 * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fill_ratio * fill_ratio;

    // Penalize leaving large post-residuals relative to capacity (dead space).
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 10.0 * waste * waste;

    // Lookahead: if the next item fits exactly into the post-residual, big bonus.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's early or unavoidable.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = (fitting_bins_count as f64).recip();
        score += 8.0 + 14.0 * (1.0 - progress) * pressure;
        if fitting_bins_count == 0 {
            score -= 30.0; // nothing fits anywhere: new bin is right
        }
    }

    // Global state coupling: prefer bins below mean residual when many bins open.
    if open_bins_count > 1 {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.05 * diff * (open_bins_count as f64).ln();
    }

    // Slight preference for consolidating into emptier bins late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = post;

    // Strong non-linear penalty on wasted space, amplified over stream progress.
    score += 1.8 * (post / cap) * (post / cap) * (1.0 + 2.0 * progress);

    // Reward near-perfect fits with a smooth exponential bonus.
    let tightness = 1.0 - (post / cap);
    score -= 12.0 * tightness * tightness * tightness;

    // Lookahead coupling: reward residuals that match the next item exactly.
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        score -= 6.0 * (-gap / 15.0).exp() * (1.0 + progress);
        // Penalize residuals just below the next item (dead space for lookahead).
        if (post_residual as f64) < next_item_size as f64 {
            score += 4.0 * (1.0 - gap / cap).abs() * (0.5 + 0.5 * progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 + 0.5 * (1.0 - progress));
    }

    // New-bin candidate: penalize opening fresh bins, more so late in stream
    // and when many bins are already open; relax when few bins fit the item.
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        score += 10.0 + 8.0 * progress + 1.5 * open_bins_count as f64 * scarcity;
        // Smooth relaxation when mean residual across bins is large (bins are roomy).
        score -= 3.0 * (mean_residual / cap).min(1.0);
    }

    // Mild preference for filling bins below mean residual (balance avoidance of fragmentation).
    score += 0.05 * (mean_residual - post).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: mod-10 residue classes
    let post = post_residual as i64;
    let next = next_item_size as i64;

    // Reward residuals that are "harmonic" multiples of common item sizes
    for m in [5i64, 10, 20, 25, 50] {
        if post > 0 && post % m == 0 {
            score -= 8.0 * (m as f64 / 50.0);
        }
    }

    // Penalize dead-space classes: residuals in awkward ranges
    if post > 0 && post < 10 {
        score += 30.0; // unusable dead space
    } else if post >= 10 && post <= 20 {
        score += 6.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next > 0 && post == next {
        score -= 40.0;
    } else if next > 0 && post >= next && post - next <= 10 {
        score -= 15.0; // near-perfect chain fit
    } else if next > 0 && post < next && post < 10 {
        score += 10.0; // next item can't use this residue
    }

    // Integer-division threshold on post_residual / item_size ratio
    if item_size > 0 {
        let ratio = post as f64 / item_size as f64;
        if ratio >= 1.0 && ratio < 1.5 {
            score -= 5.0;
        }
    }

    // Capacity fraction classes of current fill
    let fill_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    if fill_frac > 0.75 {
        score -= 12.0; // prefer filling nearly-full bins
    } else if fill_frac < 0.25 {
        score += 8.0; // discourage scattering into fresh bins
    }

    // Last-chance bonus
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no good fits exist
    if bin_residual == bin_capacity {
        let pressure = fitting_bins_count as f64;
        score += 45.0 - 10.0 * pressure.min(4.0);
        if next > 0 && next as f64 > mean_residual {
            score -= 20.0; // open a big bin when residuals are small
        }
    }

    // Mean residual drift: penalize bins far below mean (fragmentation)
    score += 0.15 * (mean_residual - post_residual as f64).abs();

    // Late-stream tightening
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let gap = post_residual as f64;
    if gap > 0.0 && gap < 10.0 {
        score += 40.0 * (10.0 - gap); // tiny dead space is worst
    } else if gap == 0.0 {
        score -= 25.0; // perfect fit reward
    }

    // Dead space relative to likely next-item sizes: penalize gaps that
    // no plausible item (1..100) can usefully fill.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
            score += 30.0; // gap too small even for the known next item
        }
        if post_residual >= next_item_size && post_residual <= next_item_size + 5 {
            score -= 15.0; // near-perfect setup for the lookahead item
        }
    }

    // Open-bins pressure: discourage scattering items when many bins are open.
    let pressure = open_bins_count as f64 / (1.0 + total_items as f64 * 0.05);
    score += 8.0 * pressure;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when open bins would leave large waste
    // or no good fit exists.
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * open_bins_count as f64;
        if gap == 0.0 { score -= 0.0; }
        // fresh bin residual = capacity, treat as neutral-large but not free
        score += 5.0;
    }

    // Mild alignment with mean residual: prefer bins whose residual is tighter
    // than average (fills fuller bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits
    if post_residual <= 2 {
        score -= 40.0;
    } else if post_residual <= 8 {
        score -= 18.0;
    }

    // 2-step lookahead: reward if next item fits snugly into post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post >= nxt {
            let gap = post - nxt;
            if gap <= 3.0 {
                score -= 30.0;
            } else if gap <= 10.0 {
                score -= 14.0;
            } else {
                score -= 6.0 * (1.0 - gap / post.max(1.0));
            }
        } else {
            // next item cannot fit: post_residual risks becoming dead space
            let dead = post / bin_capacity as f64;
            score += 25.0 * dead;
        }
    }

    // Penalize post_residual far from mean residual (fragmentation)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Mild encouragement to consolidate when many bins are open
    score -= 0.5 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: only attractive for large items or when no good fit exists
    if bin_residual == bin_capacity {
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        } else if fitting_bins_count > 0 {
            score += 30.0;
        }
    }

    // Slight time pressure to close bins early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: exponential bonus as post_residual -> 0
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness * tightness;

    // Penalize dead space relative to mean residual of open bins
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    // Lookahead: if next item fits exactly into post_residual, strongly reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_fit = 1.0 - (post_residual - next_item_size) as f64 / (bin_capacity as f64);
        score -= 25.0 * chain_fit;
    } else if next_item_size > post_residual && next_item_size <= bin_capacity {
        // next item cannot use leftover: mild penalty proportional to leftover
        score += 0.1 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }
    // Many alternatives: slight penalty to discourage wasting scarce-fit bins
    if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0);
    }

    // Time horizon: early in stream, be conservative with open bins;
    // late in stream, fill aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: empty bin gets a moderate default cost,
    // rising with number of open bins but falling when open bins are fragmented
    if bin_residual == bin_capacity {
        score = 60.0
            + 3.0 * open_bins_count as f64
            - 20.0 * (1.0 - progress)
            + 0.5 * mean_residual;
        // Open a new bin if item fits poorly everywhere (large post_residual elsewhere)
        if post_residual == bin_capacity && item_size > 0 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;
    // polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * (0.5 + progress);
    score += 30.0 * poly;
    // reward tight fits more strongly as stream progresses
    let tight = 1.0 - norm_pr;
    score -= 20.0 * tight * tight * (0.3 + progress);
    // penalize leaving residuals close to but above next item (near-miss dead space)
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr > 0.0 && pr >= n {
            let gap = (pr - n) / cap;
            score += 15.0 * gap * (1.0 - gap) * (1.0 - progress);
        }
        // reward leaving exactly enough room for the next item
        if (pr - n).abs() < 1.0 {
            score -= 10.0 * (1.0 - progress);
        }
    }
    // last-chance bonus
    if fitting_bins_count == 1 {
        score -= 12.0 * (0.5 + progress);
    }
    // mildly penalize spreading across many open bins
    score += 0.5 * open_bins_count as f64 * norm_pr;
    // new-bin candidate: prefer it only when residual is large and stream is early
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress) - 6.0 * progress;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: how "usable" the leftover space is.
    // Class 0: residual divisible by 10 (clean slot for typical items)
    // Class 1: residual in [1..9] (near-dead space)
    // Class 2: residual in [11..19] (awkward mid slot)
    // Class 3: large residual (still flexible)
    let post = post_residual as u32;
    let class = if post == 0 {
        0u32
    } else if post % 10 == 0 {
        0
    } else if post < 10 {
        1
    } else if post < 20 {
        2
    } else {
        3
    };

    match class {
        0 => score -= 12.0,                       // clean leftover, reward
        1 => score += 8.0 + (10 - post) as f64,   // dead space, penalize
        2 => score += 4.0,                        // awkward slot
        _ => {}
    }

    // Lookahead coupling: does the next item fit exactly into the post-residual?
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 25.0; // perfect follow-up fit
        } else if next_item_size <= post {
            // partial fit: reward proportional to how much of next item's size is covered
            let cover = next_item_size as f64 / post.max(1) as f64;
            score -= 6.0 * cover;
            // harmonic bonus when post % next_item_size == 0 (multiple follow-ups possible)
            if next_item_size > 0 && post % next_item_size == 0 {
                score -= 5.0;
            }
        } else {
            // next item cannot use this bin's leftover; penalize wasted potential
            score += 3.0;
        }
    }

    // Integer-division threshold on residual: bins whose residual is at least
    // half capacity are valuable; near-full bins should absorb items greedily.
    let half = bin_capacity / 2;
    if post <= half {
        score -= 4.0 * (1.0 - post as f64 / (half as f64 + 1.0));
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate (empty bin): only attractive when residuals are badly fragmented.
    if bin_residual == bin_capacity {
        let frag = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        // reward opening a new bin when mean residual is low (open bins nearly full)
        score -= 20.0 * (1.0 - frag);
        // but penalize if many bins already open and stream is late
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 * progress;
        if post == bin_capacity {
            // base cost of a fresh bin when alternatives exist
            score += 10.0;
        }
    }

    // Mild preference for tight fits overall
    score += 0.05 * (post_residual as f64 - (bin_capacity as f64 - item_size as f64)).abs() * 0.0;

    // Tie-break: prefer bins with residual closest to a multiple of the item size
    if item_size > 0 {
        let rem = bin_residual % item_size;
        score -= 2.0 * (1.0 - rem as f64 / item_size as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest item (1..=10) are unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }
    // Tight fit reward: leave nothing behind.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Penalize bins whose remaining space is wasted relative to the stream's needs.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && next_item_size > 0 && (post_residual as u32) < next_item_size {
        score += 25.0 * (1.0 - progress);
    }
    // Reward when this bin can also serve the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // Open-bin pressure: prefer filling existing bins over opening new ones.
    score += open_bins_count as f64 * 3.0;

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: make it unattractive unless open bins are very full.
    if bin_residual == bin_capacity {
        score += 40.0 + mean_residual * 0.5;
    }

    // Prefer bins below mean residual (fill emptier-ish bins to balance)? No:
    // strict dead-space archetype prefers tightest fit; small nudge toward mean.
    score += (post_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: exact match with next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual > next_item_size {
            // Next item could still fit here: mild reward scaled by slack.
            score -= 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // Next item cannot fit the leftover: penalize dead space.
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize bins far below mean residual (already tight bins are precious).
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score += 0.4 * dev;
    } else {
        score += 0.2 * dev;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize unless nothing better exists.
    if bin_residual == bin_capacity {
        score += 50.0;
        // Prefer new bin late in stream when leftovers are large.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits aggressively (non-linear).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Strongly reward exact or near-exact closure of a bin.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this bin;
    // otherwise penalize leaving a residual that is "almost" useful for the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0 * (1.0 - (next_item_size as f64 / post_residual as f64));
        } else {
            // Dead space risk: residual too small for the known next item.
            let waste = post_residual as f64;
            score += 0.35 * waste;
            // If the next item would need a new bin anyway, closing this bin tightly matters more.
            if next_item_size > bin_residual {
                score -= 10.0;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 0.2 * item_size as f64;
    }

    // Penalize dumping into large-residual bins when many bins are open
    // (preserve flexibility), scaled by stream progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive when open bins are fragmented or fit is poor.
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 40.0 - 8.0 * (open_bins_count as f64).ln().max(0.0);
        // Early in the stream, opening bins is cheap; late, prefer consolidation.
        score -= 25.0 * (1.0 - progress);
        let _ = fragmentation;
    } else {
        // Mild penalty for using bins whose residual deviates from the mean
        // (keeps a portfolio of useful gap sizes).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.08 * dev * progress;
    }

    // Prefer filling bins with smaller residuals overall (best-fit core).
    score += 0.10 * bin_residual as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth polynomial coupling of post_residual with stream progress:
    // waste is penalized more strongly as the stream advances (less time to fill gaps).
    let norm_pr = pr / cap; // in [0,1]
    let poly = norm_pr * norm_pr * (1.0 + 3.0 * progress) + norm_pr * (0.5 + 2.0 * progress * (1.0 - progress));
    score += 20.0 * poly;

    // Reward tight fits (small post_residual) with a smooth super-linear bonus.
    score -= 30.0 * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Dead-space penalty: post_residual too small to hold the smallest plausible item.
    let dead = (1.0 - (pr / 10.0).min(1.0)) * (pr / 10.0).max(0.0);
    score += 15.0 * dead * (0.5 + progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - 0.5 * progress);
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward; if it barely
    // misses, penalize smoothly.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let diff = pr - ni;
        if diff >= 0.0 {
            score -= 12.0 * (1.0 - (diff / cap)) * (1.0 - progress * 0.5);
        } else {
            score += 8.0 * ((-diff) / cap) * (1.0 + progress);
        }
    }

    // Mild preference for balancing residuals against the mean when many bins are open.
    score += 0.05 * open_bins_count as f64 * (mean_residual - pr).abs() / cap;

    // Slight bias against opening new bins early, stronger late.
    if bin_residual == bin_capacity {
        score += 5.0 + 20.0 * (1.0 - progress) + 10.0 * (fitting_bins_count.max(1) as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: mod-10 bands penalize "dead zones"
    let pr = post_residual;
    let class = pr % 10;
    // Residuals in [1..9] are hard to fill; 0 is perfect; >=10 still usable.
    if pr == 0 {
        score -= 60.0; // perfect fit reward
    } else if pr < 10 {
        score += 25.0 + (10 - pr) as f64; // unusable sliver penalty
    } else {
        // mild reward for residuals that are nice multiples of 5/10
        if pr % 10 == 0 {
            score -= 8.0;
        } else if pr % 5 == 0 {
            score -= 4.0;
        } else {
            score += class as f64 * 0.5;
        }
    }

    // Integer-division threshold: can next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits here: reward chaining, more if snug
            let slack = pr - next_item_size;
            score -= 12.0;
            if slack == 0 {
                score -= 15.0; // perfect pair
            } else if slack < 10 {
                score += 8.0; // leaves sliver after next
            }
        } else {
            // next item cannot follow into this bin
            score += 6.0;
            if pr >= 10 {
                score += (pr / 10) as f64 * 0.5; // larger wasted potential
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: keep empty bins neutral-high unless
    // current bin fit is bad or nothing fits well.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual < 10 && post_residual > 0;
        if bad_fit {
            score -= 20.0; // opening fresh bin beats making dead space
        } else {
            score += 15.0 + 0.1 * open_bins_count as f64; // prefer existing bins
        }
    }

    // Tight bins (small residual fraction) are precious; prefer filling them
    let frac = bin_residual as f64 / bin_capacity as f64;
    score += frac * 5.0;

    // Mean residual coupling: if average residual is small, conserve tight fits
    if (mean_residual - item_size as f64).abs() < 5.0 {
        score -= 5.0;
    }

    // Stream progression: late in stream, be greedier about perfect fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    if pr == 0 {
        score -= 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps more than proportionally.
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap < 10.0 {
            score += 60.0 * (10.0 - gap); // tiny gaps are almost worthless
        } else if gap < 20.0 {
            score += 20.0 * (20.0 - gap) / 10.0;
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Pressure from number of open bins: discourage spreading when many bins open.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: penalize opening a new bin unless current bin leaves a bad gap.
    if bin_residual == bin_capacity {
        score += 25.0;
        // But if the item nearly fills a fresh bin, opening is fine.
        if item_size as f64 >= 0.9 * bin_capacity as f64 {
            score -= 60.0;
        }
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        score += 10.0; // post gap won't serve next item
    }

    // Progression: later in stream, be more conservative with dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += gap_weight(progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

fn gap_weight(progress: f64) -> f64 {
    10.0 + 30.0 * progress
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item exactly fills the post residual, this is ideal
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward tight packing, penalize large slack after next
            let after_next = post_residual - next_item_size;
            score -= 100.0 - after_next as f64;
        } else {
            // next item does not fit here: penalize wasted residual that next item could have used elsewhere
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // last item: just prefer minimal residual
        score -= 50.0;
    }

    // Reward bins tighter than average residual (good fit relative to fleet)
    score -= 0.6 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize opening a new bin when plenty of bins fit the item
    if bin_residual == bin_capacity {
        score += 40.0 * (fitting_bins_count as f64).max(1.0);
        // new bin is fine if post residual matches next item
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    // Slightly prefer keeping number of open bins low early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // Post-residual is dead space relative to the upcoming item; penalize
            // proportionally to how close it is to being usable (near-miss waste).
            let waste = post_residual as f64;
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * waste;
            if gap <= 10.0 {
                score += 8.0; // tantalizing but unusable dead space
            }
        }
    } else {
        // Last item: maximize final fill aggressively.
        score -= 40.0 * fit_ratio;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it over
    // opening a new bin, especially when the item is small relative to capacity.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 + 0.2 * item_size as f64;
    }

    // Penalize scattering into many open bins when they are mostly empty:
    // encourage consolidation by favoring bins below mean residual (fuller bins).
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // Time horizon: early in the stream, be conservative (favor opening bins
    // with balanced residuals); late in the stream, prioritize closing bins out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * fit_ratio;
    if progress > 0.8 && post_residual <= 10 {
        score -= 20.0; // late-stream: hunt for near-exact closures
    }

    // New-bin candidate calibration: empty bin gets a neutral-ish baseline;
    // only choose it when open bins would leave large unusable residuals.
    if bin_residual == bin_capacity {
        score = 0.5 * (bin_capacity as f64 - item_size as f64)
            + 0.5 * mean_residual
            - 4.0 * (open_bins_count as f64).ln().max(0.0);
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0;
        }
    }

    // Mild penalty for opening yet another bin when many are already open.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let mut score = post;

    // Non-linear penalty on post_residual, rewarding tight fits quadratically
    let fit_frac = 1.0 - post / cap;
    score -= 12.0 * fit_frac * fit_frac * fit_frac;

    // Smooth interaction: tight fits matter more as stream progresses
    score -= 8.0 * fit_frac * fit_frac * progress;

    // Penalize large dead space with cubic growth
    score += 0.002 * post * post * post / cap;

    // Last-chance bin bonus (smooth gate via fitting_bins_count)
    let last_chance = 1.0 / (fitting_bins_count as f64);
    score -= 15.0 * last_chance * (0.5 + 0.5 * progress);

    // Lookahead: favor bins whose post_residual can host next item
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        score -= 6.0 * (next_item_size as f64 / cap) * (1.0 - progress * 0.5);
    } else if next_item_size > 0 {
        score += 3.0 * (1.0 - post / cap);
    }

    // Mild dispersion penalty: prefer bins near mean residual
    score += 0.05 * ((bin_residual as f64) - mean_residual).abs();

    // New-bin candidate: penalize mildly, less so late in stream
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) + 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover space is.
    // Residuals divisible by 10 are classic-friendly; small odd leftovers are dead space.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit is always best
    } else {
        let class = pr % 10;
        // Penalize awkward leftovers (1..9 residue) proportionally to how small they are.
        if class != 0 {
            score += (10 - class) as f64 * 1.5;
        }
        // Integer-division thresholds: how many "typical" items (>=10) still fit.
        let slots = pr / 10;
        score -= slots as f64 * 4.0;
        if slots == 0 {
            score += 25.0; // bin becomes dead space
        }
    }

    // Lookahead coupling: if next item fits exactly in the post residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 50.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            // Harmonic pairing: reward when leftover after next item is again a round class.
            if slack as u32 % 10 == 0 {
                score -= 15.0;
            }
            score -= (pr / next_item_size.max(1)) as f64 * 2.0;
            score += slack * 0.3;
        } else {
            // Next item cannot use this bin's leftover; leftover likely wasted.
            score += (next_item_size - pr).min(20) as f64 * 0.8;
        }
    }

    // Capacity-fraction logic: favor filling bins past key fractions (50%, 75%, 90%).
    let fill = 1.0 - (post_residual as f64) / cap;
    for (frac, bonus) in [(0.5, 6.0), (0.75, 8.0), (0.9, 10.0)] {
        if fill >= frac && fill - (item_size as f64) / cap < frac {
            score -= bonus; // crossing a threshold with this placement
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bin would leave a bad class
    // and the stream is early (plenty of future items to fill it).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bad_leftover = pr > 0 && (pr % 10 != 0 || pr < 20);
        let next_fits_new = next_item_size == 0 || next_item_size <= bin_capacity;
        if bad_leftover && progress < 0.7 && next_fits_new {
            score -= 20.0 + 15.0 * (1.0 - progress);
        } else {
            score += 35.0; // default: prefer existing bins
        }
    }

    // Mild pressure against bin proliferation.
    score += open_bins_count as f64 * 0.05;

    // Mean-residual coupling: when open bins are already loose, tighten selection.
    score += (mean_residual - pr as f64).max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 40.0; // tiny dead space, nearly unusable
        } else if post_residual < 30 {
            score += 15.0; // awkward gap
        } else {
            // larger residuals are usable: reward them
            score -= (post_residual as f64 - 30.0) * 0.35;
        }
    } else {
        score -= 60.0; // perfect fit
    }

    // Reward tight fits (item fills most of the residual)
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 25.0;

    // Open bins pressure: discourage opening new bins when many are open
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 8.0;
        // opening a new bin is acceptable only if no good fit exists
        if post_residual == bin_capacity as f64 - item_size as f64 {
            score += 5.0;
        }
    } else {
        score -= 10.0; // mild preference for using existing bins
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: prefer residual that can still host the next item
    if next_item_size > 0 {
        if post_residual as u32 >= next_item_size {
            score -= 12.0;
        } else {
            score += 6.0;
        }
    }

    // Early stream: be slightly more conservative about dead space
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0;

    // Mean residual coupling: if open bins are already loose, penalize adding slack
    score += (post_residual as f64 - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: next item exactly fills the bin after this one.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Leftover after next item would also fit here: penalize by gap size.
            let gap = (post_residual - next_item_size) as f64;
            score += gap * 0.5;
        } else {
            // Next item won't fit after this placement: dead space penalty.
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 0.8;
        }
    } else {
        // Last item: prefer tightest fit only.
        score += (bin_capacity as f64 - post_residual as f64) * 0.0;
    }

    // Relative-to-mean residual coupling: bins with residual near mean are neutral;
    // leaving much more than mean residual wastes potential elsewhere.
    let pr = post_residual as f64;
    score += (pr - mean_residual) * 0.15;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent fits exist (new-bin candidate guard).
    if bin_residual == bin_capacity {
        let tightness = (bin_capacity - item_size) as f64;
        score += 20.0 + tightness * 0.3;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // new bin can chain two items
        }
    }

    // Early-stream exploration bias: keep fewer bins open early on.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.3 - 0.2 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward tight fits (small post_residual) — already the base term.

    // Lookahead: bonus if the next item also fits into the post residual
    // (chain packing), scaled by lookahead size fraction.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 0.35 * next_item_size as f64 * (post_residual - next_item_size) as f64 / bin_capacity as f64;
        } else {
            // Post residual likely dead space for the next item; penalize
            // proportionally to how close it is to next_item_size.
            let waste = (post_residual as f64 - (next_item_size - post_residual).min(post_residual) as f64).abs();
            score += 0.10 * waste;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    } else if fitting_bins_count > 1 {
        // Mild preference for bins that are more filled relative to others
        // (best-fit across alternatives).
        score += 0.05 * (fitting_bins_count as f64 - 1.0);
    }

    // Penalize bins whose residual deviates badly from the mean residual:
    // prefer consolidating into below-average-residual (fuller) bins.
    score += 0.15 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);

    // Time horizon: early in the stream, be more conservative about fragmenting
    // space (large post residuals hurt more); late, just pack greedily.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 0.20 * post_residual as f64 / bin_capacity as f64;

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity (then a fresh bin is often fine).
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        score += 12.0 - 10.0 * fill_frac;
        // If no open bin fits, opening is unavoidable — soften the penalty.
        if fitting_bins_count == 0 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits (low post residual), with non-linear shaping
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, tolerate waste (quadratic penalty reduced); late, punish dead space harder
    let progress_coupling = pr_norm * pr_norm * (0.5 + 1.5 * progress) * cap;
    score += progress_coupling;

    // Reward filling bins deeply (large item fraction of residual)
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill * fill;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // partial reward proportional to how well next item uses leftover
        let next_fit = next_item_size as f64 / pr.max(1.0);
        score -= 8.0 * next_fit * (1.0 - next_fit.abs());
    } else if next_item_size > 0 {
        // next item won't fit: penalize leaving moderately-sized leftovers
        score += 5.0 * pr_norm;
    }

    // Mean residual coupling: prefer bins whose residual deviates below mean (tighter bins)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev * (1.0 - progress);

    // Mild penalty for opening new bins early in the stream
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) + 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    let pr = post_residual;
    let class = pr % 10;                     // fine granularity class
    let band = (pr / 25) * 25;               // coarse band: 0,25,50,75,100

    // Penalize dead space that is too small for typical items (1..100 unknown dist).
    // Residuals < 10 are almost surely dead; residuals in [10,30] risky.
    if pr < 10 {
        score += 60.0 - 6.0 * pr as f64;     // strong penalty near 0
    } else if pr < 30 {
        score += (30 - pr) as f64 * 0.8;
    } else if pr >= 50 {
        score -= 12.0;                       // roomy leftover is good
    }

    // Class-based bonus: residuals that are nice multiples of 25 are reusable.
    if band >= 25 && pr % 25 == 0 {
        score -= 8.0;
    }
    // Fine class coupling: even classes slightly favored.
    if class % 2 == 0 {
        score -= 1.5;
    } else {
        score += 1.5;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            if slack < 10 {
                score += 10.0;               // would leave new dead space
            } else {
                score -= (slack / 10) as f64 * 3.0;
            }
        } else {
            // next item won't fit here anyway; slight penalty for wasting a good bin
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: opening a fresh bin is only attractive when open bins
    // are crowded (low mean residual) or late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = mean_residual / cap;  // 0..1, low = crowded
        let penalty = 55.0 * (1.0 - crowding) * (0.4 + 0.6 * progress);
        score += penalty;                    // prefer existing bins when they're full-ish
        if pr == bin_capacity {
            score -= 5.0;                    // trivial exact-fit bonus (item_size==0 case safe)
        }
    }

    // Exact fit reward.
    if pr == 0 {
        score -= 70.0;
    }

    // Mild scaling with item size: prefer placing large items into tight bins.
    score += item_size as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Gap in (0, 10] is "dead" for standard items; scale penalty by gap smallness.
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap < 10.0 {
            score += 60.0 * (10.0 - gap) / 10.0; // tiny gap = worst outcome
        } else if gap < 20.0 {
            score += 25.0 * (20.0 - gap) / 10.0; // marginal gap
        }
        // Perfect fit: strong reward.
        if post_residual == 0 {
            score -= 40.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score += 20.0; // would create dead space for next item
        } else if post_residual < next_item_size && post_residual > 0 {
            score += 8.0; // next item can't use this bin's remainder
        }
    }

    // Open-bins pressure: discourage opening new bins when many bins are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 30.0 + 4.0 * open_bins_count as f64 * (0.5 + progress);
        // Allow new bin if existing fits are poor (this bin would leave tiny gap anyway)
        if post_residual > 0 && post_residual < 10 {
            score -= 45.0;
        }
    } else {
        // Slight reward for using tighter existing bins relative to mean residual.
        score -= 0.05 * (mean_residual - bin_residual as f64);
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits: reward small post_residual nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Aggressive 2-step lookahead: perfect match with next item is heavily rewarded.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // exact two-item fill
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // penalize leftover after hypothetical next placement, scaled by slack size
            score += 0.35 * slack;
            if slack <= 10.0 {
                score -= 15.0; // near-perfect chain
            }
        } else {
            // next item can't fit here regardless; mild penalty grows with gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.10 * gap;
        }
    }

    // Relative to mean residual: prefer bins with less residual than average
    // (concentrate filling) unless post_residual is small.
    let rel = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 8.0 * rel;

    // Last-chance bin: strong reward to use it and avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize tiny useless fragments more than proportionally.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Early in the stream, be slightly more willing to open bins for good future chains.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if no open bin fits well.
        score += 30.0 * (1.0 - progress);
        if fitting_bins_count > 0 && post_residual == bin_capacity {
            // open bins exist that fit; discourage new bin unless lookahead is great
            if next_item_size > 0 && next_item_size <= bin_capacity {
                score -= 0.0; // neutral; base +30 keeps preference for existing bins
            }
        }
    }

    // Mild open-bin pressure: with many open bins, prefer consolidating.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 {
        if next_item_size > 0 && next_item_size <= post_residual {
            // Lookahead item fits exactly or nearly: big reward.
            let gap = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - gap / bin_capacity as f64);
        } else if next_item_size > post_residual {
            // Lookahead cannot use the leftover: penalize proportionally.
            score += 3.0 * (post_residual as f64 / 100.0);
        }
    }

    // Perfect closure bonus: bin fully used.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Many fitting bins: mild penalty for wasting choice on poor fits.
    if fitting_bins_count > 1 {
        score += 0.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Global state coupling: prefer filling bins when mean residual is low (bins nearly saturated).
    let t = step_index as f64 / (total_items.max(1) as f64);
    let mean_gap = (mean_residual - post_residual as f64).abs();
    score += 0.05 * mean_gap;
    score -= (1.0 - t) * 0.5 * (mean_residual / bin_capacity as f64);

    // Late in the stream, consolidate aggressively into existing bins.
    if t > 0.7 && bin_residual != bin_capacity {
        score -= 4.0 * t;
    }

    // New-bin candidate: penalize opening new bins unless current bin fits are very poor.
    if bin_residual == bin_capacity {
        score += 6.0 + 2.0 * open_bins_count as f64 * (1.0 - t);
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // Pair fits in a fresh bin: soften the penalty.
            score -= 5.0;
        }
    }

    // Reward moderate fill of partially used bins (avoid scattering small items).
    let fill_frac = item_size as f64 / bin_residual as f64;
    score -= 3.0 * fill_frac * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let is_new_bin = (bin_residual == bin_capacity) as f64;

    // Base: waste after placement, normalized
    let mut score = pr / cap;

    // Reward tight fits: smooth quadratic decay of waste
    score -= (1.0 - pr / cap).powi(2) * 0.6;

    // Lookahead coupling: if next item fits the post-residual, strongly favor this bin
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = (post_residual - next_item_size) as f64 / cap;
        score -= 0.8 * (1.0 - slack_after_next).powi(2);
    } else if next_item_size > 0 {
        // Next item cannot use leftover: penalize dead space mildly, more as stream progresses
        score += 0.15 * pr / cap * (0.5 + progress);
    }

    // Last-chance bin bonus: only bin that fits -> avoid opening a new bin
    if fitting_bins_count == 1 && is_new_bin < 0.5 {
        score -= 0.5;
    }

    // Penalize the new-bin candidate smoothly; allow it when existing fits are bad
    score += is_new_bin * (0.9 - 0.3 * (pr / cap).powi(2)) * (0.6 + 0.4 * progress);

    // Prefer spreading load when many open bins have large mean residual
    if is_new_bin < 0.5 {
        score -= 0.2 * (mean_residual / cap) * (1.0 - pr / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Best-fit flavor: prefer bins that are already full (small bin_residual)
    score += (bin_residual as f64 / bin_capacity as f64) * 3.0;

    // Harmonic class logic: residuals divisible by 10 are "clean" slots
    // (likely reusable by future items drawn from typical granularities)
    if post_residual % 10 == 0 {
        score -= 4.0;
    } else if post_residual % 5 == 0 {
        score -= 2.0;
    }

    // Penalize tiny dead space: unusable slivers are pure waste
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Lookahead coupling: reward if the next item fits the post-residual
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
        // extra reward when next item exactly fills the bin (perfect chaining)
        if next_item_size == post_residual {
            score -= 4.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        // dead space that the next item cannot use: heavy penalty
        score += 4.0;
    }

    // New-bin candidate handling (empty bin has bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // default: discourage opening a new bin when open bins could fit
        score += 12.0 + open_bins_count as f64 * 0.5;
        // if this is the only (or no) fitting option, opening a new bin is fine
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
        // late in the stream, prefer consolidating into existing bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 6.0;
    }

    // Last-chance bin: if this is the only open bin that fits, strongly favor it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Mild tie-breaker: prefer bins whose residual deviates favorably from mean
    score -= (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any plausible item (1..100) are pure waste.
    // Penalize unusable gaps super-linearly; small gaps below next item are the worst case.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // tiny sliver: nearly unusable
        } else if next_item_size > 0 && post_residual < next_item_size {
            score += 25.0 + 0.5 * (next_item_size - post_residual) as f64; // can't hold the lookahead item
        } else if post_residual > 80 {
            score += 8.0; // near-empty bin barely used
        }
    }

    // Reward tight fits (small post_residual relative to item size)
    score -= 30.0 / (1.0 + post_residual as f64);

    // Perfect or near-perfect closure bonus
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 3 {
        score -= 20.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits, avoiding a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    let open_pressure = open_bins_count as f64;
    if bin_residual != bin_capacity {
        score -= 0.4 * open_pressure;
    } else {
        // New bin: penalize more when many bins are already open
        score += 3.0 + 0.5 * open_pressure;
    }

    // Mean-residual coupling: if open bins are already loose (high mean residual),
    // avoid spreading items into a new bin; prefer filling existing slack.
    if bin_residual != bin_capacity {
        score -= 0.1 * mean_residual;
    } else {
        score += 0.15 * mean_residual;
    }

    // Lookahead synergy: if the next item exactly fits the post residual, big reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 10.0;
    }

    // Slight mid-stream conservatism: keep bins flexible early, pack tightly late
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead: if the next item exactly fills the post residual,
    // strongly reward this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // Next item fits here too: reward proportional to how snugly it fits.
            let slack_after_next = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack_after_next / bin_capacity as f64);
        } else {
            // Next item won't fit in the leftover: penalize proportionally to the gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 8.0 * (gap / 100.0).min(1.0);
        }
    }

    // Penalize tiny unusable residuals (dead space), but reward exact fills.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        score += 6.0;
    }

    // Compare against mean residual: bins tighter than average are better targets.
    score += (post_residual as f64 - mean_residual) * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and no decent fit exists among open bins.
    if bin_residual == bin_capacity {
        score += 15.0;
        if fitting_bins_count == 0 {
            score -= 60.0;
        } else if item_size >= 60 {
            score -= 10.0;
        }
    }

    // Late in the stream, prefer closing bins tightly (consolidation).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals too small to plausibly fit future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Prefer bins with residuals near the mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Late in the stream, consolidate: favor already-open bins over new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 12.0 + 20.0 * progress;
    } else {
        score -= 5.0 * progress;
    }

    // Slight penalty when many bins are open, encouraging reuse.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64) / (total_items as f64).max(1.0);
    let pr_norm = pr / cap;
    let fit_frac = (item_size as f64) / cap;

    // Base: prefer tight fits (small post_residual), with smooth non-linear shaping.
    let mut score = pr * (1.0 + 0.35 * pr_norm * pr_norm);

    // Stream-progress coupling: later in stream, penalize wasted residual more strongly.
    score += 40.0 * progress * pr_norm * pr_norm;

    // Dead-space penalty: residual too small to be useful for typical items.
    let dead = (1.0 - pr_norm).max(0.0);
    score += 8.0 * dead * dead * dead;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: reward if next item fits into post_residual (chaining).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 4.0 * (nxt - pr) / cap;
        }
    }

    // Mild pressure to prefer filling bins when many are open.
    score += 0.5 * open_bins_count as f64 * pr_norm;

    // Slight preference for bins below mean residual (balance avoidance of fragmentation).
    score += 0.1 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction band does it fall in?
    let post = post_residual as f64;
    let frac = post / cap; // 0..1
    let class = (frac * 8.0).floor() as i64; // 8 harmonic classes of capacity

    // Reward small residuals, but with class-quantized jumps (dead-space bands).
    match class {
        0 => score -= 30.0,                 // near-perfect fit
        1 => score -= 18.0,
        2 => score -= 10.0,
        3 => score -= 4.0,
        4 => score -= 2.0,
        5 => score += 3.0,
        6 => score += 8.0,
        _ => score += 14.0,                 // large dead space
    }

    // Modulo arithmetic on post_residual: residuals that are multiples of common
    // item sizes (10, 20, 25, 50) are reusable; odd/prime-ish residuals are not.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 6.0; }
        if post_residual % 20 == 0 { score -= 3.0; }
        if post_residual % 25 == 0 { score -= 3.0; }
        if post_residual % 50 == 0 { score -= 4.0; }
        if post_residual % 2 == 1 { score += 2.5; } // odd residual: harder to fill
        if post_residual < 10 { score -= 12.0; }    // unusable sliver, but "closed" bin
    } else {
        score -= 25.0; // exact fill is ideal
    }

    // Lookahead coupling: if the next item fits the post residual exactly or well,
    // strongly reward this placement (chain packing).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 22.0;
        } else if next_item_size <= post_residual {
            let nfrac = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - nfrac / cap);
        } else {
            // next item won't fit here: penalize leaving awkward gaps
            score += 4.0 * (nxt / cap);
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate handling: empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is fine early (many items remain) or when many bins
        // already open; penalize when stream is nearly done and few bins open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 - 25.0 * progress;
        if open_bins_count > 4 { score -= 8.0; }
        // A new bin is attractive if the item is large and would leave bad fits elsewhere
        if item_size as f64 / cap > 0.7 { score -= 10.0; }
    }

    // Mean residual context: if this bin's residual is far below the mean, it's a tight fit — good.
    let dev = mean_residual - post;
    if dev > 0.0 { score -= 2.0 * dev.min(20.0) / 10.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (1..=10) are heavily penalized.
    if post_residual >= 1 && post_residual <= 10 {
        score += 25.0 + (10 - post_residual) as f64 * 3.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += 6.0; // mildly risky gap
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 15.0;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: discourage opening new bins when several are open,
    // but relax pressure late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (3.0 - 2.0 * progress);
    if bin_residual == bin_capacity {
        score += pressure + 10.0;
    } else {
        score -= pressure * 0.5;
    }

    // Prefer bins whose residual deviates from the mean (consolidate slack).
    score += (bin_residual as f64 - mean_residual).abs() * 0.15;

    // Lookahead: if the next item would fit into the post_residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 200.0;
    }

    // Lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        // Exact 2-step chain: item then next item exactly fills bin
        if post_residual == next_item_size {
            score -= 120.0;
        }
        // Penalize leaving residual just below next item (dead space)
        if post_residual > 0 && post_residual < next_item_size {
            score += 25.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.8 * (mean_residual - post_residual as f64);

    // Penalize very small unusable residuals (fragmentation)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate: mildly penalize so we prefer reusing open bins,
    // unless current fit is terrible (large post_residual vs mean)
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > mean_residual + item_size as f64 * 0.5;
        score += if poor_fit { -40.0 } else { 70.0 };
    }

    // Late in stream: consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual already does this); add quadratic dead-space penalty
    let dead = post_residual as f64;
    score += 0.35 * dead * dead / bin_capacity as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead: if next item fits in the post residual, reward leaving that space
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // post residual likely unusable for next item: penalize proportionally
        score += 0.15 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Many open bins with large mean residual: prefer consolidation into existing bins
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 0.10 * mean_residual;
    }

    // New-bin candidate handling: default penalty so existing bins win,
    // but allow opening a new bin when fits are scarce or item is large
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let large_item = (item_size as f64 / bin_capacity as f64).powi(2);
        let early = (1.0 - progress) * 0.5;
        score += 30.0 - 45.0 * scarcity - 20.0 * large_item - 15.0 * early;
        // if it truly cannot fit anywhere else, new bin must win
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Late in stream: avoid leaving tiny residuals that waste capacity
    if progress > 0.7 && post_residual > 0 && post_residual < 10 {
        score += 12.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with non-linear sharpening.
    let mut score = post + (post / cap).powi(3) * cap * 2.0;

    // Penalize residual that cannot fit the lookahead item (dead space).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual < next_item_size {
            let unusable = (next_item_size - post_residual) as f64;
            score += unusable * (0.5 + 1.5 * progress) * (nx / cap);
        } else {
            // Reward bins that can still host the next item: smooth coupling.
            score -= (nx / cap) * (1.0 - (post / cap).powi(2)) * 4.0;
        }
    } else {
        // Last item: strongly prefer minimal final residual.
        score -= (cap - post) * 0.5;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= cap * 0.8;
    } else if fitting_bins_count > 1 {
        // Among many candidates, tighten preference toward exact fills.
        score += (post / cap).powi(2) * 3.0;
    }

    // New-bin candidate handling: neutral-ish but adapts to stream state.
    if bin_residual == bin_capacity {
        // Opening a new bin is good when open bins are already fragmented
        // (high mean residual spread) or this bin would leave a poor residual.
        let fragmentation = (mean_residual / cap - post / cap).abs();
        score = post + 5.0 + fragmentation * 10.0 - progress * 3.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 2.0; // fresh bin can host the next item too
        }
        if fitting_bins_count <= 1 {
            score -= 10.0; // no real alternative: new bin is fine
        }
    }

    // Mild global pressure: many open bins -> favor filling existing ones.
    score += open_bins_count as f64 * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: classify dead space by modulo classes.
    // Residuals that are multiples of common item sizes (or near-capacity) are reusable.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        -60.0 // perfect fit, best possible
    } else if pr >= 10 && pr <= 80 {
        // residual in item-size range: likely fillable by a future item
        -25.0
    } else if pr > 80 {
        -10.0 // large residual, still quite usable
    } else {
        // 1..9: dead-space danger zone
        30.0
    };
    score += harmonic_bonus;

    // Modulo-10 class: residuals divisible by 10 align with the decimal grid
    // of item sizes and are more likely to be exactly consumed.
    if pr % 10 == 0 && pr > 0 {
        score -= 12.0;
    }
    // Harmonic sub-classes: multiples of 5 and 20 are secondary alignment points.
    if pr % 5 == 0 && pr % 10 != 0 {
        score -= 4.0;
    }
    if pr % 20 == 0 && pr > 0 {
        score -= 3.0;
    }
    // Odd residuals below 10 are worst: heavily penalize.
    if pr < 10 && pr % 2 == 1 {
        score += 15.0;
    }

    // Lookahead coupling: if the next item cannot fit in post_residual,
    // this residual becomes locked dead space until later.
    if next_item_size > 0 {
        if next_item_size > pr {
            // dead space relative to the immediate future; worse when small
            let lock = (next_item_size - pr) as f64;
            score += 0.6 * lock;
            // extra penalty if residual falls in dead zone AND next item can't use it
            if pr < 10 {
                score += 10.0;
            }
        } else if next_item_size == pr {
            score -= 40.0; // next item perfectly completes this bin
        } else {
            // next item fits: reward tight two-step packing
            let after2 = pr - next_item_size;
            score -= 8.0;
            if after2 % 10 == 0 {
                score -= 6.0;
            }
            if after2 < 10 && after2 > 0 {
                score += 8.0; // would create fresh dead space
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless it creates terrible dead space).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
        if pr < 10 && next_item_size > pr {
            score += 20.0; // but not if it strands tiny dead space
        }
    }

    // New-bin candidate: empty bin has bin_residual == bin_capacity.
    // Prefer reusing open bins generally; only allow new bin when open bins
    // are nearly full (mean_residual low) or many bins already fit.
    if bin_residual == bin_capacity {
        score += 45.0; // base cost of opening a new bin
        // If open bins are nearly exhausted (low mean residual), new bin is fine.
        score -= (cap - mean_residual).max(0.0) * 0.5;
        // Early in stream, opening bins is cheaper (builds a pool of residuals).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        // If many bins fit already, definitely don't open a new one.
        if fitting_bins_count > 2 {
            score += 25.0;
        }
    }

    // Mild preference for tighter (fuller) bins overall, scaled by stream progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.15 * post * (0.5 + progress);

    // Prefer bins whose residual deviates from the mean toward small values
    // (consolidate fullness into few bins).
    if bin_residual < bin_capacity {
        score += 0.2 * (post - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to be useful
    // (below the minimum plausible item size) are heavily penalized.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // unusable sliver -> strong penalty
        } else if post_residual <= 20 {
            score += 25.0; // marginal gap -> moderate penalty
        } else if post_residual <= 40 {
            score += 8.0;  // partially usable
        } else {
            score -= 10.0; // large residual remains flexible
        }
    } else {
        score -= 80.0; // perfect fill: reward heavily
    }

    // Reward tight fits relative to the item size (low waste ratio).
    let waste_ratio = post_residual as f64 / (bin_residual as f64 + 1.0);
    score += 30.0 * waste_ratio;

    // Open-bin pressure: discourage scattering items across many bins
    // when few bins are open; encourage consolidation later.
    score += (open_bins_count as f64) * 0.8;

    // Last-chance bonus: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // New-bin candidate: make the empty bin attractive only when the
    // item fits poorly everywhere else (i.e., its natural score is low
    // only for large post_residual). Penalize new bins slightly by
    // default so consolidation wins ties, but keep them viable for
    // items that would strand big items.
    if bin_residual == bin_capacity {
        score += 5.0;
        // If the next item is large and this bin would be nearly empty
        // after placement, opening fresh is risky -> extra penalty.
        if next_item_size > 60 && post_residual < 40 {
            score += 20.0;
        }
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // reward this placement strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below the
    // mean (i.e., closer to full) to drain nearly-full bins first.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Slight early-stream preference for opening bins with big items
    // (long streams: progress-aware nudge).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (tight packing).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // 2-step lookahead: reward bins whose post_residual exactly matches next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 35.0 * (1.0 - diff / (bin_capacity as f64));
        // Exact chain fit is a jackpot.
        if post_residual == next_item_size {
            score -= 45.0;
        }
        // If next item cannot fit anywhere after this placement, penalize dead space.
        if post_residual < next_item_size && post_residual > 0 {
            score += 15.0 * (post_residual as f64 / 100.0);
        }
    }

    // Relative to mean residual: prefer bins that keep average slack balanced,
    // but reward using bins with larger residual (big holes first).
    if mean_residual > 0.0 {
        score += 8.0 * (post_residual as f64 - mean_residual) / mean_residual.max(1.0);
    }

    // Last-chance bin: strongly favor to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: only attractive if item is large relative to capacity
    // (poor fit elsewhere) — otherwise penalize opening bins.
    if bin_residual == bin_capacity {
        score += 20.0 - 0.25 * (item_size as f64);
        // Opening a bin is fine early in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
    }

    // Slight preference for fuller bins overall.
    score += 0.05 * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: subtract proportionally to how much of the bin is used.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio;

    // Penalize dead space that cannot fit the next item (lookahead-aware).
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 8.0 + 0.25 * (next_item_size - post_residual) as f64;
        } else if post_residual >= next_item_size {
            score -= 4.0; // residual remains usable for the lookahead item
        }
        // Perfect pair: item + next item exactly fills the bin
        if item_size + next_item_size == bin_residual {
            score -= 20.0;
        }
    } else {
        // Last item: strongly prefer minimizing leftover space.
        score += 3.0 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or the fit is terrible.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = open_bins_count as f64 / (mean_residual / bin_capacity as f64).max(0.1);
        score += 25.0 - 15.0 * progress - 0.5 * crowded.min(20.0);
        // Discourage opening new bins when a decent fit exists elsewhere
        if fill_ratio > 0.5 {
            score += 15.0;
        }
    } else {
        // Mild preference for bins below mean residual (keep spread balanced)
        score -= 0.05 * (mean_residual - bin_residual as f64).max(-30.0).min(30.0);
    }

    // Time-horizon modulation: early in the stream, be conservative with
    // large-item placements; later, pack aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * fill_ratio;

    // Penalize very small unusable slivers slightly more than mid-range gaps
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear waste penalty: quadratic coupling of post_residual with progress.
    // Later in the stream, wasted space becomes increasingly costly.
    let norm_waste = pr / cap;
    score += norm_waste * norm_waste * (1.0 + 3.0 * progress) * cap * 0.5;

    // Reward tight fits (small post_residual) with a smooth saturating bonus.
    let tightness = 1.0 - norm_waste;
    score -= tightness * tightness * cap * 0.6;

    // Lookahead coupling: penalize post_residual that cannot host the next item
    // (dead space), reward residuals that leave room for the lookahead item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            let gap = (nxt - pr) / cap;
            score += gap * gap * cap * (0.8 + 1.2 * progress);
        } else {
            let slack = (pr - nxt) / cap;
            score -= (1.0 - slack) * cap * 0.3;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= cap * 1.5 * (1.0 + progress);
    } else if fitting_bins_count > 1 {
        // Mild crowding penalty when many bins compete.
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // Mean-residual coupling: penalize bins whose residual deviates above the mean
    // (fragmented bins), reward below-mean residuals.
    let dev = pr - mean_residual;
    score += dev * 0.05 * (1.0 + progress);

    // New-bin candidate: an empty bin must score high (bad) unless all fits are poor.
    // Its raw post_residual is already large; add a smooth opening penalty that
    // decays as the stream progresses (late stream: consolidate instead of open).
    if bin_residual == bin_capacity {
        let open_penalty = cap * (1.2 - 0.5 * progress) * (1.0 - (open_bins_count as f64).ln().max(0.0) / 8.0);
        score += open_penalty;
    } else {
        // Favor reusing bins with smaller residuals (best-fit-like drift).
        score += (bin_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of the residual: capacity divided into fractional classes.
    // Residuals in the lowest class (0..=10) are near-perfect; higher classes waste space.
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (post_residual / (bin_capacity / 4).max(1)) as f64; // 0..4 harmonic classes
    score -= (4.0 - class) * 6.0;

    // Reward residuals that the NEXT item can exactly or nearly consume (lookahead pairing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // perfect chain
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            // penalize leftover after the lookahead item, harmonic-scaled
            score += (slack as f64) * (1.0 + frac);
        } else {
            // next item won't fit here: residual risks becoming dead space,
            // especially if it's small (unusable) — penalize tiny leftovers.
            if post_residual < 10 {
                score += (10 - post_residual) as f64 * 8.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    } else if fitting_bins_count > 1 {
        // among many fitting bins, best-fit dominates (already via post_residual)
        score += 10.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        // high mean residual => open bins are roomy, prefer them; penalize new bin
        score += 80.0 + fragmentation * 120.0;
        // early in the stream, opening bins is cheap-ish; late, consolidate
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 60.0;
        // large items leave little residual; still allow new bins for huge items
        if item_size > bin_capacity * 3 / 4 {
            score -= 70.0;
        }
    }

    // Slight preference to fill bins with larger mean residual (consolidate waste).
    score -= mean_residual * 0.05;

    // Modulo arithmetic on residual: residuals that divide capacity evenly
    // (harmonic splits like 50, 25, 20, 10) are more reusable.
    if post_residual > 0 && bin_capacity % post_residual == 0 {
        score -= 25.0;
    }

    // Integer-division threshold: residuals in [1,9] are dead space.
    if post_residual >= 1 && post_residual <= 9 {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_threshold: f64 = 10.0; // items are >= 10 in classic streams; anything below min size is dead
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward tight fits generally (post_residual small relative to capacity).
    score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Last chance: if this is the only bin that fits, prefer using it to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Pressure from number of open bins: encourage filling existing bins when many are open.
    score += 2.0 * open_bins_count as f64;

    // If this bin's residual is far below the mean, it is a good "garbage collector" bin.
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    }

    // Lookahead: if the next item fits the post-residual, reward leaving that exact gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Gap too small for the next item: penalize as potential dead space.
        score += 10.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no open bin
    // offers a good fit (residual much larger than item) or when bins are scarce.
    if bin_residual == bin_capacity {
        // Base new-bin score: its post_residual is large, so add open-bin pressure
        // and a fixed inertia term; it wins only when all open fits are bad.
        score += 15.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        // Early in the stream, opening bins is cheap and useful.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    } else {
        // Existing bin that fits poorly (large leftover) should lose to a fresh bin
        // when the leftover would be dead space for the near future.
        if post_residual > 0 && post_residual < item_size.min(20) {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate handling: neutral baseline, penalize opening early in stream
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 - 25.0 * progress;
        // opening a new bin is fine if nothing fits well; slight bonus when many bins already open
        score -= (open_bins_count as f64).min(10.0);
        return score;
    }

    // Reward tight fits strongly (waste minimization)
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 35.0;
    }

    // 2-step lookahead: reward residuals that can exactly or well fit the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0; // perfect chain: bin becomes exactly usable
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize proportionally to how much dead space remains
            let dead = post_residual as f64;
            score += 0.5 * dead;
        }
    }

    // Compare against mean residual: placing into a bin with residual above mean
    // concentrates waste; prefer bins whose residual is close to the item (below-mean waste)
    let diff = bin_residual as f64 - mean_residual;
    score += 0.15 * diff;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Mild preference for bins with fewer competitors (scarce capacity)
    if fitting_bins_count == 2 {
        score -= 10.0;
    }

    // Penalize leaving residuals in the awkward 11..=19 zone (hard to fill later)
    if post_residual >= 11 && post_residual <= 19 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: squared post-residual penalizes wasted space non-linearly.
    score += 0.35 * (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Lookahead: reward bins whose post-residual can still hold the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.08 * (post_residual - next_item_size) as f64;
        } else {
            // Post-residual too small for next item: penalize dead space more strongly.
            score += 6.0 + 0.15 * (post_residual as f64);
        }
    } else {
        // Last item: prefer fullest packing.
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Many fitting bins: mild penalty to encourage consolidation into fewer, fuller bins.
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Global state coupling: if mean residual is high, prefer reusing existing space.
    if bin_residual < bin_capacity {
        let tightness = (bin_residual as f64) / (bin_capacity as f64);
        score -= 5.0 * (1.0 - tightness);
        if (mean_residual as f64) > (item_size as f64) {
            score -= 3.0;
        }
    } else {
        // New-bin candidate: penalize opening a new bin unless it's early in the stream
        // or no open bin offers a decent fit.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_penalty = 25.0 + 30.0 * progress;
        if fitting_bins_count > 0 {
            new_bin_penalty += 15.0;
        }
        // If next item is large and current open bins have small residuals, new bin is fine.
        if next_item_size > 0 && post_residual >= next_item_size {
            new_bin_penalty -= 10.0;
        }
        score += new_bin_penalty;
    }

    // Early stream: slight openness to new bins for flexibility.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.1 && bin_residual == bin_capacity {
        score -= 8.0;
    }

    // Open bins count: discourage bin proliferation late in the stream.
    score += 0.5 * (open_bins_count as f64) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    // non-linear polynomial coupling of post_residual with stream progress
    let t = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += t * (pr_norm * pr_norm) * 20.0;
    score -= (1.0 - t) * (pr_norm) * 8.0;
    // reward tight fits non-linearly
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * fit_ratio * 10.0;
    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - pr_norm);
    }
    // lookahead coupling: penalize if next item cannot use the post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let waste = (pr - nx).max(0.0) / cap;
        score += waste * waste * 25.0;
        let gap = (nx - pr).max(0.0) / cap;
        score += gap * 6.0 * t;
    }
    // dead space penalty relative to mean residual
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / cap;
    // mild pressure to fill crowded states
    score -= (open_bins_count as f64).ln().max(0.0) * pr_norm * 3.0;
    // new-bin candidate: keep it neutral-to-slightly-high unless residual would be perfect
    if bin_residual == bin_capacity {
        score += 5.0 - 10.0 * (1.0 - fit_ratio).abs();
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize into capacity fractions
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap_f; // 0..1 fraction of capacity wasted/left

    // Harmonic class via integer division thresholds on post_residual
    let class = post_residual / 10; // 0..10 harmonic bucket
    // Penalize dead space non-linearly: small leftovers (class 0..3) are unusable
    // since min item size is 1..100 unknown; treat <20 as near-dead.
    if post_residual > 0 && post_residual < 20 {
        score += 25.0 - 1.25 * post_residual as f64; // dead-space penalty
    } else if post_residual == 0 {
        score -= 15.0; // perfect fit reward
    }

    // Modulo coupling: residuals that are multiples of common item sizes (10,20,25,50)
    // are more reusable by future items.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 - slack * 0.1; // reward, decaying with slack
        if (post_residual % next_item_size.max(1)) == 0 {
            score -= 4.0; // harmonic divisibility bonus
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        score += 3.0; // next item won't reuse this bin
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // Tight fit reward: how well item fills the bin relative to residual
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill * 8.0;

    // Progression-aware new-bin logic: early in stream, opening fresh bins is cheap;
    // late in stream, prefer consolidating into open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 4.0 + 20.0 * progress; // penalize new bins more as stream grows
        if open_bins_count > 0 && fitting_bins_count > 0 {
            score += 6.0; // extra penalty if open bins could fit
        }
    }

    // Mean residual coupling: prefer bins near the mean residual (balanced packing)
    score += (post_f - mean_residual).abs() * 0.15;

    // Class-based smooth penalty: quadratic in fraction wasted
    score += frac * frac * 10.0;

    // Tie-break by harmonic class to prefer mid-size reusable leftovers
    score += (class as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are almost unusable
    // (items are >= 1 but small gaps below ~20 waste capacity). Penalize hard.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if pr < 20.0 {
            score += (20.0 - pr) * 2.5; // dead-space penalty
        }
        // Perfect fit bonus
        if post_residual == 0 {
            score -= 15.0;
        }
    }

    // Tight fit reward: fraction of bin consumed by this placement
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    // Open bins pressure: prefer using existing bins over proliferating bins
    score += open_bins_count as f64 * 0.35;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 6.0;
    }
    // If next item nearly fits but not quite, mild penalty for blocking
    if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size && post_residual < 10 {
        score += 5.0;
    }

    // Mean residual coupling: if this bin is much tighter than average, it's a good home
    score -= (mean_residual - bin_residual as f64).max(0.0) * 0.05;

    // New-bin candidate: make empty bins moderately attractive only when
    // existing bins would create dead space; otherwise discourage.
    if bin_residual == bin_capacity {
        score += 12.0;
        // Late in stream, opening a new bin is cheaper than fragmentation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 6.0;
        // Large items deserve fresh bins if they'd leave big gaps elsewhere handled above
        if item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: small post_residual is good.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Penalize dead space that is too small for typical future items.
        if post_residual < 10 {
            score += 25.0;
        }
        // Tight fit reward relative to item size.
        let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
        score -= tightness * 10.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // matches the next item exactly or nearly.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 30.0; // chain perfect fit
        } else {
            score += diff * 0.5; // penalize mismatch
        }
        // If next item cannot fit after placement and this is the only fitting bin,
        // this placement "wastes" the bin for the next item.
        if next_item_size > post_residual && fitting_bins_count <= 1 {
            score += 15.0;
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only option.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Relative to mean residual: prefer bins with below-average residual
    // (fill the emptiest bins first, keep slack concentrated).
    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    } else {
        score -= 5.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        let bad_fit = if next_item_size > 0 && (post_residual as i64 - next_item_size as i64).abs() < 10 { 0.0 } else { 0.0 };
        score += 60.0 + bad_fit;
        // Early in stream, opening bins is fine; late in stream, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual is already rewarded by base score).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize creating small unusable dead space (< 10, or less than min item size 1... use 10 threshold).
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // Mild penalty for spreading across many fitting bins (prefer best fit).
        score += 1.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to waste potential.
            score += 3.0;
        }
    }

    // Time horizon: early in stream, be more willing to open new bins (penalize tight packing slightly less late).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New bin candidate: penalize mildly, less as stream progresses or when open bins are full-ish.
        score += 10.0 - 6.0 * progress;
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 12.0; // existing bins nearly exhausted, new bin is good
        }
    } else {
        // Prefer filling existing bins more aggressively later in the stream.
        score -= 6.0 * progress;
    }

    // Global balance: penalize bins far from mean residual to keep pool homogeneous.
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    // Reward closing out bins: post_residual near zero gets extra bonus.
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer tight fits (low post_residual), with non-linear sharpening.
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate slack; later, penalize waste quadratically.
    let coupling = 1.0 + 2.5 * progress * progress + 3.0 * progress * norm_post;
    score *= coupling;

    // Reward nearly-full bins smoothly via smoothstep-like term on tightness.
    let tightness = 1.0 - norm_post;
    score -= 12.0 * tightness * tightness * tightness * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    } else if fitting_bins_count > 1 {
        // Mild penalty when many alternatives, scaled by slack in this bin.
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln_1p() * norm_post;
    }

    // Lookahead: if next item fits smoothly into post_residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let fit_quality = 1.0 - (post - nxt) / cap;
            score -= 8.0 * fit_quality * fit_quality;
        } else {
            // Next item won't fit here: penalize creating large unusable gaps.
            score += 3.0 * norm_post * (1.0 - progress);
        }
    }

    // Mean-residual context: opening bins with large slack when mean residual is
    // already high is wasteful; smooth sigmoidal modulation.
    let mean_norm = mean_residual / cap;
    let sigmoid = 1.0 / (1.0 + (-5.0 * (mean_norm - 0.5)).exp());
    score += 6.0 * sigmoid * norm_post;

    // Mild preference for consolidating into fewer bins as stream progresses.
    score += 0.15 * open_bins_count as f64 * (1.0 - progress) * norm_post;

    // New-bin candidate: empty bin gets a calibrated penalty so it's chosen only
    // when all open bins would leave very large dead space.
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress + 4.0 * mean_norm * cap * 0.1;
    } else {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of the post-residual: dead space in low classes is more wasteful.
    let class = post_residual / 10; // 0..=9 harmonic bucket
    score += (class as f64) * 1.7;

    // Lookahead: penalize post-residuals that cannot host the next item.
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += 22.0;
        } else {
            // Reward residual that exactly or near-exactly hosts next item.
            let slack = post_residual - next_item_size;
            score -= 14.0 * (1.0 - slack as f64 / cap);
            if slack == 0 {
                score -= 12.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: only attractive when open bins are nearly full.
    if bin_residual == bin_capacity {
        let mean_fill = 1.0 - mean_residual / cap;
        if open_bins_count == 0 {
            score -= 40.0;
        } else if mean_fill < 0.55 {
            score += 35.0; // open bins have room; discourage new bin
        } else {
            score -= 6.0 * mean_fill;
        }
    }

    // Tight fits are excellent: reward small post_residual fraction.
    let frac = post_residual as f64 / cap;
    score -= 20.0 * (1.0 - frac) * (1.0 - frac);

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Late in the stream, prefer compacting into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space (residual < 10 after placement is wasted)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 && post_residual > 0 {
        score += 8.0;
    }

    // Reward tight fits
    score -= (item_size as f64 / bin_capacity as f64) * 5.0;

    // Reward exact fits strongly
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward heavily
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when current bin fit is poor
    if bin_residual == bin_capacity {
        // penalize opening new bins when open bins exist and fit is decent
        if open_bins_count > 0 && item_size <= bin_residual {
            score += 15.0 + (open_bins_count as f64).sqrt() * 2.0;
        }
        // but favor new bin if item is small relative to capacity (would waste open bins)
        if item_size < 30 && open_bins_count > 3 {
            score -= 5.0;
        }
    }

    // Open bins pressure: mild penalty encouraging consolidation
    score += (open_bins_count as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (post_residual == 0)
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // next item fits here afterwards: good chaining
            score -= 0.5 * next_item_size as f64;
        }
        // Penalize dead space that next item cannot use
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.3 * post_residual as f64;
        }
    }

    // Penalize small unusable residuals relative to typical item size range
    if post_residual > 0 && post_residual < 10 {
        score += 100.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables good lookahead
    if bin_residual == bin_capacity {
        score += 50.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    // Prefer bins tighter than the mean residual (best-fit flavor)
    score += 0.2 * (post_residual as f64 - mean_residual).max(0.0);

    // Late in the stream, be more conservative with residuals
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.1 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus as post_residual approaches zero.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 6.0 * tightness * tightness;

    // Penalize creating dead space that nothing can use (min item size 1 => any
    // residual is usable, but very small residuals are less valuable than large ones;
    // penalize residuals that are too small to fit a typical item).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // near-dead space
    }

    // Lookahead: reward if the next item fits exactly into the post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0; // perfect chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 5.0 * (1.0 - slack / cap);
        } else {
            // next item cannot follow here; mild penalty if post residual is stranded
            score += 1.5;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a new bin is discouraged unless current bin
    // would be left with unusable residue or the stream is early and bins are scarce.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // A fresh bin is attractive early (builds diversity) or when existing bins fit poorly.
        score -= 4.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 20.0; // no alternative
        }
        // If mean residual across open bins is large, prefer using them over a new bin.
        score += 0.15 * mean_residual;
    }

    // Global balance: prefer bins whose residual deviates favorably from the mean
    // (filling the fullest bins first keeps many mid-size residuals available).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score -= 3.0 * dev;

    // Late-stream consolidation: as the stream ends, prefer bins that end near-empty
    // (post_residual close to 0) to avoid many slightly-filled bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * progress * (post_residual as f64 / cap);

    // Crowding: with many open bins, slightly favor tightening existing ones
    // rather than spreading; with few bins, spreading is cheaper.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling: quadratic residual term scaled by progress.
    let norm_res = post_residual as f64 / cap;
    score += 8.0 * norm_res * norm_res * (0.5 + progress);

    // Reward tight fits more aggressively as the stream progresses.
    let tightness = 1.0 - norm_res;
    score -= 6.0 * tightness * tightness * (0.3 + 0.7 * progress);

    // Last-chance bonus: strongly prefer the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin, less so early or when residuals are large.
    if bin_residual == bin_capacity {
        let mean_crowding = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        score += 15.0 + 10.0 * mean_crowding * (1.0 - progress);
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        let slack = (post_residual as f64 - next_item_size as f64) / cap;
        score -= 4.0 * (1.0 - slack) * (1.0 - progress);
    } else if next_item_size > 0 {
        // Penalize dead space that next item cannot use.
        score += 2.0 * (next_item_size as f64 / cap);
    }

    // Mild penalty for many open bins to encourage consolidation.
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals that are "nice" fractions
    // of capacity (multiples of 10, 20, 25) are more reusable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_mod10 = post_residual % 10;
    let pr_mod20 = post_residual % 20;
    let pr_mod25 = post_residual % 25;

    // Reward post_residuals that lie on harmonic grid points (0, 10, 20, 25, 50...)
    if post_residual == 0 {
        score -= 30.0; // perfect fit is always excellent
    } else {
        if pr_mod10 == 0 { score -= 8.0; }
        if pr_mod20 == 0 { score -= 4.0; }
        if pr_mod25 == 0 { score -= 4.0; }
        if post_residual % 50 == 0 { score -= 6.0; }
        // Penalize awkward residuals in dead zones (1..9, 11..19 etc. small slivers)
        if post_residual < 10 {
            score += 15.0 * (1.0 - pr / 10.0);
        }
    }

    // Dead-space penalty: residual too small for the smallest plausible item (1)
    // is fine, but residual in [1, next_item_size) blocks the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0 + (next_item_size - post_residual) as f64 * 0.3;
    }
    // Reward if the next item fits exactly into the post residual (chain fit)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // next item still fits: mild reward scaled by leftover after chaining
        let chained = post_residual - next_item_size;
        score -= 5.0 * (1.0 - chained as f64 / cap);
    }

    // Integer-division thresholds on residual: classify bin fullness.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual <= quarter {
        score += 3.0; // nearly full bin, good to fill tightly but don't over-favor
    }
    if post_residual > half {
        score -= 2.0; // keeping large residual bins flexible is good
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: an empty bin has large residual; make it
    // moderately attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized when many open bins already exist
        // and their mean residual is large (waste accumulation).
        let waste_pressure = mean_residual / cap;
        score += 20.0 + 10.0 * waste_pressure;
        // But early in the stream, allow opening bins freely.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
        // If the item is large and next item is also large, a fresh bin is good.
        if item_size > half && next_item_size > half {
            score -= 10.0;
        }
    }

    // Tightness reward: how well the item fills the bin (fraction used).
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * fill;

    // Modulo harmony between item and residual: item sizes sharing a divisor
    // class with residual tend to tile better.
    let g = gcd(item_size, bin_residual);
    if g > 1 {
        score -= (g.min(20)) as f64 * 0.2;
    }

    // Mild pressure to consolidate: fewer open bins relative to items is good.
    score += (open_bins_count as f64) * 0.05;

    score
}

fn gcd(a: u32, b: u32) -> u32 {
    if b == 0 { a } else { gcd(b, a % b) }
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose leftover could still host the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 15.0; // leftover too small for next item: dead space risk
        }
    } else if post_residual == 0 {
        score -= 20.0; // last item: prefer closing bins exactly
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += 0.6 * open_bins_count as f64;

    // Slight preference for bins below mean residual (consolidation).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count == 0
            || (post_residual > 0 && post_residual < 10 && next_item_size > post_residual);
        if poor_fit {
            score -= 25.0;
        } else {
            score += 20.0;
        }
    }

    // Late-stream tightening: waste less as the stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Aggressive 2-step lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits, but penalize leftover slack after the lookahead placement.
            let lookahead_slack = (post_residual - next_item_size) as f64;
            score += 0.5 * lookahead_slack;
            score -= 10.0;
        } else {
            // Next item cannot use the residual: penalize unusable dead space,
            // scaled by how dead it is relative to smallest possible item (1).
            score += 0.8 * post_residual as f64;
        }
    }

    // Relative-to-mean coupling: bins with residual near the mean are "normal";
    // prefer placing into bins with larger residual when post_residual is large.
    let res = post_residual as f64;
    if res > mean_residual {
        score += 0.3 * (res - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - res);
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it unattractive unless the item is huge relative to
    // capacity or no good fit exists elsewhere (handled implicitly by score above).
    if bin_residual == bin_capacity {
        score += 30.0 + 0.2 * (bin_capacity - item_size) as f64;
        // Late in the stream, opening new bins is fine since leftover bins are less useful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * progress;
    }

    // Mild preference for consolidating when many bins are open.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small to plausibly fit future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: bonus if the next item fits exactly in the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Next item won't fit here; slight penalty proportional to overshoot.
            score += ((next_item_size - post_residual) as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Favor filling bins when many bins are open (contain fragmentation).
    score -= (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Global state: if mean residual is high, prefer bins below mean
    // (balance toward consolidating space).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (better long-run packing); late in the stream, squeeze into open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress;

    // New-bin candidate handling: opening a fresh bin is attractive early
    // or when the fit here is poor (large post residual waste).
    if bin_residual == bin_capacity {
        let waste_penalty = (post_residual as f64) / 6.0;
        let early_bonus = 14.0 * (1.0 - progress);
        let poor_fit = if post_residual > 40 { 18.0 } else { 0.0 };
        score = score.min( post_residual as f64 + waste_penalty - early_bonus - poor_fit );
    }

    // Mild preference for near-full bins regardless of everything else.
    if post_residual <= 5 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, non-linearly scaled by stream progress.
    // Early on, prefer tight packing mildly; later, dead space matters more.
    let mut score = pr * (0.6 + 0.8 * progress * progress);

    // Smooth polynomial coupling: penalize residuals that are neither ~0 nor
    // comfortably reusable, with strength growing as the stream advances.
    let coupling = norm_pr * (1.0 - norm_pr); // peaks at 0.5 (worst dead space)
    score += 30.0 * coupling * coupling * (0.5 + progress);

    // Reward filling a bin nearly completely (wasted-capacity avoidance).
    score -= 15.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 + 2.0 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 10.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        // Next item won't fit here: slight penalty proportional to leftover.
        score += 5.0 * norm_pr * (1.0 + progress);
    }

    // Prefer bins with residual below the mean (tighter bins first),
    // smoothly weighted.
    let mean_norm = mean_residual / cap;
    score += 8.0 * (norm_pr - mean_norm) * (1.0 + progress);

    // New-bin candidate: acceptable early or when residuals are all poor,
    // penalized late in the stream to force consolidation.
    if bin_residual == bin_capacity {
        score += 12.0 * progress * progress - 4.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into residue classes.
    let post = post_residual as f64;
    let cap = bin_capacity as f64;

    // Reward small post_residual (tight fits) nonlinearly.
    score -= 40.0 * ((cap - post) / cap).powi(3);

    // Penalize "awkward" residual classes: residuals in (0,10] are dead space.
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0;
    }
    // Residuals that are multiples of 10 are more reusable (harmonic classes).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    }
    // Class via integer division thresholds on post_residual.
    let class = post_residual / 10; // 0..=10
    score -= match class {
        0 => 0.0,
        1 => 6.0,
        2 => 3.0,
        3 => 1.0,
        _ => 0.5,
    };

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        score -= 30.0;
        if slack == 0 {
            score -= 25.0; // perfect chaining
        } else if slack <= 10 {
            score += 8.0; // would leave dead space after next
        }
    } else if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        // next item can never use this sliver
        score += 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Prefer bins below mean residual when many bins open (balance load).
    let mean = mean_residual;
    if post < mean {
        score -= 5.0 * (mean - post) / cap;
    } else {
        score += 3.0 * (post - mean) / cap;
    }

    // New-bin candidate: neutral baseline with mild penalty so we prefer
    // reusing open bins unless the fit is poor; becomes attractive for big items.
    if bin_residual == bin_capacity {
        score = 0.55 * cap - 0.35 * item_size as f64;
        if item_size > 60 {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size > item_size {
            score -= 5.0; // big item followed by bigger: fresh bin good
        }
    }

    // Mild time decay: early on, be conservative with open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // possible item (size 1) are pure waste — but any residual >= 1 is
    // technically usable, so weight small gaps (< 20) as near-dead.
    if post_residual == 0 {
        // Perfect fit: heavily reward.
        score -= 1000.0;
    } else if post_residual < 10 {
        // Near-dead space: strong penalty.
        score += 500.0;
    } else if post_residual < 20 {
        score += 150.0;
    } else if post_residual < 40 {
        score += 30.0;
    }

    // Reward bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 200.0 * (1.0 - tightness);

    // Lookahead: if the next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 120.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        // Post-residual unusable by the next item: penalize proportionally.
        score += 60.0;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid forcing a
    // bad placement unless the fit is genuinely good.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: mildly discourage spreading across many bins so the
    // new-bin candidate wins only when fits are poor elsewhere.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline handicap so it only wins on bad fits.
        score += 25.0 + 3.0 * open_bins_count as f64;
    } else {
        score += 0.5 * open_bins_count as f64;
    }

    // Mild coupling with mean residual: prefer bins deviating below mean
    // (consuming fuller bins first keeps more large residuals available).
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            score -= 50.0 + (post_residual - next_item_size) as f64 * -0.5;
        } else {
            // next item won't fit: penalize wasted space relative to mean residual
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Compare residual to mean residual: tight packing favored
    score += (bin_residual as f64 - mean_residual) * 0.2;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Penalize opening new bins when decent fits exist
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 150.0;
    }

    // Late-stream consolidation pressure
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * (0.1 + 0.3 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) with a nonlinear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that can never fit a typical future item.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 1.0 } else { 0.0 };
        score += 25.0 * dead;
    }

    // Lookahead: bonus if the next item exactly fills the post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item cannot use this residual: mild penalty proportional to leftover.
            score += 6.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    } else {
        // Last item: prefer fullest packing.
        score -= 30.0 * tightness;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Many open bins: prefer consolidating into bins with larger residuals already;
    // few open bins: allow spreading.
    let spread = open_bins_count as f64 / (total_items.max(1) as f64).sqrt().max(1.0);
    score += 4.0 * spread * (bin_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: when mean residual is high, prefer bins below mean
    // (use up the loose space); when low, prefer larger residuals.
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.15 * dev;

    // Time horizon: early in the stream, be more selective (penalize bad fits);
    // late in the stream, just fill bins greedily.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (post_residual as f64 * 0.10);
    score -= progress * 8.0;

    // New-bin candidate: open a new bin only if no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = if pressure > 0.0 { -5.0 } else { score + 45.0 + 10.0 * (1.0 - progress) };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;

    // Core tightness reward: quadratic in post_residual, modulated by stream progress.
    let mut score = post * post / cap;

    // Smooth polynomial coupling: later in the stream, waste is punished harder.
    score += (1.0 + progress * progress) * post / cap * 20.0;

    // Reward high fill ratio with a smooth cubic term.
    score -= 15.0 * fit_ratio * fit_ratio * fit_ratio;

    // Penalize bins whose residual deviates from the mean (fragmentation).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && next_item_size as f64 == post {
        score -= 25.0;
    } else if next_item_size > 0 {
        // Penalize leaving a residual that is too small for the next item (dead space).
        let gap = (post - next_item_size as f64).max(0.0);
        if next_item_size as f64 > post {
            score += 10.0 * (next_item_size as f64 - post) / cap;
        } else {
            score += 4.0 * gap / cap;
        }
    }

    // New-bin candidate: mildly penalize opening a new bin unless residuals are tight.
    if bin_residual == bin_capacity {
        score = 45.0 + 20.0 * (1.0 - progress) - 5.0 * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "coarse" residue classes (multiples of a coarse quantum) are more likely
    // to be filled by future items, so reward them.
    let quantum: u32 = 10;
    let residue = post_residual % quantum;
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 200.0;
    } else if residue == 0 {
        // Post residual is a multiple of the quantum: harmonically clean.
        score -= 25.0;
    } else {
        // Penalize ragged leftovers proportionally to distance from quantum grid.
        let dist = residue.min(quantum - residue) as f64;
        score += dist * 1.5;
    }

    // Integer-division thresholds: how many "medium chunks" (size ~25) still fit.
    let chunks = post_residual / 25;
    score -= chunks as f64 * 12.0;

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // this is a golden pairing; reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Favor pairings leaving a harmonically clean slack.
            if slack as u32 % quantum == 0 {
                score -= 40.0;
            }
            score -= (post_residual as f64 - slack) * 0.2;
        } else {
            // Next item cannot follow here; slight penalty scaled by overshoot.
            let over = (next_item_size - post_residual) as f64;
            score += (over / 20.0).min(15.0);
        }
    }

    // Capacity fraction logic: residual as a fraction of capacity.
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac < 0.05 {
        score -= 30.0; // nearly-full bin: close it out, great outcome
    } else if frac > 0.6 {
        score += 20.0; // leaving a mostly-empty bin wastes capacity
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: a fresh empty bin should only win when no
    // open bin gives a decent fit. Penalize it by default, less so when the
    // item is large relative to capacity or open bins are already crowded.
    if bin_residual == bin_capacity {
        let base_penalty = 60.0;
        let crowd = (open_bins_count as f64).ln().max(0.0) * 5.0;
        let big_item_bonus = if item_size > bin_capacity / 2 { 15.0 } else { 0.0 };
        score += base_penalty + crowd - big_item_bonus;
    }

    // Stream progression: late in the stream, prefer consolidating into open
    // bins rather than spawning new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual != bin_capacity {
        score -= progress * 10.0;
    } else {
        score += progress * 10.0;
    }

    // Mean residual context: when open bins are generally loose, tighten the
    // preference for tight fits to avoid residual sprawl.
    score += (mean_residual - post_residual as f64).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps disproportionately.
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap < 10.0 {
            score += 60.0 * (10.0 - gap) / 10.0; // unusable dead space (min item is 1)
        } else if gap < 20.0 {
            score += 25.0 * (20.0 - gap) / 10.0; // near-unusable gap
        } else {
            // superlinear penalty on small residual space
            score += 300.0 / (gap * gap);
        }
    } else {
        // perfect fit: strong reward
        score -= 80.0;
    }

    // Reward tight fits relative to bin residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Open-bin pressure: fewer bins favored when this bin absorbs the item well.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress);
    score += 0.05 * pressure * (1.0 - fit_ratio);

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 70.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here anyway; slightly penalize leaving a gap that is
        // neither large nor zero (wasted space from stream perspective)
        if post_residual > 0 && post_residual < next_item_size {
            score += 8.0;
        }
    }

    // Mean residual context: placing into a bin far below mean residual wastes capacity elsewhere.
    if (post_residual as f64) > mean_residual * 1.5 {
        score += 6.0;
    } else if (post_residual as f64) < mean_residual * 0.5 {
        score -= 6.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let decent_fit_exists = fitting_bins_count > 0 && mean_residual >= item_size as f64 * 0.35;
        if decent_fit_exists {
            score += 55.0; // discourage opening new bin when open bins are usable
        } else {
            score -= 10.0; // encourage fresh bin when open bins are poor
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a slight superlinear penalty
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 0.5);

    // Aggressive 2-step lookahead: reward if the next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chaining: item + next item fills bin
        } else if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            score -= 15.0 - slack_after_next as f64 * 0.25; // good chaining, penalize leftover slack mildly
        } else {
            // next item won't fit here; penalize proportional to overshoot
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Relative to mean residual: bins with residual far below mean are scarce space; using them is costly
    let resid_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let rel = resid_f / mean_residual;
        if rel < 1.0 {
            score += (1.0 - rel) * 10.0; // tighter-than-average bin: penalize wasting it
        } else {
            score -= (rel - 1.0).min(2.0) * 3.0; // roomier-than-average bin: favor using it
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make empty bin attractive only when item is large relative to capacity
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        // large items justify a fresh bin; small items should go into existing bins
        score = score * 0.5 + (bin_capacity as f64 - item_size as f64) * (1.3 - fill_frac);
        if fill_frac > 0.7 {
            score -= 20.0;
        }
    }

    // Late-stream consolidation: as stream progresses, prefer filling existing bins tighter
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.1;

    // Mild penalty when many bins are open (encourage consolidation)
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 14.0 * tightness * tightness;

    // Dead-space penalty: leftover space too small for the smallest plausible item.
    if post_residual < 10 {
        score -= 18.0; // near-perfect fill, big reward
    } else if post_residual <= 20 {
        score -= 6.0;
    } else if post_residual < item_size {
        score += 3.0; // awkward wedge: fits nothing as big as this item
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 0.15 * (bin_residual as f64 - item_size as f64).max(0.0);
    }

    // Lookahead: reward if the next item fits into the post-residual (chaining).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else if next_item_size > post_residual && next_item_size <= bin_capacity {
            // Next item will need another bin anyway; slight penalty for wasting space here.
            score += 2.0 * (post_residual as f64 / next_item_size as f64);
        }
    }

    // New-bin candidate handling: an empty bin is attractive only when open bins are crowded
    // or the fit into existing bins is poor.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        let mut new_score = 20.0; // base cost of opening a bin
        new_score -= 25.0 * crowding; // crowded bins -> new bin more attractive
        if fitting_bins_count == 0 {
            new_score -= 30.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            new_score -= 6.0; // room to pair the next item in a fresh bin
        }
        if open_bins_count == 0 {
            new_score = -100.0; // must open first bin
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_score += 4.0 * progress; // late in the stream, be slightly more conservative
        score = score.min(score) ; // keep type checker happy
        return new_score.min(1e9);
    }

    // Prefer bins with smaller residuals among comparable fits (best-fit flavor).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Mild exploration: occasionally favor mid-crowded bins via open_bins_count coupling.
    score += 0.02 * open_bins_count as f64;

    // Time-horizon modulation: early in the stream, be pickier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0 * (1.0 - tightness).min(1.0) * 0.0
           + progress * 2.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Base: post-residual (minimize wasted space)
    let mut score = pr;

    // Smooth non-linear coupling: residual squared grows penalty for dead space
    score += 0.5 * pr_norm * pr_norm * cap;

    // Interaction of post-residual with stream progress: late in stream,
    // prefer tight fits more aggressively
    score += 2.0 * pr_norm * progress * cap;

    // Cubic term: heavily penalize mid-range residuals that are hard to fill
    let mid = (pr_norm - 0.5).abs();
    score += 1.5 * mid * mid * mid * cap;

    // Lookahead: reward if next item fits into post-residual
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 1.0 + (ni / cap) * 2.0;
        } else {
            score += (ni - pr) / cap * 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 3.0 + progress * 2.0;
    }

    // Many open bins: prefer consolidating into existing bins
    let ob = open_bins_count as f64;
    score += 0.1 * ob.ln().max(0.0);

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += 0.3 * (mean_residual - pr).signum() * ((mean_residual - pr).abs() / cap).min(1.0);

    // New-bin candidate: penalize opening a new bin unless item is large
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / cap;
        score += 2.5 - 2.0 * fill_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: capacity fractions
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // fraction of capacity left after placement

    // Penalize residuals that fall into "dead zones" (too small to be useful)
    // Harmonic classes: post_residual % 10, % 20, % 25, % 50
    let r = post_residual;
    if r == 0 {
        // Perfect fit: strong reward
        score -= 40.0;
    } else {
        // dead-space penalty grows as residual shrinks below useful thresholds
        if r < 10 {
            score += 25.0; // unusable for any item
        } else if r < 20 {
            score += 10.0;
        } else if r < 30 {
            score += 4.0;
        }

        // modulo arithmetic: residuals that are multiples of 10/25 are more reusable
        if r % 10 == 0 {
            score -= 3.0;
        }
        if r % 25 == 0 {
            score -= 2.0;
        }
        if r % 50 == 0 {
            score -= 2.0;
        }
    }

    // Coupling with next item: reward if next item fits exactly or well into post_residual
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 20.0; // perfect chain
        } else if next_item_size <= r {
            let next_left = r - next_item_size;
            // reward tight fits of the lookahead
            score -= 8.0 * (1.0 - (next_left as f64) / cap);
            if next_left % 10 == 0 {
                score -= 2.0;
            }
        } else {
            // next item cannot fit here: slight penalty proportional to wasted potential
            score += 2.0 * ((next_item_size - r) as f64 / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Tightness reward: prefer bins where item fills a large share of residual
    let fill = item_size as f64 / bin_residual as f64;
    score -= 10.0 * fill * fill;

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - frac);

    // Prefer fuller bins relative to the fleet mean residual
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0) * 0.1;

    // Slight penalty for proliferating open bins when many alternatives exist
    if open_bins_count > 3 && bin_residual == bin_capacity {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to host the
    // smallest plausible future item are pure waste -> heavy nonlinear penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Medium dead space (10..=20) is only usable by small items: moderate penalty.
    if post_residual >= 10 && post_residual <= 20 {
        score += 0.35 * post_residual as f64;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly favor this bin; if next item cannot fit, penalize slightly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            score += 8.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.6 * open_bins_count as f64 * (0.5 + progress);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: neutral-ish baseline; only attractive when current bin
    // would leave very poor fit / many bins already open.
    if bin_residual == bin_capacity {
        score = 30.0 + 1.5 * open_bins_count as f64 - 20.0 * (1.0 - progress);
        if post_residual == 0 {
            score -= 5.0;
        }
        // If an existing bin fits tightly, keep it below new-bin score.
        if item_size as f64 / bin_capacity as f64 > 0.85 {
            score += 25.0;
        }
    }

    // Mean-residual coupling: prefer bins whose residual is below mean
    // (i.e., fuller bins) to consolidate filling.
    score += 0.4 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled relative to capacity.
    score = post_residual as f64 * (1.0 + 0.5 * (post_residual as f64 / bin_capacity as f64));

    // Lookahead: reward if the next item exactly fills the post_residual (perfect 2-step chain).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strongly subtract when the next item fits snugly into the leftover space.
        if (post_residual as u32) >= next_item_size {
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Penalize leftovers the next item cannot use (dead space risk).
            score += 10.0 * (1.0 - gap / bin_capacity as f64);
        }
        // Exact match bonus: next item seals this bin perfectly.
        if post_residual == next_item_size {
            score -= 40.0;
        }
    } else {
        // Last item: minimize final leftover directly.
        score -= 20.0;
    }

    // Relative-to-mean coupling: bins tighter than average are valuable, use them;
    // bins looser than average can absorb odd items later.
    let rel = post_residual as f64 - mean_residual;
    score += 0.3 * rel;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make a fresh bin moderately attractive only when
    // the item is large and no good squeeze exists, otherwise discourage opening bins.
    if bin_residual == bin_capacity {
        let pressure = item_size as f64 / bin_capacity as f64;
        let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
        // Penalize new bins by default; discount penalty when item is big and fits are scarce.
        score += 45.0 - 40.0 * pressure * scarcity;
        // Early in the stream, opening bins is cheaper (future items need room).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Mild preference to fill bins with more open bins present (consolidation).
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in stream: early -> explore new bins, late -> pack tight
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness: how fully the item fills the bin
    let fill_ratio = item_size as f64 / bin_capacity as f64;

    // Reward near-perfect fills (small post_residual) aggressively
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 300.0;
    } else {
        // Penalize dead space non-linearly: residuals that can't fit typical items
        let dead = if post_residual < 10 { 1.0 } else { 0.0 };
        score += dead * 50.0 * (1.0 + progress);
    }

    // Lookahead coupling: if next item fits into post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 120.0 + 0.5 * next_item_size as f64;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // residual too small for next item: penalize proportionally to wasted potential
        let waste = (post_residual as f64) / bin_capacity as f64;
        score += 40.0 * waste * (0.5 + progress);
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Many open bins with high mean residual: discourage spreading, prefer consolidation
    if open_bins_count > 2 && mean_residual > 0.0 {
        let spread = (post_residual as f64 - mean_residual).abs();
        score += 0.3 * spread;
        // if this bin is far below mean residual (already tight), slight reward
        if (post_residual as f64) < mean_residual {
            score -= 15.0;
        }
    }

    // New-bin candidate handling: empty bin gets baseline; open new bin early or when
    // no open bin fits well (post_residual large relative to capacity)
    if bin_residual == bin_capacity {
        // baseline cost for opening a new bin; cheaper early, expensive late
        score = 150.0 + 250.0 * progress - 0.5 * fill_ratio * 100.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 60.0;
        }
    }

    // Mild global pressure: as stream progresses, favor bins with less residual
    score += progress * (post_residual as f64) * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: waste matters less; late: tightly packed residuals are critical.
    let w = 0.5 + 2.5 * progress * progress;
    score += w * (pr / cap) * (pr / cap) * cap * 0.1;

    // Dead-space penalty: residual too small to be useful for future items.
    let dead = if pr < 10.0 { (10.0 - pr) * 0.0 } else { 0.0 };
    let _ = dead;
    if pr < 10.0 {
        score -= 8.0; // near-perfect fill, reward strongly
    } else {
        // smooth penalty growing with unusable gap
        let gap = (pr - 10.0).max(0.0) / cap;
        score += 30.0 * gap * gap * (1.0 - 0.5 * progress);
    }

    // Lookahead: reward if next item fits in the post residual.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 + 4.0 * progress;
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Mild penalty for spreading across many open bins.
    score += 0.05 * open_bins_count as f64 * (pr / cap);

    // New-bin candidate: bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Prefer new bin only for large items or when mean residual is poor.
        let large = item_size as f64 / cap;
        let poor = (mean_residual / cap).max(0.0);
        score -= 15.0 * large * (1.0 - progress) + 10.0 * poor * (1.0 - poor);
        score += 5.0 * (1.0 - large); // penalize new bin for small items
    }

    // Slight preference for bins tighter than the mean residual.
    score -= 0.5 * (mean_residual - pr) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: reward residuals that are "usable slots" ---
    // Residuals divisible by common small sizes (10, 20, 25, 50) are reusable.
    let pr = post_residual;
    if pr > 0 {
        let mut bonus = 0.0;
        if pr % 10 == 0 { bonus -= 6.0; }
        if pr % 20 == 0 { bonus -= 4.0; }
        if pr % 25 == 0 { bonus -= 4.0; }
        if pr % 50 == 0 { bonus -= 6.0; }
        // Integer-division class: how many generic small items (<=10) still fit
        bonus -= 2.0 * (pr / 10) as f64;
        score += bonus;
    }

    // --- Perfect fit: overwhelming reward ---
    if pr == 0 {
        score -= 1000.0;
    }

    // --- Penalize tiny dead space (waste class: 1..=9 unusable slivers) ---
    if pr > 0 && pr < 10 {
        score += 15.0;
    }

    // --- Lookahead coupling: does next_item_size fit into post_residual? ---
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Harmonic compatibility: next item divides or nearly divides residual
            let compat = (pr % next_item_size == 0) as f64 * 8.0
                + (pr / next_item_size.max(1)) as f64 * 1.5;
            score -= compat;
        } else {
            // Next item won't fit here; slight penalty proportional to overshoot class
            let over = (next_item_size - pr) / 10;
            score += 2.0 + over as f64;
        }
    }

    // --- Tightness reward: fraction of bin used ---
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 20.0 * fill * fill;

    // --- Last-chance bin: strongly favor using the only fitting bin ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // --- Penalize spreading across too many open bins when mean residual is high ---
    if open_bins_count > 2 && mean_residual > 30.0 && bin_residual < bin_capacity {
        score += 3.0;
    }

    // --- New-bin candidate handling: only attractive when nothing fits well ---
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a bin, discounted if stream is early or bins scarce
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_cost = 60.0 + 40.0 * progress;
        if fitting_bins_count == 0 { new_bin_cost -= 200.0; }
        // If existing fit would leave bad sliver, new bin becomes competitive
        if pr > 0 && pr < 10 { new_bin_cost -= 25.0; }
        score += new_bin_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    // A gap is "dead" if it is tiny relative to the smallest plausible item.
    let dead_threshold = 10.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 50.0;
    }

    // Moderate gaps that can't fit the lookahead item are also suspect.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Bin remains useful for the next item: reward.
        score -= 5.0;
    }

    // Reward using bins that are already fairly full (low residual before placement).
    score += (bin_residual as f64 / bin_capacity as f64) * 10.0;

    // Open-bins pressure: with many open bins, discourage opening new ones.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 5.0;
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly favor using it.
        score -= 40.0;
    }

    // Slight coupling with mean residual: prefer bins below mean residual (fuller bins).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Late-stream tightening: as the stream progresses, avoid waste more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Penalize dead space that cannot fit the next item (wasted sliver).
    if next_item_size > 0 && post_residual < next_item_size {
        // Smaller unusable slivers are worse: scale by how close we came to fitting.
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 0.8;
    }

    // Reward leaving post_residual large enough to be generically reusable.
    if post_residual >= 80 {
        score -= 8.0;
    } else if post_residual >= 40 {
        score -= 3.0;
    } else if post_residual > 0 {
        score += (40 - post_residual) as f64 * 0.15;
    }

    // Prefer bins tighter than the mean residual (best-fit style bias).
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 20.0 - 45.0 * desperation;
    }

    // Late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio: later in the stream, prefer tighter packing / fewer bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize residuals that are too small to be useful for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space penalty
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 8.0; // next item won't fit here; slight penalty
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when decent open bins exist, more so late in the stream.
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * progress + 0.5 * open_bins_count as f64;
        // But allow new bin if no open bin fits well (post_residual here == capacity - item).
        if fitting_bins_count == 0 {
            score -= 35.0;
        }
    }

    // Global state: if mean residual is high, prefer using existing slack.
    if bin_residual != bin_capacity {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Mild time-horizon scaling of the base residual term.
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap; // normalized post residual in [0,1]

    // Base: minimize leftover space, with a non-linear (quadratic) penalty on waste
    let mut score = pr as f64 + 40.0 * norm_pr * norm_pr;

    // Smooth coupling: waste is more tolerable early in the stream, harsher later
    score += 60.0 * norm_pr * norm_pr * progress;

    // Perfect-fit reward (smooth, avoids hard constants)
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: reward bins whose post_residual matches the next item size
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let match_bonus = (1.0 - gap / cap).max(0.0);
        score -= 25.0 * match_bonus * match_bonus;
        // Penalize leaving exactly a sliver the next item can't use
        if next_item_size as f64 > pr {
            score += 10.0 * (next_item_size as f64 - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0 + 30.0 * progress;
    }

    // New-bin candidate handling: opening a bin is expensive; allow it only
    // when the fit into open bins is very poor (large post_residual).
    if bin_residual == bin_capacity {
        score = 0.5 * cap + 0.6 * mean_residual - 20.0 * (1.0 - norm_pr);
        // As the stream progresses, prefer consolidating into open bins more strongly
        score += 40.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across many open bins (encourages closing bins out)
    score += 0.05 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: small leftovers are valuable.
    let pr = post_residual;
    let class = match pr {
        0 => -8.0,                       // perfect fit
        1..=5 => -4.0,
        6..=10 => -2.0,
        11..=20 => -0.5,
        21..=40 => 1.5,
        41..=70 => 3.0,
        _ => 4.5,
    };
    score += class;

    // Modulo coupling: residuals that are multiples of common item sizes
    // (10, 20, 25, 50) are more reusable.
    if pr % 10 == 0 { score -= 2.0; }
    if pr % 20 == 0 { score -= 1.0; }
    if pr % 25 == 0 { score -= 1.0; }
    if pr % 50 == 0 { score -= 1.5; }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 6.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            if slack <= 10.0 { score -= 3.0; }
            else { score += slack * 0.05; }
        } else {
            // next item cannot use this bin's leftover; penalize large leftover
            score += (pr as f64) * 0.02;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate: only attractive when current fit is terrible.
    if bin_residual == bin_capacity {
        let tight = (item_size as f64) / cap;
        if tight > 0.5 { score += 2.0; }        // keep big items for fresh bins
        else { score += 12.0; }                 // discourage opening new bins for small items
        if open_bins_count == 0 { score -= 20.0; }
    }

    // Prefer filling bins that are already relatively full.
    let fill = 1.0 - (bin_residual as f64) / cap;
    score -= fill * 2.0;

    // Stream progression: later in the stream, be more conservative (favor tight fits).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.03;

    // Slight pull toward bins near the mean residual (balance load).
    score += ((bin_residual as f64) - mean_residual).abs() * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are worse than large ones.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny dead space is nearly worthless
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    } else if post_residual == 0 {
        score -= 40.0; // perfect fill is excellent
    }

    // Reward filling bins tightly relative to their residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Pressure from too many open bins: prefer consolidating into existing bins.
    score += 3.0 * open_bins_count as f64;

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit
    // or the fit would leave a tiny dead gap; otherwise penalize opening bins.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 80.0; // must open a new bin
        } else if post_residual < 10 && post_residual > 0 {
            score += 20.0; // opening avoids creating dead space only mildly
        } else {
            score += 70.0 + 2.0 * open_bins_count as f64; // discourage new bins
        }
    }

    // Lookahead: if next item fits exactly into the post residual, reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > post_residual && next_item_size <= post_residual + 10 && post_residual > 0 {
        score += 15.0; // next item won't use this gap anyway
    }

    // Early in stream, mildly prefer new bins to build flexible capacity.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && progress < 0.2 {
        score -= 10.0;
    }

    // Mean residual coupling: if mean residual is high, tighten selection.
    score += 0.2 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward exact match between post_residual and next item size.
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 12.0 * (1.0 - lookahead_gap / bin_capacity as f64).max(-1.0);

        // Perfect chain: item fits, then next item exactly fills the remainder.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Next item fits into the post residual (good 2-item chain).
        if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Dead space the next item cannot use: penalize proportionally.
            score += 0.15 * (post_residual as f64);
        }
    } else {
        // Last item: strongly prefer tightest fit.
        score += 0.5 * (post_residual as f64);
    }

    // Relative tightness vs mean residual across open bins.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when decent existing fits exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 + 20.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size > post_residual {
            score += 5.0; // new bin can't chain the next item immediately
        }
    }

    // Slight preference for bins with smaller residual overall (best-fit flavor).
    score += 0.05 * (bin_residual as f64 - item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer smallest post_residual, scaled non-linearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score *= 1.0 + 0.6 * fit_ratio * fit_ratio;

    // Strong reward for near-perfect fits.
    if post_residual <= 3 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 90.0;
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty for leaving medium dead space.
            let t = step_index as f64 / total_items.max(1) as f64;
            score += 8.0 * (1.0 - t) * (post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: fill any bin as fully as possible.
        score -= 40.0 * fit_ratio;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0 * fit_ratio;
    }

    // Many open bins: encourage closing out existing bins (use fullest ones).
    if open_bins_count > 4 {
        let fullness = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 15.0 * fullness;
    }

    // Global mean residual coupling: penalize bins far from the mean residual
    // when mean residual is small (late consolidation phase).
    if mean_residual > 0.0 {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.15 * dev * (1.0 - mean_residual / bin_capacity as f64);
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let t = step_index as f64 / total_items.max(1) as f64;
        // Base cost of opening a bin, cheaper early, expensive later.
        score = 55.0 + 45.0 * t;
        if item_size >= 60 {
            score -= 10.0; // large items justify fresh bins more
        }
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: must open
        } else if fitting_bins_count == 1 {
            score += 25.0; // one last-chance bin exists; prefer using it
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on post-residual (waste), softened by progress
    let mut score = norm_pr * norm_pr * (1.0 + 0.5 * progress) * cap;

    // Smooth interaction: waste penalized more when bin becomes nearly dead
    let deadness = 1.0 - (norm_pr * 4.0).min(1.0).max(0.0);
    score += deadness * deadness * 3.0;

    // Reward tight fits (small post residual) more strongly early on
    score -= (1.0 - norm_pr).powi(3) * 2.0 * (1.0 - progress);

    // Lookahead: if next item fits into post residual, reward this placement
    if next_item_size > 0 {
        let fits_next = if (pr >= next_item_size as f64) { 1.0 } else { 0.0 };
        score -= fits_next * (1.0 + progress);
        // If next item exactly consumes residual, strong reward
        let exact = 1.0 - ((pr - next_item_size as f64).abs() / cap);
        score -= exact.powi(4) * 1.5;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 4.0;
    }

    // Prefer fuller bins among many open bins (mild)
    score += (open_bins_count as f64).ln().max(0.0) * norm_pr * 0.5;

    // Coupling with mean residual: placing into a bin below mean residual
    // keeps balance; penalize deviations
    score += ((pr - mean_residual) / cap).abs() * 0.8;

    // New-bin candidate: penalize gently so it's chosen only when fits are bad
    if bin_residual == bin_capacity {
        score += 2.5 + 3.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into a
    // "reusable" class (divisible by small integers) are more valuable to keep.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward residuals that are harmonic (divisible by 10, 20, 25, 50).
    if post_residual % 50 == 0 && post_residual > 0 {
        score -= 12.0;
    } else if post_residual % 25 == 0 && post_residual > 0 {
        score -= 7.0;
    } else if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Integer-division threshold: penalize tiny unusable residuals.
    if post_residual < 10 {
        score += 30.0; // dead space
    } else if post_residual < 20 {
        score += 10.0;
    }

    // Coupling with next item: reward a residual that exactly (or nearly)
    // accommodates the lookahead item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 8.0 + (slack as f64) * 0.15;
            if slack == 0 {
                score -= 10.0; // perfect lookahead fit
            }
        } else {
            score += 6.0; // lookahead won't fit here
        }
    }

    // Last-chance bin: strongly favor using the final fitting bin to avoid
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bins
    // are already crowded or the item is huge relative to capacity.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = open_bins_count as f64 / (mean_residual / cap + 1.0);
        let penalty = 20.0 + 25.0 * (1.0 - progress) + crowding * 0.5;
        // Large items relative to capacity justify a new bin.
        let size_frac = item_size as f64 / cap;
        if size_frac > 0.6 {
            score = 5.0 + 10.0 * (1.0 - size_frac);
        } else {
            score += penalty;
        }
    }

    // Mild preference for filling bins tighter than the mean residual.
    if (pr - mean_residual).abs() < 5.0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps that can never hold future items
    // (items >= 1, but realistically small fragments) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 20.0;
    }

    // Reward exact / near-exact fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Perfect fit of residual: item exactly fills the bin.
    if item_size == bin_residual {
        score -= 150.0;
    }

    // Lookahead coupling: if the next item fits in the post residual,
    // this placement chains nicely; otherwise penalize blocking.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 15.0;
        } else if post_residual > 0 {
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage proliferation of bins.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: only attractive when residual would be large dead space
    // or no good fit exists; make the fresh bin slightly less attractive than
    // a reasonable fit but better than a bad one.
    if bin_residual == bin_capacity {
        score = (bin_capacity - item_size) as f64;
        if fitting_bins_count == 0 {
            score -= 200.0; // forced new bin
        } else if (bin_capacity - item_size) < 10 {
            score += 50.0; // would create tiny dead space immediately
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward if next item fits into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits: residual quality depends on what's left after that
            let two_step_left = post_residual - next_item_size;
            score -= 50.0 + (two_step_left as f64).min(40.0);
        } else {
            // next item won't fit here: penalize leaving large dead space
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Prefer tight bins relative to mean residual: filling a loose bin is good.
    if (bin_residual as f64) > mean_residual {
        score -= (bin_residual as f64 - mean_residual) * 0.3;
    } else {
        score += (mean_residual - bin_residual as f64) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize new-bin candidate slightly when open bins exist and fit is decent.
    if bin_residual == bin_capacity {
        score += 50.0 + 10.0 * open_bins_count as f64;
    }

    // Late in stream: prefer closing out bins (use existing space).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit core: reward tight fits quadratically.
    let fit = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 6.0 * fit * fit * bin_capacity as f64;

    // Penalize bins far from full (avoid scattering residual space).
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 4.0 * fill;

    // Lookahead: if the next item fits exactly in the post-residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space that the next item cannot use: penalize.
        score += 0.05 * post_residual as f64;
    }

    // Last-chance bin: if this is the only bin that fits, keep it usable.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    // New-bin candidate handling: only attractive when open bins are nearly saturated.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let saturation = mean_residual / bin_capacity as f64;
        // Prefer new bin when mean residual is low (bins packed) or few bins open.
        let new_bin_bonus = 12.0 * (1.0 - saturation) - 2.0 * open_bins_count as f64
            - 5.0 * progress;
        score -= new_bin_bonus;
        // Base handicap so new bins are only chosen when genuinely better.
        score += 15.0;
    } else {
        // Mild preference for consolidating into bins below mean residual.
        if (bin_residual as f64) < mean_residual {
            score -= 1.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual, with non-linear sharpening
    let mut score = pr as f64;

    // Smooth non-linear coupling of post residual with stream progress:
    // early in the stream, keep bins flexible (penalize tiny residuals mildly),
    // late in the stream, exploit tight fits aggressively.
    let tightness = x * x; // convex penalty for large dead space
    let urgency = progress * progress;
    score += 20.0 * tightness * (0.5 + urgency);

    // Reward very tight fits more as stream progresses (smooth interaction)
    score -= 25.0 * (1.0 - x) * (1.0 - x) * urgency;

    // Last-chance bonus: strongly favor the only bin that fits (smooth in fitting count)
    let last_chance = 1.0 / (fitting_bins_count as f64);
    score -= 15.0 * last_chance * (1.0 - urgency * 0.5);

    // Lookahead coupling: if next item fits into the post residual, reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr as u32 >= next_item_size {
            let fit_slack = (pr - nxt) / cap;
            score -= 10.0 * (1.0 - fit_slack) * (1.0 - progress);
        } else {
            // next item won't fit here; penalize leaving a residual close to but below next item
            let gap = (nxt - pr) / cap;
            score += 8.0 * (1.0 - gap) * (1.0 - gap);
        }
    }

    // Mild penalty for proliferating bins relative to mean residual state
    score += (open_bins_count as f64).ln() * (1.0 - (x - mean_residual / cap).abs());

    // Slight preference to keep residuals near mean early on (flexibility)
    score += 5.0 * (1.0 - progress) * (x - mean_residual / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: which capacity fraction bucket does post_residual fall in?
    let class = post_residual / 10; // 0..=9 residual decile
    let class_weight = match class {
        0 => -6.0,   // near-perfect fit: strong reward
        1 => -4.0,
        2 => -2.5,
        3 => -1.0,
        4 => 0.5,
        5 => 1.5,
        6 => 2.5,
        7 => 3.5,
        8 => 4.5,
        _ => 5.5,    // mostly-empty bin after placement: wasteful
    };
    score += class_weight;

    // Modulo arithmetic on post_residual: residues that pair well with common item sizes
    // (multiples of 5 and 10) are more reusable.
    let r = post_residual % 10;
    if r == 0 {
        score -= 3.0;
    } else if r == 5 {
        score -= 1.5;
    } else if r >= 8 {
        score += 1.0;
    }

    // Lookahead coupling: does the next item fit into the post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward exact/near-exact lookahead matches (harmonic pairing)
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 8.0;
            } else if gap <= 5 {
                score -= 4.0;
            } else if gap <= 15 {
                score -= 2.0;
            }
        } else {
            // Next item won't fit here: penalize slightly, more if this bin is nearly full
            let overflow = next_item_size - post_residual;
            score += (overflow as f64) * 0.05;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 5.0;
    }

    // New-bin candidate handling: opening a fresh bin wastes capacity unless
    // current bins would leave very awkward residues.
    if bin_residual == bin_capacity {
        // Base cost of a new bin relative to mean residual of open bins
        score += 25.0;
        // But if open bins are all nearly full (mean residual small), new bin is fine
        score -= (mean_residual * 0.4).min(20.0);
        // If next item is huge, a fresh bin preserves large space for it
        if next_item_size >= 60 && next_item_size <= post_residual {
            score -= 12.0;
        }
        // Late in the stream, prefer consolidating into existing bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 5.0;
    }

    // Prefer filling bins that are already committed (higher fill ratio)
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 2.0;

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- Strict dead-space avoidance ---
    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead space is worse when it's small but nonzero: unusable sliver.
        // Penalize gaps that cannot hold the next item (true dead space).
        if next_item_size > 0 && post_residual < next_item_size {
            let dead = (next_item_size - post_residual) as f64;
            score += 2.5 * dead + 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
        // Gaps that CAN hold the next item are valuable: reward them.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0 + 0.5 * post_residual as f64;
        }
        // Penalize very small unusable slivers nonlinearly (sliver = < 10% of capacity).
        let sliver_frac = post_residual as f64 / bin_capacity as f64;
        if sliver_frac > 0.0 && sliver_frac < 0.1 {
            score += 40.0 * (0.1 - sliver_frac) / 0.1;
        }
    }

    // --- Last-chance pressure ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        // This is the only bin that fits; strongly favor using it over a new bin.
        score -= 60.0;
    }

    // --- Open-bins pressure: discourage opening new bins when many are open ---
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus pressure from open bins.
        score += 25.0 + 8.0 * open_bins_count as f64;
        // Late in the stream, opening new bins is extra wasteful.
        score += 30.0 * progress;
        // If an existing bin leaves room for the next item, prefer it over a new bin.
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 15.0;
        }
    } else {
        // Mild reward for consolidating into already-open bins.
        score -= 2.0 * open_bins_count as f64;
    }

    // --- Mean-residual coupling: prefer bins whose residual deviates from mean
    // in the "tight" direction (below mean residual = already well-packed). ---
    let dev = mean_residual - bin_residual as f64;
    score += 0.3 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills heavily.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - nxt).abs();
        if diff == 0.0 {
            score -= 500.0;
        } else {
            // Penalize residuals that cannot host the next item at all.
            if pr < nxt {
                score += 40.0 + (nxt - pr) * 0.5;
            } else {
                // Slack grows quadratically: waste is worse the bigger the leftover.
                score += diff * diff * 0.02;
            }
        }
    }

    // Compare against mean residual: prefer bins whose post residual stays near/below mean
    // (keeps a portfolio of usable residuals rather than many tiny dead slots).
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        score += (pr - mean_residual).abs() * 0.3;
        if pr < mean_residual * 0.5 {
            score -= 15.0; // compacting a loose bin is good
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
        if post_residual <= 20 {
            score -= 60.0;
        }
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when the item
    // is large and no open bin offers a good fit.
    if bin_residual == bin_capacity {
        let tight_fit_elsewhere = fitting_bins_count > 0 && (bin_residual - item_size) as f64 > mean_residual;
        let base = 300.0 + item_size as f64 * 0.5;
        if next_item_size > 0 && (next_item_size as f64) <= 100.0 - item_size as f64 {
            // pairing potential with next item in a fresh bin
            score -= 60.0;
        }
        if tight_fit_elsewhere {
            score += 250.0;
        }
        score += base * (0.5 + 0.5 * (step_index as f64 / (total_items.max(1) as f64)));
    }

    // Late in the stream: prefer closing bins tightly, waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.2 * progress;

    // Mild penalty for spreading across many open bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items
    // (items between 1 and 100; unusable slivers are costly).
    if post_residual > 0 && post_residual < 15 {
        score += 25.0 * (1.0 - post_residual as f64 / 15.0);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Extra reward for exact-looking chaining
            let gap = post_residual - next_item_size;
            if gap < 10 {
                score -= 8.0;
            }
        } else {
            // Penalize placements that strand space the next item could nearly use
            score += 6.0;
        }
    }

    // Time horizon: early in the stream, be more conservative (favor spreading
    // across bins to preserve flexibility); late, prefer filling existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;

    // Global state: many open bins with large mean residual -> discourage
    // opening yet another bin; few open bins -> new bin is cheaper.
    let open_penalty = (open_bins_count as f64).ln().max(0.0) * 4.0;
    if bin_residual == bin_capacity {
        // New-bin candidate baseline: competitive but penalized when many
        // open bins already exist with slack.
        score += open_penalty;
        score += 5.0 * (mean_residual / bin_capacity as f64).min(1.0);
        // Late in the stream, opening new bins is fine (few items left to strand).
        score -= 15.0 * progress;
    } else {
        // Existing bin: small bonus relative to mean residual alignment.
        if (bin_residual as f64) > mean_residual {
            score += 2.0;
        }
    }

    // Mild penalty for very large items going into nearly-full bins (waste risk)
    if item_size > 70 && post_residual > 0 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual (tight fit), with non-linear shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Polynomial coupling of post_residual with stream progress:
    // later in the stream, waste is penalized more aggressively (quadratic in progress)
    let coupling = pr * (0.8 + 2.2 * progress * progress);
    score += 0.6 * coupling;

    // Smooth interaction: post_residual vs next item lookahead
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (nxt - pr).abs();
        // reward when post_residual matches next item size (smooth kernel)
        let match_bonus = (gap * gap) / (cap * cap);
        score -= 6.0 * (-4.0 * match_bonus).exp() * (1.0 - 0.3 * progress);
        // penalize post_residual slightly smaller than next item (dead space)
        if pr < nxt {
            score += 3.0 * (1.0 - pr / nxt) * (1.0 + progress);
        }
    }

    // Last-chance bin: strong smooth reward, scaled by scarcity of fitting bins
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 + 0.5 * progress);
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // Mean residual coupling: prefer bins below mean residual (tighter than average)
    score += 0.8 * (mean_residual - pr) * (0.5 + progress);

    // New-bin candidate: penalize smoothly unless current fit is very poor
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / cap;
        // open new bin if item is small relative to capacity or many bins open
        score += 15.0 - 10.0 * tightness * tightness - 0.3 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residues near 0 are ideal (tight fit).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity left after placement.
    let frac = pr / cap;

    // Penalize leftovers that fall in "dead zones": small but unusable slivers.
    // Use modulo classes on post_residual: leftover in {1..=5} is great (tight),
    // {6..=15} is a dead zone (too small for typical items 10..80).
    let tightness = (post_residual % 100) as f64;
    if post_residual == 0 {
        score -= 40.0; // perfect fit
    } else if post_residual < 6 {
        score -= 25.0; // near-perfect: unusable sliver, effectively a full bin
    } else if post_residual <= 15 {
        score += 18.0; // dead zone: too small for min-size future items
    } else if post_residual <= 25 {
        score += 6.0;  // marginal zone
    } else {
        score -= 4.0;  // still roomy enough for future items
    }

    // Harmonic subdivision of capacity: reward bins whose residual matches
    // common item-size harmonics (multiples of 10, 20, 25, 50).
    let harmonic_bonus = if post_residual % 50 == 0 {
        12.0
    } else if post_residual % 25 == 0 {
        8.0
    } else if post_residual % 10 == 0 {
        5.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly favor this bin (chained fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let chain_left = post_residual - next_item_size;
            // Reward chains that leave tight or zero leftovers.
            if chain_left == 0 {
                score -= 22.0;
            } else if chain_left < 6 {
                score -= 14.0;
            } else if chain_left <= 15 {
                score += 10.0; // chain would create a dead zone
            } else {
                score -= 3.0;
            }
        } else {
            // Next item cannot use the leftover; leftover should be small or harmonic.
            score += frac * 10.0;
        }
    }

    // Last-chance logic: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: opening a new bin should only win when the current item
    // is large and all open residuals are poor. Penalize the fresh bin mildly,
    // more so early in the stream when consolidation is cheap.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 + 15.0 * (1.0 - progress);
        // If item is big, a fresh bin is actually reasonable (leaves predictable residue).
        if item_size > 50 {
            score -= 18.0;
        }
        // If many bins are open with slack, discourage scattering.
        if mean_residual > 30.0 && open_bins_count > 3 {
            score += 12.0;
        }
    }

    // Mild preference to fill bins with below-average residual (consolidate slack).
    if bin_residual != bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += 0.15 * dev;
    }

    // Small tie-breaker noise-free deterministic jitter on harmonic class.
    let class = (post_residual % 7) as f64;
    score += class * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    // Define "unusable" as a residual too small for the smallest plausible item (<= 12),
    // or a gap that cannot fit the known next item.
    let tiny_gap = post_residual <= 12;
    let blocks_next = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size;
    if tiny_gap {
        score += 40.0; // dead space penalty
    } else if blocks_next {
        score += 18.0;
    }

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual >= next_item_size.max(1) && next_item_size > 0 {
        // This bin can still host the next item: reward chainability.
        score -= 8.0;
    }

    // Open-bin pressure: discourage proliferation of bins.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin: penalize mildly, scaled by stream progress
        // (late in the stream, opening bins is more wasteful).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 + 20.0 * progress;
        // But if the current item is large, a fresh bin is actually good.
        if item_size >= 60 {
            score -= 15.0;
        }
        // If open bins are mostly full (low mean residual), a new bin is fine.
        if mean_residual < 20.0 {
            score -= 10.0;
        }
    }

    // Slight preference for bins whose residual is closest to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: perfect match of next item into post_residual is a jackpot.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 200.0; // perfect 2-chain: post_residual consumed by next item
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Prefer leaving enough room for the next item; penalize excess slack mildly.
            score -= 40.0 - slack * 0.15;
        } else {
            // Next item won't fit here: penalize dead space proportional to how
            // much of post_residual is unusable for the next item.
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 0.5;
        }
    }

    // Reward tight fits relative to mean residual across open bins.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= tightness * 30.0;

    // Penalize bins whose residual is far above the mean (they're already fragmented).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        // When many bins fit, prefer the one with the least post_residual waste.
        score += (fitting_bins_count as f64) * 2.0;
    }

    // New-bin candidate: keep it neutral-ish; only attractive when no open bin
    // offers a decent fit (post_residual large relative to capacity).
    if bin_residual == bin_capacity {
        // Slight penalty so we prefer reusing bins unless fits are terrible.
        score += 35.0;
        // But if this is a large item and post_residual elsewhere would be tiny,
        // the lookahead terms above will dominate; soften penalty late in stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 20.0;
    }

    // Discourage leaving very small, hard-to-fill residuals (< 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let t = step_index as f64 / total_items.max(1) as f64;

    // Base best-fit bias: strongly prefer tight fits.
    score += 0.35 * (post_residual as f64 / bin_capacity as f64).powi(3) * bin_capacity as f64;

    // Reward exact / near-exact fills heavily.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward leaving
    // exactly that room; penalize wasting space the next item can't use.
    if next_item_size > 0 {
        let gap = post_residual as f64 - next_item_size as f64;
        if gap == 0.0 {
            score -= 40.0; // perfect chaining opportunity
        } else if gap > 0.0 && gap <= 15.0 {
            score -= 18.0; // next item likely fits here too
        } else if gap > 0.0 {
            score -= 3.0 * (gap / 100.0); // mild preference
        } else {
            // next item won't fit in the leftover: dead space risk
            score += 6.0 * (-gap / 100.0);
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0 + 10.0 * t;
    }

    // When many bins are open, encourage consolidation into existing bins.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score -= 2.5 * open_pressure * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: if this bin's residual is far below average,
    // it's a tight bin — favor filling it; if far above, it's roomy.
    let dev = mean_residual - bin_residual as f64;
    score += 0.08 * dev;

    // Time horizon: late in the stream, be more aggressive about closing
    // bins tightly (dead space is costlier when few items remain to fill it).
    score += 8.0 * t * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: an empty bin is a fallback; prefer it only
    // when no open bin offers a decent fit (post_residual near capacity means
    // item barely dents the bin, i.e., this is likely the new-bin call).
    if bin_residual == bin_capacity {
        // Neutral-ish baseline; slightly penalized so good existing fits win,
        // but low enough that a poor existing fit (huge leftover) loses.
        score = bin_capacity as f64 * 0.9 - 0.10 * open_pressure + 5.0 * t;
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 4.0; // new bin can also host the next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post residual), with non-linear penalty on mid-size waste.
    let mut score = pr * (1.0 + 0.8 * norm_pr * (1.0 - norm_pr));

    // Stream-progress coupling: early on, waste matters less; late, squeeze hard.
    let progress_coupling = 1.0 + 1.5 * progress * progress;
    score *= progress_coupling;

    // Reward filling a bin nearly completely with smooth polynomial term.
    let fill = 1.0 - norm_pr;
    score -= 12.0 * fill * fill * fill;

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 20.0 + 10.0 * progress;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let snug = 1.0 - ((pr - next_item_size as f64) / cap).abs();
        score -= 8.0 + 6.0 * snug;
    } else if next_item_size > 0 {
        // Penalize leaving a residual that likely becomes dead space.
        score += 4.0 * (1.0 - pr / (next_item_size as f64 + 1.0)).max(0.0);
    }

    // Mean-residual coupling: if this bin is far from the mean, smooth penalty.
    score += 0.15 * (pr - mean_residual).abs();

    // Discourage opening new bins when good fits exist, especially early.
    if bin_residual == bin_capacity {
        let scarcity = (fitting_bins_count as f64).recip();
        score += 15.0 + 25.0 * (1.0 - progress) * scarcity;
    } else {
        score -= 3.0; // small bonus for reusing open bins
    }

    // Mild pressure against bin proliferation.
    score += 0.5 * (open_bins_count as f64).ln();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues that are "dead space"
    // (too small for typical items) should be penalized more than the raw value.
    let dead_threshold = 10u32;
    if post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 3.0; // unusable sliver
    }

    // Classify post_residual by harmonic class modulo 10: small residues in
    // classes 1..9 are near-dead; class 0 (exact multiples) are reusable.
    let cls = (post_residual % 10) as f64;
    if post_residual > 0 {
        score += cls * 0.8;
    } else {
        score -= 25.0; // perfect fill: strongly reward exact packing
    }

    // Reward tight fits: residual close to item size relative to capacity.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= tightness * 12.0;

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // this bin is a great choice; if next item cannot fit, penalize mildly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual {
            score += 6.0;
        } else {
            // next fits: favor leaving a residue in a "good class"
            let gap = post_residual - next_item_size;
            if gap < dead_threshold {
                score += (dead_threshold - gap) as f64 * 1.5;
            } else {
                score -= 4.0;
            }
        }
    } else {
        // last item: prefer fullest bin
        score -= 15.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: opening a fresh bin is only attractive when the item
    // is large and no open bin offers a good fit.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        if item_size >= 60 && pressure > 0.5 {
            score -= 10.0;
        } else {
            score += 18.0; // discourage wasting fresh capacity on small items
        }
    }

    // Stream progression: early on, be conservative about opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * 8.0;
    }

    // Mild penalty for many open bins with high mean residual (fragmentation).
    score += open_bins_count as f64 * 0.05 + mean_residual * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for typical future
    // items (say < 10) are worthless; gaps in [1..12) are "dead" unless post_residual == 0.
    if post_residual > 0 && post_residual < 12 {
        score += 25.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Tightness ratio: reward using a large fraction of the bin's residual.
    let fill_frac = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fill_frac;

    // Last-chance bin: strongly favor using the only bin that can fit,
    // avoids opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; with few, opening a new bin is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 1.5 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Lookahead: if the next item fits into the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    }
    // If next item would leave this bin with a dead gap, penalize.
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size < 12 && post_residual - next_item_size > 0 {
        score += 10.0;
    }

    // Mean residual coupling: prefer bins with residual below the mean
    // (fill the emptiest-but-fitting bins less; keep large residuals flexible).
    if (bin_residual as f64) < mean_residual {
        score += 6.0;
    } else {
        score -= 3.0;
    }

    // New-bin candidate handling: an empty bin is a fresh resource.
    if bin_residual == bin_capacity {
        // Opening a new bin is expensive when many bins are open; cheap early.
        score = 45.0 + 2.0 * open_bins_count as f64 - 30.0 * progress;
        // If no existing bin fits well (item barely fits anywhere), new bin looks good.
        if item_size > 90 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly favor bins where the item fills the residual.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item exactly fits the post residual,
    // this is a chain fit — reward it heavily.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size < post_residual {
            // Next item fits too: penalize proportionally to leftover dead space
            // after the hypothetical second placement.
            let second_leftover = post_residual - next_item_size;
            score += second_leftover as f64 * 0.5;
        } else {
            // Next item won't fit in this bin after placement: the leftover
            // post_residual is likely dead space. Penalize it more.
            score += post_residual as f64 * 0.3;
        }
    }

    // Relative-to-mean coupling: prefer bins with residual below the mean
    // (tighter bins get filled first), penalize very loose bins.
    score += (bin_residual as f64 - mean_residual) * 0.4;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: opening a new bin is only attractive when the item is large
    // relative to capacity and no decent fit exists.
    if bin_residual == bin_capacity {
        let fit_quality = if bin_residual >= item_size {
            (bin_residual - item_size) as f64 / bin_capacity as f64
        } else {
            1.0
        };
        // Baseline penalty for opening a bin, reduced when the item is big
        // (large items waste less of a fresh bin).
        let item_ratio = item_size as f64 / bin_capacity as f64;
        score += 120.0 - item_ratio * 80.0 + fit_quality * 50.0;
    }

    // Late-stream consolidation: as the stream progresses, prefer filling
    // existing bins over spreading out.
    let progress = step_index as f64 / total_items as f64;
    score += post_residual as f64 * progress * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (waste minimization, non-linear).
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 30.0 * tightness * tightness;

    // Lookahead: if the next item can exactly fill the post residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits here later; slight reward proportional to how well.
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / (post_residual.max(1) as f64));
        } else {
            // Next item cannot use the residual: penalize large stranded residuals.
            score += 8.0 * ((post_residual as f64) - (bin_capacity as f64 - next_item_size as f64)).max(0.0) * 0.1;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins: discourage hoarding residuals, encourage consolidation.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(0.0) / 10.0);
    score += 0.5 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: late in the stream, be greedier (avoid leaving many small bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * tightness;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let bad_open_fit = if fitting_bins_count == 0 { 40.0 } else if post_residual as f64 + item_size as f64 > 0.0 && (bin_capacity - item_size) < 20 { 20.0 } else { 0.0 };
        score += 15.0 - bad_open_fit;
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 10.0; // next item pairs well with a fresh bin
        }
    }

    // Penalize residuals too small for any plausible future item (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;

    // Base: quadratic penalty on wasted residual, damped as stream progresses
    let mut score = pr * (1.0 + 0.9 * fit_norm * (1.0 - progress));

    // Smooth non-linear coupling: tight fits rewarded more late in the stream
    let tightness = 1.0 - fit_norm;
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Penalize residual that cannot fit the lookahead item (smooth interaction)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).max(0.0) / cap;
        let unusable = if pr < nx { 1.0 } else { 0.0 };
        score += 8.0 * unusable * (0.4 + 0.6 * progress) * (nx / cap);
        score += 4.0 * gap * gap * (1.0 - progress);
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }

    // New-bin candidate: mildly discouraged unless existing residuals are poor
    if bin_residual == bin_capacity {
        let mean_gap = (mean_residual - pr) / cap;
        score += 6.0 + 10.0 * (mean_residual / cap).max(0.0) - 8.0 * mean_gap.max(0.0);
    }

    // Mild dispersion penalty: prefer bins near the mean residual
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Harmonic class of post_residual: tiny leftovers are dead space.
    if post_residual > 0 {
        let pr = post_residual;
        // class by residue modulo capacity quarters
        let q = bin_capacity / 4; // 25
        let r = pr % q;
        let dead_penalty = match r {
            0 => -30.0,               // perfectly aligned residual
            1..=5 => 45.0,            // nearly-dead sliver
            6..=15 => 20.0,           // awkward band
            _ => 0.0,
        };
        score += dead_penalty;
        // sliver threshold: residual < 10 is unusable (min item size ~1..100 unknown, but tiny waste hurts)
        if pr < 8 {
            score -= 25.0; // finishing a bin exactly is great
        }
    } else {
        score -= 40.0; // perfect fit
    }

    // Lookahead coupling: reward if next item fits into post_residual (harmonic chaining)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0 + 0.15 * next_item_size as f64;
        } else {
            // penalize residuals that just barely fail to hold next item
            let gap = next_item_size - post_residual;
            if gap <= 6 && post_residual > 0 {
                score += 12.0;
            }
        }
        // modulo harmony: next_item_size class vs post_residual class
        let q = bin_capacity / 4;
        if q > 0 && next_item_size % q == post_residual % q && post_residual >= next_item_size {
            score -= 10.0;
        }
    } else {
        // last item: prefer tightest fill
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0 + 20.0 * progress;
    }

    // New-bin candidate handling: only attractive when current bin fit is poor
    if bin_residual == bin_capacity {
        let crowded = mean_residual / bin_capacity as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative
        } else if fitting_bins_count == 1 {
            // keep last-chance usage unless residual is huge waste
            score = 60.0 + crowded * 30.0;
        } else {
            score = 55.0 + 25.0 * (1.0 - progress) + crowded * 20.0;
        }
    }

    // Mild preference to fill bins with larger residuals when many bins open
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual below 10 (min item size) is pure waste; ramp penalty as gap shrinks.
    if post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    } else if post_residual <= 25 {
        // Medium gaps: mildly risky, penalize proportionally to how little can fit.
        score += 12.0 * (25.0 - post_residual as f64) / 15.0;
    }

    // Reward near-perfect fits (tight packing) with a strong subtraction.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // penalize leaving large residuals so bins close out faster.
    let open_pressure = (open_bins_count as f64).ln().max(0.0) * 4.0;
    score += open_pressure * (post_residual as f64 / bin_capacity as f64);

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly reward this placement (chained packing).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0; // next item still fits: keep this bin attractive
    }

    // New-bin candidate: only attractive when this bin would leave a big
    // unusable gap or when open bins are congested (high mean residual spread).
    if bin_residual == bin_capacity {
        let gap_penalty = if post_residual < 10 { 25.0 } else { 0.0 };
        score += gap_penalty;
        score -= 5.0 * open_pressure;
        // If the current bin is the only fitting one, opening a new bin is bad.
        if fitting_bins_count == 1 {
            score += 80.0;
        }
    }

    // Early stream: be slightly more conservative (keep fresh bins available).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 3.0 * (post_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it's already tight — favor filling it further.
    let bin_res_f = bin_residual as f64;
    if bin_res_f < mean_residual {
        score -= (mean_residual - bin_res_f) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // 2-step lookahead: reward exact match of post_residual with next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect two-item fill
        } else if post_residual > next_item_size {
            // next item still fits: reward proportionally to how much remains after
            let after = post_residual - next_item_size;
            score -= 30.0 - (after as f64 / bin_capacity as f64) * 25.0;
        } else {
            // next item won't fit here: penalize wasted residual
            score += (post_residual as f64) * 0.4;
        }
    }

    // Relative to mean residual: avoid bins with unusually large residuals
    // unless this placement brings them near mean
    let dev = post_residual as f64 - mean_residual;
    score += dev.abs() * 0.15;

    // Last chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, more so late in stream
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 + 30.0 * progress;
        // but if next item is huge and this item leaves bad space elsewhere, allow it
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 20.0;
        }
    }

    // Prefer reusing many-open-bins situations rather than growing bin count
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary: reward tight fits nonlinearly.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Dead-space penalty: post-residual too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            // Partial reward scaled by how well next item fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty for leaving awkward gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 5.0 * (gap / bin_capacity as f64);
        }
    } else {
        // Last item: prefer minimal final residual.
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer bins with residual below mean (consolidate fuller bins).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // New-bin candidate handling: empty bin gets neutral post_residual (=capacity),
    // penalize opening new bins when decent fits exist, more so early/mid stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_pressure = (open_bins_count as f64).ln() + 1.0;
        score += 25.0 * open_pressure * (1.0 - 0.5 * progress);
        // Allow new bin if item is huge and no bin fits well.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild time pressure: later in stream, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer small post residual, with non-linear sharpening over stream progress.
    let mut score = x * (1.0 + 2.0 * t * t) * cap;

    // Smooth polynomial coupling: penalize mid-range waste more as stream progresses.
    score += 8.0 * t * x * (1.0 - x) * cap;

    // Reward tight fits (post_residual near 0) via smooth inverse-like polynomial.
    score -= (1.0 - x).powi(3) * (1.0 + t) * 15.0;

    // Lookahead: reward bins whose residual after placement matches next item.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let gap = (pr - n).abs();
        score += 0.35 * gap * (0.5 + 0.5 * t);
        // Perfect next-fit bonus
        if (pr as u32) == next_item_size {
            score -= 20.0 * (1.0 + t);
        }
    } else {
        // Last item: strongly prefer closing bins exactly.
        score -= (1.0 - x).powi(4) * 40.0;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - 0.5 * t);
    } else {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // Mean residual coupling: prefer bins below mean residual (denser bins) smoothly.
    score += 0.5 * (mean_residual - pr).max(-cap) * (0.5 + t);

    // Penalize opening a new bin mildly when open bins fit well; smooth in stream progress.
    if bin_residual == bin_capacity {
        let fit_quality = if next_item_size > 0 { ((pr - next_item_size as f64).abs()) } else { cap };
        score += 30.0 * (1.0 - t * 0.5) - 0.2 * fit_quality * t;
        // New bin attractive if existing bins are all loose.
        score += 0.3 * mean_residual * t;
    }

    // Mild open-bin pressure: with many bins open, favor consolidation.
    score += 0.15 * open_bins_count as f64 * x * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by modulo bands.
    let pr = post_residual;
    let cls = pr % 10; // decade remainder class

    // Reward perfect or near-perfect fits (small post_residual).
    if pr == 0 {
        score -= 200.0;
    } else if pr <= 5 {
        score -= 60.0;
    } else if pr <= 10 {
        score -= 25.0;
    } else if pr <= 20 {
        score -= 8.0;
    }

    // Penalize "awkward" residual classes: residuals that few typical item sizes
    // (1..100) can fill. Residual mod 10 in {1,2,3} tends to be dead space
    // unless a tiny item arrives; penalize, reward round classes.
    match cls {
        0 => score -= 12.0,          // round residuals pair with round items
        1 | 2 | 3 => score += 15.0,  // awkward dead space
        4 | 5 | 6 => score += 5.0,   // middling
        _ => {}                      // 7,8,9 fine
    }

    // Integer-division threshold: how many "half-capacity" chunks fit in leftover.
    let halves = pr / 50;
    if halves == 0 && pr > 0 {
        score += 6.0; // less than half a bin wasted
    } else if halves >= 1 {
        score -= 6.0 * halves as f64; // large leftovers still useful
    }

    // Lookahead coupling: does next item fit the post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 40.0; // chains the next item perfectly
            // Extra reward if next item exactly fills post_residual.
            if next_item_size == pr {
                score -= 40.0;
            }
        } else {
            // Next item won't fit here; if this bin is the last chance, still prefer it.
            let overflow = (next_item_size - pr) as f64;
            score += 0.15 * overflow;
        }
    } else {
        // Last item: any residual is pure waste; minimize it strongly.
        score += 30.0;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a new bin wastes (capacity - item).
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score += waste; // base cost of fresh bin
        // Open a new bin only if existing bins are fragmented (high mean residual spread)
        // or the item is large and would leave awkward residue everywhere.
        if mean_residual < 20.0 {
            score -= 10.0; // existing bins tight -> new bin reasonable
        } else {
            score += 0.5 * mean_residual; // existing bins roomy -> prefer them
        }
        if item_size >= 70 {
            score -= 25.0; // big items start fresh bins well
        }
        if next_item_size > 0 && next_item_size > item_size {
            score -= 15.0; // next item bigger: fresh bin may serve it
        }
    }

    // Stream progression: early on, be greedy about consolidation; late, tolerate spread.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.15 * progress;

    // Open bins count pressure: many open bins -> favor consolidation into existing.
    score += 0.3 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest possible item (size 1) are fine, but tiny-but-real gaps
    // (1..=12) are likely unusable dead space -> heavy penalty.
    if post_residual > 0 && post_residual <= 12 {
        score += 60.0 * (13.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 100.0;
    }

    // Reward tight fills: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: penalize placements that spread across many open
    // bins; encourage consolidating into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    // Prefer bins whose residual is close to the item (minimal waste).
    let waste = (bin_residual as f64 - item_size as f64).abs();
    score += 0.4 * waste;

    // Lookahead coupling: if the next item fits exactly in the post
    // residual, reward leaving that gap; otherwise mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size > post_residual {
            score += 8.0;
        }
    }

    // Mean-residual coupling: placing into a bin with residual far below
    // mean residual is a good consolidation move.
    score -= 0.3 * (mean_residual - bin_residual as f64).max(0.0);

    // New-bin candidate: only attractive when no open bin offers a decent
    // fit or the item is huge relative to capacity.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 || item_size >= 70 {
            score -= 30.0;
        } else {
            score += 90.0 + 3.0 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward when the NEXT item exactly fills the post residual (2-step lookahead).
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs();
        score -= 60.0 * (1.0 - lookahead_gap as f64 / bin_capacity as f64);
        // Exact chain fit: post_residual == next_item_size -> near-perfect placement.
        if post_residual == next_item_size {
            score -= 200.0;
        }
        // Post residual slightly larger than next item still useful, but penalize overshoot.
        if next_item_size as u32 > post_residual {
            score += 0.35 * (next_item_size as f64 - post_residual as f64);
        }
    } else {
        // Last item: minimize waste directly.
        score = post_residual as f64 * 2.0;
    }

    // Penalize tiny unusable dead space (fragmentation), especially when no lookahead use.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Relative to mean residual: prefer bins tighter than average (good fill),
    // penalize dumping into already-loose bins.
    let mean_gap = post_residual as f64 - mean_residual;
    score += 0.4 * mean_gap;

    // Prefer fuller bins: scale penalty by fill ratio.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 20.0 * fill;

    // New-bin candidate: only attractive when open bins are fragmented or none fit well.
    let is_new_bin = bin_residual == bin_capacity && item_size > 0;
    if is_new_bin {
        // Base cost of opening a new bin; grows with number of open bins.
        score = bin_capacity as f64 + 30.0 + 4.0 * open_bins_count as f64;
        // Cheaper to open a bin early in the stream (more future items to fill it).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 40.0 * progress;
        // If the item leaves a large residual that nothing can use, opening fresh is better.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // If next item would fit the residual left in the new bin, less attractive to open.
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward dead space (post_residual small but nonzero is fine;
    // mid-range leftovers are the worst).
    let pr = post_residual as f64;
    if pr > 0.0 {
        let awkward = 1.0 - ((pr / 30.0).powi(2)).min(1.0);
        score += 12.0 * awkward;
    }

    // Perfect closure bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: reward if the next item fits into the post-residual (chaining),
    // penalize if post_residual can hold next item but barely (would strand it).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - slack / 40.0).clamp(0.0, 1.0);
        } else if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
            // dead space for the known next item
            score += 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity unless
    // current residuals are fragmented or the item fits nothing well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // New bins are more acceptable early and when mean residual is low.
        let openness = 0.35 * (1.0 - progress) + 0.25 * (1.0 - mean_residual / bin_capacity as f64);
        let good_fit_exists = fitting_bins_count > 0 && fit_ratio > 0.7;
        score += 55.0 - 90.0 * openness;
        if good_fit_exists {
            score += 45.0; // don't open new bins when a tight fit already exists
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 20.0; // a fresh bin helps chain large items
        }
    }

    // Mild preference for consolidating into fewer bins when many are open.
    score += 0.8 * open_bins_count as f64 * (1.0 - fit_ratio);

    // Slight time pressure: later in the stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post_residual as f64 / bin_capacity as f64;
    let norm_item = item_size as f64 / bin_capacity as f64;
    let norm_next = next_item_size as f64 / bin_capacity as f64;

    // Smooth non-linear coupling: post_residual polynomial in progress
    let poly = norm_post * norm_post * (1.0 - progress) + norm_post * norm_post * norm_post * progress;
    score += 40.0 * poly;

    // Tight fit reward: smooth (not piecewise) sigmoid-like bonus near zero residual
    let tight = (-norm_post * 12.0).exp() - 1.0;
    score -= 25.0 * tight * (0.5 + 0.5 * progress);

    // Lookahead coupling: penalize residuals that neither fit nor help next item
    if next_item_size > 0 {
        let fits_next = if post_residual >= next_item_size { 1.0 } else { 0.0 };
        let gap = (post_residual as f64 - norm_next * bin_capacity as f64).abs();
        score += fits_next * (-gap / 30.0).exp() * (-8.0); // reward next-item compatibility
        score += (1.0 - fits_next) * 15.0 * (0.3 + 0.7 * progress); // penalize dead space when next item can't fit
    }

    // Last-chance bin: strong reward when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - norm_post) * (0.5 + 0.5 * progress);
    } else if fitting_bins_count > 1 {
        score += 4.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Mean-residual divergence penalty: avoid bins far from fleet average
    let dev = (post_residual as f64 - mean_residual).abs() / bin_capacity as f64;
    score += 10.0 * dev * dev;

    // New-bin candidate: neutralize base residual, add mild cost that shrinks with progress
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * (1.0 - norm_item) + 12.0 * (1.0 - progress) - 6.0 * progress;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // Fragmentation quadratic term
    score += 0.05 * (post_residual as f64).powi(2) / 100.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit -> overwhelming priority
    if post_residual == 0 {
        return -10000.0;
    }

    // Harmonic class of post_residual: how it decomposes modulo small divisors
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Small dead space classes: residuals <= 10 are nearly useless
    if post_residual <= 10 {
        score -= 60.0; // reward wasting almost nothing
    } else if post_residual <= 20 {
        score -= 20.0;
    }

    // Modulo structure: residuals divisible by common item sizes (10,20,25) are reusable
    let reusable = (post_residual % 10 == 0) || (post_residual % 20 == 0) || (post_residual % 25 == 0);
    if reusable {
        score -= 15.0;
    }

    // Harmonic fraction: post_residual as fraction of capacity
    let frac = pr / cap;
    if frac < 0.1 {
        score -= 25.0 * (0.1 - frac);
    } else {
        // penalize leaving large residual that likely won't be filled
        score += 10.0 * frac * frac;
    }

    // Last-chance bin: strongly favor to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // among many candidates, prefer tighter fit (base post_residual already does this)
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead: if next item fits into post_residual exactly, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            let next_left = post_residual - next_item_size;
            score -= 30.0 - 0.5 * next_left as f64;
        } else {
            // next item won't fit here; slight penalty if this bin's residual is mid-range
            let gap = (next_item_size - post_residual) as f64;
            score += 5.0 * (1.0 - gap / cap).min(1.0);
        }
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    // Prefer opening a new bin only when no open bin gives a decent fit.
    if bin_residual == bin_capacity {
        // baseline cost of a new bin; tight fits elsewhere will beat it
        score = 0.5 * cap;
        if fitting_bins_count <= 1 {
            score -= 60.0; // no real alternative -> open new bin
        }
        if post_residual as f64 > mean_residual * 2.0 && open_bins_count > 0 {
            score += 10.0;
        }
        // late in stream, reuse bins more aggressively
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * (1.0 - progress);
        return score;
    }

    // Mild preference for filling already-open bins when many are open
    score += 0.5 * open_bins_count as f64;

    // Alignment with mean residual: bins close to mean residual are "typical" targets
    let dev = (pr - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Post-residuals in the "unusable gap" zone are heavily penalized:
    // gaps too small for the minimum plausible item (<= 12) are wasted space.
    if post_residual > 0 && post_residual <= 12 {
        score += 60.0 * (1.0 - post_residual as f64 / 12.0);
    }
    // Medium dead zones (13..=25): moderate penalty, scaled by how far
    // the gap is from the lookahead item (a gap the next item fits is fine).
    if post_residual > 12 && post_residual <= 25 {
        let gap_ok = (next_item_size as f64) > 0.0 && (next_item_size as f64) <= post_residual as f64;
        if !gap_ok {
            score += 25.0 * (1.0 - post_residual as f64 / 25.0);
        } else {
            score -= 15.0; // gap is reusable by the lookahead item
        }
    }
    // Perfect or near-perfect fit: strong reward.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }
    // Reward leaving a gap that exactly (or nearly) accommodates the next item.
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 70.0;
        } else if gap > 0 && gap <= 8 {
            score -= 20.0;
        } else if gap < 0 {
            // next item won't fit in the leftover: mild penalty, worse for big overshoot
            score += (-gap as f64).min(30.0) * 0.5;
        }
    }

    // --- Tightness reward: prefer bins where the item fills a large fraction ---
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio;

    // --- Open-bin pressure ---
    // Encourage closing out existing bins rather than spreading; but when many
    // bins are open, prefer reusing them (avoid proliferation).
    score += open_bins_count as f64 * 1.5;
    if fitting_bins_count > 1 {
        // competition among fitting bins: mild bonus to keep scores distinct,
        // favor bins with smaller residual (handled by base term) but add
        // pressure to use the bin with least remaining flexibility.
        score += (fitting_bins_count as f64 - 1.0) * 2.0 * (1.0 - fill_ratio);
    }
    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // --- Mean-residual coupling: when mean residual is low, conserve space
    // more aggressively (penalize any leftover); when high, be lenient. ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (mean_residual - post_residual as f64).max(0.0) * 0.3 * progress;

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // New bin is attractive when: no good existing fit exists, item is large,
        // or stream is early (many items remain to fill the fresh bin).
        let early = 1.0 - progress;
        let good_fit_exists = fitting_bins_count > 0 && (post_residual as f64) < mean_residual;
        if good_fit_exists {
            score += 80.0; // discourage opening when a decent fit exists
        } else {
            score -= 30.0 * early; // early stream: fresh bin is cheap
        }
        // Large items pack best in empty bins.
        if item_size >= 60 {
            score -= 25.0;
        }
        // If many bins are already open, discourage yet another.
        score += open_bins_count as f64 * 2.5;
        // If the next item is large and this item is small, better to place the
        // small item into an existing partial bin and save the empty one.
        if next_item_size >= 50 && item_size <= 30 {
            score += 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual) strongly non-linearly.
    score += 0.05 * (post_residual as f64) * (post_residual as f64) / bin_capacity as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual and next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr == nxt {
            score -= 30.0; // perfect chain: next item fills this bin exactly
        } else if pr > nxt {
            // next item fits too: reward closeness of the chain
            score -= 20.0 * (1.0 - (pr - nxt) / bin_capacity as f64);
        } else {
            // next item does NOT fit after placement: penalize wasted residual
            score += 0.35 * (nxt - pr);
        }
    }

    // Compare post_residual against mean residual of open bins.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 12.0 + 8.0 * (1.0 - progress);
        if next_item_size > 0 && (next_item_size as f64) >= 0.9 * bin_capacity as f64 {
            // if next item is huge, a fresh bin may be preferable
            score -= 15.0;
        }
    }

    // Slight preference to keep many open bins consolidated early.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Penalize small dead space left behind (hard to reuse later).
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 20.0; // tiny slivers are useless
        } else {
            // residual value decays if it matches typical small item sizes
            score -= 4.0 * (-(dead - 10.0).abs() as f64 / 25.0).exp();
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: check whether the next item fits the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // chainability is valuable
            let chain = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 10.0 * chain;
        } else {
            // residual too small for next item: mild penalty scaled by waste
            score += 3.0 * (next_item_size as f64 - post_residual as f64).min(20.0) / 20.0;
        }
    } else {
        // last item: prefer closing bins completely
        score -= 15.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let fit_quality = fill_ratio;
        score -= 25.0 * fit_quality;
    }

    // New-bin candidate handling: opening a new bin is penalized more when
    // many bins are already open (prefer consolidation), and less early on.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 18.0 + 10.0 * (open_bins_count as f64).ln().max(0.0) + 8.0 * progress;
        // but if the item is large and no bin fits well, new bin is fine
        if item_size > bin_capacity / 2 && fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Global state coupling: if mean residual across open bins is high,
    // encourage using existing space (penalize new bins implicitly, reward this bin).
    score -= 2.0 * (mean_residual / bin_capacity as f64);

    // Slight preference for bins with residuals close to item size (smooth tightness).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.05 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;
    // normalized post residual
    let x = pr / cap;
    // non-linear polynomial coupling with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += x * x * (1.0 - progress) * 8.0;
    score += x * (progress * 6.0 - p2 * 4.0 + p3 * 2.0);
    // reward tight fits more strongly later in the stream
    score -= (1.0 - x) * (1.0 - x) * (1.0 + progress) * 4.0;
    // last-chance bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 * (1.0 - progress);
    }
    // lookahead coupling: if next item fits the post residual, reward
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * (1.0 - progress);
    }
    // penalize opening new bins when many bins already fit
    if bin_residual == bin_capacity {
        score += 5.0 + open_bins_count as f64 * 0.5;
        if next_item_size as f64 > pr {
            score += 3.0;
        }
    }
    // mild mean-residual alignment term
    score += ((pr - mean_residual) / cap).abs() * (0.5 + p2);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 8 and integer-division tiers.
    let pr = post_residual;
    let class = pr / 8; // coarse tier
    let residue = pr % 8;

    // Reward placements landing in "good" residual classes (multiples of 10/20 keep
    // space reusable by common item sizes). Penalize awkward residues.
    let residue_penalty: f64 = match residue {
        0 => -6.0,
        1 | 2 | 3 => 4.0,
        4 | 5 => 1.0,
        6 | 7 => 2.5,
        _ => 0.0,
    };
    score += residue_penalty;

    // Tier-based reward: post_residual divisible by 20 (or exactly 0) is ideal.
    if pr == 0 {
        score -= 30.0; // perfect fit
    } else if pr % 20 == 0 {
        score -= 12.0;
    } else if pr % 10 == 0 {
        score -= 6.0;
    }
    // Deep-tier penalty: very small but nonzero post_residual is dead space.
    if pr > 0 && pr < 10 {
        score += 10.0 + (10 - pr) as f64;
    }

    // Tightness: fraction of bin consumed by this item.
    let fill = item_size as f64 / cap;
    score -= 8.0 * fill;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, big reward;
    // if post_residual can't hold the next item anyway, mild bonus for wasting it here.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack == 0.0 {
                score -= 25.0;
            } else if slack < 10.0 {
                score += 3.0;
            } else {
                score -= 4.0;
            }
        } else {
            score -= 2.0; // residual unusable by next item anyway
        }
    }

    // New-bin candidate: baseline cost plus pressure from open bins and mean residual.
    if bin_residual == bin_capacity {
        score = cap * 0.55 + open_bins_count as f64 * 1.5;
        // Open fewer bins early; allow opening more as stream progresses.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * progress;
        // If existing bins are fragmented (high mean residual), new bin is attractive.
        score -= (mean_residual / cap).clamp(0.0, 1.0) * 10.0;
        // Don't open a new bin when this bin is the only fitting one.
        if fitting_bins_count == 1 {
            score += 40.0;
        }
    }

    // Mild global regularization: prefer bins whose residual is near the mean.
    score += ((post_residual as f64 - mean_residual) / cap).abs() * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftovers (1..=9) are nearly useless
    // for future items (min item size 10) -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        // moderately awkward gap
        score += 8.0;
    } else if post_residual == 0 {
        // perfect fit: strong reward
        score -= 60.0;
    }

    // Reward tight fits: fraction of bin used by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Last chance: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into
    // existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate handling: an empty bin has residual == capacity.
    // It should only win when no open bin fits reasonably, i.e. it must
    // score worse than any reasonable existing-bin placement.
    if bin_residual == bin_capacity {
        score += 120.0;
        // If nothing else fits (this call is the only candidate), let it win.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0;
    }

    // Slight preference for bins already below mean residual (balancing).
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress factor: early in stream, prefer tight packing; late, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- 2-step lookahead: reward when next item fits into post_residual ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits here: reward proportionally to how snugly it fits.
            let snug = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= 25.0 * snug;
        } else {
            // Next item will NOT fit after this placement: penalize wasted potential.
            let overflow = (next_item_size - post_residual) as f64;
            score += 0.4 * overflow;
        }
        // Perfect chaining: post_residual exactly equals next item.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else {
        // Last item: strongly prefer minimal post residual.
        score += 0.5 * post_residual as f64;
    }

    // --- Dead space penalty: small residuals are hard to use later ---
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // --- Relative to mean residual: prefer bins tighter than average ---
    score += 0.3 * ((post_residual as f64) - mean_residual);

    // --- Last-chance bin: if this is the only fitting bin, avoid opening new ---
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // --- New-bin candidate: only attractive when it enables a good 2-step chain ---
    if bin_residual == bin_capacity {
        let open_penalty = 30.0 + 40.0 * progress;
        let chain_bonus = if next_item_size > 0 {
            // New bin residual after placing = capacity - item_size; check chain.
            if bin_capacity >= item_size + next_item_size {
                let left = bin_capacity - item_size - next_item_size;
                20.0 - 0.3 * left as f64
            } else {
                -10.0
            }
        } else {
            0.0
        };
        score += open_penalty - chain_bonus;
    }

    // Slight preference to fill already-open bins to reduce bin count pressure.
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.01;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Base: strongly reward small post_residual with smooth non-linear decay.
    let tightness = 1.0 - pr / cap; // 1.0 = perfect fit
    score -= 30.0 * tightness * tightness * tightness;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, prefer larger residuals (flexibility); late, pack tight.
    let flex = pr / cap;
    let coupling = flex * flex * (1.0 - progress) * (1.0 - progress) * 40.0
                 - flex * progress * progress * 25.0;
    score += coupling;

    // Penalize post_residual that is too small to hold the lookahead item
    // (dead space), but reward if lookahead fits into the resulting residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx > pr {
            let waste = (nx - pr) / cap;
            score += 15.0 * waste * (1.0 + progress);
        } else {
            score -= 10.0 * (pr - nx) / cap;
        }
    }

    // Last-chance bin: strong reward to use the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 20.0 + 10.0 * tightness;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate: penalize mildly early (reuse bins), less late or
    // when many bins are open and mean residual is small.
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64;
        let pressure = (mean_residual / cap).max(0.0).min(1.0);
        score += 8.0 * (1.0 - progress) * (1.0 + openness / (openness + 5.0))
               - 12.0 * (1.0 - pressure) * progress;
    }

    // Mild penalty for bins deviating from the mean residual (balance load).
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 5.0 * dev * dev * (0.5 + 0.5 * (1.0 - progress));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class: reward small post-residuals that form useful remainder classes.
    // Items 1..100 unknown distribution; classify residual into coarse buckets.
    let pr = post_residual;
    let class = match pr {
        0 => 0.0,
        1..=10 => 1.0,
        11..=25 => 2.0,
        26..=50 => 4.0,
        _ => 6.0,
    };
    score += class * 10.0;

    // Modulo harmonic: residual divisible by common item sizes is more reusable.
    if pr > 0 {
        let mut reuse = 0.0;
        for d in [10u32, 20, 25, 50] {
            if pr % d == 0 {
                reuse += 5.0;
            }
        }
        score -= reuse;
    }

    // Dead-space penalty: residual too small for the smallest plausible item.
    if pr > 0 && pr < 5 {
        score += 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: default is a fresh empty bin with residual = capacity.
    // Penalize opening new bins unless open bins are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        // If mean residual across open bins is small (bins mostly full), new bin is fine.
        score += 40.0 + 60.0 * (1.0 - fragmentation);
        // Late in stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    } else {
        // Using an existing bin is generally good; reward more when bins are many.
        score -= 10.0 + 2.0 * open_bins_count as f64;
    }

    // Lookahead: if the next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 200.0;
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // Next item cannot use the leftover; penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Prefer filling bins with larger mean residual (consolidate waste).
    score -= 0.1 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible future item (size ~1, but practically anything < ~10) are
    // dead space. Penalize small-but-nonzero gaps harshly.
    if post_residual > 0 {
        // gap smaller than a "useful" threshold is nearly worthless
        let dead_threshold = 10.0f64;
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 12.0;
        }
        // mild progressive penalty on leftover size
        score += (post_residual as f64) * 0.15;
    } else {
        // perfect fit: strong reward
        score -= 25.0;
    }

    // Reward tight fits relative to item size
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 8.0;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, encourage
    // filling existing bins; few open bins -> opening new bins is cheap.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 3.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; allow it when the
        // item would leave a bad gap in an existing bin.
        score += 15.0 + pressure;
        if post_residual == 0 {
            score -= 5.0;
        }
    } else {
        score -= pressure * 0.5;
    }

    // Lookahead: if next item fits exactly in the post residual, reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
    }

    // Mean residual coupling: placing into a bin far below mean residual
    // (i.e., leaving richer bins untouched) is slightly discouraged.
    score += ((post_residual as f64) - mean_residual).abs() * 0.05;

    // Slight preference early in the stream to consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward bins whose post_residual exactly matches next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
            if post_residual == next_item_size {
                score -= 25.0; // perfect 2-chain match
            }
        } else {
            // next item cannot use this residual: penalize proportionally to wasted potential
            score += 8.0 + 12.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    } else {
        // last item: minimize residual directly (already the base)
        score -= 5.0;
    }

    // Penalize large residuals relative to mean residual (avoid hoarding space)
    score += 0.15 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Discard near-full bins are good: reward small post_residual
    if post_residual < 10 {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are poor
    if bin_residual == bin_capacity {
        score += 45.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing fits, must open new bin
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0; // opening new bin allows a fresh 2-chain
        }
    }

    // Late in stream: consolidate, prefer filling existing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Strong best-fit pressure: squared residual waste dominates.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Lookahead coupling: if the next item cannot fit in the leftover, the
    // residual is likely dead space; penalize proportionally to how far short it falls.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            let shortfall = (next_item_size - post_residual) as f64;
            score += 4.0 * shortfall;
        } else {
            // Reward bins whose leftover stays useful for the known next item.
            score -= 2.0 * (next_item_size as f64).min(post_residual as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Scarcity pressure: many open bins -> consolidate; few open bins -> new bins are cheap.
    let scarcity = (open_bins_count as f64).ln().max(0.0);
    score += 1.5 * scarcity;

    // Prefer bins tighter than the current mean residual (they are closer to full).
    score += 0.8 * (mean_residual - post_residual as f64);

    // Early in the stream, opening fresh bins is more acceptable; later, avoid
    // spreading out — penalize the new-bin candidate progressively.
    if bin_residual == bin_capacity {
        score += 10.0 + 25.0 * progress - 2.0 * scarcity;
        // If nothing else fits (this call is the only candidate), opening is fine.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Perfect fit celebration.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr_norm = pr / cap;
    let poly = pr_norm * pr_norm * (0.5 + progress) + pr_norm * (1.0 - progress) * 0.3;
    score += poly * cap * 0.4;

    // Reward tight fits more strongly as the stream progresses
    let tightness = 1.0 - pr_norm;
    score -= tightness * tightness * (10.0 + 20.0 * progress);

    // Last-chance bin: strong reward, growing with progress
    if fitting_bins_count == 1 {
        score -= 25.0 + 30.0 * progress;
    }

    // Lookahead: penalize leaving residual that fits next item poorly (dead space)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let leftover = pr - nxt;
            let waste = leftover / cap;
            score += waste * waste * 15.0;
            // Reward exact chain fits
            score -= 8.0 * (1.0 - waste);
        } else {
            // residual too small for next item: dead space penalty, worse early
            score += (pr / cap) * (12.0 + 18.0 * (1.0 - progress));
        }
    }

    // Slight preference to fill bins with larger residuals vs mean (balance)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * 5.0;

    // Mild penalty for opening new bins when many exist, easing late in stream
    if bin_residual == bin_capacity {
        score += 6.0 + 0.15 * open_bins_count as f64 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that are "nice" multiples
    // of common item sizes are more reusable, so penalize them less.
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -30.0 // perfect fit: strongly reward
    } else if pr % 10 == 0 {
        -6.0
    } else if pr % 5 == 0 {
        -3.0
    } else if pr < 10 {
        12.0 // tiny dead space: unusable for most items
    } else {
        0.0
    };
    score += class_bonus;

    // Lookahead: reward bins whose post_residual still fits the next item.
    if next_item_size > 0 && pr >= next_item_size {
        score -= 8.0 + 0.05 * next_item_size as f64;
    } else if next_item_size > 0 {
        score += 4.0;
    }

    // Last chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when open bins fit poorly or are scarce.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let desperation = if fitting_bins_count == 0 {
            100.0
        } else if post_residual > 40 {
            5.0
        } else {
            0.0
        };
        let crowding = if open_bins_count > 8 { -2.0 } else { 0.0 };
        score = 100.0 - desperation + crowding + 10.0 * progress;
        if next_item_size > 0 && 100 >= next_item_size {
            score -= 1.0; // fresh bin always fits next item
        }
    }

    // Slight preference for filling already-open bins tightly.
    score += 0.02 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps (1..10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 35 {
        score += 4.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= 25.0 / (1.0 + tightness * 8.0);

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last chance: strongly prefer using the only bin that fits, avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward keeping this bin useful.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    }
    // If next item would NOT fit into the post-residual, mild penalty for stranding space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 20.0;
    }

    // Open-bin pressure: discourage spreading across many bins; favor new bin when few open.
    score += (open_bins_count as f64) * 1.5;

    // Prefer bins with residual close to mean residual (keeps bin pool homogeneous).
    score += ((bin_residual as f64) - mean_residual).abs() * 0.15;

    // Early in stream: opening bins is cheaper; late: consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 6.0;

    // New-bin candidate baseline: neutral-ish but beatable by good fits / last-chance reuse.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.55 + 15.0;
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative: new bin is fine
        }
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: leftover exactly matches next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 12.0 * (1.0 - diff / (bin_capacity as f64));

        // Small post residual that cannot hold the next item is dead space.
        if post_residual < next_item_size {
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative fill vs mean residual: prefer bins tighter than average.
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin bonus: avoid wasting a unique fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize new-bin candidate slightly unless current bins fit poorly.
    if bin_residual == bin_capacity {
        let poor = if next_item_size > 0 && post_residual >= next_item_size { 0.0 } else { 1.0 };
        score += 5.0 + 3.0 * poor - 2.0 * (mean_residual / bin_capacity as f64);
    }

    // Late-stream consolidation: tighten up as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core tightness reward: strongly favor bins whose post_residual is small.
    // Non-linear coupling: dead space is quadratically penalized as it grows.
    let dead = post_residual as f64;
    score += 0.35 * dead * dead / bin_capacity as f64;

    // Lookahead: if the next item fits into the post_residual, this placement
    // chains nicely — reward it (subtract). If next item is bigger than
    // post_residual but this bin still had room, mild penalty for stranding space.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item stacks perfectly; reward proportional to how well it fills.
            score -= 12.0 * (next_item_size as f64 / bin_capacity as f64);
        } else if next_item_size <= bin_residual {
            // Next item could have fit this bin anyway; slight penalty for
            // leaving fragmented space it can't use.
            score += 4.0;
        }
    } else {
        // Last item: absolutely minimize waste.
        score -= 50.0 * (1.0 - dead / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: the empty bin (bin_residual == bin_capacity)
    // should only win when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 45.0;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        score -= 25.0 * (1.0 - progress);
        // If many bins are open, discourage adding more (consolidate).
        score += 2.0 * open_bins_count as f64;
        // If the item is large relative to capacity, a fresh bin is more attractive.
        score -= 10.0 * (item_size as f64 / bin_capacity as f64);
        // If the average open residual is small, open bins are nearly full anyway;
        // a new bin becomes more attractive.
        score -= 0.3 * mean_residual;
    } else {
        // Reward using bins that are already partially filled, especially
        // when their residual is close to the item (good fit ratio).
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 15.0 * fit_ratio;
        // Late in the stream, favor closing out existing bins.
        score -= 8.0 * progress;
    }

    // Global pressure: when many bins are open with large mean residual,
    // prefer placements that reduce fragmentation (low post_residual already does).
    if bin_residual < bin_capacity {
        score += 0.15 * (mean_residual - post_residual as f64).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = norm_pr * norm_pr;
    let p3 = p2 * norm_pr;
    let prog_c = 0.5 + progress; // smooth progress factor in [0.5, 1.5]
    score += prog_c * (p3 * 40.0 - p2 * 12.0);

    // Penalize wasted space scaled by mean residual context
    score += (pr - mean_residual).abs() * 0.15 * prog_c;

    // Reward tight fits (small post_residual) more as stream progresses
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 8.0 * (0.5 + progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Lookahead: favor bins whose residual can also fit the next item
    if next_item_size > 0 {
        let fits_next = pr >= next_item_size as f64;
        if fits_next {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    // Discourage opening new bins early when existing bins fit well
    if bin_residual == bin_capacity {
        score += 6.0 - 4.0 * progress;
        if fitting_bins_count > 0 {
            score += 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) strongly favored.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize residuals in "dead zone" classes: small unusable leftovers (1..10)
        if post_residual < 10 {
            score += 50.0 * (10 - post_residual) as f64;
        }
        // Modulo-10 harmonic classes: residuals divisible by 10 pair well with
        // typical item sizes; reward multiples of 10 and 25.
        if post_residual % 10 == 0 {
            score -= 8.0;
        }
        if post_residual % 25 == 0 {
            score -= 5.0;
        }
        // Penalize odd residuals (harder to pair with even items)
        if post_residual % 2 == 1 {
            score += 3.0;
        }
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            // Reward small gaps (good chaining), penalize large gaps
            score -= 20.0 * (1.0 - gap as f64 / bin_capacity as f64);
            if gap < 10 {
                score += 30.0; // tiny leftover becomes dead space
            }
        }
        // If next item won't fit here at all, residual is final: penalize waste
        if next_item_size > post_residual {
            score += 0.5 * post_residual as f64;
        }
    }

    // Tight fit reward: fraction of bin consumed by this item
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill;

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate logic: only attractive when current bins are crowded
    if bin_residual == bin_capacity {
        let crowded = mean_residual < item_size as f64 * 0.5;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if crowded {
            score -= 25.0; // allow opening fresh bin when residuals are fragmented
        } else {
            score += 60.0 + 40.0 * (1.0 - progress); // early stream: keep bins open
        }
        // If only one bin can fit and it's tight, opening new bin is fine
        if fitting_bins_count <= 1 && !crowded {
            score -= 10.0;
        }
    }

    // Mild preference to fill bins with low residual relative to mean
    score += 0.2 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum plausible future item are "dead". Penalize them heavily.
    if post_residual > 0 {
        let dead_threshold = 10.0; // smallest typical future item footprint
        if (post_residual as f64) < dead_threshold {
            score += 60.0 * (1.0 - post_residual as f64 / dead_threshold);
        }
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= 25.0 / (1.0 + tightness);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            // post residual can't host next item -> mild penalty
            score += 8.0;
        }
    }

    // Open-bins pressure: discourage spreading across many bins unless the
    // fit is genuinely good; encourage consolidation when many bins are open.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 2.0 * (open_bins_count as f64) * (0.5 + 0.5 * progress);

    // Mean-residual coupling: if this bin's residual is well below the mean,
    // it's a good consolidation target.
    let bin_res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let rel = bin_res_f / mean_residual;
        if rel < 1.0 {
            score -= 10.0 * (1.0 - rel);
        } else {
            score += 5.0 * (rel - 1.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: an empty bin is a fallback; make it
    // unattractive unless no decent fit exists (its baseline post_residual is
    // large, which already hurts it, but add explicit pressure scaled by how
    // many bins could fit the item).
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 1.0 };
        score += 30.0 + 10.0 * pressure;
        // Late in the stream, opening new bins is cheaper than wasting space.
        score -= 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward bins whose post residual matches next item well
    if next_item_size > 0 {
        let next_fits = (post_residual >= next_item_size) as f64;
        let exact_match = (post_residual == next_item_size) as f64;
        score -= 60.0 * next_fits;
        score -= 40.0 * exact_match;
        // penalize post residual slightly larger than next item (wasted gap)
        if post_residual > next_item_size && post_residual < next_item_size * 2 {
            score += 10.0;
        }
    } else {
        // last item: prefer tightest fit
        score += 50.0;
    }

    // relative to mean residual: prefer bins tighter than average
    let mean_gap = mean_residual - bin_residual as f64;
    score -= 3.0 * mean_gap;

    // last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // penalize opening a new bin when open bins fit reasonably
    if bin_residual == bin_capacity {
        score += 35.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 20.0; // fresh bin still good for lookahead though
            score -= 25.0;
        }
    }

    // late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * (bin_residual != bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strongly prefer bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Lookahead: if the next item can fit in the post residual, this is a great chain placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0 + 0.05 * next_item_size as f64;
    }
    // Penalize leaving a residual that is too small for the next item (dead space risk),
    // but only mildly if the residual itself is tiny.
    if next_item_size > post_residual && post_residual > 0 {
        score += 3.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Last-chance bonus: if this is the only bin that can fit the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when existing bins fit badly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 20.0;
        // If few bins fit the item, opening a new bin becomes more attractive.
        if fitting_bins_count == 0 {
            score -= 40.0;
        } else if fitting_bins_count == 1 {
            score -= 10.0;
        }
        // When open bins are crowded on average, a fresh bin is reasonable.
        if mean_residual < item_size as f64 {
            score -= 15.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Slight preference for using bins with below-average residual (keeps large residuals free).
    if bin_residual != bin_capacity {
        score += 0.05 * (bin_residual as f64 - mean_residual).max(0.0);
    }

    // Prefer keeping a small number of open bins when they are relatively empty.
    if open_bins_count > 0 && mean_residual > 40.0 && bin_residual != bin_capacity {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap; // normalized post residual in [0,1)

    // Base: prefer tight fits (low post residual), with smooth polynomial shaping
    let mut score = pr;

    // Non-linear coupling: quadratic penalty on wasted space, modulated by stream progress.
    // Later in the stream, dead space becomes more costly (bins must be reused efficiently).
    let waste_penalty = norm_pr * norm_pr * (1.0 + 60.0 * progress) * cap;
    score += waste_penalty;

    // Smooth cubic term: extremely small residuals are great, tiny-but-nonzero less so;
    // use smooth cubic decay of reward as residual shrinks.
    let tight_reward = -40.0 * (1.0 - norm_pr).powi(3) * (0.5 + progress);
    score += tight_reward;

    // Interaction with mean residual across open bins: placing into a bin whose residual
    // is far from the mean keeps residuals heterogeneous (good for future fits).
    let bin_res = bin_residual as f64;
    let dev = (bin_res - mean_residual) / cap;
    score -= 15.0 * dev.abs() * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // (smoothly scaled by how well it fits).
    if fitting_bins_count == 1 {
        score -= 50.0 * (1.0 - norm_pr);
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward (smooth).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        if gap <= pr {
            score -= 35.0 * (1.0 - gap / cap) * (1.0 - progress * 0.5);
        } else {
            // penalize post residuals that leave nothing usable for the lookahead
            score += 10.0 * (gap / cap) * norm_pr;
        }
    }

    // Mild penalty for proliferating bins early; smooth in open_bins_count.
    score += 2.0 * (open_bins_count as f64).powf(0.5) * (1.0 - progress);

    // New-bin candidate: make it moderately attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - norm_pr) + 25.0 * (1.0 - progress);
        // If open bins are crowded (high mean fill), opening a new bin is reasonable.
        score -= 20.0 * (1.0 - mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // residue classes (divisible by common item sizes) are favored.
    let pr = post_residual;
    if pr > 0 {
        let mut bonus = 0.0;
        if pr % 10 == 0 { bonus += 6.0; }
        if pr % 20 == 0 { bonus += 4.0; }
        if pr % 25 == 0 { bonus += 3.0; }
        if pr % 50 == 0 { bonus += 3.0; }
        score -= bonus;

        // Dead-space penalty: tiny unusable leftovers (1..10) are heavily penalized
        if pr < 10 {
            score += 25.0 + (10 - pr) as f64;
        } else if pr < 20 {
            score += 8.0;
        }
    } else {
        // Perfect fit
        score -= 40.0;
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual,
    // penalize if next item nearly fits (leaving worse residue).
    if next_item_size > 0 {
        let nx = next_item_size;
        if nx <= pr {
            if pr - nx < 10 { score -= 12.0; }        // chainable near-perfect
            if pr % nx == 0 { score -= 6.0; }          // divisible leftover
        } else {
            score += (nx - pr) as f64 * 0.3;           // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: neutral-ish baseline, penalize early in stream,
    // allow opening new bins when mean residual is already fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual / cap - 0.35).max(0.0);
        score = score.max(0.0) + 30.0 + 20.0 * (1.0 - progress) + 40.0 * fragmentation;
        // But if all open bins would leave terrible residue, new bin is attractive
        if post_residual == bin_capacity && next_item_size > 0 && mean_residual < 20.0 {
            score -= 10.0;
        }
    }

    // Mild tightness reward: filling a tight bin well is good.
    score -= (1.0 - (post_residual as f64 / cap)).min(1.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead space penalty
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 8.0; // mildly awkward gap
    }

    // Reward tight fits (small post_residual relative to item size).
    if post_residual == 0 {
        score -= 50.0; // perfect fill
    } else {
        let tightness = item_size as f64 / bin_residual.max(1) as f64;
        score -= 25.0 * tightness;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open,
    // but allow it when the stream is early or bins are congested.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate baseline: attractive only if existing residuals are poor.
        score = 35.0 + pressure * 2.0 - mean_residual * 0.3;
        if next_item_size > 0 && next_item_size > post_residual.max(item_size) {
            score -= 10.0; // lookahead suggests fresh space is useful
        }
    } else {
        // Prefer bins whose residual is close to the mean (balanced packing),
        // with slight preference for larger residuals when item is large.
        score += (bin_residual as f64 - mean_residual).abs() * 0.4;
        // Lookahead coupling: leaving room for the next item is good.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 12.0;
            } else if bin_residual >= next_item_size && post_residual < next_item_size {
                score += 5.0; // this placement blocks the next item here
            }
        }
        // Mild pressure against accumulating many open bins.
        score += pressure * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual)
    score += 0.5 * (post_residual as f64 / bin_capacity as f64) * (bin_capacity as f64);

    // 2-step lookahead: reward bins whose post_residual matches the next item well
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // next item won't fit here; penalize proportionally to wasted potential
        let miss = (next_item_size - post_residual) as f64;
        score += 4.0 * (miss / bin_capacity as f64);
    }

    // Perfect wrap: post_residual exactly equals next item => strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Relative-to-mean coupling: bins below mean residual are scarcer, favor them
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: neutral-to-slightly-high baseline; only wins when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 25.0;
        // opening a new bin is attractive if next item is large and no good match exists
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Early stream: be slightly more willing to open bins to build diversity
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: early stream -> be picky, penalize waste; late stream -> fill greedily.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Waste penalty: quadratic in post_residual, softened over time.
    let waste = (post_residual as f64 / bin_capacity as f64).powi(2) * 60.0;
    score += waste * (1.0 - 0.5 * progress);

    // Lookahead: reward bins whose post_residual can host the next item (chain fits).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0 + 0.3 * post_residual as f64 * (1.0 - progress);
        } else {
            // Penalize leaving a sliver the next item cannot use.
            let dead = post_residual as f64;
            score += 0.4 * dead * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Tight-fit reward: small post_residual relative to capacity is great.
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 15.0 * tightness * tightness;

    // Crowd effect: many open bins -> prefer consolidating into existing bins.
    let crowd = (open_bins_count as f64).ln().max(0.0);
    if bin_residual < bin_capacity {
        score -= 3.0 * crowd;
    } else {
        // New-bin candidate: only attractive if it enables a better long-term fit
        // (large item, low mean residual spread) or stream is young.
        let openness = 1.0 - progress;
        score -= 10.0 * openness * crowd.min(3.0);
        if mean_residual > 0.0 && (post_residual as f64) < mean_residual {
            score += 8.0;
        }
    }

    // Mean residual coupling: prefer bins close to the mean residual (balanced packing),
    // penalize outliers that create fragmented space.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Exact-fill bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        // tiny unusable sliver
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let fit = fitting_bins_count as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p_norm = pr / cap; // normalized post residual [0,1]
    let mut score = pr;

    // Polynomial in progress: weight residual waste more later in the stream
    let w = 0.5 + 1.5 * progress * progress;
    score += w * (p_norm * p_norm) * cap * 0.3;

    // Cubic coupling: penalize mid-range residuals (dead space) via smooth bump
    let bump = p_norm * (1.0 - p_norm);
    score += 8.0 * bump * bump * (1.0 + progress);

    // Lookahead synergy: reward residual matching next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let diff = (pr - ni).abs();
        score -= 6.0 * (1.0 - diff / cap) * (1.0 + progress);
        // exact fit reward
        if post_residual == next_item_size {
            score -= 12.0;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 10.0 + 20.0 * progress;
    } else {
        score += 1.5 * (fit - 1.0).sqrt();
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += 0.5 * (pr as f64 - mean_residual) * (0.5 + progress);

    // New-bin candidate: make empty bin costly unless residuals are hopeless
    if bin_residual == bin_capacity {
        let hopeless = (mean_residual / cap).max(0.0).min(1.0);
        score = 60.0 + 40.0 * (1.0 - hopeless) - 25.0 * hopeless * hopeless;
        if fitting_bins_count == 0 {
            score = -100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residues divisible by small sizes are reusable.
    let pr = post_residual;
    if pr % 10 == 0 { score -= 12.0; }
    if pr % 20 == 0 { score -= 8.0; }
    if pr % 25 == 0 { score -= 6.0; }
    if pr % 50 == 0 { score -= 6.0; }

    // Dead space: post_residual smaller than the minimum item size is unusable.
    if pr < 10 && pr > 0 {
        score += 40.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly or well.
    if next_item_size > 0 && next_item_size <= pr {
        score -= 10.0;
        if pr == next_item_size {
            score -= 30.0;
        } else if (pr - next_item_size) % 10 == 0 {
            score -= 8.0;
        }
    } else if next_item_size > pr && next_item_size > 0 {
        // Next item won't fit here; penalize slightly unless residual already small.
        score += 5.0;
    }

    // Fractional tightness: prefer bins that end up mostly full.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 15.0 * fill;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless residual would be tiny dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost so we prefer
    // reusing open bins when they fit reasonably well, but allow opening a new
    // bin when the best existing fit leaves bad dead space.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Late in the stream, opening fresh bins is less costly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
        // If no existing bin fits well (large post_residual elsewhere), new bin wins.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // If the item is large relative to capacity, a fresh bin is attractive.
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Slight penalty proportional to open bins to encourage consolidation.
    score += 0.5 * open_bins_count as f64;

    // Mean residual coupling: when mean residual is large, prefer bins below mean
    // (use up the stragglers); when small, prefer bins above mean.
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // Integer-division threshold on post_residual quarters.
    match pr / 25 {
        0 => score -= 5.0,   // very tight fit, good
        1 => score += 0.0,
        2 => score += 4.0,
        _ => score += 2.0,   // large leftover
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Tight fit relative to residual: fraction of residual consumed.
    let fill_frac = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fill_frac;

    // Pressure from number of open bins: discourage spreading when many bins open.
    score += 2.0 * open_bins_count as f64;

    // Mean residual coupling: prefer bins whose residual is below mean (tighter bins).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Lookahead: if next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 90.0;
        } else if next_item_size <= post_residual {
            score -= 20.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            // next item can't use this gap: penalize medium dead gaps less if large
            score += 10.0;
        }
    }

    // New-bin candidate: baseline preference to reuse open bins, unless
    // existing fits are all poor (large dead space) or bins are numerous.
    if bin_residual == bin_capacity {
        let mut new_bin_score = 55.0 + 1.5 * open_bins_count as f64;
        // If the item is large, opening fresh is safer than wasting space.
        if item_size >= 60 {
            new_bin_score -= 30.0;
        }
        // If no open bin leaves a decent residual, opening a new bin is attractive:
        // emulate by penalizing existing-bin path when item barely fits.
        if bin_residual - item_size <= 0 {
            new_bin_score -= 100.0;
        }
        // Late in stream, prefer consolidation into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score += 20.0 * progress;
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Perfect fit for next item -> strong reward.
        if diff == 0.0 {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportional to closeness of match.
            score -= 40.0 * (1.0 - diff / (bin_capacity as f64));
        } else {
            // Next item won't fit in the remainder: penalize wasted potential.
            score += 15.0 + 0.25 * diff;
        }
    }

    // Penalize residuals that are too small to ever be useful again (dead space).
    let min_useful = 1u32;
    if post_residual < min_useful {
        score -= 100.0; // perfect fill, best possible outcome
    } else if post_residual < 10 {
        // Small unusable sliver is acceptable only if it's near zero.
        score -= 5.0;
    }

    // Reward filling bins tighter than the current average residual (compactness).
    score += 0.35 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that can fit, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Late in the stream, prefer closing out bins (consolidation pressure).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mild penalty when many bins are open: encourage reducing bin count.
    score += 0.5 * open_bins_count as f64;

    // New-bin candidate: make it moderately attractive only when nothing fits well.
    if bin_residual == bin_capacity {
        score += 12.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0; // fresh bin keeps 2-step flexibility
        }
    }

    score
}
